// TypeFeaturing changes context, not owned typing or default selector predicates.
// Admit an already executed featuring stage only after canonical endpoint checks.
fn definition_non_typing_featuring(graph:&[KirElement],owner:&KirElement,rel:&KirElement)->Result<bool,QueryFailure> {
    let index=graph.iter().map(|node|(node.id.as_str(),node)).collect::<BTreeMap<_,_>>();
    definition_non_typing_featuring_in_view(&DefinitionNameQuery::new(graph,&index),owner,rel)
}
fn definition_non_typing_featuring_in_view(query:&DefinitionNameQuery<'_, '_>,owner:&KirElement,rel:&KirElement)->Result<bool,QueryFailure> {
    if rel.kind.rsplit("::").next()!=Some("TypeFeaturing") {return Ok(false);}
    if rel.properties.get("owning_related_element").and_then(Value::as_str)!=Some(owner.id.as_str())
        || query_reference_in_view(query,rel,"feature_of_type")?.id!=owner.id
        || !metaclass_conforms(&query_reference_in_view(query,rel,"featuring_type")?.kind,"Type") {
        return Err(query_failure("non-typing featuring stage requires canonical owner and Type endpoints"));
    }
    Ok(true)
}
fn occurrence_strategy_supports(kind:&str)->bool {occurrence_contributions::supports(kind)||action_contributions::supports(kind)}
fn occurrence_strategy_names_query(graph:&[KirElement],owner:&KirElement)->Result<Vec<&'static str>,QueryFailure> {
 if action_contributions::supports(&owner.kind) {action_contributions::names_query(graph,owner)} else {occurrence_contributions::names_query(graph,owner)}
}
fn occurrence_strategy_names(graph:&[KirElement],owner:&KirElement)->Result<Vec<&'static str>,Diagnostic> {occurrence_strategy_names_query(graph,owner).map_err(|failure| failure.into_diagnostic_at("occurrence_strategy_names"))}
fn occurrence_strategy_contributions(graph:&[KirElement],owner:&KirElement)->Result<Vec<(&'static str,String)>,Diagnostic> {
 if action_contributions::supports(&owner.kind) {action_contributions::contributions(graph,owner)} else {occurrence_contributions::contributions(graph,owner)}
}

