/// Handwritten transactional execution of the resolved TypeUtil constructor.
/// This adds owned result storage only; typing, bindings and transformation stay separate.
pub(crate) fn definition_materialize_expression_result(elements: &mut Vec<KirElement>, owner_id: &str, membership_id: &str, result_id: &str)
    -> Result<bool, Diagnostic>
{
    if let Some(issue) = ecore_model::validate_publication(elements, ecore_model::ReferenceCompleteness::Closed).first() {
        return Err(error(format!("invalid result-construction input: {}", issue.message)));
    }
    let owner = elements.iter().find(|e| e.id == owner_id).ok_or_else(|| error("result owner is absent"))?;
    if !result_construction_generated::supported(owner.kind.rsplit("::").next().unwrap_or(&owner.kind)) {
        return Err(error("result construction requires an assessed member provider"));
    }
    // Preserve the single-owner no-op boundary before snapshot recomputation.
    if stored_children(elements, owner, "owned_relationship")?.iter().any(|r| metaclass_conforms(&r.kind, result_construction_generated::MEMBERSHIP)) {
        return Ok(false);
    }
    let mut staged = elements.clone();
    reject_result_snapshots(&staged)?;
    let changed = append_owned_expression_result(&mut staged, owner_id, membership_id, result_id)?;
    if let Some(issue) = ecore_model::validate_publication(&staged, ecore_model::ReferenceCompleteness::Closed).first() {
        return Err(error(format!("invalid result-construction output: {}", issue.message)));
    }
    *elements = staged;
    Ok(changed)
}

fn reject_result_snapshots(elements: &[KirElement]) -> Result<(), Diagnostic> {
    if elements.iter().any(|e| e.properties.keys().any(|field| ecore_model::feature(&e.kind, field).is_some_and(|c| c.derived || c.volatile))) {
        return Err(error("result construction requires derived-value recomputation for stored snapshots"));
    }
    Ok(())
}

// Called only on a private staged graph; imported construction and ownership
// contracts are shared by the single-owner and whole-document entry points.
fn append_owned_expression_result(elements: &mut Vec<KirElement>, owner_id: &str, membership_id: &str, result_id: &str)
    -> Result<bool, Diagnostic>
{
    let owner = elements.iter().find(|e| e.id == owner_id).ok_or_else(|| error("result owner is absent"))?;
    if !result_construction_generated::supported(owner.kind.rsplit("::").next().unwrap_or(&owner.kind)) {
        return Err(error("result construction requires an assessed member provider"));
    }
    append_owned_expression_result_storage(elements,owner_id,membership_id,result_id)
}

// Shared storage constructor: callers must establish their resolved producer
// binding. The bounded chain producer composes this with its source-target stage.
fn append_owned_expression_result_storage(elements:&mut Vec<KirElement>,owner_id:&str,membership_id:&str,result_id:&str)->Result<bool,Diagnostic> {
    let owner=elements.iter().find(|e|e.id==owner_id).ok_or_else(||error("result owner is absent"))?;
    if !metaclass_conforms(&owner.kind,"Expression") {return Err(error("result storage requires an Expression"));}
    // Pilot tests membership presence, not whether an existing member has an endpoint.
    if stored_children(elements, owner, "owned_relationship")?.iter().any(|r| metaclass_conforms(&r.kind, result_construction_generated::MEMBERSHIP)) {
        return Ok(false);
    }
    if membership_id.is_empty() || result_id.is_empty() || membership_id == result_id
        || elements.iter().any(|e| e.id == membership_id || e.id == result_id) {
        return Err(error("result construction requires fresh distinct nonempty identities"));
    }
    let mut membership = fresh_definition_element(membership_id.into(), result_construction_generated::MEMBERSHIP)?;
    let mut result = fresh_definition_element(result_id.into(), result_construction_generated::RESULT)?;
    let direction = json!(result_construction_generated::DIRECTION);
    ecore_model::validate_value(&result.kind, "direction", &direction).map_err(error)?;
    result.properties.insert("direction".into(), direction);
    ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS, &mut membership, &mut result)?;
    let owner = elements.iter_mut().find(|e| e.id == owner_id).ok_or_else(|| error("staged result owner is absent"))?;
    ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, owner, &mut membership)?;
    elements.extend([membership, result]);
    Ok(true)
}

/// One atomic additional-member stage for all imported owned-result providers.
/// This does not synthesize inherited literal results or complete transformations.
pub(crate) fn definition_materialize_owned_expression_results(elements: &mut Vec<KirElement>, prefix: &str)
    -> Result<usize, Diagnostic>
{
    if prefix.is_empty() { return Err(error("result batch requires a nonempty identity prefix")); }
    if let Some(issue) = ecore_model::validate_publication(elements, ecore_model::ReferenceCompleteness::Closed).first() {
        return Err(error(format!("invalid result-batch input: {}", issue.message)));
    }
    reject_result_snapshots(elements)?;
    let mut owners: Vec<_> = elements.iter().filter(|e| result_construction_generated::supported(e.kind.rsplit("::").next().unwrap_or(&e.kind)))
        .map(|e| e.id.clone()).collect();
    // Identities and stage order are stable across physical graph storage order.
    owners.sort();
    let mut staged = elements.clone();
    let mut inserted = 0;
    for owner in owners {
        let member = format!("{prefix}.{owner}.return");
        let result = format!("{prefix}.{owner}.result");
        inserted += usize::from(append_owned_expression_result(&mut staged, &owner, &member, &result)?);
    }
    if let Some(issue) = ecore_model::validate_publication(&staged, ecore_model::ReferenceCompleteness::Closed).first() {
        return Err(error(format!("invalid result-batch output: {}", issue.message)));
    }
    *elements = staged;
    Ok(inserted)
}

