/// Named handwritten TypeAdapter reduction over a fixed, normalized snapshot.
/// Producers remain responsible for selecting contributions and chain deduplication.
fn definition_reduce_implicit_generals(graph: &[KirElement], owner: &KirElement,
    pending: &[(&str,&str)]) -> Result<Vec<(String,String)>, Diagnostic> {
    definition_reduce_implicit_generals_query(graph,owner,pending)
        .map_err(|failure| failure.into_diagnostic_at("implicit reduction external boundary"))
}

fn definition_reduce_implicit_generals_query(graph: &[KirElement], owner: &KirElement,
    pending: &[(&str,&str)]) -> Result<Vec<(String,String)>, QueryFailure> {
    fn specializes_excluding(graph: &[KirElement], subtype: &str, supertype: &str, excluded: &str) -> Result<bool, QueryFailure> {
        let mut visited=BTreeSet::from([excluded.to_owned()]);
        let mut queue=vec![subtype.to_owned()];
        while let Some(id)=queue.pop() {
            if id==supertype {return Ok(true);}
            if !visited.insert(id.clone()) {continue;}
            let node=graph.iter().find(|e|e.id==id).ok_or_else(||query_failure("missing reduction ancestry endpoint"))?;
            let generals=definition_general_type_inputs_query(graph,node)?;
            queue.extend(generals.into_iter().filter(|id|!visited.contains(id)));
        }
        Ok(false)
    }
    if graph.iter().map(|e|e.id.as_str()).collect::<BTreeSet<_>>().len()!=graph.len() {return Err(query_failure("duplicate reduction graph identity"));}
    if !metaclass_conforms(&owner.kind,"Type") {return Err(query_failure("implicit reduction requires a Type owner"));}
    let mut seen=BTreeSet::new();
    let mut chains=BTreeSet::new();
    for &(kind,id) in pending {
        if implicit_reduction_generated::rank(kind).is_none() {return Err(query_failure("unassessed implicit reduction category"));}
        if id==owner.id || !seen.insert((kind,id)) {return Err(query_failure("reduction requires normalized nonself pending contributions"));}
        let general=graph.iter().find(|e|e.id==id).ok_or_else(||query_failure("missing reduction general"))?;
        if metaclass_conforms(&general.kind,"Feature") {
            let index=graph.iter().map(|e|(e.id.as_str(),e)).collect();
            let chain=definition_chain_reference_targets_typed_query(&DefinitionNameQuery::new(graph,&index),general,"chaining_feature")?.iter().map(|e|e.id.clone()).collect::<Vec<_>>();
            if !chain.is_empty() && !chains.insert((kind,chain)) {return Err(query_failure("reduction requires deduplicated pending chains"));}
        }
        for (field,endpoint) in [("specific",owner),("general",general)] {
            let contract=ecore_model::redefined_feature(kind,field).map_err(query_failure)?;
            ecore_model::validate_reference_endpoint(kind,contract.field,&endpoint.kind).map_err(query_failure)?;
        }
    }
    let mut explicit=Vec::new();let mut redefined=BTreeSet::new();
    for relation in stored_children(graph,owner,"owned_relationship")? {
        if !metaclass_conforms(&relation.kind,"Specialization") {continue;}
        if query_reference(graph,relation,"specific")?.id!=owner.id {continue;}
        let general=query_reference(graph,relation,"general")?;
        if general.id==owner.id {continue;}
        explicit.push(general.id.as_str());
        if metaclass_conforms(&relation.kind,"Redefinition") {redefined.insert(general.id.as_str());}
    }
    let mut result=Vec::new();
    for &(kind,general) in pending {
        let mut redundant=false;
        if kind=="Redefinition" {redundant=redefined.contains(general);}
        else {
            for candidate in explicit.iter().copied().chain(pending.iter().map(|(_,id)|*id).filter(|id|*id!=general)) {
                if specializes_excluding(graph,candidate,general,&owner.id)? {redundant=true;break;}
            }
        }
        if !redundant {result.push((kind.to_owned(),general.to_owned()));}
    }
    // A removal must remain justified after the whole snapshot is reduced.
    // Pilot drops all members of some mutually-specializing pending cycles;
    // reject that unqualified loss instead of silently deleting constraints.
    for &(kind,general) in pending {
        if result.iter().any(|(k,g)|k==kind && g==general) {continue;}
        let mut covered=false;
        for candidate in explicit.iter().copied().chain(result.iter().map(|(_,id)|id.as_str())) {
            if specializes_excluding(graph,candidate,general,&owner.id)? {covered=true;break;}
        }
        if !covered {return Err(query_failure("implicit reduction would discard a cyclic specialization constraint"));}
    }
    result.sort_by_key(|(kind,_)|implicit_reduction_generated::rank(kind).unwrap());
    Ok(result)
}

/// Reduce and atomically insert already-selected, normalized contributions.
/// No semantic producer or transformation-completeness flag is fabricated here.
pub(crate) fn definition_materialize_selected_generals(elements: &mut Vec<KirElement>, owner_id: &str,
    prefix: &str, pending: &[(&str,&str)]) -> Result<usize, Diagnostic> {
    definition_materialize_general_batch(elements, &[(owner_id, prefix, pending)])
}

/// Plan every owner against the same immutable graph before inserting anything.
/// This is a transaction for selected contributions, not a contribution producer.
pub(crate) fn definition_materialize_general_batch(elements: &mut Vec<KirElement>,
    batches: &[(&str, &str, &[(&str, &str)])]) -> Result<usize, Diagnostic> {
    definition_materialize_general_batch_query(elements,batches,ecore_model::ReferenceCompleteness::Closed)
        .map_err(|failure| failure.into_diagnostic_at("definition_materialize_general_batch external boundary"))
}

fn definition_materialize_general_batch_query(elements: &mut Vec<KirElement>,
    batches: &[(&str, &str, &[(&str, &str)])], boundary: ecore_model::ReferenceCompleteness) -> Result<usize, QueryFailure> {
    if let Some(issue)=ecore_model::validate_publication(elements,boundary).first() {
        return Err(query_failure(format!("invalid implicit insertion input: {}",issue.message)));
    }
    let mut owners=BTreeSet::new();
    let mut plan=Vec::new();
    for &(owner_id,prefix,pending) in batches {
        if prefix.is_empty() {return Err(query_failure("implicit insertion requires a nonempty identity prefix"));}
        if !owners.insert(owner_id) {return Err(query_failure("implicit batch requires one normalized snapshot per owner"));}
        let owner=elements.iter().find(|e|e.id==owner_id).ok_or_else(||query_failure("missing implicit insertion owner"))?;
        let selected=definition_reduce_implicit_generals_query(elements,owner,pending)?;
        for (i,(kind,general)) in selected.into_iter().enumerate() {
            plan.push((owner_id,format!("{prefix}.{i}"),kind,general));
        }
    }
    // Read-only replay does not invalidate persisted derived snapshots.
    // Preserve the insertion guard for every batch that actually writes.
    if plan.is_empty() { return Ok(0); }
    definition_check_specialization_storage(elements)?;
    let mut staged=elements.clone();
    for (owner,id,kind,general) in &plan {
        definition_append_implied_specialization_in_stage(&mut staged,id,kind,owner,general)?;
    }
    if let Some(issue)=ecore_model::validate_publication(&staged,boundary).first() {
        return Err(query_failure(format!("invalid implicit insertion output: {}",issue.message)));
    }
    *elements=staged;
    Ok(plan.len())
}

// Admission for one assessed partial default-contribution category. Canonical
// source/general endpoints and empty relationship ownership remain required;
// recognizing a default does not imply other transformation stages completed.
fn definition_assessed_type_default_relation(graph: &[KirElement], owner: &KirElement,
    relation: &KirElement, kind: &str, targets: &[String]) -> Result<bool, Diagnostic> {
    let index = graph.iter().map(|e| (e.id.as_str(), e)).collect::<BTreeMap<_, _>>();
    definition_assessed_type_default_relation_in_view(&DefinitionNameQuery::new(graph, &index), owner, relation, kind, targets)
}

fn definition_assessed_type_default_relation_in_view(query: &DefinitionNameQuery<'_, '_>, owner: &KirElement,
    relation: &KirElement, kind: &str, targets: &[String]) -> Result<bool, Diagnostic> {
    definition_assessed_type_default_relation_typed_in_view(query,owner,relation,kind,targets)
        .map_err(|failure|failure.into_diagnostic_at("definition_assessed_type_default_relation external boundary"))
}

fn definition_assessed_type_default_relation_typed_in_view(query: &DefinitionNameQuery<'_, '_>, owner: &KirElement,
    relation: &KirElement, kind: &str, targets: &[String]) -> Result<bool, QueryFailure> {
    if relation.kind.rsplit("::").next() != Some(kind)
        || !stored_children_projection_query(query, relation, "owned_related_element")?.is_empty() {
        return Ok(false);
    }
    let specific = query_reference_in_view(query, relation, "specific")?;
    let general = query_reference_in_view(query, relation, "general")?;
    Ok(specific.id == owner.id && general.id != owner.id && targets.contains(&general.id))

}

/// Exact assessed selector domain, not a whole-transformation capability claim.
pub(crate) fn definition_type_default_contribution_owners(elements: &[KirElement]) -> Vec<String> {
    elements.iter().filter(|owner| {
        let kind = owner.kind.rsplit("::").next().unwrap_or(&owner.kind);
        default_generals_generated::DEFAULT_GENERALS.iter().any(|(candidate, _, _)| *candidate == kind)
            || definition_defaults_generated::inputs(kind).is_some()
    }).map(|owner| owner.id.clone()).collect()
}

/// Select and reduce generated plain-Type/Definition defaults for every requested
/// owner before inserting any relationship. Replays reuse assessed stored
/// contributions; no completion or semantic-validation flag is written.
pub(crate) fn definition_materialize_type_defaults(elements: &mut Vec<KirElement>,
    owners: &[(&str, &str)]) -> Result<usize, Diagnostic> {
    let mut selected = Vec::new();
    for &(id, prefix) in owners {
        let owner = elements.iter().find(|e| e.id == id).ok_or_else(|| error("type default owner is absent"))?;
        if scope_boolean(owner, "is_implied_included")? {
            return Err(error("type default contribution selection requires incomplete inputs"));
        }
        let kind = owner.kind.rsplit("::").next().unwrap_or(&owner.kind);
        let (relationship_kind, names) = if let Some((_, name, relation)) =
            default_generals_generated::DEFAULT_GENERALS.iter().find(|(candidate, _, _)| *candidate == kind) {
            (*relation, vec![*name])
        } else if definition_defaults_generated::inputs(kind).is_some() {
            ("Subclassification", definition_default_names(elements, owner)?)
        } else { return Err(error("type default contribution adapter is unassessed")); };
        let library = standard_default_bindings(elements, &names.iter().copied().collect())?;
        // Existing providers validate structural inputs, semantic metadata,
        // conjugation and any previously stored partial default contributions.
        if definition_defaults_generated::inputs(kind).is_some() {
            stored_definition_generalizations(elements, owner, &library)?;
        } else { stored_plain_type_generalizations(elements, owner, &library)?; }
        let mut seen = BTreeSet::new();
        let mut contributions = Vec::new();
        for name in names {
            let target = library.get(name).ok_or_else(|| error("resolved default binding is absent"))?;
            if target != &owner.id && seen.insert(target.clone()) {
                contributions.push((relationship_kind, target.clone()));
            }
        }
        selected.push((id, prefix, contributions));
    }
    let entries = selected.iter().map(|(_, _, items)| items.iter()
        .map(|(kind,id)| (*kind,id.as_str())).collect::<Vec<_>>()).collect::<Vec<_>>();
    let batches = selected.iter().zip(&entries).map(|((id,prefix,_),items)|
        (*id,*prefix,items.as_slice())).collect::<Vec<_>>();
    definition_materialize_general_batch(elements, &batches)
}

/// Exact generated default-selector domain; context guards still apply.
pub(crate) fn definition_feature_default_contribution_owners(elements: &[KirElement]) -> Vec<String> {
    elements.iter().filter(|owner| {
        let kind = owner.kind.rsplit("::").next().unwrap_or(&owner.kind);
        kind == "Feature" || multiplicity_defaults_generated::supports(kind) || step_defaults_generated::supports(kind) || connector_defaults_generated::supports(kind)
            || feature_defaults_generated::ordinary_usage_binding(kind) || occurrence_strategy_supports(kind)
    }).map(|owner| owner.id.clone()).collect()
}

/// Select bounded Feature-family default/participant/positional contributions
/// from imported providers, then commit the whole batch against one snapshot.
/// This does not execute valuation, featuring, or complete Feature transformation.
pub(crate) fn definition_materialize_feature_defaults(elements: &mut Vec<KirElement>,
    owners: &[(&str, &str)]) -> Result<usize, Diagnostic> {
    definition_materialize_feature_defaults_query(elements,owners,ecore_model::ReferenceCompleteness::Closed)
        .map_err(|failure| failure.into_diagnostic_at("definition_materialize_feature_defaults external boundary"))
}

fn definition_materialize_feature_defaults_query(elements: &mut Vec<KirElement>,
    owners: &[(&str, &str)], boundary: ecore_model::ReferenceCompleteness) -> Result<usize, QueryFailure> {
    let mut selected=Vec::new();
    for &(id,prefix) in owners {
        let owner=elements.iter().find(|e|e.id==id).ok_or_else(||query_failure("missing default contribution owner"))?;
        if scope_boolean(owner,"is_implied_included")? {return Err(query_failure("default contribution selection requires incomplete inputs"));}
        let kind=owner.kind.rsplit("::").next().unwrap_or(&owner.kind);
        if occurrence_strategy_supports(kind) {
            selected.push((id,prefix,occurrence_strategy_contributions(elements,owner)?));continue;
        }
        let name=if connector_defaults_generated::supports(kind) {definition_connector_default_name_typed_query(elements,owner)}
            else if feature_defaults_generated::ordinary_usage_binding(kind) {definition_usage_default_name_typed_query(elements,owner)}
            else if multiplicity_defaults_generated::supports(kind) {definition_multiplicity_default_name(elements,owner).map_err(QueryFailure::from)}
            else if step_defaults_generated::supports(kind) {definition_step_default_name_typed_query(elements,owner)}
            else {definition_feature_default_name_typed_query(elements,owner)}
            ?;
        let index=elements.iter().map(|e|(e.id.as_str(),e)).collect();
        let general=query_local_binding(standard_default_binding_query(&DefinitionNameQuery::new(elements,&index),name)?)?;
        let contributions=definition_implicit_feature_generals_typed_query(elements,owner,&general)?;
        // The same target can be selected by both the default and participant
        // producers. Keep the first occurrence in the fixed pending snapshot.
        let mut seen=BTreeSet::new();
        let contributions=contributions.into_iter().filter(|(kind,id)|seen.insert((*kind,id.clone()))).collect::<Vec<_>>();
        selected.push((id,prefix,contributions));
    }
    let entries=selected.iter().map(|(_,_,items)|items.iter().map(|(kind,id)|(*kind,id.as_str())).collect::<Vec<_>>()).collect::<Vec<_>>();
    let batch=selected.iter().zip(&entries).map(|((id,prefix,_),items)|(*id,*prefix,items.as_slice())).collect::<Vec<_>>();
    definition_materialize_general_batch_query(elements,&batch,boundary)
}

// Shared result-Feature strategy. The imported Feature selector reads owned
// typing, while the existing positional query supplies computed redefinitions.
// Context admission is handwritten and does not imply expression completion.
#[path = "feature_value_validation.rs"]
mod feature_value_validation;
pub(crate) use feature_value_validation::assess as definition_assess_feature_values;

#[path = "result_multiplicity.rs"]
mod result_multiplicity;
#[path = "result_multiplicity_generated.rs"]
mod result_multiplicity_generated;
#[path = "usage_variability_generated.rs"]
mod usage_variability_generated;
#[path = "reference_result_scope.rs"]
mod reference_result_scope;
#[path="general_value_provider.rs"]
mod general_value_provider;
#[path="literal_value_binding.rs"]
mod literal_value_binding;
pub(crate) use literal_value_binding::definition_complete_literal_value_bindings;

#[path="cold_literal_values.rs"]
mod cold_literal_values;
pub(crate) use cold_literal_values::definition_complete_literal_value_expressions;

// A directed parameter's valuation is irrelevant to default/general selection:
// the written checkFeatureValuationSpecialization requires direction = null.
// The resolved selector reads owned typing/flags, not the expression body.
// Preserve canonical value storage without asserting expression transformation,
// initial-value validity, binding construction or model completion.
fn definition_directed_valuation_input_in_view(query: &DefinitionNameQuery<'_, '_>, owner: &KirElement, relation: &KirElement) -> Result<bool, QueryFailure> {
    if !metaclass_conforms(&relation.kind, "FeatureValue") { return Ok(false); }
    if !definition_has_direction(owner)? { return Err(query_failure("valuation selection requires a directed Feature")); }
    let valuations = stored_children_projection_query(query, owner, "owned_relationship")?.into_iter()
        .filter(|r| metaclass_conforms(&r.kind, "FeatureValue")).collect::<Vec<_>>();
    if valuations.len() != 1 { return Err(query_failure("directed Feature has multiple valuations; single-valuation requirement is violated")); }
    if relation.properties.get("owning_related_element").and_then(Value::as_str) != Some(owner.id.as_str())
        || scope_boolean(relation, "is_implied")? {
        return Err(query_failure("directed valuation requires explicit canonical Feature ownership"));
    }
    // Read both flags through imported Boolean contracts even though neither
    // changes this selector. Invalid flags cannot become ignored model data.
    scope_boolean(relation, "is_default")?;
    scope_boolean(relation, "is_initial")?;
    let expressions = stored_children_projection_query(query, relation, "owned_related_element")?.into_iter()
        .filter(|e| metaclass_conforms(&e.kind, "Expression")).collect::<Vec<_>>();
    let selected = definition_reference_targets_typed_query(query, relation, "value")?;
    if expressions.len() != 1 || selected.len() != 1 || expressions[0].id != selected[0].id {
        return Err(query_failure("directed valuation requires exactly one canonical Expression"));
    }
    Ok(true)

}

fn definition_validate_result_feature_inputs(graph: &[KirElement], result: &KirElement)
    -> Result<String, Diagnostic> {
    let index = graph.iter().map(|e| (e.id.as_str(), e)).collect::<BTreeMap<_, _>>();
    definition_validate_result_feature_inputs_query(&DefinitionNameQuery::new(graph, &index), result)
        .map_err(|failure| failure.into_diagnostic_at("definition_result_feature_inputs external boundary"))
}

fn definition_validate_result_feature_inputs_query(query: &DefinitionNameQuery<'_, '_>, result: &KirElement)
    -> Result<String, QueryFailure> {
    let graph = query.graph;
    let (member,owner)=definition_feature_owner_indexed(query.graph.len(),query.index,result)?.ok_or_else(||error("result defaults require canonical ownership"))?;
    if result.kind.rsplit("::").next()!=Some("Feature") || !metaclass_conforms(&member.kind,"ReturnParameterMembership")
        || !(matches!(owner.kind.rsplit("::").next(),Some("Expression"|"FeatureReferenceExpression"|"Function"|"Predicate"))
            || result_construction_generated::supported(owner.kind.rsplit("::").next().unwrap_or(&owner.kind))
            || feature_chain_members::supports(&owner.kind))
        || result.properties.get("direction")!=Some(&json!("out"))
        || scope_boolean(result,"is_end")? || scope_boolean(result,"is_variable")?
        || scope_boolean(result,"is_composite")? || scope_boolean(result,"is_portion")? {
        return Err(query_failure("result defaults require fixed noncomposite out Feature under an assessed Function/Predicate/Expression"));
    }
    definition_projection::require_empty_metadata_bases(graph, result)?;
    let positional=definition_positional_parameters_query(query,result,owner)?;
    let mut structure=false;let mut class=false;let mut data=false;
    let relationships=stored_children(graph,result,"owned_relationship")?;
    for (ordinal,relation) in relationships.iter().enumerate() {
        if metaclass_conforms(&relation.kind,"FeatureTyping") && !scope_boolean(relation,"is_implied")? {
            let target=query_reference_in_view(query,relation,"type")?;
            structure|=metaclass_conforms(&target.kind,"Structure");class|=metaclass_conforms(&target.kind,"Class");data|=metaclass_conforms(&target.kind,"DataType");
        } else if result_multiplicity::is_owned_context(graph,result,relation)? {
            // The selector reads owned typing. This separately verified owned
            // multiplicity does not assert bound evaluation or model validity.
        } else if general_value_binding::contribution(query,result,relation)?
            || literal_value_binding::binding_contribution_query(graph, result, relation)? {
            // Canonical non-typing containment of the completed literal's value
            // binding. This does not claim result/owner lifecycle completion.
        } else if definition_directed_valuation_input_in_view(query, result, relation)? {
            // This is a default-query dependency boundary, not a value producer.
        } else if !metaclass_conforms(&relation.kind,"Subsetting") && !metaclass_conforms(&relation.kind,"TypeFeaturing") {
            return Err(QueryFailure::Rejected(error(format!("result defaults require separate nested/crossing/typing dependencies; service=result-feature-defaults owner_id={} owner_kind={} field=owned_relationship ordinal={} relationship_id={} relationship_kind={}", result.id, result.kind, ordinal, relation.id, relation.kind))
                .with_subject(result.id.clone()).with_subject(relation.id.clone())));
        }
        if metaclass_conforms(&relation.kind,"CrossSubsetting") {return Err(query_failure("result crossing is unassessed"));}
    }
    let name=feature_defaults_generated::feature_default_name(structure,class,data,false,false,false);
    let default=query_local_binding(standard_default_binding_query(query,name)?)?;
    for relation in &relationships {
        if !scope_boolean(relation,"is_implied")? || metaclass_conforms(&relation.kind,"TypeFeaturing") {continue;}
        let target=query_reference_in_view(query,relation,"general")?;
        let known=if relation.kind.rsplit("::").next()==Some("Redefinition") {positional.iter().any(|e|e.id==target.id)}
            else if relation.kind.rsplit("::").next()==Some("Subsetting") {
                target.id==default || (owner.kind.rsplit("::").next()==Some("FeatureReferenceExpression")
                    && definition_explicit_expression_referent_in_view(query,owner)?.is_some_and(|e|e.id==target.id)) || chain_specialization::assessed_relation(query,result,relation)?.unwrap_or(false)
                    || argument_result_specialization::assessed_relation(query,result,relation)?.unwrap_or(false)
            } else {false};
        if !known {return Err(query_failure("unassessed partial result specialization"));}
    }
    Ok(default)
}

fn definition_result_feature_generals(graph: &[KirElement], result: &KirElement)
    -> Result<Vec<(&'static str,String)>, Diagnostic> {
    let index = graph.iter().map(|e| (e.id.as_str(), e)).collect::<BTreeMap<_, _>>();
    definition_result_feature_generals_query(&DefinitionNameQuery::new(graph, &index), result)
        .map_err(|failure| failure.into_diagnostic_at("definition_result_feature_generals external boundary"))
}

fn definition_result_feature_generals_query(query: &DefinitionNameQuery<'_, '_>, result: &KirElement)
    -> Result<Vec<(&'static str,String)>, QueryFailure> {
    let default=definition_validate_result_feature_inputs_query(query,result)?;
    let mut selected=definition_redefined_features_typed_query(query,result,false)?.iter().map(|e|("Redefinition",e.id.clone())).collect::<Vec<_>>();
    if default!=result.id {selected.push(("Subsetting",default));}
    let mut seen=BTreeSet::new();selected.retain(|item|seen.insert(item.clone()));Ok(selected)
}

/// Atomic default and positional-redefinition contributions for admitted results.
/// Other expression/result producers remain separate; no completeness flags change.
pub(crate) fn definition_materialize_result_feature_defaults(elements: &mut Vec<KirElement>,
    result_id: &str, prefix: &str) -> Result<usize, Diagnostic> {
    if let Some(issue)=ecore_model::validate_publication(elements,ecore_model::ReferenceCompleteness::Closed).first() {
        return Err(error(format!("invalid result default input: {}",issue.message)));
    }
    let result=elements.iter().find(|e|e.id==result_id).ok_or_else(||error("missing result default owner"))?;
    if scope_boolean(result,"is_implied_included")? {return Err(error("result defaults require incomplete input"));}
    let selected=definition_result_feature_generals(elements,result)?;
    let inputs=selected.iter().map(|(kind,id)|(*kind,id.as_str())).collect::<Vec<_>>();
    definition_materialize_selected_generals(elements,result_id,prefix,&inputs)
}

/// Bound-value contribution selection is separate from expression transformation.
/// Only the agreed single, non-default valuation branch is admitted. The written
/// rule covers all valuations and permits existing implied specializations; Pilot
/// selects the first and suppresses on any specialization. Disputed branches
/// reject pending normative assessment. Expression completion is a precondition.
pub(crate) fn definition_materialize_bound_value_subsetting(elements: &mut Vec<KirElement>,
    owner_id: &str, chain_id: &str, relation_id: &str) -> Result<bool, Diagnostic> {
    if let Some(issue)=ecore_model::validate_publication(elements,ecore_model::ReferenceCompleteness::Closed).first() {
        return Err(error(format!("invalid bound-value input: {}",issue.message)));
    }
    let owner=elements.iter().find(|e|e.id==owner_id).ok_or_else(||error("missing bound-value Feature"))?;
    if owner.kind.rsplit("::").next()!=Some("Feature") || scope_boolean(owner,"is_implied_included")? {
        return Err(error("bound-value contribution requires an incomplete exact Feature"));
    }
    let relationships=stored_children(elements,owner,"owned_relationship")?;
    let values=relationships.iter().filter(|r|metaclass_conforms(&r.kind,"FeatureValue")).collect::<Vec<_>>();
    let Some(value)=values.first() else {return Ok(false);};
    if values.len()!=1 || scope_boolean(value,"is_default")? {
        return Err(error("default/multiple valuations require normative all-valuation assessment"));
    }
    let expressions=stored_children(elements,value,"owned_related_element")?;
    if expressions.is_empty() {return Err(error("bound valuation is missing its required expression"));}
    let expression=definition_reference_targets(elements,value,"value")?.first().copied()
        .ok_or_else(||error("bound value requires a resolved expression"))?;
    if !scope_boolean(expression,"is_implied_included")? {
        return Err(error("bound-value expression transformation must be completed separately"));
    }
    let result=definition_result_parameter(elements,expression)?.ok_or_else(||error("bound valuation requires a resolved expression result"))?;
    for relation in &relationships {
        if metaclass_conforms(&relation.kind,"Specialization") && scope_boolean(relation,"is_implied")? {
            return Err(error("existing implied specialization requires normative valuation composition assessment"));
        }
    }
    if relationships.iter().any(|r|metaclass_conforms(&r.kind,"Specialization"))
        || owner.properties.get("direction").is_some_and(|v|!v.is_null()) {return Ok(false);}
    let inputs=[expression.id.clone(),result.id.clone()];
    let mut staged=elements.clone();
    definition_append_feature_chain(&mut staged,chain_id,&[inputs[0].as_str(),inputs[1].as_str()])?;
    definition_append_implied_specialization(&mut staged,relation_id,"Subsetting",owner_id,chain_id)?;
    *elements=staged;
    Ok(true)
}

/// Written checkFeatureValuationSpecialization (KerML PDF page 196).
/// This handwritten predicate consumes imported ownership, result and Type
/// queries. Unlike Pilot's producer it checks every valuation, including defaults.
/// An unavailable semantic query is an error, never a successful assessment.
pub(crate) fn definition_assess_valuation_specialization(elements: &[KirElement])
    -> Result<Vec<(String, String, String)>, Diagnostic> {
    if let Some(issue)=ecore_model::validate_publication(elements,ecore_model::ReferenceCompleteness::Closed).first() {
        return Err(error(format!("invalid valuation assessment input: {}",issue.message)));
    }
    let mut issues=Vec::new();
    for owner in elements.iter().filter(|e|metaclass_conforms(&e.kind,"Feature")) {
        if owner.properties.get("direction").is_some_and(|v|!v.is_null()) {continue;}
        let relationships=stored_children(elements,owner,"owned_relationship")?;
        let mut explicit=false;
        for relation in &relationships {
            if metaclass_conforms(&relation.kind,"Specialization")
                && redefined_reference(elements,relation,"specific")?.id==owner.id
                && !scope_boolean(relation,"is_implied")? {explicit=true;break;}
        }
        if explicit {continue;}
        for value in relationships.iter().filter(|r|metaclass_conforms(&r.kind,"FeatureValue")) {
            let expressions=definition_reference_targets(elements,value,"value")?;
            if expressions.len()!=1 {return Err(error("valuation assessment requires exactly one value expression"));}
            let result=definition_result_parameter(elements,expressions[0])?
                .ok_or_else(||error("valuation assessment requires a resolved expression result"))?;
            if !definition_specializes(elements,owner,result)? {
                issues.push((owner.id.clone(),value.id.clone(),result.id.clone()));
            }
        }
    }
    Ok(issues)
}

/// Physical insertion of one already-selected implicit contribution. Selection,
/// pending-chain deduplication and redundant-general removal are separate services.
pub(crate) fn definition_append_implied_specialization(elements: &mut Vec<KirElement>, id: &str,
    kind: &str, specific_id: &str, general_id: &str) -> Result<(), Diagnostic>
{
    definition_append_implied_specialization_with_boundary(elements,id,kind,specific_id,general_id,ecore_model::ReferenceCompleteness::Closed)
}

fn definition_check_specialization_storage(elements: &[KirElement]) -> Result<(), Diagnostic> {
    for element in elements.iter() {
        for field in element.properties.keys() {
            if ecore_model::feature(&element.kind, field).is_some_and(|c| c.derived || c.volatile) {
                return Err(error(format!("specialization insertion requires derived-value recomputation: {} ({}).{}", element.id, element.kind, field)));
            }
        }
    }
    Ok(())
}

fn definition_append_implied_specialization_with_boundary(elements: &mut Vec<KirElement>, id: &str,
    kind: &str, specific_id: &str, general_id: &str, boundary: ecore_model::ReferenceCompleteness) -> Result<(), Diagnostic>
{
    if let Some(issue) = ecore_model::validate_publication(elements, boundary).first() {
        return Err(error(format!("invalid specialization input: {}", issue.message)));
    }
    definition_check_specialization_storage(elements)?;
    let mut staged=elements.clone();
    definition_append_implied_specialization_in_stage(&mut staged,id,kind,specific_id,general_id)?;
    if let Some(issue)=ecore_model::validate_publication(&staged,boundary).first() {
        return Err(error(format!("invalid specialization output: {}",issue.message)));
    }
    *elements=staged;Ok(())
}

// Private worker. Callers must validate their whole input and discard the entire
// stage on any error, including final publication/adoption-cycle failure.
fn definition_append_implied_specialization_in_stage(elements: &mut Vec<KirElement>, id: &str,
    kind: &str, specific_id: &str, general_id: &str) -> Result<(), Diagnostic> {
    if !specialization_construction_generated::supported(kind) { return Err(error("unassessed specialization construction kind")); }
    if id.is_empty() || elements.iter().any(|e| e.id == id) { return Err(error("specialization identity must be fresh and nonempty")); }
    if specific_id == general_id { return Err(error("self-specialization is not a pending implicit contribution")); }
    let mut relation = fresh_definition_element(id.into(), kind)?;
    for (field, target) in [("specific", specific_id), ("general", general_id)] {
        let endpoint = elements.iter().find(|e| e.id == target).ok_or_else(|| error("missing specialization endpoint"))?;
        let contract = ecore_model::redefined_feature(&relation.kind, field).map_err(error)?;
        ecore_model::validate_reference_endpoint(&relation.kind, contract.field, &endpoint.kind).map_err(error)?;
        if contract.derived {
            if field != "specific" || !matches!(contract.field, "referencing_feature" | "crossing_feature") {
                return Err(error("specialization endpoint requires an unassessed derived setter"));
            }
            // These setters establish owning containment; the matching delegate
            // reads it after attachment. Do not store a derived alias snapshot.
        } else {
            relation.properties.insert(contract.field.into(), json!(target));
        }
    }
    relation.properties.insert("is_implied".into(), json!(true));
    let general = elements.iter_mut().find(|e| e.id == general_id).ok_or_else(|| error("missing staged general"))?;
    // Unlike connector construction, an unowned membership still counts as
    // an owning relationship here. Match the resolved TypeUtil null test.
    if general.properties.get("owning_relationship").is_none_or(Value::is_null) {
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS, &mut relation, general)?;
    }
    let specific = elements.iter_mut().find(|e| e.id == specific_id).ok_or_else(|| error("missing staged specific"))?;
    ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, specific, &mut relation)?;
    elements.push(relation);
    Ok(())
}

/// Reference binding selection from canonical imported membership/result views.
/// Handwritten checkFeatureReferenceExpressionBindingConnector dependency;
/// shared construction and context selection provide canonical placement.
/// Defaults, self-reference fallback and lifecycle completion remain separate.
fn definition_reference_binding_endpoints(elements: &[KirElement], expression_id: &str) -> Result<(String,String), Diagnostic> {
    let expression=elements.iter().find(|e|e.id==expression_id).ok_or_else(||error("missing reference expression"))?;
    if expression.kind.rsplit("::").next()!=Some(specialization_construction_generated::RESULT_PROVIDER)
        || scope_boolean(expression,"is_implied_included")? {
        return Err(error("reference binding requires an incomplete FeatureReferenceExpression"));
    }
    let referent=definition_explicit_expression_referent(elements,expression)?
        .filter(|e|metaclass_conforms(&e.kind,"Feature"))
        .ok_or_else(||error("reference binding requires an explicit Feature referent; self-reference fallback remains unassessed"))?.id.clone();
    let result=definition_result_parameter(elements,expression)?
        .ok_or_else(||error("reference result must be constructed before binding"))?.id.clone();
    Ok((referent,result))
}

pub(crate) fn definition_materialize_reference_binding(elements: &mut Vec<KirElement>,
    expression_id: &str, identity: &str) -> Result<(), Diagnostic> {
    let (referent,result)=definition_reference_binding_endpoints(elements,expression_id)?;
    definition_materialize_binding_structure(elements,expression_id,identity,&referent,&result)
}

/// Reference binding plus connector/end defaults and featuring; no completion flags.
pub(crate) fn definition_materialize_reference_binding_defaults(elements: &mut Vec<KirElement>,
    expression_id: &str, identity: &str) -> Result<(), Diagnostic> {
    let (referent,result)=definition_reference_binding_endpoints(elements,expression_id)?;
    definition_materialize_binding_defaults(elements,expression_id,identity,&referent,&result)
}

/// Bounded FeatureReferenceExpressionAdapter.addResultSubsetting producer.
/// It requires result construction first. Self-reference defaults, result binding,
/// full transformation and redundant-specialization removal remain separate.
pub(crate) fn definition_materialize_reference_result_subsetting(elements: &mut Vec<KirElement>, expression_id: &str, relation_id: &str)
    -> Result<bool, Diagnostic>
{
    if let Some(issue) = ecore_model::validate_publication(elements, ecore_model::ReferenceCompleteness::Closed).first() {
        return Err(error(format!("invalid result specialization input: {}", issue.message)));
    }
    let expression = elements.iter().find(|e| e.id == expression_id).ok_or_else(|| error("missing reference expression"))?;
    if expression.kind.rsplit("::").next() != Some(specialization_construction_generated::RESULT_PROVIDER) {
        return Err(error("result subsetting requires resolved FeatureReferenceExpression dispatch"));
    }
    let result = definition_result_parameter(elements, expression)?.ok_or_else(|| error("reference result must be constructed before specialization"))?;
    let result_id = result.id.clone();
    let referent = definition_explicit_expression_referent(elements, expression)?;
    let Some(referent) = referent.filter(|e| metaclass_conforms(&e.kind, "Feature")) else { return Ok(false); };
    let general_id = referent.id.clone();
    if result_id == general_id { return Ok(false); }
    definition_append_implied_specialization(elements, relation_id, specialization_construction_generated::RESULT_KIND, &result_id, &general_id)?;
    Ok(true)
}

// Shared resolved ExpressionUtil.getReferentFor semantics. The first nonparameter
// membership wins even when its target is not a Feature; later targets cannot
// turn an explicitly non-Feature referent into a Feature.
fn definition_explicit_expression_referent<'g>(graph: &'g [KirElement], expression: &'g KirElement)
    -> Result<Option<&'g KirElement>, Diagnostic> {
    let index=graph.iter().map(|e|(e.id.as_str(),e)).collect::<BTreeMap<_,_>>();
    definition_explicit_expression_referent_in_view(&DefinitionNameQuery::new(graph,&index),expression).map_err(|failure|failure.into_diagnostic_at("definition_explicit_expression_referent external boundary"))
}

fn definition_explicit_expression_referent_in_view<'g>(query: &DefinitionNameQuery<'g, '_>, expression: &'g KirElement) -> Result<Option<&'g KirElement>, QueryFailure> {
    for member in stored_children_projection_query(query, expression, "owned_relationship")? {
        if !metaclass_conforms(&member.kind,"Membership") || metaclass_conforms(&member.kind,"ParameterMembership") {continue;}
        if let Some(target)=definition_reference_targets_typed_query(query,member,"member_element")?.first().copied() {return Ok(Some(target));}
    }
    Ok(None)

}

#[path = "featuring_queries_generated.rs"]
mod featuring_queries_generated;
#[path = "no_owning_type_featuring_generated.rs"]
mod no_owning_type_featuring_generated;
#[path = "transition_context_stage.rs"]
mod transition_context_stage;

/// Handwritten resolved featuring delegate. Complete stored inputs or the fixed
/// fixed owning-type provider supply implicit contributions; unresolved providers reject.
fn definition_featuring_types<'g>(graph: &'g [KirElement], owner: &'g KirElement) -> Result<Vec<&'g KirElement>, Diagnostic> {
    definition_featuring_types_typed_query(graph, owner).map_err(|failure| failure.into_diagnostic_at("definition_featuring_types"))
}

// Named handwritten no-owning-Type branch of the resolved common producer.
// Package/plain-Namespace/detached ownership proves inherited owning-namespace and crossing
// contributions inapplicable. Specialized Connector/Expression dispatch is
// excluded by the imported producer inventory, not treated as empty state.
#[cfg(test)]
fn definition_no_owning_type_featuring_is_empty(graph:&[KirElement], feature:&KirElement) -> Result<bool,QueryFailure> {
    let index=graph.iter().map(|e|(e.id.as_str(),e)).collect::<BTreeMap<_,_>>();
    definition_no_owning_type_featuring_is_empty_in_view(&DefinitionNameQuery::new(graph,&index),feature)
}

fn definition_no_owning_type_featuring_is_empty_in_view(query: &DefinitionNameQuery<'_, '_>, feature: &KirElement) -> Result<bool, QueryFailure> {
    if !no_owning_type_featuring_generated::supports(feature.kind.rsplit("::").next().unwrap_or(&feature.kind)) {return Ok(false);}
    let index=query.index;
    if index.len()!=query.graph.len() {return Err(query_failure("duplicate no-owning-Type featuring identity"));}
    if canonical_chain_lifecycle::adopted(query,feature)? {return Ok(true);}
    let Some(member)=scope_container_query(query,feature)? else {return Ok(true);};
    if !matches!(member.kind.rsplit("::").next(),Some("OwningMembership"|"FeatureMembership")) {return Ok(false);}
    let StoredMembershipEndpoint::Resolved(endpoint)=stored_membership_endpoint_indexed(query.graph.len(),index,member,"member_element")? else {return Err(query_failure("no-owning-Type featuring requires canonical membership endpoint"));};
    if endpoint.id!=feature.id {return Err(query_failure("no-owning-Type featuring endpoint disagrees with ownership"));}
    let namespace=scope_container_query(query,member)?.ok_or_else(||query_failure("no-owning-Type featuring membership has no namespace"))?;
    // The imported Multiplicity selector also admits Feature/Classifier
    // ownership through ordinary OwningMembership. That containment supplies
    // no owning Type. Implicit featuring construction remains a separate stage.
    // Other binding/context algorithms retain their existing admission guards.
    Ok(metaclass_conforms(&namespace.kind,"Package")
        || namespace.kind.rsplit("::").next()==Some("Namespace")
        || (multiplicity_defaults_generated::supports(
            feature.kind.rsplit("::").next().unwrap_or(&feature.kind))
            && metaclass_conforms(&namespace.kind,"Namespace")))

}

fn definition_featuring_types_typed_query<'g>(graph: &'g [KirElement], owner: &'g KirElement) -> Result<Vec<&'g KirElement>, QueryFailure> {
    let index = graph.iter().map(|e| (e.id.as_str(), e)).collect::<BTreeMap<_, _>>();
    if index.len() != graph.len() { return Err(query_failure("duplicate featuring-query identity")); }
    definition_featuring_types_in_view(&DefinitionNameQuery::new(graph, &index), owner)
}

fn definition_featuring_types_in_view<'g>(query: &DefinitionNameQuery<'g, '_>, owner: &'g KirElement)
    -> Result<Vec<&'g KirElement>, QueryFailure> {
    fn visit<'g>(query: &DefinitionNameQuery<'g, '_>, owner: &'g KirElement, active: &mut BTreeSet<String>) -> Result<Vec<&'g KirElement>, QueryFailure> {
        if !active.insert(owner.id.clone()) || active.len() > 128 { return Err(query_failure("featuring chain is cyclic or exceeds the evaluation limit")); }
        let contract = ecore_model::feature(&owner.kind, "featuring_type").ok_or_else(|| query_failure("missing featuringType contract"))?;
        if !contract.setting_delegate.as_ref().is_some_and(|d| d.uri == "http://www.omg.org/spec/SysML" && d.status == "custom_setting_delegate_source" && d.candidates == [featuring_queries_generated::DELEGATE]) {
            return Err(query_failure("unassessed featuringType delegate"));
        }
        // The written rule reads all typeFeaturing inverses, while the pinned
        // Pilot getter traverses ownedTypeFeaturing. Do not silently omit an
        // external inverse while that normative scope is unqualified.
        for relation in query.featuring_relations() {
            if query_reference_in_view(query, relation, "feature_of_type")?.id == owner.id
                && relation.properties.get("owning_related_element").and_then(Value::as_str) != Some(owner.id.as_str()) {
                return Err(query_failure("externally owned TypeFeaturing requires normative inverse assessment"));
            }
        }
        let mut result = Vec::new();
        for relation in definition_owned_type_featuring_in_view(query, owner)? { result.push(query_reference_in_view(query, relation, "featuring_type")?); }
        if !scope_boolean(owner, "is_implied_included")? {
            let owning = definition_feature_owner_indexed(query.graph.len(),query.index, owner)?;
            if let Some((_, owning_type)) = owning {
                let (_, variable) = definition_owning_featuring_input_in_view(query, owner)?
                    .ok_or_else(|| query_failure("missing canonical featuring owner"))?;
                if variable {
                    let snapshot=definition_assessed_variable_featuring_in_view(query,owner,owning_type)?
                        .ok_or_else(||query_failure("featuring query requires variable snapshot construction"))?;
                    result.push(snapshot);
                } else { result.push(owning_type); }
            } else if let Some(types)=definition_binary_cross_featuring_targets_in_view(query,owner)? {
                result.extend(types);
            } else if let Some(parent) = transition_context_stage::parent_in_view(query,owner)? {
                result.extend(visit(query,parent,active)?);
            } else if compatibility_generated::expression_featuring_supported(owner.kind.rsplit("::").next().unwrap_or(&owner.kind)) {
                let context = if let Some(range) = definition_bound_expression_range_in_view(query, owner)? {
                    range
                } else {
                    definition_value_expression_owner_in_view(query, owner)?
                };
                result.extend(visit(query, context, active)?);
            } else if !definition_no_owning_type_featuring_is_empty_in_view(query,owner)? {
                if owner.kind.rsplit("::").next() != Some("Feature") || scope_boolean(owner, "is_variable")? {
                    return Err(QueryFailure::Rejected(error("featuring query requires complete implicit inputs or a fixed owning-type provider").with_subject(owner.id.clone())));
                }
                if let Some(member) = scope_container_query(query, owner)? {
                    let namespace = scope_container_query(query, member)?;
                    if namespace.is_some_and(|n| metaclass_conforms(&n.kind, "Feature") && scope_boolean(n, "is_end").unwrap_or(true))
                        && !metaclass_conforms(&member.kind, "FeatureMembership") && !metaclass_conforms(&member.kind, "FeatureValue") {
                        return Err(query_failure(format!("featuring query requires owned-cross-feature semantics: {}",owner.id)));
                    }
                }
            }
        }

        if let Some(chain) = stored_children_projection_query(query, owner, "owned_relationship")?.into_iter().find(|r| metaclass_conforms(&r.kind,"FeatureChaining")) {
            result.extend(visit(query, query_reference_in_view(query, chain, "chaining_feature")?, active)?);
        }
        if contract.unique { let mut seen = BTreeSet::new(); result.retain(|e| seen.insert(e.id.as_str())); }
        active.remove(&owner.id);
        Ok(result)
    }
    visit(query, owner, &mut BTreeSet::new())
}

/// Stable breadth-first featuring closure, including FeatureValue owner substitution.
pub(crate) fn definition_all_featuring_types<'g>(graph: &'g [KirElement], original: &'g KirElement) -> Result<Vec<&'g KirElement>, Diagnostic> {
    definition_all_featuring_types_typed_query(graph, original).map_err(|failure| failure.into_diagnostic_at("definition_all_featuring_types"))
}

fn definition_all_featuring_types_typed_query<'g>(graph: &'g [KirElement], original: &'g KirElement) -> Result<Vec<&'g KirElement>, QueryFailure> {
    let index=graph.iter().map(|e|(e.id.as_str(),e)).collect::<BTreeMap<_,_>>();
    definition_all_featuring_types_in_view(&DefinitionNameQuery::new(graph,&index),original)
}

fn definition_all_featuring_types_in_view<'g>(query: &DefinitionNameQuery<'g, '_>, original: &'g KirElement) -> Result<Vec<&'g KirElement>, QueryFailure> {
    if !metaclass_conforms(&original.kind,"Feature") { return Err(query_failure("featuring closure requires a Feature")); }
    let index=query.index;
    if index.len()!=query.graph.len() { return Err(query_failure("duplicate featuring graph identity")); }
    let mut pending = std::collections::VecDeque::from([original]);
    let mut seen = BTreeSet::new();
    let mut result = Vec::new();
    while let Some(mut feature) = pending.pop_front() {
        if let Some(member) = scope_container_query(query, feature)? {
            if metaclass_conforms(&member.kind,"FeatureValue") {
                feature = scope_container_query(query, member)?.filter(|e|metaclass_conforms(&e.kind,"Feature")).ok_or_else(||query_failure("FeatureValue requires a canonical Feature owner"))?;
            }
        }
        for target in definition_featuring_types_in_view(query,feature)? {
            if seen.insert(target.id.as_str()) {
                result.push(target);
                if metaclass_conforms(&target.kind,"Feature") { pending.push_back(target); }
            }
        }
    }
    Ok(result)

}

/// Consume the resolved ExpressionAdapter base selector in contexts where its
/// inherited and conditional producers are proven inapplicable. This is a
/// default-contribution stage, not complete Expression generalization/lifecycle.
pub(crate) fn definition_materialize_value_expression_defaults(elements: &mut Vec<KirElement>,
    expression_id: &str, prefix: &str) -> Result<usize, Diagnostic> {
    definition_materialize_value_expression_defaults_query(elements,expression_id,prefix,ecore_model::ReferenceCompleteness::Closed)
        .map_err(|failure| failure.into_diagnostic_at("definition_materialize_value_expression_defaults external boundary"))
}

fn definition_materialize_value_expression_defaults_query(elements: &mut Vec<KirElement>,
    expression_id: &str, prefix: &str, boundary: ecore_model::ReferenceCompleteness) -> Result<usize, QueryFailure> {
    if let Some(issue)=ecore_model::validate_publication(elements,boundary).first() {
        return Err(query_failure(format!("invalid expression default input: {}",issue.message)));
    }
    let expression=elements.iter().find(|e|e.id==expression_id).ok_or_else(||query_failure("missing expression default owner"))?;
    let index=elements.iter().map(|e|(e.id.as_str(),e)).collect::<BTreeMap<_,_>>();
    let effects=definition_expression_default_contributions_query(&DefinitionNameQuery::new(elements,&index),expression)?;
    let selected=effects.iter().map(|(kind,id)|(*kind,id.as_str())).collect::<Vec<_>>();
    definition_materialize_general_batch_query(elements,&[(expression_id,prefix,&selected)],boundary)
}

// Shared admitted provider for both read-only semantic queries and physical
// insertion. Only a previously materialized copy of this exact default may be
// consumed as partial implicit state; unrelated producers remain unassessed.
fn definition_expression_default_generals(elements: &[KirElement], expression: &KirElement)
    -> Result<Vec<String>, Diagnostic> {
    let index=elements.iter().map(|e|(e.id.as_str(),e)).collect::<BTreeMap<_,_>>();
    if index.len()!=elements.len() {return Err(error("duplicate model identity"));}
    definition_expression_default_generals_query(&DefinitionNameQuery::new(elements,&index),expression)
}

fn definition_expression_default_generals_query(query: &DefinitionNameQuery<'_, '_>, expression: &KirElement)
    -> Result<Vec<String>, Diagnostic> {
    definition_expression_default_generals_query_typed_query(query, expression).map_err(|failure| failure.into_diagnostic_at("definition_expression_default_generals_query"))
}

#[path="instantiation_strategy_generated.rs"]
mod instantiation_strategy_generated;
#[path="library_instantiation_generated.rs"]
mod library_instantiation_generated;
#[path="instantiation_contributions_generated.rs"]
mod instantiation_contributions_generated;

// Named handwritten canonical graph and library-navigation services.
// Delegate selection and selector recipes come from resolved pinned definitions.
// Normative KerML 8.3.4.8.7 makes the first eligible membership decisive;
// unlike Pilot's null filter, an explicit null cannot select a later member.
fn definition_instantiated_type_query<'g>(query: &DefinitionNameQuery<'g,'_>, owner: &'g KirElement)
    -> Result<Option<&'g KirElement>,QueryFailure> {
    let _definition=instantiation_strategy_generated::DEFINITION_SHA;
    if query.index.len()!=query.graph.len() || !query.index.get(owner.id.as_str()).is_some_and(|e|std::ptr::eq(*e,owner)) {
        return Err(query_failure("instantiated type requires a unique canonical graph owner"));
    }
    let kind=owner.kind.rsplit("::").next().unwrap_or(&owner.kind);
    let selector=instantiation_strategy_generated::selector(kind).ok_or_else(||query_failure("unsupported instantiated type operation"))?;
    let contract=ecore_model::feature(&owner.kind,"instantiated_type").ok_or_else(||query_failure("missing instantiated type contract"))?;
    if !contract.setting_delegate.as_ref().is_some_and(|d|d.uri=="http://www.omg.org/spec/SysML" && d.status=="custom_setting_delegate_source" && d.candidates==["org.omg.sysml.delegate.setting.InstantiationExpression_instantiatedType_SettingDelegate"]) {
        return Err(query_failure("unsupported instantiated type setting delegate"));
    }
    let _library_definition=library_instantiation_generated::DEFINITION_SHA;
    match selector {
        instantiation_strategy_generated::Selector::Operator => {
            let default=library_instantiation_generated::operator_default(kind).ok_or_else(||query_failure("missing operator constructor default"))?;
            let operator=match owner.properties.get("operator") {
                None => default,
                Some(Value::Null) => None,
                Some(Value::String(value)) => Some(value.as_str()),
                _ => return Err(query_failure("invalid operator value")),
            };
            let Some(operator)=operator else {return Ok(None);};
            let target=definition_library_type_query(query,&library_instantiation_generated::operator_names(operator))?;
            if target.is_some_and(|value|!metaclass_conforms(&value.kind,"Function")) {
                return Err(query_failure("operator instantiated Type is not a Function"));
            }
            return Ok(target);
        },
        instantiation_strategy_generated::Selector::Trigger => {
            let trigger=match owner.properties.get("kind") {
                None | Some(Value::Null) => return Ok(None),
                Some(Value::String(value)) => value.as_str(),
                _ => return Err(query_failure("invalid TriggerKind value")),
            };
            let name=library_instantiation_generated::trigger_name(trigger).ok_or_else(||query_failure("unsupported TriggerKind literal"))?;
            return definition_library_type_query(query,&[name.into()]);
        },
        instantiation_strategy_generated::Selector::Membership => {},
    }
    for member in stored_children_projection_query(query, owner,"owned_relationship")? {
        if !metaclass_conforms(&member.kind,"Membership") || metaclass_conforms(&member.kind,"FeatureMembership") {continue;}
        let target=if metaclass_conforms(&member.kind,"OwningMembership") {
            let children=stored_children_projection_query(query, member,"owned_related_element")?;
            if children.len()!=1 {return Err(query_failure("instantiation owning membership requires one canonical member"));}
            children[0]
        } else {
            if member.properties.get("member_element").is_some_and(Value::is_null) {return Ok(None);}
            query_reference_in_view(query,member,"member_element")?
        };
        return Ok(metaclass_conforms(&target.kind,"Type").then_some(target));
    }
    Ok(None)
}

fn definition_expression_default_generals_query_typed_query(query: &DefinitionNameQuery<'_, '_>, expression: &KirElement)
    -> Result<Vec<String>, QueryFailure> {
    definition_expression_default_contributions_query(query,expression).map(|effects|effects.into_iter().map(|(_,id)|id).collect())
}

// Handwritten composition of the admitted resolved adapter effect programs.
// Relationship identity is part of each effect; target identity alone is insufficient.
fn definition_expression_default_contributions_query(query: &DefinitionNameQuery<'_, '_>, expression: &KirElement)
    -> Result<Vec<(&'static str,String)>, QueryFailure> {
    let name=compatibility_generated::expression_default_name(expression.kind.rsplit("::").next().unwrap_or(&expression.kind),
        if ecore_model::feature(&expression.kind,"is_negated").is_some() {scope_boolean(expression,"is_negated")?}else{false})
        .or_else(||instantiation_strategy_generated::base(expression.kind.rsplit("::").next().unwrap_or(&expression.kind)))
        .ok_or_else(||query_failure("expression default requires an admitted resolved provider"))?;
    // The imported Expression/Invocation default programs do not exclude
    // directed parameters. Direction only gates separate bound-value effects
    // in FeatureAdapter; that composition remains an explicit dependency below.
    if let Some(direction) = expression.properties.get("direction") {
        ecore_model::validate_value(&expression.kind, "direction", direction).map_err(query_failure)?;
    }
    if scope_boolean(expression,"is_implied_included")? || scope_boolean(expression,"is_end")? {
        return Err(QueryFailure::Rejected(error(format!("expression defaults require incomplete non-end inputs: kind={}, complete={}, end={}",
            expression.kind, scope_boolean(expression,"is_implied_included")?, scope_boolean(expression,"is_end")?)).with_subject(expression.id.clone())));
    }
    let index=query.index;
    if let Some(member)=scope_container_query(query,expression)? {
        let namespace=scope_container_query(query,member)?.ok_or_else(||query_failure("expression membership has no owner"))?;
        let value=metaclass_conforms(&member.kind,"FeatureValue") && metaclass_conforms(&namespace.kind,"Feature");
        let package=member.kind.rsplit("::").next()==Some("OwningMembership")
            && matches!(namespace.kind.rsplit("::").next(),Some("Namespace"|"Package"|"LibraryPackage"));
        let typed=metaclass_conforms(&member.kind,"FeatureMembership") && metaclass_conforms(&namespace.kind,"Type");
        let bound=definition_bound_expression_range_in_view(query,expression)?.is_some();
        if !value && !package && !typed && !bound {
            return Err(query_failure("expression defaults require canonical FeatureMembership, package, FeatureValue or selected multiplicity-bound ownership"));
        }
    }
    let composite=scope_boolean(expression,"is_composite")?;
    let (structure_owned,behavior_owned)=definition_performance_owner_predicates_in_view(query,expression,composite)?;
    definition_projection::require_empty_metadata_bases_query(query, expression)?;
    let names=expression_context_defaults_generated::names(expression.kind.rsplit("::").next().unwrap_or(&expression.kind),name,composite,structure_owned,behavior_owned)
        .or_else(||instantiation_strategy_generated::names(expression.kind.rsplit("::").next().unwrap_or(&expression.kind),composite,structure_owned,behavior_owned))
        .ok_or_else(||query_failure("expression context defaults require an admitted resolved program"))?;
    let kind=expression.kind.rsplit("::").next().unwrap_or(&expression.kind);
    let _program=instantiation_contributions_generated::DEFINITION_SHA;
    let instantiated=if instantiation_strategy_generated::adds_instantiated_general(kind) {
        definition_instantiated_type_query(query,expression)?
    } else {None};
    let mut effects=Vec::new();
    if instantiation_contributions_generated::direct_typing(kind) {
        if let Some(target)=instantiated.filter(|t|t.id!=expression.id) {effects.push(("FeatureTyping",target.id.clone()));}
    }
    for name in names {
        let general=query_local_binding(standard_default_binding_query(query,name)?)?;
        let target=*index.get(general.as_str()).ok_or_else(||query_failure("missing expression default endpoint"))?;
        ecore_model::validate_reference_endpoint("Subsetting","subsetted_feature",&target.kind).map_err(query_failure)?;
        if target.id!=expression.id {effects.push(("Subsetting",general));}
    }
    if let Some(target)=instantiated.filter(|t|t.id!=expression.id) {
        effects.push((if metaclass_conforms(&target.kind,"Feature") {"Subsetting"}else{"FeatureTyping"},target.id.clone()));
    }
    // TypeAdapter sorts class groups by imported Ecore classifier ID, retaining
    // insertion order within a group. Equivalence is tested within that group.
    effects.sort_by_key(|(kind,_)|if (*kind=="FeatureTyping")==instantiation_strategy_generated::TYPE_BEFORE_SUBSETTING {0}else{1});
    let mut generals:Vec<(&'static str,String)>=Vec::new();
    for (kind,id) in effects {
        let target=*index.get(id.as_str()).ok_or_else(||query_failure("missing contribution target"))?;
        let mut equivalent=false;
        for (previous_kind,previous_id) in &generals {
            if *previous_kind==kind && definition_equivalent_implicit_generals_query(query,index[previous_id.as_str()],target)? {equivalent=true;break;}
        }
        if !equivalent {generals.push((kind,id));}
    }
    for relation in stored_children_projection_query(query, expression,"owned_relationship")? {
        if ["Conjugation","CrossSubsetting","FeatureValue","FeatureChaining"].iter().any(|kind|metaclass_conforms(&relation.kind,kind)) {
            return Err(query_failure("expression defaults require separate crossing/valuation/chaining composition assessment"));
        }
        if metaclass_conforms(&relation.kind,"Specialization") && scope_boolean(relation,"is_implied")?
            && !(query_reference_in_view(query,relation,"specific")?.id==expression.id
                && {let target=query_reference_in_view(query,relation,"general")?;
                    generals.iter().any(|(kind,id)|relation.kind.rsplit("::").next()==Some(*kind) && id==&target.id)}) {
            return Err(query_failure("expression default provider cannot certify an unrelated implied contribution"));
        }
    }
    Ok(generals)
}

// Named handwritten dependencies of the resolved FeatureAdapter predicates.
// Ecore ancestry and canonical owning-Type membership drive both consumers.


fn definition_performance_owner_predicates_in_view(query: &DefinitionNameQuery<'_, '_>, feature: &KirElement, composite: bool) -> Result<(bool,bool), QueryFailure> {
    let mut structure=false;let mut behavior=false;
    if let Some((_,owner))=definition_feature_owner_indexed(query.graph.len(),query.index,feature)? {
        behavior=metaclass_conforms(&owner.kind,"Behavior") || metaclass_conforms(&owner.kind,"Step");
        if composite {
            structure=metaclass_conforms(&owner.kind,"Structure");
            if !structure && metaclass_conforms(&owner.kind,"Feature") {
                structure=definition_feature_types_in_view(query,owner)?.iter().any(|target|metaclass_conforms(&target.kind,"Structure"));
            }
        }
    }
    Ok((structure,behavior))

}

#[cfg(test)]
fn definition_step_default_name(graph: &[KirElement], step: &KirElement) -> Result<&'static str,Diagnostic> {
    definition_step_default_name_typed_query(graph, step).map_err(|failure| failure.into_diagnostic_at("definition_step_default_name"))
}

fn definition_step_default_name_typed_query(graph: &[KirElement], step: &KirElement) -> Result<&'static str,QueryFailure> {
    let index=graph.iter().map(|e|(e.id.as_str(),e)).collect::<BTreeMap<_,_>>();
    definition_step_default_name_in_view(&DefinitionNameQuery::new(graph,&index),step)
}

fn definition_step_default_name_in_view(query: &DefinitionNameQuery<'_, '_>, step: &KirElement) -> Result<&'static str, QueryFailure> {
    if !step_defaults_generated::supports(step.kind.rsplit("::").next().unwrap_or(&step.kind)) {
        return Err(query_failure("Step defaults require resolved Step adapter dispatch"));
    }
    if scope_boolean(step,"is_implied_included")? || scope_boolean(step,"is_end")?
        || step.properties.get("direction").is_some_and(|v|!v.is_null()) {
        return Err(query_failure("Step default requires incomplete nondirected non-end inputs"));
    }
    definition_projection::require_empty_metadata_bases_query(query,step)?;
    for relation in stored_children_projection_query(query,step,"owned_relationship")? {
        if ["Conjugation","CrossSubsetting","FeatureValue","FeatureChaining"].iter().any(|kind|metaclass_conforms(&relation.kind,kind)) {
            return Err(query_failure("Step defaults require separate crossing/valuation/chaining assessment"));
        }
        if scope_boolean(relation,"is_implied")? && relation.kind.rsplit("::").next()!=Some("Subsetting") {
            return Err(query_failure("Step defaults require assessed implicit contribution categories"));
        }
    }
    let composite=scope_boolean(step,"is_composite")?;
    let (structure,behavior)=definition_performance_owner_predicates_in_view(query,step,composite)?;
    let incoming=definition_owned_features_query(query,step,false)?.iter().any(|feature|metaclass_conforms(&feature.kind,step_defaults_generated::PAYLOAD_TYPE));
    let name=step_defaults_generated::name(composite,structure,behavior,incoming);
    let mut implied=Vec::new();
    for relation in stored_children_projection_query(query,step,"owned_relationship")? {
        if relation.kind.rsplit("::").next()==Some("Subsetting") && scope_boolean(relation,"is_implied")? {implied.push(relation);}
    }
    if !implied.is_empty() {
        let GeneratedLinkTarget::Local(id)=standard_default_binding_query(query,name)? else {return Err(query_failure("partial Step default requires local library"));};
        for relation in implied {
            if !definition_assessed_type_default_relation_typed_in_view(query,step,relation,"Subsetting",&[id.clone()])? {
                return Err(query_failure("unassessed partial Step default contribution"));
            }
        }
    }
    Ok(name)

}

// Canonical ownership for semantic queries before and after transformation.
// Physical insertion separately requires an incomplete receiver; structural
// lookup alone neither admits a write nor asserts lifecycle completion.
// Other ownership contexts (notably multiplicity bounds) remain dependencies.
fn definition_value_expression_owner<'g>(elements: &'g [KirElement], expression: &KirElement)
    -> Result<&'g KirElement, Diagnostic> {
    let index=elements.iter().map(|e|(e.id.as_str(),e)).collect();
    definition_value_expression_owner_in_view(&DefinitionNameQuery::new(elements,&index),expression)
}

fn definition_value_expression_owner_in_view<'g>(query: &DefinitionNameQuery<'g, '_>, expression: &KirElement)
    -> Result<&'g KirElement, Diagnostic> {
    if !compatibility_generated::expression_featuring_supported(expression.kind.rsplit("::").next().unwrap_or(&expression.kind)) {
        return Err(error("value-expression ownership requires an admitted Expression"));
    }
    let value=scope_container_query(query,expression)?.filter(|e|metaclass_conforms(&e.kind,"FeatureValue"))
        .ok_or_else(||error("expression featuring currently requires FeatureValue ownership"))?;
    scope_container_query(query,value)?.filter(|e|metaclass_conforms(&e.kind,"Feature"))
        .ok_or_else(||error("value expression requires a Feature owner"))
}

// Named handwritten semantic dependency. Pinned Xtext creates ordinary
// OwningMemberships for bounds; imported Ecore/delegate projections select the
// first two owned Expressions. This preserves that selection and validates
// reciprocal ownership. Containment never fabricates Feature.owningType.
fn definition_bound_expression_range_in_view<'g>(
    query: &DefinitionNameQuery<'g, '_>, expression: &KirElement,
) -> Result<Option<&'g KirElement>, QueryFailure> {
    let Some(member)=scope_container_query(query,expression)? else {return Ok(None);};
    if member.kind.rsplit("::").next()!=Some("OwningMembership") {return Ok(None);}
    let Some(range)=scope_container_query(query,member)? else {
        return Err(query_failure("bound membership requires canonical namespace ownership"));
    };
    if !metaclass_conforms(&range.kind,"MultiplicityRange") {return Ok(None);}
    let StoredMembershipEndpoint::Resolved(endpoint)=stored_membership_endpoint_indexed(
        query.graph.len(),query.index,member,"member_element")? else {
        return Err(query_failure("bound membership requires a resolved canonical endpoint"));
    };
    if endpoint.id!=expression.id {
        return Err(query_failure("bound membership endpoint disagrees with ownership"));
    }
    if !definition_reference_targets_query(query,range,"bound")?.iter().any(|e|e.id==expression.id) {
        return Err(query_failure("owned Expression is not a selected multiplicity bound"));
    }
    Ok(Some(range))
}

/// Named handwritten FeatureValue expression featuring stage. Imported runtime
/// dispatch admits the shared ExpressionAdapter/FeatureAdapter method; Ecore
/// contracts govern canonical insertion. The shared featuring query requires
/// complete inputs or its assessed fixed ordinary Feature provider.
/// This is not expression completion, evaluation, or the multiplicity-bound path.
pub(crate) fn definition_materialize_value_expression_featuring(elements: &mut Vec<KirElement>,
    expression_id: &str, prefix: &str) -> Result<usize, Diagnostic> {
    definition_materialize_value_expression_featuring_query(elements,expression_id,prefix,ecore_model::ReferenceCompleteness::Closed)
        .map_err(|failure| failure.into_diagnostic_at("definition_materialize_value_expression_featuring external boundary"))
}

fn definition_materialize_value_expression_featuring_query(elements: &mut Vec<KirElement>,
    expression_id: &str, prefix: &str, boundary: ecore_model::ReferenceCompleteness) -> Result<usize, QueryFailure> {
    if let Some(issue)=ecore_model::validate_publication(elements,boundary).first() {
        return Err(query_failure(format!("invalid expression featuring input: {}",issue.message)));
    }
    if prefix.is_empty() {return Err(query_failure("expression featuring requires a nonempty identity prefix"));}
    let expression=elements.iter().find(|e|e.id==expression_id).ok_or_else(||query_failure("missing value expression"))?;
    if scope_boolean(expression,"is_implied_included")? {return Err(query_failure("expression featuring requires an admitted incomplete Expression"));}
    let owner=definition_value_expression_owner(elements,expression)?;
    let index=elements.iter().map(|e|(e.id.as_str(),e)).collect();
    let existing=definition_owned_type_featuring_typed_query(elements,expression)?.iter()
        .map(|r|query_reference(elements,r,"featuring_type").map(|e|e.id.clone())).collect::<Result<BTreeSet<_>,_>>()?;
    let selected=definition_featuring_types_typed_query(elements,owner)?.iter().filter(|e|!existing.contains(&e.id))
        .map(|e|e.id.clone()).collect::<Vec<_>>();
    if elements.iter().any(|e|e.properties.keys().any(|f|ecore_model::feature(&e.kind,f).is_some_and(|c|c.derived||c.volatile))) {
        return Err(query_failure("expression featuring requires derived-value recomputation"));
    }
    let mut staged=elements.clone();
    for (i,target) in selected.iter().enumerate() {
        let id=format!("{prefix}.{i}");
        if staged.iter().any(|e|e.id==id) {return Err(query_failure("expression featuring identity collision"));}
        let mut relation=fresh_definition_element(id,"TypeFeaturing")?;
        relation.properties.insert("is_implied".into(),json!(true));
        relation.properties.insert("feature_of_type".into(),json!(expression_id));
        relation.properties.insert("featuring_type".into(),json!(target));
        let target=staged.iter_mut().find(|e|e.id==*target).ok_or_else(||query_failure("missing expression featuring target"))?;
        if target.properties.get("owning_relationship").is_none_or(Value::is_null) {
            // A detached ancestor cannot be adopted below its own descendant.
            let mut ancestor=Some(expression);
            while let Some(node)=ancestor {
                if node.id==target.id {return Err(query_failure("expression featuring adoption would create an ownership cycle"));}
                ancestor=scope_container(&index,node)?;
            }
            ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS,&mut relation,target)?;
        }
        let expression=staged.iter_mut().find(|e|e.id==expression_id).unwrap();
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,expression,&mut relation)?;
        staged.push(relation);
    }
    if let Some(issue)=ecore_model::validate_publication(&staged,boundary).first() {
        return Err(query_failure(format!("invalid expression featuring output: {}",issue.message)));
    }
    *elements=staged;Ok(selected.len())
}

fn construction_metadata(owner: &KirElement, kind: &str) -> Value {
    let mut metadata = owner
        .properties
        .get("metadata")
        .cloned()
        .unwrap_or_else(|| json!({}));
    metadata["lowering"] = json!({"construct":kind, "metaclass":format!("SysML::{kind}")});
    metadata
}

fn error(message: impl Into<String>) -> Diagnostic {
    Diagnostic::new(format!("Operand construction: {}", message.into()), None)
}

fn fresh_definition_element(id: String, kind: &str) -> Result<KirElement, Diagnostic> {
    let mut element = KirElement { id, kind: format!("SysML::{kind}"), layer: 2, properties: BTreeMap::new() };
    ecore_model::initialize_fresh_structure(&mut element);
    super::super::ecore_defaults::apply(std::slice::from_mut(&mut element));
    super::super::ecore_defaults::apply_implicit_primitives(std::slice::from_mut(&mut element)).map_err(error)?;
    Ok(element)
}

// Shared resolved adapter/getter dispatch for read and construction. Usage's
// isVariable getter consumes mayTimeVary even when contradictory raw storage is
// present. Missing semantic inputs remain errors, never false defaults.
fn definition_owning_featuring_input<'g>(graph: &'g [KirElement], feature: &KirElement)
    -> Result<Option<(&'g KirElement, bool)>, Diagnostic> {
    definition_owning_featuring_input_typed_query(graph, feature).map_err(|failure| failure.into_diagnostic_at("definition_owning_featuring_input"))
}

fn definition_owning_featuring_input_typed_query<'g>(graph: &'g [KirElement], feature: &KirElement)
    -> Result<Option<(&'g KirElement, bool)>, QueryFailure> {
    let index=graph.iter().map(|e|(e.id.as_str(),e)).collect::<BTreeMap<_,_>>();
    definition_owning_featuring_input_in_view(&DefinitionNameQuery::new(graph,&index),feature)
}

fn definition_owning_featuring_input_in_view<'g>(query: &DefinitionNameQuery<'g, '_>, feature: &KirElement) -> Result<Option<(&'g KirElement,bool)>, QueryFailure> {
    let kind = feature.kind.rsplit("::").next().unwrap_or(&feature.kind);
    let uses_variability = feature_redefinitions_generated::owning_type_featuring_uses_variability(kind);
    if !feature_redefinitions_generated::owning_type_featuring_supported(kind) && !uses_variability {
        return Err(query_failure("owning-type featuring requires specialized variability/adapter assessment"));
    }
    let Some((_, owner)) = definition_feature_owner_indexed(query.graph.len(),query.index, feature)? else { return Ok(None); };
    let variable = if uses_variability { definition_may_time_vary_in_view(query, feature)? }
        else { super::super::ecore_defaults::read_attribute(feature, "is_variable").map_err(query_failure)? == json!(true) };
    Ok(Some((owner, variable)))

}

/// Bounded FeatureAdapter.computeFeaturingType + insertImplicitTypeFeaturings.
/// Resolved FeatureImpl getter bindings support owning types and variable snapshots. This
/// does not claim expression or full Feature transformation is complete.
pub(crate) fn definition_materialize_owning_type_featuring(elements: &mut Vec<KirElement>, feature_id: &str, relation_id: &str)
    -> Result<bool, Diagnostic>
{
    definition_materialize_owning_type_featuring_query(elements,feature_id,relation_id,ecore_model::ReferenceCompleteness::Closed)
        .map_err(|failure| failure.into_diagnostic_at("definition_materialize_owning_type_featuring external boundary"))
}

fn definition_materialize_owning_type_featuring_query(elements:&mut Vec<KirElement>,feature_id:&str,relation_id:&str,
    boundary:ecore_model::ReferenceCompleteness)->Result<bool,QueryFailure> {
    if let Some(issue)=ecore_model::validate_publication(elements,boundary).first() {
        return Err(query_failure(format!("invalid featuring input: {}",issue.message)));
    }
    let mut staged=elements.clone();
    let changed=definition_materialize_owning_type_featuring_in_stage(&mut staged,feature_id,relation_id)?;
    if !changed {return Ok(false);}
    if let Some(issue)=ecore_model::validate_publication(&staged,boundary).first() {
        return Err(query_failure(format!("invalid featuring result: {}",issue.message)));
    }
    *elements=staged;Ok(true)
}

// Private worker: the caller must discard its entire stage on failure.
fn definition_materialize_owning_type_featuring_in_stage(elements:&mut Vec<KirElement>,feature_id:&str,relation_id:&str)
    -> Result<bool,QueryFailure> {
    let feature = elements.iter().find(|e| e.id == feature_id).ok_or_else(|| query_failure("missing featured Feature"))?;
    let Some((owner, variable)) = definition_owning_featuring_input_typed_query(elements, feature)? else { return Ok(false); };
    let owned = definition_owned_type_featuring_typed_query(elements, feature)?;
    if variable {
        let owner_id = owner.id.clone();
        return definition_materialize_variable_featuring(elements, feature_id, &owner_id, relation_id).map_err(QueryFailure::from);
    }
    if owned.iter().any(|r| r.properties.get("featuring_type").and_then(Value::as_str) == Some(owner.id.as_str())) { return Ok(false); }
    // Pilot's physical insertion adopts a detached featuring Type. Here it is
    // the ancestor of this Feature, so adoption would introduce a containment cycle.
    if !owner.properties.get("owning_relationship").is_some_and(|v| !v.is_null()) {
        return Err(query_failure("owning Type must be contained before featuring materialization"));
    }
    for element in elements.iter() {
        if element.properties.keys().any(|field| ecore_model::feature(&element.kind, field).is_some_and(|c| c.derived || c.volatile)) {
            return Err(query_failure("featuring mutation requires derived-value recomputation for stored snapshots"));
        }
    }
    let owner_id = owner.id.clone();
    let mut relation = fresh_definition_element(relation_id.into(), "TypeFeaturing")?;
    for (field, target) in [("feature_of_type", feature_id), ("featuring_type", owner_id.as_str())] {
        let endpoint = elements.iter().find(|e| e.id == target).ok_or_else(|| query_failure("missing featuring endpoint"))?;
        ecore_model::validate_reference_endpoint(&relation.kind, field, &endpoint.kind).map_err(query_failure)?;
        relation.properties.insert(field.into(), json!(target));
    }
    ecore_model::validate_value(&relation.kind, "is_implied", &json!(true)).map_err(query_failure)?;
    relation.properties.insert("is_implied".into(), json!(true));
    let feature = elements.iter_mut().find(|e| e.id == feature_id).ok_or_else(|| query_failure("missing staged Feature"))?;
    ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, feature, &mut relation)?;
    elements.push(relation);
    Ok(true)
}

// Qualified naming dependency used only for Pilot's generated snapshot name.
// Canonical owned-member ordering controls ambiguity; anonymous ancestry has no
// qualified name. This does not implement imported/inherited name resolution.
#[cfg(test)]
fn snapshot_qualified_name(graph: &[KirElement], element: &KirElement, visited: &mut BTreeSet<String>)
    -> Result<Option<String>, Diagnostic>
{
    let index=graph.iter().map(|e|(e.id.as_str(),e)).collect::<BTreeMap<_,_>>();
    snapshot_qualified_name_in_view(&DefinitionNameQuery::new(graph,&index),element,visited).map_err(|failure|failure.into_diagnostic_at("snapshot_qualified_name external boundary"))
}

fn snapshot_qualified_name_in_view(query: &DefinitionNameQuery<'_, '_>, element: &KirElement, visited: &mut BTreeSet<String>) -> Result<Option<String>, QueryFailure> {
    if !visited.insert(element.id.clone()) { return Err(query_failure("cyclic snapshot name ancestry")); }
    let Some(parent) = generated_parent_namespace_query(query, &element.id)? else { return Ok(None); };
    let Some(name) = generated_effective_names_inner_query(query.graph,Some(query), element,&mut BTreeSet::new())?[0].clone() else { return Ok(None); };
    let mut first = None;
    for membership in stored_children_projection_query(query, parent, "owned_relationship")? {
        if !metaclass_conforms(&membership.kind, "OwningMembership") { continue; }
        if let StoredMembershipEndpoint::Resolved(member) = stored_membership_endpoint_indexed(query.graph.len(),query.index,membership, "member_element")? {
            if generated_effective_names_inner_query(query.graph,Some(query), member,&mut BTreeSet::new())?[0].as_ref() == Some(&name) { first = Some(member.id.as_str()); break; }
        }
    }
    if first != Some(element.id.as_str()) { return Ok(None); }
    let identifier = name.chars().next().is_some_and(|c| c.is_ascii_alphabetic() || c == '_')
        && name.chars().all(|c| c.is_ascii_alphanumeric() || c == '_');
    let escaped = if name.is_empty() || identifier || name == "$" { name } else {
        let mut escaped = String::from("'");
        for c in name.chars() {
            let code = match c as u32 { 8 => Some('b'), 9 => Some('t'), 10 => Some('n'),
                12 => Some('f'), 13 => Some('r'), 34 | 39 | 92 => Some(c), _ => None };
            if let Some(code) = code { escaped.push(char::from(92)); escaped.push(code); }
            else { escaped.push(c); }
        }
        escaped.push(char::from(39)); escaped
    };
    if scope_container_query(query, parent)?.is_none() { return Ok(Some(escaped)); }
    Ok(snapshot_qualified_name_in_view(query, parent, visited)?.map(|prefix| format!("{prefix}::{escaped}")))

}

// Recognize the exact native snapshot producer graph; recording an arbitrary
// implied TypeFeaturing is not evidence that variable featuring is implemented.
fn definition_assessed_variable_featuring<'g>(graph: &'g [KirElement], feature: &KirElement,
    owner: &KirElement) -> Result<Option<&'g KirElement>, Diagnostic> {
    let index=graph.iter().map(|e|(e.id.as_str(),e)).collect::<BTreeMap<_,_>>();
    definition_assessed_variable_featuring_in_view(&DefinitionNameQuery::new(graph,&index),feature,owner).map_err(|failure|failure.into_diagnostic_at("definition_assessed_variable_featuring external boundary"))
}

fn definition_assessed_variable_featuring_in_view<'g>(query: &DefinitionNameQuery<'g, '_>, feature: &KirElement, owner: &KirElement) -> Result<Option<&'g KirElement>, QueryFailure> {
    let graph=query.graph;
    let local=|name:&str| match standard_default_binding_query(query,name)? {
        GeneratedLinkTarget::Local(id)=>graph.iter().find(|e|e.id==id).ok_or_else(||query_failure("snapshot library target absent")),
        _=>Err(query_failure("snapshot recognition requires resolved local library")),
    };
    let owned=definition_owned_type_featuring_in_view(query,feature)?;
    let mut materialized=Vec::new();
    for relation in owned {if scope_boolean(relation,"is_implied")? {materialized.push(relation);}}
    if materialized.is_empty() {return Ok(None);}
    let occurrence=local("Occurrences::Occurrence")?;
    let snapshots=local("Occurrences::Occurrence::snapshots")?;
    let expected_name=definition_snapshot_name_in_view(query,owner)?;
    let mut result=None;
    for relation in materialized {
        let target=query_reference_in_view(query,relation,"featuring_type")?;
        let children=stored_children_projection_query(query,relation,"owned_related_element")?;
        let valid=if owner.id==occurrence.id {target.id==snapshots.id && children.is_empty()}
        else {
            let relations=stored_children_projection_query(query,target,"owned_relationship")?;
            let redefinitions=relations.iter().filter(|r|r.kind.rsplit("::").next()==Some("Redefinition")).collect::<Vec<_>>();
            let contexts=definition_owned_type_featuring_in_view(query,target)?;
            target.kind.rsplit("::").next()==Some("Feature") && children.len()==1 && children[0].id==target.id
                && target.properties.get("declared_name")==Some(&json!(expected_name))
                && !scope_boolean(target,"is_variable")? && !scope_boolean(target,"is_end")?
                && !scope_boolean(target,"is_composite")? && !scope_boolean(target,"is_portion")?
                && relations.len()==2 && redefinitions.len()==1 && contexts.len()==1
                && query_reference_in_view(query,redefinitions[0],"specific")?.id==target.id
                && query_reference_in_view(query,redefinitions[0],"general")?.id==snapshots.id
                && query_reference_in_view(query,contexts[0],"featuring_type")?.id==owner.id
        };
        if !valid || result.is_some() {return Err(query_failure("unassessed or duplicate variable snapshot featuring contribution"));}
        result=Some(target);
    }
    Ok(result)

}

fn definition_snapshot_name(graph: &[KirElement], owner: &KirElement) -> Result<String, Diagnostic> {
    let index=graph.iter().map(|e|(e.id.as_str(),e)).collect::<BTreeMap<_,_>>();
    definition_snapshot_name_in_view(&DefinitionNameQuery::new(graph,&index),owner).map_err(|failure|failure.into_diagnostic_at("definition_snapshot_name external boundary"))
}

fn definition_snapshot_name_in_view(query: &DefinitionNameQuery<'_, '_>, owner: &KirElement) -> Result<String, QueryFailure> {
    let name=snapshot_qualified_name_in_view(query,owner,&mut BTreeSet::new())?.unwrap_or_default();
    Ok(name.split_once("::").map_or(name.as_str(),|(_,tail)|tail).replace("::","_")+"_snapshots")

}

fn definition_materialize_variable_featuring(elements: &mut Vec<KirElement>, feature_id: &str, owner_id: &str, relation_id: &str)
    -> Result<bool, Diagnostic>
{
    let resolve = |name: &str| -> Result<String, Diagnostic> {
        match standard_default_binding(elements, name)? {
            GeneratedLinkTarget::Local(id) => Ok(id),
            _ => Err(error("snapshot construction requires local resolved library definitions")),
        }
    };
    let occurrence = resolve("Occurrences::Occurrence")?;
    let snapshots = resolve("Occurrences::Occurrence::snapshots")?;
    for element in elements.iter() {
        if element.properties.keys().any(|field| ecore_model::feature(&element.kind, field).is_some_and(|c| c.derived || c.volatile)) {
            return Err(error("snapshot mutation requires derived-value recomputation for stored snapshots"));
        }
    }
    let owner = elements.iter().find(|e| e.id == owner_id).ok_or_else(|| error("missing snapshot owner"))?;
    let feature=elements.iter().find(|e|e.id==feature_id).ok_or_else(||error("missing variable Feature"))?;
    if definition_assessed_variable_featuring(elements,feature,owner)?.is_some() {return Ok(false);}
    let snapshot_name=definition_snapshot_name(elements,owner)?;
    let mut staged = elements.clone();
    let mut outer = fresh_definition_element(relation_id.into(), "TypeFeaturing")?;
    let target_id = if owner_id == occurrence {
        let feature = elements.iter().find(|e| e.id == feature_id).ok_or_else(|| error("missing variable Feature"))?;
        if definition_owned_type_featuring(elements, feature)?.iter().any(|r| r.properties.get("featuring_type").and_then(Value::as_str) == Some(snapshots.as_str())) { return Ok(false); }
        snapshots.clone()
    } else {
        let mut snapshot = fresh_definition_element(format!("{relation_id}.snapshot"), "Feature")?;
        snapshot.properties.insert("declared_name".into(), json!(snapshot_name));
        let mut redefinition = fresh_definition_element(format!("{relation_id}.redefinition"), "Redefinition")?;
        redefinition.properties.insert("redefined_feature".into(), json!(snapshots));
        redefinition.properties.insert("redefining_feature".into(), json!(snapshot.id));
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, &mut snapshot, &mut redefinition)?;
        let mut featuring = fresh_definition_element(format!("{relation_id}.context"), "TypeFeaturing")?;
        featuring.properties.insert("feature_of_type".into(), json!(snapshot.id));
        featuring.properties.insert("featuring_type".into(), json!(owner_id));
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, &mut snapshot, &mut featuring)?;
        let target_id = snapshot.id.clone();
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS, &mut outer, &mut snapshot)?;
        staged.extend([snapshot, redefinition, featuring]);
        target_id
    };
    outer.properties.insert("feature_of_type".into(), json!(feature_id));
    outer.properties.insert("featuring_type".into(), json!(target_id));
    outer.properties.insert("is_implied".into(), json!(true));
    let feature = staged.iter_mut().find(|e| e.id == feature_id).ok_or_else(|| error("missing variable Feature"))?;
    ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, feature, &mut outer)?;
    staged.push(outer);
    let issues = ecore_model::validate_publication(&staged, ecore_model::ReferenceCompleteness::Closed);
    if let Some(issue) = issues.first() { return Err(error(format!("invalid snapshot construction: {}", issue.message))); }
    *elements = staged;
    Ok(true)
}

fn definition_owned_type_featuring<'g>(graph: &'g [KirElement], owner: &KirElement) -> Result<Vec<&'g KirElement>, Diagnostic> {
    definition_owned_type_featuring_typed_query(graph, owner).map_err(|failure| failure.into_diagnostic_at("definition_owned_type_featuring"))
}

fn definition_owned_type_featuring_typed_query<'g>(graph: &'g [KirElement], owner: &KirElement) -> Result<Vec<&'g KirElement>, QueryFailure> {
    let index = graph.iter().map(|e| (e.id.as_str(), e)).collect::<BTreeMap<_, _>>();
    definition_owned_type_featuring_in_view(&DefinitionNameQuery::new(graph, &index), owner)
}

fn definition_owned_type_featuring_in_view<'g>(query: &DefinitionNameQuery<'g, '_>, owner: &KirElement) -> Result<Vec<&'g KirElement>, QueryFailure> {
    let contract = ecore_model::feature(&owner.kind, "owned_type_featuring").ok_or_else(|| query_failure("missing ownedTypeFeaturing contract"))?;
    let delegate = contract.setting_delegate.as_ref().ok_or_else(|| query_failure("missing ownedTypeFeaturing delegate"))?;
    if delegate.uri != "http://www.omg.org/spec/SysML" || delegate.status != "custom_setting_delegate_source"
        || delegate.candidates != ["org.omg.sysml.delegate.setting.Feature_ownedTypeFeaturing_SettingDelegate"]
        || !ecore_model::has_subset_contract(&owner.kind, "owned_type_featuring", "owned_relationship") {
        return Err(query_failure("unsupported ownedTypeFeaturing contract"));
    }
    if !owner.properties.contains_key("owned_relationship") { return Err(query_failure("ownedTypeFeaturing requires canonical relationships")); }
    let mut result = Vec::new();
    for relation in stored_children_projection_query(query, owner, "owned_relationship")? {
        if !metaclass_conforms(&relation.kind, contract.target) { continue; }
        if relation.properties.get("owning_related_element").and_then(Value::as_str) != Some(owner.id.as_str()) {
            return Err(query_failure("TypeFeaturing ownership mismatch"));
        }
        if query_reference_in_view(query, relation, "feature_of_type")?.id == owner.id {
            query_reference_in_view(query, relation, "featuring_type")?;
            result.push(relation);
        }
    }
    Ok(result)

}

/// Atomic composition for freshly constructed binary bindings: placement,
/// owning featuring and bounded default contributions. Full transformation and
/// lifecycle completion remain separate; completeness flags are not fabricated.
pub(crate) fn definition_materialize_binding_defaults(elements: &mut Vec<KirElement>,
    owner: &str, id: &str, source: &str, target: &str) -> Result<(), Diagnostic> {
    definition_materialize_binding_defaults_query(elements,owner,id,source,target,ecore_model::ReferenceCompleteness::Closed)
        .map_err(|failure| failure.into_diagnostic_at("definition_materialize_binding_defaults external boundary"))
}

fn definition_materialize_binding_defaults_query(elements: &mut Vec<KirElement>,
    owner: &str, id: &str, source: &str, target: &str, boundary: ecore_model::ReferenceCompleteness) -> Result<(), QueryFailure> {
    definition_materialize_binding_defaults_observed_query(elements,owner,id,source,target,boundary,id,&|_|{})
}

fn definition_materialize_binding_defaults_observed_query(elements: &mut Vec<KirElement>,
    owner: &str, id: &str, source: &str, target: &str, boundary: ecore_model::ReferenceCompleteness,
    receiver: &str, observer: &dyn for<'e> Fn(DefinitionConstructionEvent<'e>)) -> Result<(), QueryFailure> {
    let mut staged=elements.clone();
    let result=definition_materialize_binding_defaults_observed_query_in_stage(&mut staged,owner,id,source,target,boundary,receiver,observer)?;
    *elements=staged;
    Ok(result)
}

// Private worker: the caller must discard its entire stage on any failure.
fn definition_materialize_binding_defaults_observed_query_in_stage(elements: &mut Vec<KirElement>,
    owner: &str, id: &str, source: &str, target: &str, boundary: ecore_model::ReferenceCompleteness,
    receiver: &str, observer: &dyn for<'e> Fn(DefinitionConstructionEvent<'e>)) -> Result<(), QueryFailure> {

    trace_definition_stage(elements,receiver,"binding_structure",observer,|graph|
        definition_materialize_binding_structure_with_boundary_in_stage(graph,owner,id,source,target,boundary))?;
    let connector=elements.iter().find(|e|e.id==id).ok_or_else(||query_failure("constructed binding absent from private stage"))?;
    let mut owners=vec![id.to_owned()];
    owners.extend(definition_owned_features(elements,connector,true)?.iter().map(|e|e.id.clone()));
    if owners.len()!=3 {return Err(query_failure("fresh binary binding requires exactly two owned ends"));}
    let prefixes=owners.iter().map(|owner|format!("{owner}.defaults")).collect::<Vec<_>>();
    let inputs=owners.iter().zip(&prefixes).map(|(owner,prefix)|(owner.as_str(),prefix.as_str())).collect::<Vec<_>>();
    trace_definition_stage(elements,receiver,"binding_defaults",observer,|graph|
        definition_materialize_feature_defaults_query(graph,&inputs,boundary))?;
    for owner in &owners {
        trace_definition_stage(elements,receiver,"binding_featuring",observer,|graph|
            definition_materialize_owning_type_featuring_query(graph,owner,&format!("{owner}.featuring"),boundary))?;
    }
    // Pilot flushes pending specializations before pending TypeFeaturing, including
    // context featuring selected during placement. Preserve order within each group.
    for owner in &owners {
        let node=elements.iter().find(|e|e.id==*owner).ok_or_else(||query_failure("constructed binding owner absent from private stage"))?;
        let relationships=stored_children(elements,node,"owned_relationship")?;
        let ordered=relationships.iter().filter(|r|!metaclass_conforms(&r.kind,"TypeFeaturing"))
            .chain(relationships.iter().filter(|r|metaclass_conforms(&r.kind,"TypeFeaturing")))
            .map(|r|r.id.clone()).collect::<Vec<_>>();
        elements.iter_mut().find(|e|e.id==*owner).ok_or_else(||query_failure("constructed binding owner absent from private stage"))?.properties.insert("owned_relationship".into(),json!(ordered));
    }
    if let Some(issue)=ecore_model::validate_publication(elements,boundary).first() {
        return Err(query_failure(format!("invalid binding stage output: {}",issue.message)));
    }


    Ok(())
}

fn definition_require_ordinary_lifecycle_dependencies(elements: &[KirElement]) -> Result<(), Diagnostic> {
    // A fresh connector/end has no valuation, expression, crossing feature or
    // assignment ancestry. Reject graph-wide inherited producers too: a value
    // or cross-feature may otherwise enter through the library/general closure.
    for node in elements.iter() {
        if ["FeatureValue","CrossSubsetting","Conjugation","MetadataFeature","Annotation","Expression","AssignmentActionUsage"]
            .iter().any(|kind|metaclass_conforms(&node.kind,kind)) {
            return Err(error("binding lifecycle requires valuation/crossing/expression/metadata-free dependencies"));
        }
    }
    Ok(())
}

/// Shared completion for fixed, non-end, non-parameter leaf Features owned by
/// ordinary Classes. Producer inputs are assessed before any completion flags.
pub(crate) fn definition_complete_ordinary_features(elements: &mut Vec<KirElement>,
    owners: &[(&str,&str)]) -> Result<(), Diagnostic> {
    definition_require_ordinary_lifecycle_dependencies(elements)?;
    for (id,_) in owners {
        let node=elements.iter().find(|e|e.id==*id).ok_or_else(||error("missing ordinary lifecycle Feature"))?;
        if node.kind.rsplit("::").next()!=Some("Feature") || scope_boolean(node,"is_implied_included")?
            || scope_boolean(node,"is_variable")? || scope_boolean(node,"is_end")?
            || node.properties.get("direction").is_some_and(|v|!v.is_null())
            || !definition_owned_features(elements,node,false)?.is_empty() {
            return Err(error("ordinary lifecycle requires incomplete fixed non-end non-parameter leaf Features"));
        }
        let Some((member,owner))=definition_feature_owner(elements,node)? else {
            return Err(error("ordinary lifecycle requires Class-owned Features"));
        };
        if member.kind.rsplit("::").next()!=Some("FeatureMembership") || owner.kind.rsplit("::").next()!=Some("Class") {
            return Err(error("ordinary lifecycle requires exact Class/FeatureMembership ownership"));
        }
        definition_ordinary_feature_inputs(elements,node)?;
        if !definition_no_additional_members(node)? {return Err(error("ordinary lifecycle requires additional members"));}
    }
    let mut staged=elements.clone();
    definition_materialize_feature_defaults(&mut staged,owners)?;
    for (id,prefix) in owners {
        definition_materialize_owning_type_featuring(&mut staged,id,&format!("{prefix}.featuring"))?;
    }
    for (id,_) in owners {
        staged.iter_mut().find(|e|e.id==*id).unwrap().properties.insert("is_implied_included".into(),json!(true));
    }
    if let Some(issue)=ecore_model::validate_publication(&staged,ecore_model::ReferenceCompleteness::Closed).first() {
        return Err(error(format!("invalid ordinary lifecycle output: {}",issue.message)));
    }
    *elements=staged;
    Ok(())
}

/// Complete a fresh binary binding within the reviewed ordinary-context lifecycle.
/// This is a construction transaction, not a generic operation that blesses an
/// existing partial graph. All newly created Types are known from construction.
/// Named exclusions discharge adapter branches that have no native producer yet.
pub(crate) fn definition_materialize_complete_binding(elements: &mut Vec<KirElement>,
    owner: &str, id: &str, source: &str, target: &str) -> Result<(), Diagnostic> {
    let lookup=|id: &str|elements.iter().find(|e|e.id==id).ok_or_else(||error("binding lifecycle endpoint is absent"));
    let context=lookup(owner)?;
    if context.kind.rsplit("::").next()!=Some("Class") {
        return Err(error("binding lifecycle requires ordinary Class ownership; specialized owner adapters remain unqualified"));
    }
    definition_require_ordinary_lifecycle_dependencies(elements)?;
    for endpoint in [source,target] {
        let node=lookup(endpoint)?;
        if node.kind.rsplit("::").next()!=Some("Feature") || definition_feature_owner(elements,node)?.is_none() {
            return Err(error("binding lifecycle requires already-owned ordinary Feature endpoints; adopted subtrees remain unqualified"));
        }
        if scope_boolean(node,"is_implied_included")? {
            if !matches!(definition_general_type_inputs(elements,node)?,DefinitionGeneralTypes::Ready(_)) {
                return Err(error("completed endpoint generalizations are unresolved"));
            }
        } else { definition_ordinary_feature_inputs(elements,node)?; }
        if scope_boolean(node,"is_variable")? || !definition_owned_features(elements,node,false)?.is_empty() {
            return Err(error("binding lifecycle requires fixed endpoints without nested Feature producers"));
        }
    }
    definition_finish_fresh_binding(elements, owner, id, source, target)
}

/// Fresh binding transformation with explicitly complete canonical inputs.
/// The supplied owner/endpoints retain their flags and stored state. This is
/// not a lifecycle provider for incomplete specialized Usage or Type models.
pub(crate) fn definition_materialize_resolved_binding(elements: &mut Vec<KirElement>,
    owner: &str, id: &str, source: &str, target: &str) -> Result<(), Diagnostic> {
    definition_require_ordinary_lifecycle_dependencies(elements)?;
    for identity in [owner, source, target] {
        let node = elements.iter().find(|e| e.id == identity).ok_or_else(|| error("resolved binding input is absent"))?;
        if !metaclass_conforms(&node.kind, "Type") || !scope_boolean(node, "is_implied_included")? {
            return Err(error("resolved binding requires explicitly complete owner and endpoints"));
        }
        if !matches!(definition_general_type_inputs(elements, node)?, DefinitionGeneralTypes::Ready(_)) {
            return Err(error("resolved binding input generalizations are unavailable"));
        }
    }
    for identity in [source, target] {
        let endpoint = elements.iter().find(|e| e.id == identity).unwrap();
        if !metaclass_conforms(&endpoint.kind, "Feature") || definition_feature_owner(elements, endpoint)?.is_none() {
            return Err(error("resolved binding endpoints require canonical owned Feature inputs"));
        }
        let Some((_, variable)) = definition_owning_featuring_input(elements, endpoint)? else {
            return Err(error("resolved binding endpoint has no assessed owning-type provider"));
        };
        if variable { return Err(error("resolved binding requires fixed endpoints")); }
        // Validate derived featuring independently of a raw completeness flag.
        // Missing explicit fixed-owner featuring remains a model defect.
        let (_, endpoint_owner) = definition_feature_owner(elements, endpoint)?.unwrap();
        if !definition_featuring_types(elements, endpoint)?.iter().any(|e| e.id == endpoint_owner.id) {
            return Err(error("resolved binding endpoint is missing required owning-Type featuring"));
        }
    }
    definition_finish_fresh_binding(elements, owner, id, source, target)
}

fn definition_finish_fresh_binding(elements: &mut Vec<KirElement>,
    owner: &str, id: &str, source: &str, target: &str) -> Result<(), Diagnostic> {
    definition_finish_fresh_binding_query(elements,owner,id,source,target,ecore_model::ReferenceCompleteness::Closed)
        .map_err(|failure| failure.into_diagnostic_at("definition_finish_fresh_binding external boundary"))
}

fn definition_finish_fresh_binding_query(elements: &mut Vec<KirElement>,
    owner: &str, id: &str, source: &str, target: &str, boundary: ecore_model::ReferenceCompleteness) -> Result<(), QueryFailure> {
    definition_finish_fresh_binding_observed_query(elements,owner,id,source,target,boundary,id,&|_|{})
}

fn definition_finish_fresh_binding_observed_query(elements: &mut Vec<KirElement>,
    owner: &str, id: &str, source: &str, target: &str, boundary: ecore_model::ReferenceCompleteness,
    receiver: &str, observer: &dyn for<'e> Fn(DefinitionConstructionEvent<'e>)) -> Result<(), QueryFailure> {
    let mut staged=elements.clone();
    let result=definition_finish_fresh_binding_observed_query_in_stage(&mut staged,owner,id,source,target,boundary,receiver,observer)?;
    *elements=staged;
    Ok(result)
}

// Private worker: the caller must discard its entire stage on any failure.
fn definition_finish_fresh_binding_observed_query_in_stage(elements: &mut Vec<KirElement>,
    owner: &str, id: &str, source: &str, target: &str, boundary: ecore_model::ReferenceCompleteness,
    receiver: &str, observer: &dyn for<'e> Fn(DefinitionConstructionEvent<'e>)) -> Result<(), QueryFailure> {

    definition_materialize_binding_defaults_observed_query_in_stage(elements,owner,id,source,target,boundary,receiver,observer)?;
    // The constructor establishes exactly two fresh, fixed Feature ends under
    // ordinary memberships. The shared stage has computed default/participant/
    // positional generalizations, reduction and owning/context featuring. The
    // exclusions above eliminate value bindings, expression ends, crossing and
    // specialized write contributions. No pre-existing Type is marked complete.
    let ids=[id.to_owned(),format!("{id}.end.0"),format!("{id}.end.1")];
    for identity in &ids {
        let node=elements.iter_mut().find(|e|e.id==*identity).ok_or_else(||query_failure("missing constructed lifecycle Type"))?;
        if !definition_no_additional_members(node)? {return Err(query_failure("binding lifecycle requires an additional-member producer"));}
        node.properties.insert("is_implied_included".into(),json!(true));
    }
    // Re-enter the ordinary public semantic services on the completed graph.
    // Their inherited-end/general dependencies must still be resolvable; any
    // failure discards the entire transaction, including the completion flags.
    let connector=elements.iter().find(|e|e.id==id).ok_or_else(||query_failure("completed connector is absent"))?;
    let index=elements.iter().map(|e|(e.id.as_str(),e)).collect();
    let query=DefinitionNameQuery::observed(elements,&index,observer);
    query.trace(DefinitionConstructionPhase::LiteralStageStarted,DefinitionConstructionPhase::LiteralStageFinished,
        receiver,Some(&connector.kind),Some("binding_projection"),|| {
            for field in ["source","target","related_feature"] {
                definition_reference_targets_typed_query(&query,connector,field)?;
            }
            Ok::<_,QueryFailure>(())
        })?;
    if let Some(issue)=ecore_model::validate_publication(elements,boundary).first() {
        return Err(query_failure(format!("invalid completed binding: {}",issue.message)));
    }

    Ok(())
}

// Private batch worker: caller owns and must discard the complete transaction
// on any failure. All fresh connectors share one default/reduction write stage.
fn definition_finish_fresh_binding_batch_in_stage(elements:&mut Vec<KirElement>,
    bindings:&[(&str,&str,&str,&str)],boundary:ecore_model::ReferenceCompleteness)
    -> Result<(),QueryFailure> {
    let mut owners=Vec::new();
    for (owner,id,source,target) in bindings {
        definition_materialize_binding_structure_with_boundary_in_stage(elements,owner,id,source,target,boundary)?;
        owners.extend([(*id).to_owned(),format!("{id}.end.0"),format!("{id}.end.1")]);
    }
    let prefixes=owners.iter().map(|id|format!("{id}.defaults")).collect::<Vec<_>>();
    let defaults=owners.iter().zip(&prefixes).map(|(id,prefix)|(id.as_str(),prefix.as_str())).collect::<Vec<_>>();
    definition_materialize_feature_defaults_query(elements,&defaults,boundary)?;
    for owner in &owners {
        definition_materialize_owning_type_featuring_in_stage(elements,owner,&format!("{owner}.featuring"))?;
    }
    // Flush specialization contributions before TypeFeaturing, preserving order
    // within each group exactly as the independent upstream stage does.
    for owner in &owners {
        let node=elements.iter().find(|node|node.id==*owner).ok_or_else(||query_failure("fresh binding owner is absent"))?;
        let relations=stored_children(elements,node,"owned_relationship")?;
        let ordered=relations.iter().filter(|relation|!metaclass_conforms(&relation.kind,"TypeFeaturing"))
            .chain(relations.iter().filter(|relation|metaclass_conforms(&relation.kind,"TypeFeaturing")))
            .map(|relation|relation.id.clone()).collect::<Vec<_>>();
        if !definition_no_additional_members(node)? {
            return Err(query_failure("fresh binding requires an additional-member semantic producer"));
        }
        let node=elements.iter_mut().find(|node|node.id==*owner).ok_or_else(||query_failure("fresh binding owner vanished"))?;
        node.properties.insert("owned_relationship".into(),json!(ordered));
        node.properties.insert("is_implied_included".into(),json!(true));
    }
    let index=elements.iter().map(|node|(node.id.as_str(),node)).collect();
    let query=DefinitionNameQuery::new(elements,&index);
    for (_,id,_,_) in bindings {
        let connector=query.index.get(*id).copied().ok_or_else(||query_failure("fresh binding absent at projection boundary"))?;
        for field in ["source","target","related_feature"] {definition_reference_targets_typed_query(&query,connector,field)?;}
    }
    if let Some(issue)=ecore_model::validate_publication(elements,boundary).first() {
        return Err(query_failure(format!("invalid fresh binding batch: {}",issue.message)));
    }
    Ok(())
}

/// Construct and place a binding using the shared context computation.
/// This consumes already-selected endpoints; connector/end transformation is
/// separate. All context queries run before any adoption or graph mutation.
pub(crate) fn definition_materialize_binding_structure(elements: &mut Vec<KirElement>,
    owner_id: &str, id: &str, source_id: &str, target_id: &str) -> Result<(), Diagnostic> {
    definition_materialize_binding_structure_with_boundary(elements,owner_id,id,source_id,target_id,ecore_model::ReferenceCompleteness::Closed).map_err(|failure| failure.into_diagnostic_at("definition_materialize_binding_structure"))
}

// Private construction boundary: unrelated pending references may remain only
// inside the document transaction. Every selected endpoint/ownership contract
// is still checked, and the document's final Closed publication is unchanged.
fn definition_materialize_binding_structure_with_boundary(elements: &mut Vec<KirElement>,
    owner_id: &str, id: &str, source_id: &str, target_id: &str,
    boundary: ecore_model::ReferenceCompleteness) -> Result<(), QueryFailure> {
    let mut staged=elements.clone();
    let result=definition_materialize_binding_structure_with_boundary_in_stage(&mut staged,owner_id,id,source_id,target_id,boundary)?;
    *elements=staged;
    Ok(result)
}

// Private worker: the caller must discard its entire stage on any failure.
fn definition_materialize_binding_structure_with_boundary_in_stage(elements: &mut Vec<KirElement>,
    owner_id: &str, id: &str, source_id: &str, target_id: &str,
    boundary: ecore_model::ReferenceCompleteness) -> Result<(), QueryFailure> {
    let lookup=|id: &str|elements.iter().find(|e|e.id==id).ok_or_else(||query_failure("binding placement endpoint is absent"));
    let owner=lookup(owner_id)?;
    if !metaclass_conforms(&owner.kind,"Type") {return Err(query_failure("binding placement requires a Type owner"));}
    let context=definition_binding_context_query(elements,lookup(source_id)?,lookup(target_id)?)?.map(|e|e.id.clone());
    let feature=context.as_deref()==Some(owner_id);

    definition_append_binding_connector_with_boundary_in_stage(elements,id,Some(source_id),Some(target_id),boundary)?;
    if let Some(context)=context.filter(|_|!feature) {
        let mut relation=fresh_definition_element(format!("{id}.context"),"TypeFeaturing")?;
        // TypeAdapter queues this context via addFeaturingTypesTo; the native
        // physical relationship represents FeatureUtil's implied queue flush.
        relation.properties.insert("is_implied".into(),json!(true));
        relation.properties.insert("feature_of_type".into(),json!(id));
        relation.properties.insert("featuring_type".into(),json!(context));
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,elements.iter_mut().find(|e|e.id==id).ok_or_else(||query_failure("constructed binding absent from private stage"))?,&mut relation)?;
        elements.push(relation);
    }
    let mut member=fresh_definition_element(format!("{id}.membership"),if feature {"FeatureMembership"}else{"OwningMembership"})?;
    let connector=elements.iter_mut().find(|e|e.id==id).ok_or_else(||query_failure("constructed binding absent from private stage"))?;
    connector.properties.insert("is_implied".into(),json!(true));
    ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS,&mut member,connector)?;
    ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,elements.iter_mut().find(|e|e.id==owner_id).ok_or_else(||query_failure("binding placement owner absent from private stage"))?,&mut member)?;
    elements.push(member);
    if let Some(issue)=ecore_model::validate_publication(elements,boundary).first() {return Err(query_failure(format!("invalid binding placement: {}",issue.message)));}

    Ok(())
}

/// Handwritten ConnectorUtil.createBindingConnector construction dependency.
/// This creates canonical ends and adopts detached endpoints; it does not run
/// connector transformation, choose a context or declare implied completeness.
pub(crate) fn definition_append_binding_connector(elements: &mut Vec<KirElement>, id: &str,
    source: Option<&str>, target: Option<&str>) -> Result<(), Diagnostic>
{
    definition_append_binding_connector_with_boundary(elements,id,source,target,ecore_model::ReferenceCompleteness::Closed)
}

fn definition_append_binding_connector_with_boundary(elements: &mut Vec<KirElement>, id: &str,
    source: Option<&str>, target: Option<&str>, boundary: ecore_model::ReferenceCompleteness)
    -> Result<(), Diagnostic> {
    let mut staged=elements.clone();
    let result=definition_append_binding_connector_with_boundary_in_stage(&mut staged,id,source,target,boundary)?;
    *elements=staged;
    Ok(result)
}

// Private worker: the caller must discard its entire stage on any failure.
fn definition_append_binding_connector_with_boundary_in_stage(elements: &mut Vec<KirElement>, id: &str,
    source: Option<&str>, target: Option<&str>, boundary: ecore_model::ReferenceCompleteness)
    -> Result<(), Diagnostic> {
    let check = |graph: &[KirElement]| -> Result<(), Diagnostic> {
        let issues = ecore_model::validate_publication(graph, boundary);
        if let Some(issue) = issues.first() {
            return Err(error(format!("invalid binding graph: {}.{}: {}", issue.element_id, issue.field, issue.message)));
        }
        Ok(())
    };
    check(elements)?;

    let mut connector = fresh_definition_element(id.into(), "BindingConnector")?;
    for (ordinal, related) in [source, target].into_iter().enumerate() {
        let mut end = fresh_definition_element(format!("{id}.end.{ordinal}"), "Feature")?;
        ecore_model::validate_value(&end.kind, "is_end", &json!(true)).map_err(error)?;
        end.properties.insert("is_end".into(), json!(true));
        if let Some(related) = related {
            let endpoint = elements.iter().find(|e| e.id == related).ok_or_else(|| error("missing binding endpoint"))?;
            ecore_model::validate_reference_endpoint("ReferenceSubsetting", "referenced_feature", &endpoint.kind).map_err(error)?;
            let relationship = endpoint.properties.get("owning_relationship").and_then(Value::as_str)
                .and_then(|id| elements.iter().find(|e| e.id == id));
            let adopt = relationship.is_none_or(|r| r.properties.get("owning_related_element").is_none_or(Value::is_null));
            let has_relationship = relationship.is_some();
            let mut reference = fresh_definition_element(format!("{id}.end.{ordinal}.reference"), "ReferenceSubsetting")?;
            if adopt {
                if endpoint.properties.get("owner").is_some_and(|v| !v.is_null()) {
                    return Err(error("binding adoption requires canonical ownership, not an owner snapshot"));
                }
                if has_relationship {
                    // An unowned membership has no semantic owner. Reuse the
                    // imported-contract move service to remove its old inverse.
                    let reference_id = reference.id.clone();
                    elements.push(reference);
                    ecore_model::move_contained_element(elements, related, &reference_id, "owned_related_element").map_err(error)?;
                    reference = elements.pop().ok_or_else(|| error("missing elements reference"))?;
                } else {
                    let endpoint = elements.iter_mut().find(|e| e.id == related).ok_or_else(|| error("missing binding endpoint"))?;
                    ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS, &mut reference, endpoint)?;
                }
            }
            reference.properties.insert("referenced_feature".into(), json!(related));
            ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, &mut end, &mut reference)?;
            elements.push(reference);
        }
        let mut membership = fresh_definition_element(format!("{id}.end.{ordinal}.membership"), "FeatureMembership")?;
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS, &mut membership, &mut end)?;
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, &mut connector, &mut membership)?;
        elements.extend([end, membership]);
    }
    elements.push(connector);
    check(elements)?;

    Ok(())
}

/// Handwritten Pilot chainFeatures dependency over imported Ecore contracts.
/// Expand direct chains once, preserving order/repeats; do not transform expressions.
pub(crate) fn definition_append_feature_chain(
    elements: &mut Vec<KirElement>, id: &str, inputs: &[&str],
) -> Result<(), Diagnostic> {
    definition_append_feature_chain_query(elements,id,inputs,ecore_model::ReferenceCompleteness::Closed)
        .map_err(|failure| failure.into_diagnostic_at("definition_append_feature_chain external boundary"))
}

fn definition_append_feature_chain_query(
    elements: &mut Vec<KirElement>, id: &str, inputs: &[&str],
    boundary: ecore_model::ReferenceCompleteness) -> Result<(), QueryFailure> {
    let mut staged=elements.clone();
    let result=definition_append_feature_chain_query_in_stage(&mut staged,id,inputs,boundary)?;
    *elements=staged;
    Ok(result)
}

// Private worker: the caller must discard its entire stage on any failure.
fn definition_append_feature_chain_query_in_stage(
    elements: &mut Vec<KirElement>, id: &str, inputs: &[&str],
    boundary: ecore_model::ReferenceCompleteness) -> Result<(), QueryFailure> {
    let mut targets = Vec::new();
    let issues = ecore_model::validate_publication(elements, boundary);
    if let Some(issue) = issues.first() { return Err(query_failure(format!("invalid chain input graph: {}.{}: {}", issue.element_id, issue.field, issue.message))); }
    for input in inputs {
        let feature = elements.iter().find(|e| e.id == *input)
            .ok_or_else(|| query_failure(format!("missing chain input {input}")))?;
        ecore_model::validate_reference_endpoint("FeatureChaining", "chaining_feature", &feature.kind).map_err(query_failure)?;
        let index=elements.iter().map(|e|(e.id.as_str(),e)).collect();
        let chain=definition_chain_reference_targets_typed_query(&DefinitionNameQuery::new(elements,&index),feature,"chaining_feature")?.iter().map(|e|e.id.clone()).collect::<Vec<_>>();
        if chain.is_empty() { targets.push(feature.id.clone()); } else { targets.extend(chain); }
    }

    definition_append_direct_feature_chain_in_stage(elements,id,&targets,boundary)
}

/// Shared physical constructor. Exact normative sequences must not be flattened
/// by an upstream utility's implementation convention.
fn definition_append_direct_feature_chain_in_stage(elements:&mut Vec<KirElement>,id:&str,
    targets:&[String],boundary:ecore_model::ReferenceCompleteness)->Result<(),QueryFailure> {
    for target in targets {
        let endpoint=elements.iter().find(|node|node.id==*target)
            .ok_or_else(||query_failure("direct chain endpoint is absent"))?;
        ecore_model::validate_reference_endpoint("FeatureChaining","chaining_feature",&endpoint.kind).map_err(query_failure)?;
    }
    let mut feature = fresh_definition_element(id.into(), "Feature")?;
    for (ordinal, target) in targets.iter().enumerate() {
        let mut relation = fresh_definition_element(format!("{id}.chain.{ordinal}"), "FeatureChaining")?;
        relation.properties.insert("chaining_feature".into(), json!(target));
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, &mut feature, &mut relation)?;
        elements.push(relation);
    }
    elements.push(feature);
    let issues = ecore_model::validate_publication(elements, boundary);
    if let Some(issue) = issues.first() { return Err(query_failure(format!("invalid constructed chain: {}.{}: {}", issue.element_id, issue.field, issue.message))); }

    Ok(())
}

pub(super) fn append(
    owner: &mut KirElement,
    operand: KirElement,
    elements: &mut Vec<KirElement>,
) -> Result<(), Diagnostic> {
    let binding = ecore_model::feature(&owner.kind, "operand")
        .ok_or_else(|| error("owner has no operand binding"))?;
    if binding.owner != "InvocationExpression"
        || !binding.derived
        || !binding.transient
        || !binding.volatile
        || !binding.containment
        || !binding.ordered
        || !binding.unique
        || binding.opposite.is_some()
        || binding.upper != -1
    {
        return Err(error("unsupported derived operand contract"));
    }
    let dispatch = binding
        .setting_delegate
        .as_ref()
        .ok_or_else(|| error("missing operand delegate"))?;
    if dispatch.uri != "http://www.omg.org/spec/SysML"
        || dispatch.status != "custom_setting_delegate_source"
        || dispatch.candidates
            != ["org.omg.sysml.delegate.setting.InvocationExpression_operand_SettingDelegate"]
    {
        return Err(error(
            "operand delegate requires a different native implementation",
        ));
    }
    ecore_model::validate_reference_endpoint(&owner.kind, "operand", &operand.kind)
        .map_err(error)?;
    if owner.properties.contains_key("operand") {
        return Err(error(
            "operand is a parsing adapter, not stored containment",
        ));
    }
    for field in ["owning_relationship", "owning_related_element"] {
        if operand.properties.get(field).is_some_and(|v| !v.is_null()) {
            return Err(error("append requires a fresh uncontained operand"));
        }
    }
    let ordinal = match owner.properties.get("owned_relationship") {
        None => 0,
        Some(Value::Array(values)) => values.len(),
        _ => return Err(error("malformed owned relationships")),
    };
    let prefix = format!("{}.operand.{ordinal}", owner.id);
    let membership_id = format!("{prefix}.membership");
    let parameter_id = format!("{prefix}.parameter");
    let value_id = format!("{prefix}.value");
    let mut ids: BTreeSet<&str> = elements.iter().map(|e| e.id.as_str()).collect();
    for id in [
        &owner.id,
        &operand.id,
        &membership_id,
        &parameter_id,
        &value_id,
    ] {
        if id.is_empty() || !ids.insert(id) {
            return Err(error("duplicate or empty construction identity"));
        }
    }
    let make = |id: String, kind: &str| {
        let mut element = KirElement {
            id,
            kind: format!("SysML::{kind}"),
            layer: owner.layer,
            properties: BTreeMap::from([("metadata".into(), construction_metadata(owner, kind))]),
        };
        ecore_model::initialize_fresh_structure(&mut element);
        element
    };
    let mut membership = make(membership_id.clone(), "ParameterMembership");
    let mut parameter = make(parameter_id.clone(), "Feature");
    let mut value = make(value_id.clone(), "FeatureValue");
    for (element, field, literal) in [
        (&mut membership, "visibility", "private"),
        (&mut parameter, "direction", "in"),
        (&mut value, "visibility", "public"),
    ] {
        ecore_model::validate_value(&element.kind, field, &json!(literal)).map_err(error)?;
        element.properties.insert(field.into(), json!(literal));
    }
    // Stage every change: no caller-owned graph is mutated on failure.
    let mut staged_owner = owner.clone();
    let mut staged_operand = operand;
    use ecore_ownership_generated::{OWNED_ELEMENTS, OWNED_RELATIONSHIPS};
    ecore_ownership::attach(&OWNED_ELEMENTS, &mut value, &mut staged_operand)?;
    ecore_ownership::attach(&OWNED_RELATIONSHIPS, &mut parameter, &mut value)?;
    ecore_ownership::attach(&OWNED_ELEMENTS, &mut membership, &mut parameter)?;
    ecore_ownership::attach(&OWNED_RELATIONSHIPS, &mut staged_owner, &mut membership)?;
    *owner = staged_owner;
    elements.extend([membership, parameter, value, staged_operand]);
    Ok(())
}

/// Bounded constructor assignments resolved by javac at build time.
/// These are separate from Ecore literals and other constructor/delegate effects.
fn initialize_expression_constructor(owner: &mut KirElement) -> Result<(), Diagnostic> {
    let kind = owner.kind.rsplit("::").next().unwrap_or(&owner.kind);
    let operator = super::super::ecore_defaults::constructor_attribute(kind, "operator");
    if operator.is_none()
        && kind != "OperatorExpression"
        && metaclass_conforms(kind, "OperatorExpression")
    {
        return Err(error("unimplemented specialized operator constructor"));
    }
    if let Some(operator) = operator {
        ecore_model::validate_value(kind, "operator", &json!(operator)).map_err(error)?;
        owner.properties.insert("operator".into(), json!(operator));
    }
    Ok(())
}

/// Convert generated expression captures through the existing handwritten
/// operand delegate. All output is local until success. This is intentionally not
/// wired to production parsing before full rule qualification.
#[allow(dead_code)]
fn materialize_generated_expression(
    tree: &crate::xtext_fragment::Match,
    id: &str,
) -> Result<(KirElement, Vec<KirElement>), Diagnostic> {
    materialize_generated_with_links(tree, id, &|_| Err(error("unresolved generated reference")))
}

/// A private structural view of one immutable graph. Slice identity prevents a
/// same-ID copy from borrowing stale properties or cached containment facts.
/// All semantic algorithms remain explicit native services over imported contracts.
struct DefinitionReferenceView<'g> {
    graph: &'g [KirElement],
    index: BTreeMap<&'g str, &'g KirElement>,
}

impl<'g> DefinitionReferenceView<'g> {
    fn new(graph: &'g [KirElement]) -> Result<Self, Diagnostic> {
        let index = graph.iter().map(|e| (e.id.as_str(), e)).collect::<BTreeMap<_, _>>();
        if index.len() != graph.len() {
            return Err(error("duplicate scope graph identity"));
        }
        Ok(Self { graph, index })
    }

    fn is_for(&self, graph: &[KirElement]) -> bool {
        std::ptr::eq(self.graph, graph)
    }
}

/// Context supplied to a native scope service. Ancestors run from root to
/// immediate container, retaining the imported construction graph and call site.
/// This is a linking interface, not a choice of namespace/scope algorithm.
#[allow(dead_code)] // Ancestor and namespace fields also support controlled consumers.
struct GeneratedReferenceSite<'s> {
    reference: &'s crate::xtext_fragment::PendingReference,
    owner_id: &'s str,
    owner_kind: &'s str,
    feature: &'static ecore_model::FeatureContract,
    ancestors: &'s [&'s crate::xtext_fragment::Match],
    /// Complete containment graph, including delegate-created wrappers. Earlier
    /// references may be bound; unresolved dependencies remain absent.
    graph: &'s [KirElement],
    /// Shared only while this field attempt borrows the same immutable graph.
    /// A foreign graph supplied by a controlled scope service gets a fresh view.
    graph_view: Option<&'s DefinitionReferenceView<'s>>,
    parent_namespace: Option<&'s KirElement>,
    non_expression_namespace: Option<&'s KirElement>,
    /// Active pending-field dependencies; import scope excludes these imports
    /// while resolving their targets, as upstream lazy linking does.
    resolution_path: &'s [(String, String)],
}

/// Handwritten containment traversal; classifier and reciprocal ownership
/// checks use imported Ecore contracts. Missing external lexical context is
/// represented by None at the constructed root, not guessed from a name.
fn generated_parent_namespace<'g>(
    graph: &'g [KirElement],
    identity: &str,
) -> Result<Option<&'g KirElement>, Diagnostic> {
    let index: BTreeMap<_, _> = graph.iter().map(|e| (e.id.as_str(), e)).collect();
    if index.len() != graph.len() {
        return Err(error("duplicate scope graph identity"));
    }
    generated_parent_namespace_indexed(&index, identity)
}

fn generated_parent_namespace_indexed<'g>(index: &BTreeMap<&str, &'g KirElement>,
    identity: &str) -> Result<Option<&'g KirElement>, Diagnostic> {
    generated_parent_namespace_with_container(index,identity,|current|scope_container(index,current))
}

fn generated_parent_namespace_query<'g>(query: &DefinitionNameQuery<'g, '_>, identity: &str)
    -> Result<Option<&'g KirElement>,Diagnostic> {
    if query.index.len()!=query.graph.len() {return Err(error("duplicate scope graph identity"));}
    generated_parent_namespace_with_container(query.index,identity,|current|scope_container_query(query,current))
}

fn generated_parent_namespace_with_container<'g>(index: &BTreeMap<&str,&'g KirElement>,
    identity: &str, container: impl Fn(&KirElement)->Result<Option<&'g KirElement>,Diagnostic>)
    -> Result<Option<&'g KirElement>,Diagnostic> {
    let mut current = *index
        .get(identity)
        .ok_or_else(|| error("scope owner is absent"))?;
    let mut visited = BTreeSet::new();
    loop {
        if !visited.insert(current.id.as_str()) {
            return Err(error("cyclic scope containment"));
        }
        let Some(parent) = container(current)? else {
            return Ok(None);
        };
        let parent_id = parent.id.as_str();
        if visited.contains(parent_id) {
            return Err(error("cyclic scope containment"));
        }
        if metaclass_conforms(&parent.kind, "Namespace") {
            return Ok(Some(parent));
        }
        current = parent;
    }
}

/// Immediate containment, validated against both ends of the imported opposite.
fn scope_container<'g>(
    index: &BTreeMap<&str, &'g KirElement>,
    current: &KirElement,
) -> Result<Option<&'g KirElement>, Diagnostic> {
    let mut containers = Vec::new();
    for (field, value) in &current.properties {
        if value.is_null() {
            continue;
        }
        if ecore_model::feature(&current.kind, field).is_some_and(|f| f.container && !f.derived) {
            let id = value
                .as_str()
                .filter(|id| !id.is_empty())
                .ok_or_else(|| error("invalid scope container identity"))?;
            containers.push((field.as_str(), id));
        }
    }
    let (inverse, parent_id) = match containers.as_slice() {
        [] => return Ok(None),
        [entry] => *entry,
        _ => return Err(error("conflicting scope containers")),
    };
    let parent = *index
        .get(parent_id)
        .ok_or_else(|| error("scope container is absent"))?;
    let reciprocal = parent.properties.iter().any(|(field, value)| {
        let contains = value.as_str() == Some(current.id.as_str())
            || value
                .as_array()
                .is_some_and(|v| v.iter().any(|v| v.as_str() == Some(current.id.as_str())));
        contains
            && ecore_model::containment_inverse(&parent.kind, field, &current.kind)
                .is_ok_and(|f| f.field == inverse)
    });
    if !reciprocal {
        return Err(error("scope containment lacks reciprocal ownership"));
    }
    Ok(Some(parent))
}

/// Handwritten dependencies of NamespaceUtil: owningMembership and
/// owningNamespace are derived from stored containment, never cached guesses.
/// A detached fragment has no external lexical namespace and returns None.
#[cfg(test)]
fn generated_non_expression_namespace<'g>(
    graph: &'g [KirElement],
    identity: &str,
) -> Result<Option<&'g KirElement>, Diagnostic> {
    let view = DefinitionReferenceView::new(graph)?;
    generated_non_expression_namespace_indexed(&view.index, identity)
}

fn generated_non_expression_namespace_indexed<'g>(
    index: &BTreeMap<&str, &'g KirElement>,
    identity: &str,
) -> Result<Option<&'g KirElement>, Diagnostic> {
    generated_non_expression_namespace_with_container(index, identity, |node| scope_container(index, node))
}

fn generated_non_expression_namespace_query<'g>(
    query: &DefinitionNameQuery<'g, '_>,
    identity: &str,
) -> Result<Option<&'g KirElement>, Diagnostic> {
    if query.index.len() != query.graph.len() {
        return Err(error("duplicate scope graph identity"));
    }
    generated_non_expression_namespace_with_container(query.index, identity, |node| scope_container_query(query, node))
}

fn generated_non_expression_namespace_with_container<'g>(
    index: &BTreeMap<&str, &'g KirElement>,
    identity: &str,
    container: impl Fn(&KirElement) -> Result<Option<&'g KirElement>, Diagnostic>,
) -> Result<Option<&'g KirElement>, Diagnostic> {
    let mut element = *index
        .get(identity)
        .ok_or_else(|| error("scope owner is absent"))?;
    let mut visited = BTreeSet::new();
    loop {
        if !visited.insert(element.id.as_str()) {
            return Err(error("cyclic expression scope"));
        }
        let Some(mut namespace) = generated_parent_namespace_with_container(index, &element.id, &container)? else {
            return Ok(None);
        };
        let membership = if metaclass_conforms(&element.kind, "Relationship") {
            Some(element)
        } else {
            container(element)?
                .filter(|e| metaclass_conforms(&e.kind, "OwningMembership"))
        };
        // FeatureValue inside a parameter Feature belongs to the containing
        // instantiation expression's context, as specified by NamespaceUtil.
        if membership.is_some_and(|e| metaclass_conforms(&e.kind, "FeatureValue")) {
            if let Some(owner) = container(namespace)?
                .filter(|e| metaclass_conforms(&e.kind, "OwningMembership"))
            {
                if let Some(outer) = container(owner)?
                    .filter(|e| metaclass_conforms(&e.kind, "InstantiationExpression"))
                {
                    namespace = outer;
                }
            }
        }
        if !metaclass_conforms(&element.kind, "FeatureValue")
            && !metaclass_conforms(&namespace.kind, "InstantiationExpression")
            && !metaclass_conforms(&namespace.kind, "FeatureReferenceExpression")
        {
            return Ok(Some(namespace));
        }
        let Some(owner) = container(namespace)?
            .filter(|e| metaclass_conforms(&e.kind, "OwningMembership"))
        else {
            return Ok(None);
        };
        element = owner;
    }
}

/// Checked stored containment projection, preserving imported collection order.
fn stored_children<'g>(
    graph: &'g [KirElement],
    owner: &KirElement,
    field: &str,
) -> Result<Vec<&'g KirElement>, Diagnostic> {
    let index: BTreeMap<_, _> = graph.iter().map(|e| (e.id.as_str(), e)).collect();
    if index.len() != graph.len() {
        return Err(error("duplicate model identity"));
    }
    stored_children_indexed(&index, owner, field)
}

fn stored_children_indexed<'g>(index: &BTreeMap<&str, &'g KirElement>,
    owner: &KirElement, field: &str) -> Result<Vec<&'g KirElement>, Diagnostic> {
    stored_children_with_container(index, owner, field, |child| scope_container(index, child))
}

fn stored_children_with_container<'g>(
    index: &BTreeMap<&str, &'g KirElement>, owner: &KirElement, field: &str,
    container: impl Fn(&KirElement) -> Result<Option<&'g KirElement>, Diagnostic>,
) -> Result<Vec<&'g KirElement>, Diagnostic> {
    let Some(value) = owner.properties.get(field) else {
        return Ok(Vec::new());
    };
    let values = value
        .as_array()
        .ok_or_else(|| error("invalid containment list"))?;
    let mut result = Vec::new();
    let mut seen = BTreeSet::new();
    for value in values {
        let id = value
            .as_str()
            .ok_or_else(|| error("invalid child identity"))?;
        if !seen.insert(id) {
            return Err(error("duplicate contained identity"));
        }
        let child = *index
            .get(id)
            .ok_or_else(|| error("missing contained element"))?;
        ecore_model::containment_inverse(&owner.kind, field, &child.kind).map_err(error)?;
        if container(child)?.map(|e| e.id.as_str()) != Some(owner.id.as_str()) {
            return Err(error("nonreciprocal contained element"));
        }
        result.push(child);
    }
    Ok(result)
}

/// Derive ownedMembership from canonical reciprocal ownedRelationship storage.
/// The second result identifies whether an Import is present; absence proves an
/// empty importedMembership input, but presence requires the import service.
pub(crate) fn stored_namespace_membership_inputs(
    graph: &[KirElement],
    namespace: &KirElement,
) -> Result<Option<(Value, bool)>, Diagnostic> {
    let index = graph.iter().map(|e| (e.id.as_str(), e)).collect::<BTreeMap<_, _>>();
    stored_namespace_membership_inputs_query(&DefinitionNameQuery::new(graph, &index), namespace)
}

fn stored_namespace_membership_inputs_query(
    query: &DefinitionNameQuery<'_, '_>,
    namespace: &KirElement,
) -> Result<Option<(Value, bool)>, Diagnostic> {
    if !metaclass_conforms(&namespace.kind, "Namespace")
        || !namespace.properties.contains_key("owned_relationship") { return Ok(None); }
    if !ecore_model::has_subset_contract(&namespace.kind, "owned_membership", "owned_relationship") {
        return Err(error("missing imported owned membership subset contract"));
    }
    let target = ecore_model::feature(&namespace.kind, "owned_membership")
        .ok_or_else(|| error("missing imported owned membership contract"))?.target;
    let relationships = stored_children_projection_query(query, namespace, "owned_relationship")?;
    let owned = relationships.iter().filter(|e| metaclass_conforms(&e.kind, target))
        .map(|e| Value::String(e.id.clone())).collect();
    let imports = relationships.iter().any(|e| metaclass_conforms(&e.kind, "Import"));
    Ok(Some((Value::Array(owned), imports)))
}

/// Bounded handwritten membership delegates over stored reciprocal ownership.
/// Absence of ownership data leaves materialized-library adapters responsible;
/// present but invalid data is an error, never a reason to use a stale snapshot.
pub(crate) enum StoredMembershipEndpoint<'g> {
    Unavailable,
    Absent,
    Resolved(&'g KirElement),
}

pub(crate) fn stored_membership_endpoint<'g>(
    graph: &'g [KirElement],
    membership: &'g KirElement,
    requested: &str,
) -> Result<StoredMembershipEndpoint<'g>, Diagnostic> {
    let index=graph.iter().map(|e|(e.id.as_str(),e)).collect::<BTreeMap<_,_>>();
    stored_membership_endpoint_indexed(graph.len(),&index,membership,requested)
}

fn stored_membership_endpoint_indexed<'g>(graph_len: usize, index: &BTreeMap<&str,&'g KirElement>,
    membership: &'g KirElement, requested: &str) -> Result<StoredMembershipEndpoint<'g>, Diagnostic> {
    if requested == "member_element"
        && metaclass_conforms(&membership.kind, "OwningMembership")
        && membership.properties.contains_key("owned_related_element") {
        if index.len()!=graph_len {return Err(error("duplicate model identity"));}
        let children = stored_children_indexed(index, membership, "owned_related_element")?;
        if children.len() != 1 {
            return Err(error("stored owning membership requires exactly one member"));
        }
        return Ok(StoredMembershipEndpoint::Resolved(children[0]));
    }
    if requested == "membership_owning_namespace"
        && membership.properties.contains_key("owning_related_element") {
        if index.len() != graph_len { return Err(error("duplicate model identity")); }
        return Ok(match scope_container(index, membership)? {
            Some(owner) => StoredMembershipEndpoint::Resolved(owner),
            None => StoredMembershipEndpoint::Absent,
        });
    }
    Ok(StoredMembershipEndpoint::Unavailable)
}

/// Handwritten TypeUtil.getOwnedResultParameterOf dependency. This reads the
/// current graph only: inherited results and adapter-generated members require
/// separate services, and must not be inferred from this bounded query.
#[allow(dead_code)]
fn generated_owned_result_parameter<'g>(
    graph: &'g [KirElement],
    identity: &str,
) -> Result<Option<&'g KirElement>, Diagnostic> {
    let index = graph.iter().map(|e| (e.id.as_str(), e)).collect::<BTreeMap<_, _>>();
    generated_owned_result_parameter_query(&DefinitionNameQuery::new(graph, &index), identity)
}

fn generated_owned_result_parameter_query<'g>(
    query: &DefinitionNameQuery<'g, '_>, identity: &str,
) -> Result<Option<&'g KirElement>, Diagnostic> {
    parameter_members::owned_result(query, identity)
        .map_err(|failure| failure.into_diagnostic_at("generated_owned_result_parameter external boundary"))
}

fn specialization_owner_reference<'g>(graph: &'g [KirElement], owner: &KirElement, field: &str) -> Result<Option<&'g KirElement>, Diagnostic> {
    let index = graph.iter().map(|e| (e.id.as_str(), e)).collect();
    specialization_owner_reference_indexed(&index, owner, field)
}

fn specialization_owner_reference_indexed<'g>(index: &BTreeMap<&str, &'g KirElement>,
    owner: &KirElement, field: &str) -> Result<Option<&'g KirElement>, Diagnostic> {
    let contract = ecore_model::redefined_feature(&owner.kind, field).map_err(error)?;
    // Named handwritten Specialization_owningType delegate family. The
    // resolved Ecore delegate selects the expected owner type; canonical
    // reciprocal containment supplies the owner, never a stored snapshot.
    let binding = contract.setting_delegate.as_ref().ok_or_else(|| error("missing specialization owner delegate"))?;
    if binding.uri != "http://www.omg.org/spec/SysML" || binding.status != "custom_setting_delegate_source" {
        return Err(error("unsupported specialization owner delegate"));
    }
    let expected = match binding.candidates {
        ["org.omg.sysml.delegate.setting.Specialization_owningType_SettingDelegate"] => "Type",
        ["org.omg.sysml.delegate.setting.Subsetting_owningFeature_SettingDelegate"]
        | ["org.omg.sysml.delegate.setting.FeatureTyping_owningFeature_SettingDelegate"]
        | ["org.omg.sysml.delegate.setting.ReferenceSubsetting_referencingFeature_SettingDelegate"]
        | ["org.omg.sysml.delegate.setting.CrossSubsetting_crossingFeature_SettingDelegate"] => "Feature",
        _ => return Err(error("unsupported specialization owner implementation")),
    };
    Ok(scope_container(index, owner)?.filter(|target| metaclass_conforms(&target.kind, expected)))
}

/// Read a resolved scalar reference through imported property redefinitions.
/// Derived aliases require their own delegate; absent values are unresolved.
#[track_caller]
fn redefined_reference<'g>(graph: &'g [KirElement], owner: &KirElement, field: &str) -> Result<&'g KirElement, Diagnostic> {
    let boundary=format!("redefined_reference; caller {}",std::panic::Location::caller());
    query_reference(graph, owner, field).map_err(|failure| failure.into_diagnostic_at(&boundary))
}

#[track_caller]
fn redefined_reference_in_view<'g>(query: &DefinitionNameQuery<'g, '_>, owner: &KirElement, field: &str) -> Result<&'g KirElement, Diagnostic> {
    let boundary=format!("redefined_reference; caller {}",std::panic::Location::caller());
    query_reference_in_view(query, owner, field).map_err(|failure| failure.into_diagnostic_at(&boundary))
}

fn query_failure(message: impl Into<String>) -> QueryFailure { error(message).into() }

fn query_reference<'g>(
    graph: &'g [KirElement],
    owner: &KirElement,
    field: &str,
) -> Result<&'g KirElement, QueryFailure> {
    query_reference_with_index(graph, None, owner, field)
}

fn query_reference_in_view<'g>(query: &DefinitionNameQuery<'g, '_>, owner: &KirElement,
    field: &str) -> Result<&'g KirElement, QueryFailure> {
    query_reference_with_index(query.graph, Some(query.index), owner, field)
}

// One contract/validation path serves standalone and immutable indexed reads.
// Missing fields remain typed prerequisites; no failed result is cached.
fn query_reference_with_index<'g>(graph: &'g [KirElement],
    index: Option<&BTreeMap<&str, &'g KirElement>>, owner: &KirElement,
    field: &str) -> Result<&'g KirElement, QueryFailure> {
    let contract = ecore_model::redefined_feature(&owner.kind, field).map_err(query_failure)?;
    if contract.derived && contract.upper == 1 && metaclass_conforms(&owner.kind, "Specialization")
        && matches!(contract.field, "owning_type" | "owning_feature" | "referencing_feature" | "crossing_feature") {
        let target = if let Some(index) = index {
            specialization_owner_reference_indexed(index, owner, contract.field)?
        } else { specialization_owner_reference(graph, owner, contract.field)? };
        return target.ok_or_else(|| query_failure("specialization scalar endpoint has no canonical owner"));
    }
    if contract.derived || contract.upper != 1 {
        return Err(query_failure(
            "reference dispatch requires a derived or collection service",
        ));
    }
    let id = match owner.properties.get(contract.field) {
        None => return Err(QueryFailure::Required(Prerequisite::ReadField {
            owner_id: owner.id.clone(), field: contract.field.into(),
        })),
        Some(value) => value.as_str().ok_or_else(|| query_failure("invalid scalar reference storage"))?,
    };
    let target = if let Some(index) = index.filter(|index| index.len() == graph.len()) {
        index.get(id).copied()
    } else {
        // Preserve the standalone reader's first-target behavior on invalid
        // duplicate graphs. Production consumers reject duplicate identities.
        graph.iter().find(|e| e.id == id)
    }.ok_or_else(|| query_failure("reference target is absent"))?;
    ecore_model::validate_reference_endpoint(&owner.kind, contract.field, &target.kind)
        .map_err(query_failure)?;
    Ok(target)
}

/// Named handwritten FeatureUtil dependency. Imported ancestry, ownership and
/// ordered membership determine the first eligible owned cross-feature.
pub(crate) fn definition_owned_cross_feature<'g>(graph: &'g [KirElement], owner: &'g KirElement)
    -> Result<Option<&'g KirElement>, Diagnostic> {
    if !metaclass_conforms(&owner.kind,"Feature") || !scope_boolean(owner,"is_end")? {return Ok(None);}
    let index=graph.iter().map(|e|(e.id.as_str(),e)).collect::<BTreeMap<_,_>>();
    definition_owned_cross_feature_in_view(&DefinitionNameQuery::new(graph,&index),owner)
}

fn definition_owned_cross_feature_in_view<'g>(query: &DefinitionNameQuery<'g, '_>, owner: &'g KirElement)
    -> Result<Option<&'g KirElement>, Diagnostic> {
    let graph=query.graph;
    if !metaclass_conforms(&owner.kind, "Feature") || !scope_boolean(owner, "is_end")?
        || definition_feature_owner_indexed(graph.len(),query.index,owner)?.is_none() { return Ok(None); }
    for membership in stored_children_projection_query(query, owner, "owned_relationship")? {
        if !metaclass_conforms(&membership.kind, "OwningMembership")
            || metaclass_conforms(&membership.kind, "FeatureMembership")
            || metaclass_conforms(&membership.kind, "FeatureValue") { continue; }
        let children = stored_children_projection_query(query, membership, "owned_related_element")?;
        if children.len() != 1 { return Err(error("owned cross-feature selection requires one owned member")); }
        let candidate = children[0];
        if metaclass_conforms(&candidate.kind, "Feature")
            && !["Multiplicity", "MetadataFeature", "BindingConnector"].iter().any(|kind| metaclass_conforms(&candidate.kind, kind)) {
            return Ok(Some(candidate));
        }
    }
    Ok(None)

}

/// Binary branch of checkFeatureCrossingSpecialization. Construction reuses
/// imported Ecore chain/specialization setters, including adoption of the fresh
/// chain by CrossSubsetting. N-ary featuring and cross-feature typing remain
/// separate prerequisites; no transformation-completeness flag is changed.
pub(crate) fn definition_materialize_binary_crossing(elements: &mut Vec<KirElement>, owner_id: &str, prefix: &str)
    -> Result<bool, Diagnostic> {
    definition_materialize_binary_crossing_query(elements, owner_id, prefix)
        .map_err(|failure| failure.into_diagnostic_at("definition_materialize_binary_crossing"))
}

// The same immutable plan admits a query prerequisite and constructs it. Missing
// chaining fields retain their typed identity; no guessed endpoint is inserted.
fn definition_binary_crossing_inputs_in_view(query: &DefinitionNameQuery<'_, '_>, owner: &KirElement)
    -> Result<Option<[String; 2]>, QueryFailure> {
    if owner.kind.rsplit("::").next() != Some("Feature") {
        return Err(query_failure("crossing construction requires assessed Feature adapter"));
    }
    let Some(cross) = definition_owned_cross_feature_in_view(query, owner)? else { return Ok(None); };
    if stored_children_projection_query(query, owner, "owned_relationship")?.iter()
        .any(|e| metaclass_conforms(&e.kind, "CrossSubsetting")) { return Ok(None); }
    let (_, context) = definition_feature_owner_indexed(query.graph.len(), query.index, owner)?
        .ok_or_else(|| query_failure("crossing owner requires a Type"))?;
    let ends = definition_owned_features_query(query, context, true)?;
    if ends.len() != 2 {
        return Err(query_failure("nonbinary crossing requires constructed featuring and type dependencies"));
    }
    let position = ends.iter().position(|end| end.id == owner.id)
        .ok_or_else(|| query_failure("crossing owner is not an owned end"))?;
    let other = ends[1 - position];
    if scope_boolean(owner, "is_implied_included")? {
        return Err(query_failure("crossing insertion requires incomplete Feature inputs"));
    }
    // KerML's binary crossing rule requires this owned cross-feature as the
    // second endpoint. Compound chains remain a separate normative assessment.
    for input in [other, cross] {
        if !definition_chain_reference_targets_typed_query(query, input, "chaining_feature")?.is_empty() {
            return Err(query_failure("compound end/cross chains require normative crossing assessment"));
        }
    }
    Ok(Some([other.id.clone(), cross.id.clone()]))
}

fn definition_materialize_binary_crossing_query(elements: &mut Vec<KirElement>, owner_id: &str, prefix: &str)
    -> Result<bool, QueryFailure> {
    if let Some(issue) = ecore_model::validate_publication(elements, ecore_model::ReferenceCompleteness::Closed).first() {
        return Err(query_failure(format!("invalid crossing input: {}", issue.message)));
    }
    let index = elements.iter().map(|e| (e.id.as_str(), e)).collect::<BTreeMap<_, _>>();
    if index.len() != elements.len() { return Err(query_failure("duplicate crossing input identity")); }
    let owner = index.get(owner_id).copied().ok_or_else(|| query_failure("crossing owner is absent"))?;
    let Some(inputs) = definition_binary_crossing_inputs_in_view(&DefinitionNameQuery::new(elements, &index), owner)?
        else { return Ok(false); };
    if prefix.is_empty() { return Err(query_failure("crossing requires a nonempty identity prefix")); }
    let mut staged = elements.clone();
    let chain_id = format!("{prefix}.chain");
    definition_append_feature_chain(&mut staged, &chain_id, &[inputs[0].as_str(), inputs[1].as_str()])?;
    definition_append_implied_specialization(&mut staged, &format!("{prefix}.crossing"), "CrossSubsetting", owner_id, &chain_id)?;
    *elements = staged;
    Ok(true)
}

/// Named handwritten checkFeatureOwnedCrossFeatureSpecialization and
/// checkFeatureOwnedCrossFeatureRedefinitionSpecialization dependencies.
/// All queries finish before mutation; incomplete providers remain errors.
pub(crate) fn definition_materialize_owned_cross_specialization(elements: &mut Vec<KirElement>, cross_id: &str, prefix: &str) -> Result<usize, Diagnostic> {
    definition_materialize_owned_cross_specialization_query(elements, cross_id, prefix).map_err(|failure| failure.into_diagnostic_at("definition_materialize_owned_cross_specialization"))
}

fn definition_materialize_owned_cross_specialization_query(
    elements: &mut Vec<KirElement>, cross_id: &str, prefix: &str,
) -> Result<usize, QueryFailure> {
    if let Some(issue) = ecore_model::validate_publication(elements, ecore_model::ReferenceCompleteness::Closed).first() {
        return Err(query_failure(format!("invalid cross specialization input: {}", issue.message)));
    }
    let cross = elements.iter().find(|e| e.id == cross_id).ok_or_else(|| query_failure("cross-feature is absent"))?;
    if cross.kind.rsplit("::").next() != Some("Feature") {
        return Err(query_failure("cross specialization requires assessed Feature adapter"));
    }
    let pending = definition_pending_cross_specializations_query(elements, cross)?;
    if pending.is_empty() { return Ok(0); }
    if scope_boolean(cross, "is_implied_included")? { return Err(query_failure("cross specialization insertion requires incomplete Feature inputs")); }
    if prefix.is_empty() { return Err(query_failure("cross specialization requires a nonempty identity prefix")); }
    let mut staged = elements.clone();
    for (index, (kind, target)) in pending.iter().enumerate() {
        definition_append_implied_specialization(&mut staged, &format!("{prefix}.{index}"), kind, cross_id, target)?;
    }
    *elements = staged;
    Ok(pending.len())
}

// Compare semantic obligations with canonical stored contributions once, so
// construction, provider admission and the linker share the same readiness rule.
#[cfg(test)]
fn definition_pending_cross_specializations(graph: &[KirElement], cross: &KirElement) -> Result<Vec<(&'static str, String)>, Diagnostic> {
    definition_pending_cross_specializations_query(graph, cross).map_err(|failure| failure.into_diagnostic_at("definition_pending_cross_specializations"))
}

fn definition_pending_cross_specializations_query(graph: &[KirElement], cross: &KirElement)
    -> Result<Vec<(&'static str, String)>, QueryFailure> {
    let index=graph.iter().map(|e|(e.id.as_str(),e)).collect::<BTreeMap<_,_>>();
    definition_pending_cross_specializations_in_view(&DefinitionNameQuery::new(graph,&index),cross)
}

fn definition_pending_cross_specializations_in_view(query: &DefinitionNameQuery<'_, '_>, cross: &KirElement)
    -> Result<Vec<(&'static str, String)>, QueryFailure> {
    let Some(contributions) = definition_required_cross_specializations_in_view(query, cross)? else { return Ok(Vec::new()); };
    let relationships = stored_children_projection_query(query, cross, "owned_relationship")?;
    let mut pending = Vec::new();
    for (kind, target) in contributions {
        let mut present = false;
        for relation in &relationships {
            if metaclass_conforms(&relation.kind, kind) && query_reference_in_view(query, relation, "general")?.id == target {
                present = true;
                break;
            }
        }
        if !present && !pending.contains(&(kind, target.clone())) { pending.push((kind, target)); }
    }
    Ok(pending)

}

// Shared specification obligations used by construction and provider admission.
fn definition_required_cross_specializations_in_view(query: &DefinitionNameQuery<'_, '_>, cross: &KirElement)
    -> Result<Option<Vec<(&'static str, String)>>, QueryFailure> {
    if cross.kind.rsplit("::").next() != Some("Feature") { return Ok(None); }
    let Some(owner) = generated_parent_namespace_query(query, &cross.id)? else { return Ok(None); };
    if definition_owned_cross_feature_in_view(query, owner)?.map(|e| e.id.as_str()) != Some(cross.id.as_str()) { return Ok(None); }
    let mut contributions = Vec::new();
    for target in definition_feature_types_in_view(query, owner)? { contributions.push(("FeatureTyping", target.id.clone())); }
    for redefined in definition_redefined_features_typed_query(query, owner, false)? {
        if scope_boolean(redefined, "is_end")? {
            if let Some(target) = definition_cross_feature_in_view(query, redefined)? { contributions.push(("Subsetting", target.id.clone())); }
        }
    }
    if contributions.iter().any(|(_, target)| target == &cross.id) {
        return Err(query_failure("self-dependent cross specialization requires separate assessment"));
    }
    Ok(Some(contributions))

}

/// Binary checkFeatureOwnedCrossFeatureTypeFeaturing dependency. Effective
/// ends (including inheritance) and end types come from the shared queries.
/// Nonbinary Cartesian products remain an explicit separate dependency.
// Handwritten checkFeatureOwnedCrossFeatureTypeFeaturing consumer. Binary
// crossing uses the actual other effective end's type set; absence is concluded
// only after its full native type provider succeeds. This is a cold projection,
// not physical insertion, cross lifecycle completion or n-ary product support.
fn definition_binary_cross_featuring_targets_in_view<'g>(query:&DefinitionNameQuery<'g, '_>, cross:&'g KirElement)
    -> Result<Option<Vec<&'g KirElement>>,QueryFailure> {
    if cross.kind.rsplit("::").next()!=Some("Feature") {return Ok(None);}
    let Some(owner)=generated_parent_namespace_query(query,&cross.id)? else{return Ok(None);};
    if definition_owned_cross_feature_in_view(query,owner)?.is_none_or(|feature|feature.id!=cross.id) {return Ok(None);}
    let Some((_,context))=definition_feature_owner_indexed(query.graph.len(),query.index,owner)? else {
        return Err(query_failure("cross featuring requires the actual owning Type"));
    };
    let key=(cross.id.clone(),"native:binary-cross-featuring".to_owned());
    if !query.active_reference_projections.borrow_mut().insert(key.clone()) {
        return Err(query_failure("cyclic binary cross featuring dependency"));
    }
    let answer=(||{
        let ends=definition_end_features_query(query,context,false)?;
        if ends.len()!=2 {return Err(query_failure("nonbinary cross featuring requires Cartesian-product semantics"));}
        let position=ends.iter().position(|end|end.id==owner.id)
            .ok_or_else(||query_failure("cross featuring owner is absent from effective ends"))?;
        Ok(Some(definition_feature_types_in_view(query,ends[1-position])?))
    })();
    query.active_reference_projections.borrow_mut().remove(&key);answer
}

pub(crate) fn definition_materialize_binary_cross_featuring(
    elements: &mut Vec<KirElement>, cross_id: &str, prefix: &str,
) -> Result<usize, Diagnostic> {
    if let Some(issue) = ecore_model::validate_publication(elements, ecore_model::ReferenceCompleteness::Closed).first() {
        return Err(error(format!("invalid cross featuring input: {}", issue.message)));
    }
    let cross = elements.iter().find(|e| e.id == cross_id).ok_or_else(|| error("cross-feature is absent"))?;
    if cross.kind.rsplit("::").next() != Some("Feature") { return Err(error("cross featuring requires assessed Feature adapter")); }
    let Some(owner) = generated_parent_namespace(elements, cross_id)? else { return Ok(0); };
    if definition_owned_cross_feature(elements, owner)?.map(|e| e.id.as_str()) != Some(cross_id) { return Ok(0); }
    if !definition_owned_type_featuring(elements, cross)?.is_empty() { return Ok(0); }
    let (_, context) = definition_feature_owner(elements, owner)?.ok_or_else(|| error("cross featuring requires owning Type"))?;
    let ends = definition_end_features(elements, context, false)?;
    if ends.len() != 2 { return Err(error("nonbinary cross featuring requires Cartesian-product assessment")); }
    let position = ends.iter().position(|end| end.id == owner.id).ok_or_else(|| error("owning end is absent from effective ends"))?;
    let targets = definition_feature_types(elements, ends[1 - position])?;
    if targets.is_empty() { return Ok(0); }
    if scope_boolean(cross, "is_implied_included")? { return Err(error("cross featuring insertion requires incomplete Feature inputs")); }
    if prefix.is_empty() { return Err(error("cross featuring requires a nonempty identity prefix")); }
    if elements.iter().any(|e| e.properties.keys().any(|f| ecore_model::feature(&e.kind, f).is_some_and(|c| c.derived || c.volatile))) {
        return Err(error("cross featuring requires derived-value recomputation"));
    }
    let index = elements.iter().map(|e| (e.id.as_str(), e)).collect();
    let mut staged = elements.clone();
    for (i, target) in targets.iter().enumerate() {
        let id = format!("{prefix}.{i}");
        if staged.iter().any(|e| e.id == id) { return Err(error("cross featuring identity collision")); }
        let mut relation = fresh_definition_element(id, "TypeFeaturing")?;
        relation.properties.insert("is_implied".into(), json!(true));
        relation.properties.insert("feature_of_type".into(), json!(cross_id));
        relation.properties.insert("featuring_type".into(), json!(target.id));
        if target.properties.get("owning_relationship").is_none_or(Value::is_null) {
            let mut ancestor = Some(cross);
            while let Some(node) = ancestor {
                if node.id == target.id { return Err(error("cross featuring adoption would create an ownership cycle")); }
                ancestor = scope_container(&index, node)?;
            }
            let adopted = staged.iter_mut().find(|e| e.id == target.id).ok_or_else(|| error("missing staged featuring Type"))?;
            ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS, &mut relation, adopted)?;
        }
        let featured = staged.iter_mut().find(|e| e.id == cross_id).ok_or_else(|| error("missing staged cross-feature"))?;
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, featured, &mut relation)?;
        staged.push(relation);
    }
    if let Some(issue) = ecore_model::validate_publication(&staged, ecore_model::ReferenceCompleteness::Closed).first() {
        return Err(error(format!("invalid cross featuring result: {}", issue.message)));
    }
    let count = targets.len();
    *elements = staged;
    Ok(count)
}

// Recognize the already-qualified binary construction structurally. This is
// deliberately not a general transformation-completeness assertion.
#[cfg(test)]
fn definition_assessed_binary_crossing<'g>(graph: &'g [KirElement], owner: &'g KirElement)
    -> Result<Option<&'g KirElement>, Diagnostic> {
    if owner.kind.rsplit("::").next()!=Some("Feature") {return Ok(None);}
    let index=graph.iter().map(|e|(e.id.as_str(),e)).collect::<BTreeMap<_,_>>();
    definition_assessed_binary_crossing_in_view(&DefinitionNameQuery::new(graph,&index),owner)
}

fn definition_assessed_binary_crossing_in_view<'g>(query: &DefinitionNameQuery<'g, '_>, owner: &'g KirElement)
    -> Result<Option<&'g KirElement>, Diagnostic> {
    let graph=query.graph;
    if owner.kind.rsplit("::").next() != Some("Feature") { return Ok(None); }
    let Some(cross) = definition_owned_cross_feature_in_view(query, owner)? else { return Ok(None); };
    let crossings: Vec<_> = stored_children_projection_query(query, owner, "owned_relationship")?.into_iter()
        .filter(|r| metaclass_conforms(&r.kind, "CrossSubsetting")).collect();
    if crossings.len() != 1 { return Ok(None); }
    let relation = crossings[0];
    if relation.kind.rsplit("::").next() != Some("CrossSubsetting")
        || redefined_reference_in_view(query, relation, "specific")?.id != owner.id { return Ok(None); }
    let (_, context) = definition_feature_owner_indexed(graph.len(),query.index,owner)?.ok_or_else(|| error("crossing requires owning Type"))?;
    let ends = definition_owned_features_query(query, context, true)?;
    if ends.len() != 2 { return Ok(None); }
    let Some(position) = ends.iter().position(|e| e.id == owner.id) else { return Ok(None); };
    let other = ends[1-position];
    if !implicit_chain_signature_query(query, other)?.is_empty() || !implicit_chain_signature_query(query, cross)?.is_empty() { return Ok(None); }
    let chain = redefined_reference_in_view(query, relation, "general")?;
    if chain.kind.rsplit("::").next() != Some("Feature") { return Ok(None); }
    if implicit_chain_signature_query(query, chain)? != [other.id.clone(), cross.id.clone()] { return Ok(None); }
    // Extra contributions on the constructed wrapper need their own provider.
    if !definition_assessed_cross_chain_parts_in_view(query, chain)? {return Ok(None);}
    Ok(Some(relation))

}

// A crossing wrapper's only assessed addition is its imported untyped Feature
// default. It creates no owning-Type contribution and keeps ordered chaining.
fn definition_assessed_cross_chain_parts_in_view(query: &DefinitionNameQuery<'_, '_>, chain: &KirElement)
    -> Result<bool,Diagnostic> {
    canonical_chain_lifecycle::assessed_wrapper(query,chain)
        .map_err(|failure|failure.into_diagnostic_at("canonical crossing chain contributions"))

}

// Explicit source crossings contribute an existing specialization. Their
// owned chain has no owning-Type contribution; pending chaining references are
// still resolved by the ordinary reference scheduler, not guessed here.
fn definition_assessed_explicit_crossing_in_view(query: &DefinitionNameQuery<'_, '_>, owner: &KirElement, relation: &KirElement) -> Result<bool, Diagnostic> {
    if owner.kind.rsplit("::").next() != Some("Feature")
        || relation.kind.rsplit("::").next() != Some("CrossSubsetting")
        || scope_boolean(relation, "is_implied")?
        || definition_owned_cross_feature_in_view(query, owner)?.is_some() { return Ok(false); }
    let crossings: Vec<_> = stored_children_projection_query(query, owner, "owned_relationship")?.into_iter().filter(|r| metaclass_conforms(&r.kind, "CrossSubsetting")).collect();
    if crossings.len() != 1 || crossings[0].id != relation.id || redefined_reference_in_view(query, relation, "specific")?.id != owner.id { return Ok(false); }
    let chain = redefined_reference_in_view(query, relation, "general")?;
    if chain.kind.rsplit("::").next() != Some("Feature")
        || chain.properties.get("owning_relationship").and_then(Value::as_str) != Some(relation.id.as_str()) { return Ok(false); }
    definition_assessed_cross_chain_parts_in_view(query, chain)

}

#[cfg(test)]
fn definition_is_assessed_cross_chain(graph: &[KirElement], feature: &KirElement) -> Result<bool, Diagnostic> {
    let index=graph.iter().map(|e|(e.id.as_str(),e)).collect::<BTreeMap<_,_>>();
    definition_is_assessed_cross_chain_in_view(&DefinitionNameQuery::new(graph,&index),feature)
}

fn definition_is_assessed_cross_chain_in_view(query: &DefinitionNameQuery<'_, '_>, feature: &KirElement)
    -> Result<bool,Diagnostic> {
    let Some(relation) = scope_container_query(query, feature)? else { return Ok(false); };
    if relation.kind.rsplit("::").next() != Some("CrossSubsetting") { return Ok(false); }
    let owner = redefined_reference_in_view(query, relation, "specific")?;
    Ok((definition_assessed_binary_crossing_in_view(query, owner)?.is_some_and(|known| known.id == relation.id)
        || definition_assessed_explicit_crossing_in_view(query, owner, relation)?)
        && redefined_reference_in_view(query, relation, "general")?.id == feature.id)

}

fn definition_cross_feature<'g>(graph: &'g [KirElement], owner: &'g KirElement) -> Result<Option<&'g KirElement>, Diagnostic> {
    definition_cross_feature_query(graph, owner).map_err(|failure| failure.into_diagnostic_at("definition_cross_feature"))
}

fn definition_cross_feature_query<'g>(graph: &'g [KirElement], owner: &'g KirElement) -> Result<Option<&'g KirElement>, QueryFailure> {
    let index=graph.iter().map(|e|(e.id.as_str(),e)).collect::<BTreeMap<_,_>>();
    definition_cross_feature_in_view(&DefinitionNameQuery::new(graph,&index),owner)
}

fn definition_cross_feature_in_view<'g>(query: &DefinitionNameQuery<'g, '_>, owner: &'g KirElement)
    -> Result<Option<&'g KirElement>, QueryFailure> {
    let contract = ecore_model::feature(&owner.kind, "cross_feature").ok_or_else(|| query_failure("missing crossFeature contract"))?;
    if !contract.setting_delegate.as_ref().is_some_and(|d| d.uri == "http://www.omg.org/spec/SysML"
        && d.status == "custom_setting_delegate_source"
        && d.candidates == ["org.omg.sysml.delegate.setting.Feature_crossFeature_SettingDelegate"]) {
        return Err(query_failure("unsupported crossFeature delegate"));
    }
    let crossings: Vec<_> = stored_children_projection_query(query, owner, "owned_relationship")?.into_iter()
        .filter(|e| metaclass_conforms(&e.kind, "CrossSubsetting")).collect();
    if crossings.len() > 1 { return Err(query_failure("multiple owned CrossSubsettings violate the Feature contract")); }
    let Some(relation) = crossings.first() else {
        if scope_boolean(owner, "is_implied_included")? { return Ok(None); }
        // The exact Feature adapter can add CrossSubsetting only for an
        // eligible owned cross-feature. Other adapters and semantic metadata
        // retain their separate contribution assessment.
        let unresolved = |reason: &str| query_failure(format!(
            "crossFeature requires assessed implicit crossing contributions: receiver {} {} ({reason})",
            owner.kind, owner.id));
        if owner.kind.rsplit("::").next() != Some("Feature") {
            return Err(unresolved("unassessed adapter"));
        }
        if query.has_semantic_metadata()? { return Err(unresolved("semantic metadata evaluation")); }
        match definition_binary_crossing_inputs_in_view(query, owner) {
            Ok(None) => return Ok(None),
            Ok(Some(_)) => return Err(QueryFailure::Required(Prerequisite::BinaryCrossing { owner_id: owner.id.clone() })),
            Err(QueryFailure::Required(requirement)) => return Err(QueryFailure::Required(requirement)),
            Err(QueryFailure::Rejected(issue)) => return Err(unresolved(&issue.message)),
        }
    };
    let crossed = query_reference_in_view(query, relation, "crossed_feature")?;
    let chains: Vec<_> = stored_children_projection_query(query, crossed, "owned_relationship")?.into_iter()
        .filter(|e| metaclass_conforms(&e.kind, "FeatureChaining")).collect();
    if let Some(second) = chains.get(1) { Ok(Some(query_reference_in_view(query, second, "chaining_feature")?)) }
    else { Ok(None) }

}

// Handwritten FeatureAdapter.getAllTypes/getTypes and typingFeatures dependency.
// Exact generated Feature/Usage/ReferenceUsage and resolved Step inheritance; other adapter overrides
// require separate qualification.
#[track_caller]
fn definition_feature_types<'g>(graph: &'g [KirElement], feature: &'g KirElement) -> Result<Vec<&'g KirElement>, Diagnostic> {
    let boundary=format!("definition_feature_types; caller {}",std::panic::Location::caller());
    definition_feature_types_query(graph, feature).map_err(|failure| failure.into_diagnostic_at(&boundary))
}

fn definition_feature_types_query<'g>(graph: &'g [KirElement], feature: &'g KirElement) -> Result<Vec<&'g KirElement>, QueryFailure> {
    let index = graph.iter().map(|e| (e.id.as_str(), e)).collect::<BTreeMap<_, _>>();
    if index.len() != graph.len() { return Err(query_failure("duplicate type-query identity")); }
    definition_feature_types_in_view(&DefinitionNameQuery::new(graph, &index), feature)
}

// All recursive type/general/default reads share this immutable query session.
// A write or dependency retry creates a fresh view; no incomplete answer is cached.
fn definition_feature_types_in_view<'g>(query: &DefinitionNameQuery<'g, '_>, feature: &'g KirElement)
    -> Result<Vec<&'g KirElement>, QueryFailure> {
    fn visit<'g>(query: &DefinitionNameQuery<'g, '_>, feature: &'g KirElement, seen: &mut BTreeSet<String>, types: &mut Vec<&'g KirElement>, depth: usize) -> Result<(), QueryFailure> {
        let graph = query.graph;
        if !seen.insert(feature.id.clone()) { return Ok(()); }
        if depth >= 128 { return Err(query_failure("Feature type traversal exceeds evaluation limit")); }
        let kind = feature.kind.rsplit("::").next().unwrap_or(&feature.kind);
        let expression_provider = compatibility_generated::expression_default_name(kind, false).is_some()
            || instantiation_strategy_generated::base(kind).is_some();
        if !feature_defaults_generated::ordinary_feature_type_binding(kind)
            && !multiplicity_defaults_generated::supports(kind)
            && !connector_defaults_generated::typing_supported(kind)
            && !step_defaults_generated::supports(kind) && !expression_provider {
            return Err(query_failure("Feature types require exact qualified adapter dispatch"));
        }
        let relationships = stored_children_projection_query(query, feature, "owned_relationship")?;
        // Crossing navigation is not a typing contribution. An assessed owned
        // explicit chain may still be linking while this Feature's type is read.
        let mut isolated_crossing = definition_owned_cross_feature_in_view(query, feature)?.is_some();
        for relation in &relationships {
            isolated_crossing |= definition_assessed_explicit_crossing_in_view(query, feature, relation)?;
        }
        let incomplete_crossing_end = !scope_boolean(feature, "is_implied_included")? && isolated_crossing;
        if !incomplete_crossing_end { definition_general_type_inputs_with_view(query, feature, "")?; }
        let mut typing_features = Vec::new();
        for relation in &relationships {
            if metaclass_conforms(&relation.kind, "FeatureTyping") {
                let target = query_reference_in_view(query, relation, "type")?;
                if !types.iter().any(|e| e.id == target.id) { types.push(target); }
            } else if metaclass_conforms(&relation.kind, "Subsetting") && !metaclass_conforms(&relation.kind, "CrossSubsetting") {
                typing_features.push(query_reference_in_view(query, relation, "general")?);
            }
        }
        if !scope_boolean(feature, "is_implied_included")? && expression_provider {
            // Shared Feature.type traversal consumes each resolved Expression
            // contribution with its relationship category. Instantiation typing
            // contributes a Type; Subsetting contributes another Feature's types.
            // Complete receivers read the same physically inserted relationships.
            // Directed expressions can positionally redefine inherited typed
            // parameters. Defaults alone cannot establish their full type set;
            // retain unavailable positional/write dependencies as typed errors.
            typing_features.extend(definition_redefined_features_typed_query(query, feature, false)?);
            for (kind, id) in definition_expression_default_contributions_query(query, feature)? {
                let target = graph.iter().find(|e| e.id == id).ok_or_else(|| query_failure("expression typing contribution is absent"))?;
                if kind == "FeatureTyping" {
                    if !types.iter().any(|e| e.id == target.id) { types.push(target); }
                } else if kind == "Subsetting" { typing_features.push(target); }
                else { return Err(query_failure("expression typing contribution category is unassessed")); }
            }
        } else if !scope_boolean(feature, "is_implied_included")? && definition_is_result_parameter_query(query, feature)? {
            // A return parameter's generalization strategy differs from an
            // ordinary undirected Feature. Consume the shared result selector
            // and positional contributions rather than re-running that branch.
            for (_, id) in definition_result_feature_generals_query(query, feature)? {
                typing_features.push(graph.iter().find(|e| e.id == id).ok_or_else(|| query_failure("result typing general is absent"))?);
            }
        } else if !scope_boolean(feature, "is_implied_included")? {
            let name = if incomplete_crossing_end {
                let (structure, class, data, owner_class, owner_structure) =
                    definition_ordinary_feature_inputs_with_owners_in_view(query, feature, &mut BTreeSet::new(), true)?;
                feature_defaults_generated::feature_default_name(structure, class, data,
                    scope_boolean(feature, "is_composite")? && owner_structure,
                    scope_boolean(feature, "is_composite")? && owner_class,
                    scope_boolean(feature, "is_portion")? && owner_class)
            } else if multiplicity_defaults_generated::supports(kind) { definition_multiplicity_default_name_in_view(query,feature)? }
            else if step_defaults_generated::supports(feature.kind.rsplit("::").next().unwrap_or(&feature.kind)) { definition_step_default_name_in_view(query,feature)? }
            else if feature_defaults_generated::ordinary_usage_binding(feature.kind.rsplit("::").next().unwrap_or(&feature.kind)) { definition_usage_default_name_in_view(query, feature)? }
            else { definition_feature_default_name_in_view(query, feature)? };
            let default_id = query_local_binding(standard_default_binding_query(query, name)?)?;
            let implicit = definition_implicit_feature_generals_in_view(query, feature, &default_id)?;
            for kind in ["Subsetting", "ReferenceSubsetting", "Redefinition"] {
                for (_, id) in implicit.iter().filter(|(candidate, _)| *candidate == kind) {
                    typing_features.push(graph.iter().find(|e| &e.id == id).ok_or_else(|| query_failure("implicit typing Feature is absent"))?);
                }
            }
        }
        if let Some(last) = stored_feature_chain_target_for_scope_query_in_view(query, feature, &relationships, "")? { typing_features.push(last); }
        for target in typing_features { visit(query, target, seen, types, depth + 1)?; }
        Ok(())
    }
    let mut types = Vec::new();
    visit(query, feature, &mut BTreeSet::new(), &mut types, 0)?;
    // KerML deriveFeatureType rejects against the original set, not a shrinking
    // list. Distinct mutually specializing types therefore both disappear.
    // Pilot's reverse-mutating algorithm differs; retain that disagreement.
    let mut minimal = Vec::new();
    for candidate in &types {
        let mut redundant = false;
        for other in &types {
            if other.id != candidate.id && definition_specializes_depth_in_view(query, other, candidate, 0)? { redundant = true; break; }
        }
        if !redundant { minimal.push(*candidate); }
    }
    Ok(minimal)
}

// Handwritten FeatureAdapter.getReferencedFeature dependency. Exact Feature
// generalization providers emit Subsetting/Redefinition/FeatureTyping, never
// implicit ReferenceSubsetting. Their guards must succeed before absence can
// be concluded; an inherited/redefined reference is not an owned reference.
#[cfg(test)]
fn definition_referenced_feature<'g>(graph: &'g [KirElement], feature: &'g KirElement) -> Result<Option<&'g KirElement>, Diagnostic> {
    let index=graph.iter().map(|e|(e.id.as_str(),e)).collect::<BTreeMap<_,_>>();
    definition_referenced_feature_in_view(&DefinitionNameQuery::new(graph,&index),feature).map_err(|failure|failure.into_diagnostic_at("definition_referenced_feature external boundary"))
}

fn definition_referenced_feature_in_view<'g>(query: &DefinitionNameQuery<'g, '_>, feature: &'g KirElement) -> Result<Option<&'g KirElement>, QueryFailure> {
    if !metaclass_conforms(&feature.kind, "Feature") { return Err(query_failure("referenced-feature query requires Feature")); }
    let relations = stored_children_projection_query(query, feature, "owned_relationship")?;
    if let Some(reference) = relations.iter().find(|r| metaclass_conforms(&r.kind, "ReferenceSubsetting")) {
        return Ok(definition_reference_targets_typed_query(query, reference, "referenced_feature")?.into_iter().next());
    }
    if scope_boolean(feature, "is_implied_included")? { return Ok(None); }
    if feature.kind.rsplit("::").next() != Some("Feature") {
        return Err(query_failure("connector end requires implicit reference-subsetting provider for its adapter"));
    }
    definition_general_type_inputs_with_view(query,feature,"").map_err(|failure|match failure {
        QueryFailure::Rejected(diagnostic)=>query_failure(format!("connector end requires implicit reference-subsetting provider: {}",diagnostic.message)),
        pending=>pending,
    })?;
    Ok(None)

}

/// Handwritten execution of the bounded libraryNamespace invocation family.
/// Imported Ecore hierarchy resolves the most-specific dynamic branch. Stored
/// reciprocal containment drives traversal; derived snapshots are never read.
pub(crate) struct DefinitionLibraryOriginContext<'g> {
    index: BTreeMap<&'g str, &'g KirElement>,
    memo: BTreeMap<&'g str, Option<&'g KirElement>>,
}

impl<'g> DefinitionLibraryOriginContext<'g> {
    pub(crate) fn new(graph: &'g [KirElement]) -> Result<Self, Diagnostic> {
        let index: BTreeMap<_, _> = graph.iter().map(|e| (e.id.as_str(), e)).collect();
        if index.len() != graph.len() || graph.iter().any(|e| e.id.is_empty()) {
            return Err(error("libraryNamespace requires unique nonempty canonical identities"));
        }
        Ok(Self {index, memo: BTreeMap::new()})
    }

    pub(crate) fn namespace(&mut self, owner: &'g KirElement) -> Result<Option<&'g KirElement>, Diagnostic> {
        let contract = ecore_model::library_namespace_contract();
        if contract.owner != "Element" || contract.target != "Namespace" || contract.lower != 0 || contract.upper != 1
            || contract.delegate_uri != "http://www.omg.org/spec/SysML"
            || contract.binding_status != "dynamic_invocation_candidates_not_selected" {
            return Err(error("unsupported libraryNamespace operation contract"));
        }
        if !self.index.get(owner.id.as_str()).is_some_and(|e| std::ptr::eq(*e, owner)) {
            return Err(error("libraryNamespace requires a canonical graph owner"));
        }
        let mut current = owner;
        let mut visited = BTreeSet::new();
        let result = loop {
            if let Some(result) = self.memo.get(current.id.as_str()) { break *result; }
            if !visited.insert(current.id.as_str()) { return Err(error("cyclic libraryNamespace ownership")); }
            let applicable: Vec<_> = contract.branches.iter().filter(|(kind, _)| metaclass_conforms(&current.kind, kind)).collect();
            let most_specific: Vec<_> = applicable.iter().filter(|(kind, _)|
                !applicable.iter().any(|(other, _)| kind != other && metaclass_conforms(other, kind))).collect();
            let (kind, implementation) = match most_specific.as_slice() {
                [branch] => **branch,
                _ => return Err(error("ambiguous or missing libraryNamespace invocation branch")),
            };
            if implementation != &format!("org.omg.sysml.delegate.invocation.{kind}_libraryNamespace_InvocationDelegate") {
                return Err(error("unsupported libraryNamespace implementation binding"));
            }
            match *kind {
                "LibraryPackage" => break Some(current),
                "Element" | "Relationship" => {
                    // Relationship prioritizes owningRelatedElement, then the
                    // Element owningRelationship fallback. Imported reciprocal
                    // container contracts reject conflicts and cached guesses.
                    let Some(parent) = scope_container(&self.index, current)? else { break None; };
                    let field = if *kind == "Relationship" && current.properties.get("owning_related_element").is_some_and(|v| !v.is_null()) {
                        "owning_related_element"
                    } else { "owning_relationship" };
                    if current.properties.get(field).and_then(Value::as_str) != Some(parent.id.as_str()) {
                        return Err(error("libraryNamespace has an unsupported ownership path"));
                    }
                    current = parent;
                },
                _ => return Err(error("unsupported libraryNamespace dynamic algorithm")),
            }
        };
        // Readiness is evaluation-local. Nothing is persisted or marked complete.
        for id in visited { self.memo.insert(id, result); }
        Ok(result)
    }
}

pub(crate) fn definition_library_namespace<'g>(graph: &'g [KirElement], owner: &'g KirElement)
    -> Result<Option<&'g KirElement>, Diagnostic>
{
    DefinitionLibraryOriginContext::new(graph)?.namespace(owner)
}

/// Handwritten identity and Boolean projections for assessed delegate families.
/// Ecore redefinitions choose the reference and concrete delegate; canonical KIR
/// identity supplies Element.elementId unless an explicit value is represented.
/// Library origins and owned conjugators use named native consumers. Remaining
/// derived attribute algorithms stay explicitly unsupported.
pub(crate) fn definition_attribute_value(graph: &[KirElement], owner: &KirElement, field: &str)
    -> Result<Value, Diagnostic>
{
    definition_attribute_value_with_origins(graph, owner, field, None)
}

pub(crate) fn definition_attribute_value_with_origins<'g>(graph: &'g [KirElement], owner: &'g KirElement, field: &str,
    origins: Option<&mut DefinitionLibraryOriginContext<'g>>) -> Result<Value, Diagnostic>
{
    let requested = ecore_model::feature(&owner.kind, field).ok_or_else(|| error("unknown attribute property"))?;
    if requested.kind != ecore_model::FeatureKind::Attribute { return Err(error("property is not an attribute")); }
    let contract = ecore_model::redefined_feature(&owner.kind, field).map_err(error)?;
    let value = if !contract.derived && !contract.volatile {
        if contract.field == "element_id" && !owner.properties.contains_key(contract.field) {
            json!(owner.id)
        } else { ecore_defaults::read_attribute(owner, contract.field).map_err(error)? }
    } else if contract.field == "is_library_element" {
        let binding = contract.setting_delegate.as_ref().ok_or_else(|| error("missing library-element delegate"))?;
        if binding.uri != "http://www.omg.org/spec/SysML" || binding.status != "custom_setting_delegate_source"
            || binding.candidates != ["org.omg.sysml.delegate.setting.Element_isLibraryElement_SettingDelegate"] {
            return Err(error("unsupported library-element delegate binding"));
        }
        let namespace = match origins {
            Some(context) => context.namespace(owner)?,
            None => definition_library_namespace(graph, owner)?,
        };
        json!(namespace.is_some())
    } else if contract.field == "is_model_level_evaluable" && metaclass_conforms(&owner.kind, "Expression") {
        let binding = contract.setting_delegate.as_ref().ok_or_else(|| error("missing evaluability setting delegate"))?;
        if binding.uri != "http://www.omg.org/spec/SysML" || binding.status != "custom_setting_delegate_source"
            || binding.candidates != ["org.omg.sysml.delegate.setting.Expression_isModelLevelEvaluable_SettingDelegate"] {
            return Err(error("unsupported evaluability setting delegate"));
        }
        json!(definition_projection::model_level_evaluable(owner)?)
    } else if contract.field == "is_conjugated" && metaclass_conforms(&owner.kind, "Type") {
        let binding = contract.setting_delegate.as_ref().ok_or_else(|| error("missing conjugation Boolean delegate"))?;
        if binding.uri != "http://www.omg.org/spec/SysML" || binding.status != "custom_setting_delegate_source"
            || binding.candidates != ["org.omg.sysml.delegate.setting.Type_isConjugated_SettingDelegate"] {
            return Err(error("unsupported conjugation Boolean delegate binding"));
        }
        json!(!definition_reference_targets(graph, owner, "owned_conjugator")?.is_empty())
    } else {
        let (reference, delegate) = match contract.field {
            "member_element_id" if metaclass_conforms(&owner.kind, "Membership") =>
                ("member_element", "org.omg.sysml.delegate.setting.Membership_memberElementId_SettingDelegate"),
            "owned_member_element_id" if metaclass_conforms(&owner.kind, "OwningMembership") =>
                ("owned_member_element", "org.omg.sysml.delegate.setting.OwningMembership_ownedMemberElementId_SettingDelegate"),
            _ => return Err(error(format!("attribute {} requires an unsupported derived service", contract.id))),
        };
        let binding = contract.setting_delegate.as_ref().ok_or_else(|| error("missing membership identity delegate"))?;
        if binding.uri != "http://www.omg.org/spec/SysML" || binding.status != "custom_setting_delegate_source"
            || binding.candidates != [delegate] {
            return Err(error("unsupported membership identity delegate binding"));
        }
        let targets = definition_reference_targets(graph, owner, reference)?;
        match targets.as_slice() {
            [] => Value::Null,
            [target] => target.properties.get("element_id").cloned().unwrap_or_else(|| json!(target.id)),
            _ => return Err(error("membership identity requires a singular member")),
        }
    };
    ecore_model::validate_value(&owner.kind, contract.field, &value).map_err(error)?;
    ecore_model::validate_value(&owner.kind, field, &value).map_err(error)?;
    Ok(value)
}

/// Read a bounded effective reference using imported redefinition dispatch.
/// Stored scalar/list references and membership/import ownership projections
/// share one reader. Other derived references require named semantic services.
pub(crate) fn definition_reference_targets<'g>(
    graph: &'g [KirElement], owner: &'g KirElement, field: &str,
) -> Result<Vec<&'g KirElement>, Diagnostic> {
    // Stored references keep their original direct reader: constructing a view
    // is needed only by derived semantic projections.
    let requested = ecore_model::feature(&owner.kind, field).ok_or_else(|| error("unknown reference property"))?;
    if requested.kind != ecore_model::FeatureKind::Reference { return Err(error("property is not a reference")); }
    let contract = ecore_model::redefined_feature(&owner.kind, field).map_err(error)?;
    if !contract.derived && !contract.volatile && !contract.transient {
        let targets = definition_stored_reference_targets(graph, None, owner, contract).map_err(|failure|failure.into_diagnostic_at("definition_reference_targets stored boundary"))?;
        for target in &targets {
            ecore_model::validate_reference_endpoint(&owner.kind, contract.field, &target.kind).map_err(error)?;
            ecore_model::validate_reference_endpoint(&owner.kind, field, &target.kind).map_err(error)?;
        }
        return Ok(targets);
    }
    let index = graph.iter().map(|e| (e.id.as_str(), e)).collect::<BTreeMap<_, _>>();
    definition_reference_targets_query(&DefinitionNameQuery::new(graph, &index), owner, field)
}

fn definition_stored_reference_targets<'g>(graph: &'g [KirElement],
    index: Option<&BTreeMap<&str, &'g KirElement>>, owner: &KirElement,
    contract: &ecore_model::FeatureContract) -> Result<Vec<&'g KirElement>, QueryFailure> {
        let value = owner.properties.get(contract.field)
            .ok_or_else(|| QueryFailure::Required(Prerequisite::ReadField {owner_id:owner.id.clone(),field:contract.field.into()}))?;
        ecore_model::validate_value(&owner.kind, contract.field, value).map_err(error)?;
        let ids: Vec<&str> = match value {
            Value::Null => Vec::new(),
            Value::String(id) => vec![id],
            Value::Array(values) => values.iter().filter_map(Value::as_str).collect(),
            _ => return Err(query_failure("invalid reference storage")),
        };
        ids.into_iter().map(|id| if let Some(index)=index.filter(|index|index.len()==graph.len()) {index.get(id).copied()} else {graph.iter().find(|e|e.id==id)}
            .ok_or_else(|| query_failure("reference target is absent"))).collect::<Result<Vec<_>, _>>()

}

fn definition_reference_targets_query<'g>(query: &DefinitionNameQuery<'g, '_>, owner: &'g KirElement, field: &str)
    -> Result<Vec<&'g KirElement>, Diagnostic> {
    definition_reference_targets_typed_query(query, owner, field)
        .map_err(|failure| failure.into_diagnostic_at("definition_reference_targets external boundary"))
}

/// Native typed getter shared by diagnostic inspection and the existing facade.
/// This performs no graph edits and never consumes a derived-value snapshot.
pub(crate) fn definition_reference_targets_with_dependencies<'g>(graph: &'g [KirElement], owner: &'g KirElement, field: &str)
    -> Result<Vec<&'g KirElement>, DefinitionReferenceQueryError> {
    let index = graph.iter().map(|e| (e.id.as_str(), e)).collect::<BTreeMap<_, _>>();
    if index.len() != graph.len() {
        return Err(DefinitionReferenceQueryError::Rejected { message: "Duplicate query graph identity".into(), subjects: vec![owner.id.clone()] });
    }
    definition_reference_targets_typed_query(&DefinitionNameQuery::new(graph, &index), owner, field)
        .map_err(DefinitionReferenceQueryError::from)
}

/// Run ordered, independent getter requests against one immutable native view.
/// This reads imported Ecore contracts and existing semantic consumers; it
/// neither constructs dependencies nor promotes constructed records to a model.
pub(crate) fn definition_reference_target_batch_with_dependencies<'g>(
    graph: &'g [KirElement], requests: &[(&str, &str)],
) -> Result<Vec<Result<Vec<&'g KirElement>, DefinitionReferenceQueryError>>, DefinitionReferenceQueryError> {
    let index = graph.iter().map(|e| (e.id.as_str(), e)).collect::<BTreeMap<_, _>>();
    if index.len() != graph.len() || index.contains_key("") {
        return Err(DefinitionReferenceQueryError::Rejected {
            message: "Reference query batches require unique nonempty graph identities".into(),
            subjects: Vec::new(),
        });
    }
    let query = DefinitionNameQuery::new(graph, &index);
    Ok(requests.iter().map(|(identity, field)| {
        let owner = index.get(identity).copied().ok_or_else(|| DefinitionReferenceQueryError::Rejected {
            message: "Constructed-structure query owner is absent".into(), subjects: vec![(*identity).into()],
        })?;
        definition_reference_targets_typed_query(&query, owner, field)
            .map_err(DefinitionReferenceQueryError::from)
    }).collect())
}

/// Read the imported Type.directionOf operation in one immutable native view.
pub(crate) fn definition_direction_of_with_dependencies(graph: &[KirElement], owner_id: &str, feature_id: &str)
    -> Result<Value, DefinitionReferenceQueryError> {
    let index = graph.iter().map(|e|(e.id.as_str(),e)).collect::<BTreeMap<_,_>>();
    if index.len() != graph.len() || index.contains_key("") {
        return Err(DefinitionReferenceQueryError::Rejected {message:"Direction queries require unique nonempty graph identities".into(),subjects:Vec::new()});
    }
    let owner = index.get(owner_id).copied().ok_or_else(|| DefinitionReferenceQueryError::Rejected {
        message:"Direction query owner is absent".into(),subjects:vec![owner_id.into()]})?;
    let feature = index.get(feature_id).copied().ok_or_else(|| DefinitionReferenceQueryError::Rejected {
        message:"Direction query feature is absent".into(),subjects:vec![feature_id.into()]})?;
    type_direction::of(&DefinitionNameQuery::new(graph,&index),owner,feature)
        .map(|direction| direction.map_or(Value::Null,|direction|json!(direction)))
        .map_err(DefinitionReferenceQueryError::from)
}

fn definition_reference_targets_typed_query<'g>(
    query: &DefinitionNameQuery<'g, '_>, owner: &'g KirElement, field: &str,
) -> Result<Vec<&'g KirElement>, QueryFailure> {
    let graph = query.graph;
    let requested = ecore_model::feature(&owner.kind, field)
        .ok_or_else(|| error("unknown reference property"))?;
    if requested.kind != ecore_model::FeatureKind::Reference { return Err(query_failure("property is not a reference")); }
    let contract = ecore_model::redefined_feature(&owner.kind, field).map_err(error)?;
    let targets = if !contract.derived && !contract.volatile && !contract.transient {
        definition_stored_reference_targets(graph, Some(query.index), owner, contract)?
    } else if owner.kind.rsplit("::").next()==Some("TransitionUsage") && contract.field=="source" {
        transition_source_query::source(graph,owner,contract)?
    } else if owner.kind.rsplit("::").next()==Some("TransitionUsage")
        && matches!(contract.field,"trigger_action"|"guard_expression"|"effect_action"|"succession") {
        transition_projections::targets(graph,owner,contract)?.ok_or_else(||error("unassessed transition projection"))?
    } else if metaclass_conforms(&owner.kind, "Specialization")
        && matches!(contract.field, "owning_type" | "owning_feature" | "referencing_feature" | "crossing_feature") {
        specialization_owner_reference(graph, owner, contract.field)?.into_iter().collect()
    } else if metaclass_conforms(&owner.kind,"InstantiationExpression") && contract.field=="argument" {
        relative_namespace::arguments(query,owner)?
    } else if metaclass_conforms(&owner.kind,"InstantiationExpression") && contract.field=="instantiated_type" {
        definition_instantiated_type_query(query,owner)?.into_iter().collect()
    } else if metaclass_conforms(&owner.kind, "Usage") && contract.field == "definition" {
        let delegate=contract.setting_delegate.as_ref().ok_or_else(||error("missing Usage definition delegate"))?;
        if delegate.uri != "http://www.omg.org/spec/SysML" || delegate.status != "custom_setting_delegate_source"
            || delegate.candidates != ["org.omg.sysml.delegate.setting.Usage_definition_SettingDelegate"] {return Err(query_failure("unsupported Usage definition delegate"));}
        definition_feature_types_in_view(query,owner)?.into_iter().filter(|target|metaclass_conforms(&target.kind,"Classifier")).collect()
    } else if metaclass_conforms(&owner.kind, "Expression") && contract.field == "function" {
        let delegate = contract.setting_delegate.as_ref().ok_or_else(|| error("missing Expression function delegate"))?;
        if delegate.uri != "http://www.omg.org/spec/SysML" || delegate.status != "custom_setting_delegate_source"
            || delegate.candidates != ["org.omg.sysml.delegate.setting.Expression_function_SettingDelegate"] {
            return Err(query_failure("unsupported Expression function delegate"));
        }
        // Handwritten deriveExpressionFunction over the shared native Feature.type
        // consumer: select the first Function, preserving effective type order.
        definition_feature_types_in_view(query, owner)?.into_iter().find(|target| metaclass_conforms(&target.kind, "Function")).into_iter().collect()
    } else if metaclass_conforms(&owner.kind, "Step") && contract.field == "behavior" {
        let delegate = contract.setting_delegate.as_ref().ok_or_else(|| error("missing Step behavior delegate"))?;
        if delegate.uri != "http://www.omg.org/spec/SysML" || delegate.status != "custom_setting_delegate_source"
            || delegate.candidates != ["org.omg.sysml.delegate.setting.Step_behavior_SettingDelegate"] {
            return Err(query_failure("unsupported Step behavior delegate"));
        }
        definition_feature_types_in_view(query, owner)?.into_iter().filter(|target| metaclass_conforms(&target.kind, "Behavior")).collect()
    } else if contract.field == "parameter" && (metaclass_conforms(&owner.kind, "Behavior") || metaclass_conforms(&owner.kind, "Step")) {
        let delegate = contract.setting_delegate.as_ref().ok_or_else(|| error("missing callable parameter delegate"))?;
        let expected = if metaclass_conforms(&owner.kind, "Behavior") { "org.omg.sysml.delegate.setting.Behavior_parameter_SettingDelegate" }
            else { "org.omg.sysml.delegate.setting.Step_parameter_SettingDelegate" };
        if delegate.uri != "http://www.omg.org/spec/SysML" || delegate.status != "custom_setting_delegate_source" || delegate.candidates != [expected] {
            return Err(query_failure("unsupported callable parameter delegate"));
        }
        // Resolved shared Type.directedFeature projection; concrete overrides
        // keep separate dependencies rather than falling through this consumer.
        definition_parameter_collection_typed_query(query, owner, false)?
    } else if metaclass_conforms(&owner.kind, "Connector") && contract.field == "association" {
        let delegate = contract.setting_delegate.as_ref().ok_or_else(|| error("missing Connector association delegate"))?;
        if delegate.uri != "http://www.omg.org/spec/SysML" || delegate.status != "custom_setting_delegate_source"
            || delegate.candidates != ["org.omg.sysml.delegate.setting.Connector_association_SettingDelegate"] {
            return Err(query_failure("unassessed Connector association delegate"));
        }
        // Ecore redefines Feature.type as Connector.association. The adapter's
        // broader all-types computation remains separate for default selection.
        definition_feature_types_in_view(query, owner)?.into_iter()
            .filter(|target| metaclass_conforms(&target.kind, contract.target)).collect()
    } else if metaclass_conforms(&owner.kind, "Feature") && contract.field == "type" {
        let delegate = contract.setting_delegate.as_ref().ok_or_else(|| error("missing Feature type delegate"))?;
        if delegate.uri != "http://www.omg.org/spec/SysML" || delegate.status != "custom_setting_delegate_source"
            || delegate.candidates != ["org.omg.sysml.delegate.setting.Feature_type_SettingDelegate"] { return Err(query_failure("unsupported Feature type delegate")); }
        definition_feature_types_in_view(query, owner)?
    } else if metaclass_conforms(&owner.kind, "Association") && matches!(contract.field, "related_type" | "source_type" | "target_type") {
        let delegate = contract.setting_delegate.as_ref().ok_or_else(|| error("missing Association type projection delegate"))?;
        let expected = match contract.field {
            "related_type" => "org.omg.sysml.delegate.setting.Association_relatedType_SettingDelegate",
            "source_type" => "org.omg.sysml.delegate.setting.Association_sourceType_SettingDelegate",
            _ => "org.omg.sysml.delegate.setting.Association_targetType_SettingDelegate",
        };
        if delegate.uri != "http://www.omg.org/spec/SysML" || delegate.status != "custom_setting_delegate_source" || delegate.candidates != [expected] {
            return Err(query_failure("unsupported Association type projection delegate"));
        }
        let end_contract = ecore_model::feature(&owner.kind, "association_end").ok_or_else(|| error("missing Association end contract"))?;
        if !end_contract.setting_delegate.as_ref().is_some_and(|d| d.uri == "http://www.omg.org/spec/SysML" && d.status == "custom_setting_delegate_source" && d.candidates == ["org.omg.sysml.delegate.setting.Association_associationEnd_SettingDelegate"]) {
            return Err(query_failure("unsupported Association end delegate"));
        }
        let mut related = Vec::new();
        for end in definition_end_features_query(query, owner, false)? { related.extend(definition_feature_types_in_view(query, end)?); }
        let mut projected: Vec<_> = match contract.field {
            "source_type" => related.into_iter().take(1).collect(),
            "target_type" => related.into_iter().skip(1).collect(),
            _ => related,
        };
        if contract.unique {
            let mut seen = BTreeSet::new();
            projected.retain(|target| seen.insert(target.id.as_str()));
        }
        projected
    } else if metaclass_conforms(&owner.kind,"Connector") && contract.field=="default_featuring_type" {
        let delegate=contract.setting_delegate.as_ref().ok_or_else(||error("missing defaultFeaturingType delegate"))?;
        if delegate.uri!="http://www.omg.org/spec/SysML" || delegate.status!="custom_setting_delegate_source"
            || delegate.candidates!=["org.omg.sysml.delegate.setting.Connector_defaultFeaturingType_SettingDelegate"] {
            return Err(query_failure("unassessed defaultFeaturingType delegate"));
        }
        if !connector_contexts_generated::supports(owner.kind.rsplit("::").next().unwrap_or(&owner.kind)) {
            return Err(query_failure("unassessed defaultFeaturingType concrete binding"));
        }
        let related=definition_reference_targets_typed_query(query,owner,"related_feature")?;
        // Preserve the checked computation's typed prerequisites through projection.
        definition_related_feature_context_in_view(query,&related,true)?.into_iter().collect()
    } else if metaclass_conforms(&owner.kind, "FeatureChainExpression") && contract.field == "target_feature" {
        feature_chain_targets::target_feature(query, owner)?.into_iter().collect()
    } else if metaclass_conforms(&owner.kind, "Connector")
        && matches!(contract.field, "source_feature" | "target_feature" | "related_feature") {
        let delegate = contract.setting_delegate.as_ref().ok_or_else(|| error("missing connector projection delegate"))?;
        let expected = match contract.field {
            "source_feature" => "org.omg.sysml.delegate.setting.Connector_sourceFeature_SettingDelegate",
            "target_feature" => "org.omg.sysml.delegate.setting.Connector_targetFeature_SettingDelegate",
            _ => "org.omg.sysml.delegate.setting.Connector_relatedFeature_SettingDelegate",
        };
        if delegate.uri != "http://www.omg.org/spec/SysML" || delegate.status != "custom_setting_delegate_source"
            || delegate.candidates != [expected] { return Err(query_failure("unsupported connector projection delegate")); }
        // Handwritten ConnectorUtil projection. Effective ends must be complete;
        // using owned ends alone would silently omit inherited connections.
        let mut related = Vec::new();
        for end in definition_end_features_query(query, owner, false)? {
            related.extend(definition_referenced_feature_in_view(query, end)?);
        }
        let mut projected: Vec<_> = match contract.field {
            "source_feature" => related.into_iter().take(1).collect(),
            "target_feature" => related.into_iter().skip(1).collect(),
            _ => related,
        };
        // Ecore declares relatedFeature nonunique but targetFeature unique;
        // preserve first occurrence order for the written ordered-set rule.
        if contract.unique {
            let mut seen = BTreeSet::new();
            projected.retain(|feature| seen.insert(feature.id.as_str()));
        }
        projected
    } else if metaclass_conforms(&owner.kind, "Feature") && contract.field == "cross_feature" {
        definition_cross_feature_in_view(query, owner)?.into_iter().collect()
    } else if metaclass_conforms(&owner.kind, "Feature") && contract.field == "featuring_type" {
        definition_featuring_types_in_view(query, owner)?
    } else if metaclass_conforms(&owner.kind, "Feature") && contract.field == "owned_type_featuring" {
        definition_owned_type_featuring_in_view(query, owner)?
    } else if metaclass_conforms(&owner.kind, "Feature")
        && matches!(contract.field, "owned_feature_chaining" | "chaining_feature" | "feature_target") {
        definition_chain_reference_targets_typed_query(query, owner, contract.field)?
    } else if metaclass_conforms(&owner.kind, "Type") && contract.field == "owned_conjugator" {
        let binding = contract.setting_delegate.as_ref().ok_or_else(|| error("missing owned conjugator delegate"))?;
        if binding.uri != "http://www.omg.org/spec/SysML" || binding.status != "custom_setting_delegate_source"
            || binding.candidates != ["org.omg.sysml.delegate.setting.Type_ownedConjugator_SettingDelegate"]
            || !ecore_model::has_subset_contract(&owner.kind, contract.field, "owned_relationship") {
            return Err(query_failure("unsupported owned conjugator projection contract"));
        }
        if !owner.properties.contains_key("owned_relationship") {
            return Err(query_failure("owned conjugator requires complete canonical relationships"));
        }
        // Written ordered first-by-kind projection; its at-most-one invariant
        // is a separate validation obligation, not enforced by this getter.
        stored_children_projection_query(query, owner, "owned_relationship")?.into_iter()
            .find(|relationship| metaclass_conforms(&relationship.kind, contract.target)).into_iter().collect()
    } else if metaclass_conforms(&owner.kind, "Type") && matches!(contract.field, "owned_feature" | "owned_end_feature") {
        definition_owned_features_query(query, owner, contract.field == "owned_end_feature")?
    } else if metaclass_conforms(&owner.kind, "Type") && contract.field == "end_feature" {
        definition_end_features_query(query, owner, false)?
    } else if metaclass_conforms(&owner.kind, "Type") && contract.field == "feature" {
        definition_effective_features_typed_query(query, owner)?
    } else if owner.kind.rsplit("::").next()==Some("FeatureReferenceExpression") && contract.field=="referent" {
        match definition_explicit_expression_referent_in_view(query,owner)? {
            Some(target) if metaclass_conforms(&target.kind,"Feature")=>vec![target],
            Some(_)=>Vec::new(),
            None=>{
                let binding=standard_default_binding(graph,specialization_construction_generated::SELF_REFERENCE_FEATURE)
                    .map_err(|issue|error(format!("self-reference library provider: {}",issue.message)))?;
                let GeneratedLinkTarget::Local(id)=binding else {return Err(query_failure("self-reference library provider requires a resolved local target"));};
                let target=graph.iter().find(|e|e.id==id).ok_or_else(||error("self-reference library target is absent"))?;
                ecore_model::validate_reference_endpoint(&owner.kind,contract.field,&target.kind).map_err(error)?;
                vec![target]
            },
        }
    } else if matches!(contract.field, "result")
        && (metaclass_conforms(&owner.kind, "Function") || metaclass_conforms(&owner.kind, "Expression")) {
        definition_result_parameter_typed_query(query, owner)?.into_iter().collect()
    } else if metaclass_conforms(&owner.kind, "OwningMembership")
        && contract.upper == 1
        && ecore_model::redefined_feature(&owner.kind, "owned_member_element").map_err(error)?.field == contract.field
        && ecore_model::has_subset_contract("OwningMembership", "owned_member_element", "owned_related_element") {
        match stored_membership_endpoint_indexed(graph.len(), query.index, owner, "member_element")? {
            StoredMembershipEndpoint::Resolved(target) => vec![target],
            _ => return Err(query_failure("owning membership endpoint is unavailable")),
        }
    } else if (metaclass_conforms(&owner.kind, "Membership")
            && matches!(contract.field, "membership_owning_namespace" | "owning_type"))
        || (metaclass_conforms(&owner.kind, "Import") && contract.field == "import_owning_namespace") {
        scope_container_query(query, owner)?.into_iter().collect()
    } else {
        if let Some(targets) = ecore_reference_projections::project(query, owner, contract)? { targets }
        else if let Some(targets) = type_set_contributions::project(query, owner, contract)? { targets }
        else { definition_projection::reference_targets_query(query, owner, contract)?
            .ok_or_else(|| error(format!("reference {} requires an unsupported derived service", contract.id)))? }
    };
    for target in &targets {
        ecore_model::validate_reference_endpoint(&owner.kind, contract.field, &target.kind).map_err(error)?;
        ecore_model::validate_reference_endpoint(&owner.kind, field, &target.kind).map_err(error)?;
    }
    Ok(targets)
}

/// Named handwritten chain delegates. Ecore determines relationship ancestry,
/// endpoint types, ordering, uniqueness and the ownership subset. No cached
/// derived value is trusted and no expression/generalization provider is implied.
fn definition_chain_reference_targets<'g>(graph: &'g [KirElement], owner: &'g KirElement, field: &str)
    -> Result<Vec<&'g KirElement>, Diagnostic>
{
    let index = graph.iter().map(|e| (e.id.as_str(), e)).collect::<BTreeMap<_, _>>();
    definition_chain_reference_targets_query(&DefinitionNameQuery::new(graph, &index), owner, field)
}

fn definition_chain_reference_targets_query<'g>(query: &DefinitionNameQuery<'g, '_>, owner: &'g KirElement, field: &str)
    -> Result<Vec<&'g KirElement>, Diagnostic>
{
    definition_chain_reference_targets_typed_query(query,owner,field).map_err(|failure|failure.into_diagnostic_at("definition_chain_reference_targets_query"))
}

fn definition_chain_reference_targets_typed_query<'g>(query: &DefinitionNameQuery<'g, '_>, owner: &'g KirElement, field: &str)
    -> Result<Vec<&'g KirElement>, QueryFailure>
{
    if !owner.properties.contains_key("owned_relationship") {
        return Err(query_failure("chain query requires complete canonical relationships"));
    }
    let contract = ecore_model::feature(&owner.kind, field).ok_or_else(|| error("missing chain contract"))?;
    let binding = contract.setting_delegate.as_ref().ok_or_else(|| error("missing chain delegate"))?;
    let (status, candidates): (&str, &[&str]) = match field {
        "owned_feature_chaining" => ("default_setting_delegate_fallback_source", &[]),
        "chaining_feature" => ("custom_setting_delegate_source", &["org.omg.sysml.delegate.setting.Feature_chainingFeature_SettingDelegate"]),
        "feature_target" => ("custom_setting_delegate_source", &["org.omg.sysml.delegate.setting.Feature_featureTarget_SettingDelegate"]),
        _ => return Err(query_failure("unsupported chain projection")),
    };
    if binding.uri != "http://www.omg.org/spec/SysML" || binding.status != status || binding.candidates != candidates {
        return Err(query_failure("unsupported chain delegate binding"));
    }
    let relationships = stored_children_projection_query(query, owner, "owned_relationship")?;
    stored_feature_chain_target_for_scope_query_in_view(query, owner, &relationships, "")?;
    let owned_contract = ecore_model::feature(&owner.kind, "owned_feature_chaining")
        .ok_or_else(|| error("missing owned chain contract"))?;
    let chainings = relationships.into_iter().filter(|r| metaclass_conforms(&r.kind, owned_contract.target)).collect::<Vec<_>>();
    if field == "owned_feature_chaining" { return Ok(chainings); }
    let targets = chainings.iter().map(|r| query_reference_in_view(query, r, "chaining_feature"))
        .collect::<Result<Vec<_>, _>>()?;
    if field == "feature_target" { return Ok(vec![targets.last().copied().unwrap_or(owner)]); }
    Ok(targets)
}

// Resolved TypeAdapter equivalence: canonical identity, or the same nonempty
// ordered Feature chain. Different relationship groups never share deduplication.
fn definition_equivalent_implicit_generals_query(query:&DefinitionNameQuery<'_, '_>, first:&KirElement, second:&KirElement)
    -> Result<bool,QueryFailure> {
    if first.id==second.id {return Ok(true);}
    if !metaclass_conforms(&first.kind,"Feature") || !metaclass_conforms(&second.kind,"Feature") {return Ok(false);}
    let a=definition_chain_reference_targets_typed_query(query,first,"chaining_feature")?;
    let b=definition_chain_reference_targets_typed_query(query,second,"chaining_feature")?;
    Ok(!a.is_empty() && a.len()==b.len() && a.iter().zip(&b).all(|(a,b)|a.id==b.id))
}

// Named handwritten Type.ownedFeature / ownedEndFeature dependencies. Imported
// membership ancestry, typed ownership, subsets, defaults and delegate identities
// supply the structural contracts; no cached derived snapshot is trusted.
// Same duplicate-identity check as standalone stored_children, without rebuilding
// the index. Keep this check at the original read boundary for diagnostic order.
fn stored_children_projection_query<'g>(query: &DefinitionNameQuery<'g, '_>, owner: &KirElement, field: &str)
    -> Result<Vec<&'g KirElement>, Diagnostic> {
    if query.index.len() != query.graph.len() { return Err(error("duplicate model identity")); }
    let canonical = query.index.get(owner.id.as_str()).is_some_and(|node| std::ptr::eq(*node, owner));
    // Cloned/foreign owners retain their own input checks. Never answer them
    // from a same-identity canonical entry.
    if !canonical { return stored_children_indexed(query.index, owner, field); }
    if let Some(children) = query.containments.borrow().get(owner.id.as_str()).and_then(|fields|fields.get(field)) {
        query.observe(DefinitionConstructionEvent {phase:DefinitionConstructionPhase::ContainmentCacheHit,
            owner_id:&owner.id,owner_kind:Some(&owner.kind),field:Some(field),
            element_count:query.graph.len(),succeeded:Some(true)});
        return children.iter().map(|id|query.index.get(id.as_str()).copied()
            .ok_or_else(||error("cached contained element is absent"))).collect();
    }
    let result = query.trace(DefinitionConstructionPhase::ContainmentReadStarted,DefinitionConstructionPhase::ContainmentReadFinished,
        &owner.id,Some(&owner.kind),Some(field),||stored_children_with_container(query.index,owner,field,|child|scope_container_query(query,child)));
    if let Ok(children) = &result {
        query.containments.borrow_mut().entry(owner.id.clone()).or_default().insert(field.to_owned(),children.iter().map(|child|child.id.clone()).collect());
    }
    result
}

/// Successful reciprocal container checks share the same immutable graph view.
/// These are structural inputs, not computed scopes or lifecycle completeness.
fn scope_container_query<'g>(query: &DefinitionNameQuery<'g, '_>, current: &KirElement)
    -> Result<Option<&'g KirElement>, Diagnostic> {
    let canonical = query.index.len() == query.graph.len()
        && query.index.get(current.id.as_str()).is_some_and(|node|std::ptr::eq(*node,current));
    if !canonical {return scope_container(query.index,current);}
    if let Some(parent) = query.containers.borrow().get(current.id.as_str()) {
        query.observe(DefinitionConstructionEvent {phase:DefinitionConstructionPhase::ContainerCacheHit,
            owner_id:&current.id,owner_kind:Some(&current.kind),field:None,
            element_count:query.graph.len(),succeeded:Some(true)});
        return parent.as_ref().map(|id|query.index.get(id.as_str()).copied()
            .ok_or_else(||error("cached scope container is absent"))).transpose();
    }
    let result = query.trace(DefinitionConstructionPhase::ContainerReadStarted,DefinitionConstructionPhase::ContainerReadFinished,
        &current.id,Some(&current.kind),None,||scope_container(query.index,current));
    if let Ok(parent) = &result {query.containers.borrow_mut().insert(current.id.clone(),parent.map(|node|node.id.clone()));}
    result
}

fn definition_owned_features<'g>(graph: &'g [KirElement], owner: &KirElement, ends_only: bool)
    -> Result<Vec<&'g KirElement>, Diagnostic>
{
    let index = graph.iter().map(|e| (e.id.as_str(), e)).collect::<BTreeMap<_, _>>();
    definition_owned_features_query(&DefinitionNameQuery::new(graph, &index), owner, ends_only)
}

fn definition_owned_features_query<'g>(query: &DefinitionNameQuery<'g, '_>, owner: &KirElement, ends_only: bool)
    -> Result<Vec<&'g KirElement>, Diagnostic>
{
    if !owner.properties.contains_key("owned_relationship") { return Err(error("owned Features require complete canonical relationships")); }
    let field = if ends_only { "owned_end_feature" } else { "owned_feature" };
    let contract = ecore_model::feature(&owner.kind, field).ok_or_else(|| error("missing owned Feature contract"))?;
    let delegate = if ends_only { "org.omg.sysml.delegate.setting.Type_ownedEndFeature_SettingDelegate" }
        else { "org.omg.sysml.delegate.setting.Type_ownedFeature_SettingDelegate" };
    let binding = contract.setting_delegate.as_ref().ok_or_else(|| error("missing owned Feature delegate"))?;
    if binding.uri != "http://www.omg.org/spec/SysML" || binding.status != "custom_setting_delegate_source"
        || binding.candidates != [delegate]
        || !ecore_model::has_subset_contract(&owner.kind, "owned_feature", "owned_member")
        || !ecore_model::has_subset_contract(&owner.kind, "owned_end_feature", "owned_feature") {
        return Err(error("unsupported owned Feature derivation contract"));
    }
    let mut result = Vec::new();
    for membership in stored_children_projection_query(query, owner, "owned_relationship")? {
        if !metaclass_conforms(&membership.kind, "FeatureMembership") { continue; }
        let StoredMembershipEndpoint::Resolved(feature) = stored_membership_endpoint_indexed(query.graph.len(), query.index, membership, "member_element")? else {
            return Err(error("owned Feature membership endpoint is unavailable"));
        };
        let member_contract = ecore_model::redefined_feature(&membership.kind, "owned_member_feature").map_err(error)?;
        ecore_model::validate_reference_endpoint(&membership.kind, member_contract.field, &feature.kind).map_err(error)?;
        if (!ends_only || scope_boolean(feature, "is_end")?) && !result.iter().any(|e: &&KirElement| e.id == feature.id) {
            result.push(feature);
        }
    }
    Ok(result)
}

fn definition_default_names(graph: &[KirElement], owner: &KirElement) -> Result<Vec<&'static str>, Diagnostic> {
    let index=graph.iter().map(|e|(e.id.as_str(),e)).collect::<BTreeMap<_,_>>();
    definition_default_names_in_view(&DefinitionNameQuery::new(graph,&index),owner)
}

fn definition_default_names_in_view(query: &DefinitionNameQuery<'_, '_>, owner: &KirElement) -> Result<Vec<&'static str>, Diagnostic> {
    let kind = owner.kind.rsplit("::").next().unwrap_or(&owner.kind);
    let (needs_individual, needs_ends) = definition_defaults_generated::inputs(kind)
        .ok_or_else(|| error("missing resolved Definition default policy"))?;
    let individual = needs_individual && scope_boolean(owner, "is_individual")?;
    // Named normative boundary: the written FlowDefinition constraints count
    // flowEnd, while the imported Pilot selector counts ownedEndFeature. With
    // explicit generals, inherited ends can change that choice. Do not silently
    // adopt the Pilot choice while the recursive flowEnd dependency is unbound.
    if metaclass_conforms(&owner.kind, "FlowDefinition")
        && stored_children_projection_query(query, owner, "owned_relationship")?.iter()
            .any(|r| metaclass_conforms(&r.kind, "Specialization") && r.properties.get("is_implied") != Some(&json!(true))) {
        return Err(error("FlowDefinition default selection requires inherited flowEnd semantics"));
    }
    let ends = if needs_ends { definition_owned_features_query(query, owner, true)?.len() } else { 0 };
    definition_defaults_generated::names(kind, individual, ends).ok_or_else(|| error("missing generated Definition default program"))

}

// Metadata-derived bases remain a named, unsupported dependency. The bounded
// generated program implements only resolved default selection and additions;
// it does not assert that all implied relationships have been materialized.
fn stored_definition_generalizations(graph: &[KirElement], owner: &KirElement, library: &BTreeMap<String, String>)
    -> Result<Vec<String>, Diagnostic>
{
    let index = graph.iter().map(|e| (e.id.as_str(), e)).collect::<BTreeMap<_, _>>();
    stored_definition_generalizations_query(&DefinitionNameQuery::new(graph, &index), owner, library)
}

fn stored_definition_generalizations_query(query: &DefinitionNameQuery<'_, '_>, owner: &KirElement, library: &BTreeMap<String, String>)
    -> Result<Vec<String>, Diagnostic>
{
    let graph = query.graph;
    if !metaclass_conforms(&owner.kind, "Definition") || !owner.properties.contains_key("owned_relationship") {
        return Err(error("Definition defaults require canonical Definition ownership"));
    }
    let complete = scope_boolean(owner, "is_implied_included")?;
    let relationships = stored_children_projection_query(query, owner, "owned_relationship")?;
    for relation in &relationships {
        if metaclass_conforms(&relation.kind, "Conjugation") { return Err(error("conjugated Definition requires its generalization service")); }
        if metaclass_conforms(&relation.kind, "Specialization") && query_reference_in_view(query, relation, "specific").map_err(|failure| failure.into_diagnostic_at("stored_definition_generalizations_query"))?.id != owner.id {
            return Err(error("Definition specialization specific endpoint disagrees with owner"));
        }
    }
    generated_general_types_query(query, owner, &|owner| {
        if complete { return Ok(Vec::new()); }
        definition_projection::require_empty_metadata_bases_query(query, owner)?;
        let mut ids = Vec::new();
        for name in definition_default_names_in_view(query, owner)? {
            let id = library.get(name).ok_or_else(|| error(format!("unresolved Definition library default {name}")))?;
            let target = graph.iter().find(|e| &e.id == id).ok_or_else(|| error("Definition default endpoint is absent"))?;
            let endpoint = ecore_model::redefined_feature("Subclassification", "general").map_err(error)?;
            ecore_model::validate_reference_endpoint("Subclassification", endpoint.field, &target.kind).map_err(error)?;
            if id != &owner.id { ids.push(id.clone()); }
        }
        for relation in &relationships {
            if scope_boolean(relation, "is_implied")? && !definition_assessed_type_default_relation(
                graph, owner, relation, "Subclassification", &ids)? {
                return Err(error("unassessed implied relationship under incomplete Definition"));
            }
        }
        Ok(ids)
    })
}

/// Explicit specialization contribution only; computed generals remain a
/// separate dependency. Imported redefinitions select subtype endpoint fields.
pub(crate) fn stored_explicit_general_types(
    graph: &[KirElement], owner: &KirElement,
) -> Result<Vec<String>, Diagnostic> {
    let relationships = stored_children(graph, owner, "owned_relationship")?;
    explicit_general_types(graph, owner, &relationships)
}

fn explicit_general_types(
    graph: &[KirElement], owner: &KirElement, relationships: &[&KirElement],
) -> Result<Vec<String>, Diagnostic> {
    let index = graph.iter().map(|e| (e.id.as_str(), e)).collect::<BTreeMap<_, _>>();
    explicit_general_types_query(&DefinitionNameQuery::new(graph, &index), owner, relationships)
}

fn explicit_general_types_query(
    query: &DefinitionNameQuery<'_, '_>, owner: &KirElement, relationships: &[&KirElement],
) -> Result<Vec<String>, Diagnostic> {
    explicit_general_types_typed_query(query,owner,relationships).map_err(|failure| failure.into_diagnostic_at("explicit_general_types_query"))
}

fn explicit_general_types_typed_query(
    query: &DefinitionNameQuery<'_, '_>, owner: &KirElement, relationships: &[&KirElement],
) -> Result<Vec<String>, QueryFailure> {
    let mut result = Vec::new();
    for relation in relationships {
        if metaclass_conforms(&relation.kind, "Specialization") {
            let specific = query_reference_in_view(query, relation, "specific")?;
            if specific.id == owner.id {
                result.push(query_reference_in_view(query, relation, "general")?.id.clone());
            }
        }
    }
    Ok(result)
}

/// Handwritten Feature.featureTarget derivation (pinned KerML Feature rules): imported
/// subset/endpoint contracts select ordered owned chainings. This computes a
/// target, not chain conformance or missing implicit relationships.
fn stored_feature_chain_target<'g>(graph: &'g [KirElement], owner: &KirElement, relationships: &[&KirElement]) -> Result<Option<&'g KirElement>, Diagnostic> {
    stored_feature_chain_target_query(graph, owner, relationships).map_err(|failure| failure.into_diagnostic_at("stored_feature_chain_target"))
}

fn stored_feature_chain_target_query<'g>(
    graph: &'g [KirElement], owner: &KirElement, relationships: &[&KirElement],
) -> Result<Option<&'g KirElement>, QueryFailure> {
    stored_feature_chain_target_for_scope_query(graph, owner, relationships, "")
}

fn stored_feature_chain_target_for_scope_query<'g>(
    graph: &'g [KirElement], owner: &KirElement, relationships: &[&KirElement], excluded: &str,
) -> Result<Option<&'g KirElement>, QueryFailure> {
    let index = graph.iter().map(|e| (e.id.as_str(), e)).collect::<BTreeMap<_, _>>();
    stored_feature_chain_target_for_scope_query_in_view(&DefinitionNameQuery::new(graph, &index), owner, relationships, excluded)
}

fn stored_feature_chain_target_for_scope_query_in_view<'g>(
    query: &DefinitionNameQuery<'g, '_>, owner: &KirElement, relationships: &[&KirElement], excluded: &str,
) -> Result<Option<&'g KirElement>, QueryFailure> {
    let skip_navigation = relationships.iter().any(|r|
        r.id == excluded && metaclass_conforms(&r.kind, "FeatureChaining"));
    let mut target = None;
    for relation in relationships.iter().filter(|r| metaclass_conforms(&r.kind, "FeatureChaining")) {
        if !metaclass_conforms(&owner.kind, "Feature")
            || !ecore_model::has_subset_contract(&owner.kind, "owned_feature_chaining", "owned_relationship") {
            return Err(query_failure("owned FeatureChaining requires imported Feature subset contract"));
        }
        // featureChained is derived from canonical owningRelatedElement. Never
        // require a precomputed delegate value, but reconcile it when supplied.
        if relation.properties.get("owning_related_element").and_then(Value::as_str) != Some(owner.id.as_str()) {
            return Err(query_failure("FeatureChaining owner disagrees with canonical containment"));
        }
        if let Some(stored) = relation.properties.get("feature_chained").filter(|v| !v.is_null()) {
            if stored.as_str() != Some(owner.id.as_str()) {
                return Err(query_failure("FeatureChaining source snapshot disagrees with owner"));
            }
        }
        // Exclusion suppresses pending navigation, never canonical ownership or
        // malformed present endpoints. It applies to this ordered chain only.
        if !skip_navigation || relation.properties.contains_key("chaining_feature") {
            let endpoint = query_reference_in_view(query, relation, "chaining_feature")?;
            if !skip_navigation { target = Some(endpoint); }
        }
    }
    Ok(target.filter(|target| target.id != owner.id))
}

/// TypeUtil general-type ordering: explicit owned specializations, then supplied
/// complete implicit generals, then the final FeatureChaining target. Definition
/// annotations select each specialization's specific/general storage slots.
#[allow(dead_code)]
fn generated_general_types(
    graph: &[KirElement],
    owner: &KirElement,
    implicit: &impl Fn(&KirElement) -> Result<Vec<String>, Diagnostic>,
) -> Result<Vec<String>, Diagnostic> {
    let index = graph.iter().map(|e| (e.id.as_str(), e)).collect::<BTreeMap<_, _>>();
    generated_general_types_query(&DefinitionNameQuery::new(graph, &index), owner, implicit)
}

fn generated_general_types_query(
    query: &DefinitionNameQuery<'_, '_>,
    owner: &KirElement,
    implicit: &impl Fn(&KirElement) -> Result<Vec<String>, Diagnostic>,
) -> Result<Vec<String>, Diagnostic> {
    generated_general_types_typed_query(query, owner, &|owner| implicit(owner).map_err(QueryFailure::from)).map_err(|failure| failure.into_diagnostic_at("generated_general_types_query"))
}

fn generated_general_types_typed_query(
    query: &DefinitionNameQuery<'_, '_>,
    owner: &KirElement,
    implicit: &impl Fn(&KirElement) -> Result<Vec<String>, QueryFailure>,
) -> Result<Vec<String>, QueryFailure> {
    if !metaclass_conforms(&owner.kind, "Type") {
        return Err(query_failure("general-type owner is not a Type"));
    }
    generated_general_types_for_scope_typed_query(query, owner, implicit, "")
}

// TypeUtil.getGeneralTypesOf(type, excludeImplied, skip) omits navigation of
// an ordered Feature chain containing the reference currently being resolved.
// This context is temporary; full model queries still read every chain endpoint.
fn generated_general_types_for_scope_typed_query(
    query: &DefinitionNameQuery<'_, '_>, owner: &KirElement,
    implicit: &impl Fn(&KirElement) -> Result<Vec<String>, QueryFailure>,
    excluded: &str,
) -> Result<Vec<String>, QueryFailure> {
    let graph = query.graph;
    let relationships = stored_children_projection_query(query, owner, "owned_relationship")?;
    let mut result = explicit_general_types_typed_query(query, owner, &relationships)?;
    for id in implicit(owner)? {
        let target = graph
            .iter()
            .find(|e| e.id == id)
            .ok_or_else(|| query_failure("implicit general is absent"))?;
        if !metaclass_conforms(&target.kind, "Type") {
            return Err(query_failure("implicit general is not a Type"));
        }
        result.push(id);
    }
    if let Some(target) = stored_feature_chain_target_for_scope_query_in_view(query, owner, &relationships, excluded)? {
        result.push(target.id.clone());
    }
    Ok(result)
}

/// Bounded plain-Type default computation. The caller supplies qualified
/// library-name bindings; this service never guesses global IDs from spelling.
/// Resolved upstream defaults are generated at build time. Conditional adapter
/// subclasses and metadata-derived bases require their own semantic service.
pub(crate) fn stored_plain_type_generalizations(
    graph: &[KirElement], owner: &KirElement, library: &BTreeMap<String, String>,
) -> Result<Vec<String>, Diagnostic> {
    let index = graph.iter().map(|e| (e.id.as_str(), e)).collect::<BTreeMap<_, _>>();
    stored_plain_type_generalizations_query(&DefinitionNameQuery::new(graph, &index), owner, library)
}

fn stored_plain_type_generalizations_query(
    query: &DefinitionNameQuery<'_, '_>, owner: &KirElement, library: &BTreeMap<String, String>,
) -> Result<Vec<String>, Diagnostic> {
    let graph = query.graph;
    let kind = owner.kind.rsplit("::").next().unwrap_or(&owner.kind);
    let (_, name, relation_kind) = default_generals_generated::DEFAULT_GENERALS.iter()
        .find(|(candidate, _, _)| *candidate == kind)
        .ok_or_else(|| error("plain-Type default provider does not support this metaclass"))?;
    if !owner.properties.contains_key("owned_relationship") {
        return Err(error("default generalization requires complete canonical owned_relationship"));
    }
    let relationships = stored_children_projection_query(query, owner, "owned_relationship")?;
    if relationships.iter().any(|e| metaclass_conforms(&e.kind, "Conjugation")) {
        return Err(error("conjugated Type requires its dedicated generalization service"));
    }
    for relation in &relationships {
        if metaclass_conforms(&relation.kind, "Specialization")
            && query_reference_in_view(query, relation, "specific").map_err(|failure| failure.into_diagnostic_at("stored_plain_type_generalizations_query"))?.id != owner.id {
            return Err(error("specialization specific endpoint disagrees with owner"));
        }
    }
    let complete = scope_boolean(owner, "is_implied_included")?;
    generated_general_types_query(query, owner, &|owner| {
        if complete { return Ok(Vec::new()); }
        definition_projection::require_empty_metadata_bases_query(query, owner)?;
        let id = library.get(*name).ok_or_else(|| error(format!("unresolved library default {name}")))?;
        for relation in &relationships {
            if scope_boolean(relation, "is_implied")? && !definition_assessed_type_default_relation(
                graph, owner, relation, relation_kind, std::slice::from_ref(id))? {
                return Err(error("unassessed implied relationship under incomplete plain Type"));
            }
        }
        let target = graph.iter().find(|e| &e.id == id).ok_or_else(|| error("library default endpoint is absent"))?;
        ecore_model::validate_reference_endpoint(relation_kind, "general", &target.kind).map_err(error)?;
        if !metaclass_conforms(&target.kind, kind) {
            return Err(error("library default does not conform to its plain metaclass requirement"));
        }
        Ok(if id == &owner.id { Vec::new() } else { vec![id.clone()] })
    })
}

/// Resolve generated default names only through explicit standard-library roots
/// and canonical memberships. Legacy ID spellings never supply missing names.
pub(crate) fn stored_standard_default_bindings(graph: &[KirElement]) -> Result<BTreeMap<String, String>, Diagnostic> {
    let index = graph.iter().map(|e| (e.id.as_str(), e)).collect::<BTreeMap<_, _>>();
    if index.len() != graph.len() { return Err(error("duplicate model identity")); }
    let mut required = BTreeSet::new();
    for owner in graph.iter().filter(|e| metaclass_conforms(&e.kind, "Type")) {
        if scope_boolean(owner, "is_implied_included")? { continue; }
        let kind = owner.kind.rsplit("::").next().unwrap_or(&owner.kind);
        let (_, name, _) = default_generals_generated::DEFAULT_GENERALS.iter()
            .find(|(candidate, _, _)| *candidate == kind)
            .ok_or_else(|| error("plain-Type default provider does not support this metaclass"))?;
        required.insert(*name);
    }
    standard_default_bindings(graph, &required)
}

// Only requested defaults are resolved: unrelated source Features must not
// force the plain-Type provider to impersonate their semantic adapters.
fn standard_default_bindings(graph: &[KirElement], required: &BTreeSet<&str>) -> Result<BTreeMap<String, String>, Diagnostic> {
    let index = graph.iter().map(|e| (e.id.as_str(), e)).collect::<BTreeMap<_, _>>();
    if index.len() != graph.len() { return Err(error("duplicate model identity")); }
    let query = DefinitionNameQuery::new(graph, &index);
    let mut bindings = BTreeMap::new();
    for name in required {
        let GeneratedLinkTarget::Local(id) = standard_default_binding_query(&query, name)? else {
            return Err(error("standard library requires resolved imports and member endpoints"));
        };
        bindings.insert((*name).into(), id);
    }
    Ok(bindings)
}

fn standard_default_binding(graph: &[KirElement], name: &str) -> Result<GeneratedLinkTarget<'static>, Diagnostic> {
    let index = graph.iter().map(|e| (e.id.as_str(), e)).collect::<BTreeMap<_, _>>();
    if index.len() != graph.len() { return Err(error("duplicate model identity")); }
    standard_default_binding_query(&DefinitionNameQuery::new(graph, &index), name)
}

fn standard_default_binding_query(query: &DefinitionNameQuery<'_, '_>, name: &str)
    -> Result<GeneratedLinkTarget<'static>, Diagnostic> {
    query.trace(DefinitionConstructionPhase::LibraryPathStarted,DefinitionConstructionPhase::LibraryPathFinished,
        "",None,Some(name),||standard_default_binding_evaluate(query,name))
}

// Handwritten canonical library navigation. Known absence is separate from
// a pending semantic prerequisite or a rejected malformed/ambiguous graph.
enum StandardLibraryLookup {
    Found(GeneratedLinkTarget<'static>),
    Absent(StandardLibraryAbsence),
}

enum StandardLibraryAbsence { Root(String), Member(String) }

impl StandardLibraryAbsence {
    fn diagnostic(self) -> Diagnostic { match self {
        Self::Root(name) => error(format!("missing standard library root {name}")),
        Self::Member(name) => error(format!("unresolved standard library member {name}")),
    } }
}

fn standard_default_binding_evaluate(query: &DefinitionNameQuery<'_, '_>, name: &str)
    -> Result<GeneratedLinkTarget<'static>, Diagnostic> {
    match standard_library_lookup_evaluate(query,name)? {
        StandardLibraryLookup::Found(target) => Ok(target),
        StandardLibraryLookup::Absent(reason) => Err(reason.diagnostic()),
    }
}

fn standard_library_lookup_evaluate(query: &DefinitionNameQuery<'_, '_>, name: &str)
    -> Result<StandardLibraryLookup, Diagnostic> {
    if let Some(id) = query.standard_paths.borrow().get(name) {
        return Ok(StandardLibraryLookup::Found(GeneratedLinkTarget::Local(id.clone())));
    }
    let result = standard_library_lookup_uncached(query, name)?;
    if let StandardLibraryLookup::Found(GeneratedLinkTarget::Local(id)) = &result {
        query.standard_paths.borrow_mut().insert(name.to_owned(), id.clone());
    }
    Ok(result)
}

fn standard_library_lookup_uncached(query: &DefinitionNameQuery<'_, '_>, name: &str)
    -> Result<StandardLibraryLookup, Diagnostic> {
    let graph = query.graph;
    let index = query.index;
    let segments = crate::xtext_fragment::reference_name_segments(name,true).map_err(error)?;
    let mut root_match = None;
    for root in graph.iter().filter(|e| metaclass_conforms(&e.kind, "LibraryPackage")) {
        if !scope_boolean(root, "is_standard")? { continue; }
        if let Some(container) = generated_parent_namespace_indexed(index, &root.id)? {
            // The generated RootNamespace is an unnamed, unowned Namespace.
            // A nested package with a familiar spelling is never a library root.
            if container.kind.rsplit("::").next() != Some("Namespace")
                || scope_container(index, container)?.is_some()
                || generated_effective_names(graph, container)?.iter().any(Option::is_some) { continue; }
        }
        if generated_effective_names(graph, root)?.iter().flatten().any(|n| n == &segments[0]) {
            if root_match.replace(root).is_some() { return Err(error(format!("ambiguous standard library root {}", segments[0]))); }
        }
    }
    let Some(mut current) = root_match else { return Ok(StandardLibraryLookup::Absent(StandardLibraryAbsence::Root(segments[0].clone()))); };
    for segment in &segments[1..] {
        if !metaclass_conforms(&current.kind, "Namespace") { return Err(error("library path crosses a non-Namespace")); }
        // A direct public library member has lexical precedence. Do not require
        // unrelated inherited scopes merely to resolve an explicitly owned name.
        let mut direct = Vec::new();
        for member in stored_children_indexed(index, current, "owned_relationship")? {
            if metaclass_conforms(&member.kind, "Membership") && scope_public(member)? {
                let names = match query.membership_names_query(member, &|_| {}) {
                    Ok(value) => value,
                    Err(failure) => return query_link_target(failure).map(StandardLibraryLookup::Found),
                };
                if names.iter().any(|candidate| candidate == segment) { direct.push(member); }
            }
        }
        let members = if !direct.is_empty() { direct } else {
            match scope_memberships_query(graph, current, false, false, "", &BTreeSet::new(),
                &mut BTreeSet::new(), MembershipScopeMode::CanonicalVisible, query, &|_| {})? {
                Members::Ready(members) => members,
                Members::Deferred(deferred) => return Ok(StandardLibraryLookup::Found(deferred)),
            }
        };
        let mut selected = None;
        for member in members {
            let names = match query.membership_names_query(member, &|_| {}) {
                Ok(value) => value,
                Err(failure) => return query_link_target(failure).map(StandardLibraryLookup::Found),
            };
            if !names.iter().any(|candidate| candidate == segment) { continue; }
            let target = match membership_element_indexed(index, member)? {
                GeneratedLinkTarget::Local(id) => *index.get(id.as_str()).ok_or_else(|| error("standard library member is absent"))?,
                deferred @ (GeneratedLinkTarget::Deferred { .. } | GeneratedLinkTarget::ConstructBinaryCrossing { .. } | GeneratedLinkTarget::ConstructCrossSpecialization { .. } | GeneratedLinkTarget::ConstructAdditionalMembers { .. } | GeneratedLinkTarget::ConstructReferenceResultSubsetting { .. } | GeneratedLinkTarget::ConstructChainSpecialization { .. } | GeneratedLinkTarget::ConstructExpressionContributions { .. } | GeneratedLinkTarget::ConstructExpressionContributionBatch { .. } | GeneratedLinkTarget::ConstructReferenceBindingBatch { .. } | GeneratedLinkTarget::ConstructGeneralValueBindingBatch { .. } | GeneratedLinkTarget::ConstructArgumentResultSpecializationBatch { .. } | GeneratedLinkTarget::ConstructChainLifecycleBatch { .. } | GeneratedLinkTarget::ConstructOwningTypeFeaturingBatch { .. } | GeneratedLinkTarget::ConstructExpressionFeaturingBatch { .. } | GeneratedLinkTarget::ConstructMultiplicityFeaturing { .. }) => return Ok(StandardLibraryLookup::Found(deferred)),
                GeneratedLinkTarget::External(_) => return Err(error("standard library member must be local")),
            };
            if selected.is_some_and(|previous: &KirElement| previous.id != target.id) {
                return Err(error(format!("ambiguous standard library member {name}")));
            }
            selected = Some(target);
        }
        let Some(target) = selected else { return Ok(StandardLibraryLookup::Absent(StandardLibraryAbsence::Member(name.into()))); };
        current = target;
    }
    Ok(StandardLibraryLookup::Found(GeneratedLinkTarget::Local(current.id.clone())))
}

// Shared ordered Type selection: skip only known absence and non-Type values.
// First Type is decisive; callers apply their narrower Ecore return contract.
fn definition_library_type_query<'g>(query: &DefinitionNameQuery<'g, '_>, names: &[String])
    -> Result<Option<&'g KirElement>, QueryFailure> {
    if query.index.len()!=query.graph.len() {return Err(query_failure("duplicate model identity"));}
    for name in names {
        let lookup=query.trace(DefinitionConstructionPhase::LibraryPathStarted,DefinitionConstructionPhase::LibraryPathFinished,
            "",None,Some(name),||standard_library_lookup_evaluate(query,name))?;
        let StandardLibraryLookup::Found(target)=lookup else {continue;};
        let id=query_local_binding(target)?;
        let element=*query.index.get(id.as_str()).ok_or_else(||query_failure("library Type endpoint is absent"))?;
        if metaclass_conforms(&element.kind,"Type") {return Ok(Some(element));}
    }
    Ok(None)
}

/// Native result inheritance traversal. The caller must establish complete
/// additional members and supply ordered general types (including implicit
/// supertypes and final chain targets). These are mandatory semantic services,
/// not empty-list fallbacks. Both services may reject an unresolved dependency.
#[allow(dead_code)]
fn generated_result_parameter<'g>(
    graph: &'g [KirElement],
    identity: &str,
    members_ready: &impl Fn(&KirElement) -> Result<(), Diagnostic>,
    general_types: &impl Fn(&KirElement) -> Result<Vec<String>, Diagnostic>,
) -> Result<Option<&'g KirElement>, Diagnostic> {
    let index = graph.iter().map(|e| (e.id.as_str(), e)).collect::<BTreeMap<_, _>>();
    generated_result_parameter_query(&DefinitionNameQuery::new(graph, &index), identity,
        &|owner| members_ready(owner).map_err(QueryFailure::from),
        &|owner| general_types(owner).map_err(QueryFailure::from))
        .map_err(|failure| failure.into_diagnostic_at("generated_result_parameter external boundary"))
}

fn generated_result_parameter_query<'g>(
    query: &DefinitionNameQuery<'g, '_>,
    identity: &str,
    members_ready: &impl Fn(&KirElement) -> Result<(), QueryFailure>,
    general_types: &impl Fn(&KirElement) -> Result<Vec<String>, QueryFailure>,
) -> Result<Option<&'g KirElement>, QueryFailure> {
    let graph = query.graph;
    let index = query.index;
    if index.len() != graph.len() {
        return Err(query_failure("duplicate result graph identity"));
    }
    let mut pending = vec![identity.to_owned()];
    let mut visited = BTreeSet::new();
    while let Some(id) = pending.pop() {
        if !visited.insert(id.clone()) {
            continue;
        }
        let owner = *index
            .get(id.as_str())
            .ok_or_else(|| error("missing result general type"))?;
        if !metaclass_conforms(&owner.kind, "Type") {
            return Err(query_failure("result general is not a Type"));
        }
        members_ready(owner)?;
        if let Some(result) = parameter_members::owned_result(query, &id)? {
            return Ok(Some(result));
        }
        // Reverse stack insertion preserves the upstream depth-first, first-result
        // order. Cyclic generalization is legal and each Type is visited once.
        let generals = general_types(owner)?;
        for general in generals.iter().rev() {
            let endpoint = index
                .get(general.as_str())
                .ok_or_else(|| error("unresolved result general type"))?;
            if !metaclass_conforms(&endpoint.kind, "Type") {
                return Err(query_failure("result general is not a Type"));
            }
            pending.push(general.clone());
        }
    }
    Ok(None)
}

struct PendingModelLink<'t> {
    owner_id: String,
    owner_kind: String,
    feature: &'static ecore_model::FeatureContract,
    references: &'t [crate::xtext_fragment::PendingReference],
    ancestors: Vec<&'t crate::xtext_fragment::Match>,
}

/// Scope selection is an explicit handwritten dependency supplied by the caller.
/// It must return an existing, uniquely resolved endpoint; this bridge checks
/// both the Xtext narrowing and Ecore feature type before storing its identity.
fn materialize_generated_with_links<'a>(
    tree: &crate::xtext_fragment::Match,
    id: &str,
    resolve: &impl Fn(&crate::xtext_fragment::PendingReference) -> Result<&'a KirElement, Diagnostic>,
) -> Result<(KirElement, Vec<KirElement>), Diagnostic> {
    materialize_generated_with_context(tree, id, &|site| resolve(site.reference))
}

/// Explicit endpoint provenance prevents an external object with a colliding ID
/// from impersonating an object in the newly constructed graph.
#[allow(dead_code)]
enum GeneratedLinkTarget<'a> {
    External(&'a KirElement),
    Local(String),
    /// A concrete, bounded graph edit required before retrying this lookup.
    ConstructBinaryCrossing { owner_id: String },
    ConstructCrossSpecialization { owner_id: String },
    ConstructAdditionalMembers { owner_id: String },
    ConstructReferenceResultSubsetting { owner_id: String },
    ConstructChainSpecialization { owner_id: String },
    ConstructExpressionContributions { owner_id: String },
    ConstructExpressionContributionBatch { owner_ids: Vec<String> },
    ConstructReferenceBindingBatch { owner_ids: Vec<String> },
    ConstructGeneralValueBindingBatch { owner_ids: Vec<String> },
    ConstructArgumentResultSpecializationBatch { owner_ids: Vec<String> },
    ConstructChainLifecycleBatch { owner_ids: Vec<String> },
    ConstructOwningTypeFeaturingBatch { owner_ids: Vec<String> },
    ConstructExpressionFeaturingBatch { owner_ids: Vec<String> },
    ConstructMultiplicityFeaturing { owner_id: String },
    /// Retry only after this concrete pending storage field is resolved.
    /// Ordinary scope/ambiguity errors must remain Err, never implicit retries.
    Deferred {
        owner_id: String,
        field: String,
    },
}

fn query_requirement(target: GeneratedLinkTarget<'_>) -> QueryFailure {
    QueryFailure::Required(match target {
        GeneratedLinkTarget::Deferred { owner_id, field } => Prerequisite::ReadField { owner_id, field },
        GeneratedLinkTarget::ConstructBinaryCrossing { owner_id } => Prerequisite::BinaryCrossing { owner_id },
        GeneratedLinkTarget::ConstructCrossSpecialization { owner_id } => Prerequisite::CrossSpecialization { owner_id },
        GeneratedLinkTarget::ConstructAdditionalMembers { owner_id } => Prerequisite::AdditionalMembers { owner_id },
        GeneratedLinkTarget::ConstructReferenceResultSubsetting { owner_id } => Prerequisite::ReferenceResultSubsetting { owner_id },
        GeneratedLinkTarget::ConstructChainSpecialization { owner_id } => Prerequisite::ChainSpecialization { owner_id },
        GeneratedLinkTarget::ConstructExpressionContributions { owner_id } => Prerequisite::ExpressionContributions { owner_id },
        GeneratedLinkTarget::ConstructExpressionContributionBatch { owner_ids } => Prerequisite::ExpressionContributionBatch { owner_ids },
        GeneratedLinkTarget::ConstructReferenceBindingBatch { owner_ids } => Prerequisite::ReferenceBindingBatch { owner_ids },
        GeneratedLinkTarget::ConstructGeneralValueBindingBatch { owner_ids } => Prerequisite::GeneralValueBindingBatch { owner_ids },
        GeneratedLinkTarget::ConstructArgumentResultSpecializationBatch { owner_ids } => Prerequisite::ArgumentResultSpecializationBatch { owner_ids },
        GeneratedLinkTarget::ConstructChainLifecycleBatch { owner_ids } => Prerequisite::ChainLifecycleBatch { owner_ids },
        GeneratedLinkTarget::ConstructOwningTypeFeaturingBatch { owner_ids } => Prerequisite::OwningTypeFeaturingBatch { owner_ids },
        GeneratedLinkTarget::ConstructExpressionFeaturingBatch { owner_ids } => Prerequisite::ExpressionFeaturingBatch { owner_ids },
        GeneratedLinkTarget::ConstructMultiplicityFeaturing { owner_id } => Prerequisite::MultiplicityFeaturing { owner_id },
        _ => return query_failure("expected an unresolved query prerequisite"),
    })
}

fn query_local_binding(target: GeneratedLinkTarget<'_>) -> Result<String, QueryFailure> {
    match target {
        GeneratedLinkTarget::Local(id) => Ok(id),
        GeneratedLinkTarget::External(_) => Err(query_failure("semantic binding requires a local endpoint")),
        pending => Err(query_requirement(pending)),
    }
}

fn query_link_target(failure: QueryFailure) -> Result<GeneratedLinkTarget<'static>, Diagnostic> {
    match failure {
        QueryFailure::Required(Prerequisite::ReadField { owner_id, field }) => Ok(GeneratedLinkTarget::Deferred { owner_id, field }),
        QueryFailure::Required(Prerequisite::BinaryCrossing { owner_id }) => Ok(GeneratedLinkTarget::ConstructBinaryCrossing { owner_id }),
        QueryFailure::Required(Prerequisite::CrossSpecialization { owner_id }) => Ok(GeneratedLinkTarget::ConstructCrossSpecialization { owner_id }),
        QueryFailure::Required(Prerequisite::AdditionalMembers { owner_id }) => Ok(GeneratedLinkTarget::ConstructAdditionalMembers { owner_id }),
        QueryFailure::Required(Prerequisite::ReferenceResultSubsetting { owner_id }) => Ok(GeneratedLinkTarget::ConstructReferenceResultSubsetting { owner_id }),
        QueryFailure::Required(Prerequisite::ChainSpecialization { owner_id }) => Ok(GeneratedLinkTarget::ConstructChainSpecialization { owner_id }),
        QueryFailure::Required(Prerequisite::ExpressionContributions { owner_id }) => Ok(GeneratedLinkTarget::ConstructExpressionContributions { owner_id }),
        QueryFailure::Required(Prerequisite::ExpressionContributionBatch { owner_ids }) => Ok(GeneratedLinkTarget::ConstructExpressionContributionBatch { owner_ids }),
        QueryFailure::Required(Prerequisite::ReferenceBindingBatch { owner_ids }) => Ok(GeneratedLinkTarget::ConstructReferenceBindingBatch { owner_ids }),
        QueryFailure::Required(Prerequisite::GeneralValueBindingBatch { owner_ids }) => Ok(GeneratedLinkTarget::ConstructGeneralValueBindingBatch { owner_ids }),
        QueryFailure::Required(Prerequisite::ArgumentResultSpecializationBatch { owner_ids }) => Ok(GeneratedLinkTarget::ConstructArgumentResultSpecializationBatch { owner_ids }),
        QueryFailure::Required(Prerequisite::ChainLifecycleBatch { owner_ids }) => Ok(GeneratedLinkTarget::ConstructChainLifecycleBatch { owner_ids }),
        QueryFailure::Required(Prerequisite::OwningTypeFeaturingBatch { owner_ids }) => Ok(GeneratedLinkTarget::ConstructOwningTypeFeaturingBatch { owner_ids }),
        QueryFailure::Required(Prerequisite::ExpressionFeaturingBatch { owner_ids }) => Ok(GeneratedLinkTarget::ConstructExpressionFeaturingBatch { owner_ids }),
        QueryFailure::Required(Prerequisite::MultiplicityFeaturing { owner_id }) => Ok(GeneratedLinkTarget::ConstructMultiplicityFeaturing { owner_id }),
        QueryFailure::Rejected(diagnostic) => Err(diagnostic),
    }
}

#[allow(dead_code)]
fn materialize_generated_with_context<'a>(
    tree: &crate::xtext_fragment::Match,
    id: &str,
    resolve: &impl Fn(&GeneratedReferenceSite<'_>) -> Result<&'a KirElement, Diagnostic>,
) -> Result<(KirElement, Vec<KirElement>), Diagnostic> {
    materialize_generated_with_targets(tree, id, &|site| {
        resolve(site).map(GeneratedLinkTarget::External)
    })
}

