    fn chain_member_tree_input(node:&Value,id:&str,graph:&mut Vec<KirElement>) {
        let mut element=fresh_definition_element(id.into(),node["kind"].as_str().unwrap()).unwrap();
        for (key,field) in [("name","declared_name"),("direction","direction"),("is_implied_included","is_implied_included")] {if let Some(value)=node.get(key) {element.properties.insert(field.into(),value.clone());}}
        if let Some(value)=node.get("visibility") {element.properties.insert("visibility".into(),value.clone());}graph.push(element);
        for (field,relationship) in [("relationships",true),("elements",false)] {if let Some(children)=node.get(field).and_then(Value::as_array) {for (i,child) in children.iter().enumerate() {let child_id=format!("{id}.{field}.{i}");chain_member_tree_input(child,&child_id,graph);relative_fixture_attach(graph,id,&child_id,relationship);}}}
    }
    fn chain_member_tree_output(graph:&[KirElement],id:&str)->Value {
        let element=graph.iter().find(|e|e.id==id).unwrap();let mut row=serde_json::Map::new();row.insert("kind".into(),json!(element.kind.rsplit("::").next().unwrap()));
        if let Some(name)=element.properties.get("declared_name").filter(|v|!v.is_null()) {row.insert("name".into(),name.clone());}
        if metaclass_conforms(&element.kind,"Type") {row.insert("is_implied_included".into(),json!(scope_boolean(element,"is_implied_included").unwrap()));}
        if let Some(direction)=element.properties.get("direction").filter(|v|!v.is_null()) {row.insert("direction".into(),direction.clone());}
        if metaclass_conforms(&element.kind,"Membership") {row.insert("visibility".into(),ecore_defaults::read_attribute(element,"visibility").unwrap());}
        for (field,stored) in [("relationships","owned_relationship"),("elements","owned_related_element")] {if field=="elements"&&!metaclass_conforms(&element.kind,"Relationship") {continue;}row.insert(field.into(),json!(stored_children(graph,element,stored).unwrap().iter().map(|e|chain_member_tree_output(graph,&e.id)).collect::<Vec<_>>()));}
        Value::Object(row)
    }
    #[test]
    fn definition_feature_chain_members_match_all_cached_producers_and_persistence() {
        let artifact:Value=serde_json::from_str(include_str!("../../../../../../docs/conformance/2026-08-support/feature-chain-members-pilot-controls.json")).unwrap();let cases=artifact["controls"].as_array().unwrap();assert_eq!(cases.len(),56);
        for case in cases {
            let mut original=Vec::new();chain_member_tree_input(&case["before"],"owner",&mut original);
            for reverse in [false,true] {
                let mut graph:Vec<KirElement>=serde_json::from_value(serde_json::to_value(&original).unwrap()).unwrap();if reverse {graph.reverse();}
                let before=serde_json::to_value(&graph).unwrap();let changed=feature_chain_members::append(&mut graph,"owner","constructor").unwrap_or_else(|e|panic!("{case}: {e:?}"));
                assert_eq!(changed,case["before"]!=case["after"]);assert_eq!(chain_member_tree_output(&graph,"owner"),case["after"],"{case}");
                assert_eq!(graph.iter().find(|e|e.id=="owner").unwrap().properties.get("is_implied_included"),case["before"].get("is_implied_included"));
                assert!(!feature_chain_members::append(&mut graph,"owner","replay").unwrap());let saved=serde_json::to_value(&graph).unwrap();
                let mut persisted:Vec<KirElement>=serde_json::from_value(saved.clone()).unwrap();persisted.reverse();assert!(!feature_chain_members::append(&mut persisted,"owner","persisted.replay").unwrap());assert_eq!(chain_member_tree_output(&persisted,"owner"),case["after"]);
                assert!(feature_chain_members::ready(&graph,graph.iter().find(|e|e.id=="owner").unwrap()).unwrap().unwrap());
                if !changed {assert_eq!(serde_json::to_value(&graph).unwrap(),before);}
            }
        }
    }
