    #[test]
    fn definition_feature_defaults_unlock_connector_library_inheritance() {
        let source = "standard library package Base { feature things; } standard library package Links { feature links subsets Base::things { alias marker for Base::things; } } package P { connector x; feature y subsets x::marker; }";
        let doc = crate::definition_document::parse_and_link(source, crate::SourceLanguage::Kerml).unwrap();
        let named = |name: &str| doc.elements.iter().find(|e| e.properties.get("declared_name") == Some(&json!(name))).unwrap();
        let before = serde_json::to_value(&doc).unwrap();
        assert!(crate::definition_document::specializes(&doc, &named("x").id, &named("things").id).unwrap());
        let subset = stored_children(&doc.elements, named("y"), "owned_relationship").unwrap().into_iter().find(|e| metaclass_conforms(&e.kind, "Subsetting")).unwrap();
        assert_eq!(redefined_reference(&doc.elements, subset, "subsetted_feature").unwrap().id, named("things").id);
        assert_eq!(serde_json::to_value(&doc).unwrap(), before);
        assert!(doc.elements.iter().all(|e| e.properties.get("is_implied_included") != Some(&json!(true))));
        for field in ["is_end", "direction"] {
            let mut excluded = named("things").clone();
            excluded.properties.insert(field.into(), if field == "direction" { json!("in") } else { json!(true) });
            assert!(definition_feature_default_name(&doc.elements, &excluded).is_err());
        }
        let mut subclass = named("things").clone(); subclass.kind = "SysML::Usage".into();
        assert!(definition_feature_default_name(&doc.elements, &subclass).is_err());
        for kind in ["FeatureValue", "Conjugation", "CrossSubsetting"] {
            let mut graph = doc.elements.clone();
            let mut owner = named("things").clone();
            let mut relation = fresh_definition_element("excluded".into(), kind).unwrap();
            ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, &mut owner, &mut relation).unwrap();
            *graph.iter_mut().find(|e| e.id == owner.id).unwrap() = owner.clone(); graph.push(relation);
            assert!(definition_feature_default_name(&graph, &owner).is_err());
        }
    }

    #[test]
    fn definition_feature_owned_defaults_reach_source_and_reject_unknown_owners() {
        let source = "standard library package Base { feature things; } standard library package Links { feature links subsets Base::things { feature marker; } } package P { connector x; feature y subsets x::marker; feature outer { feature middle { feature leaf; } } }";
        let doc = crate::definition_document::parse_and_link(source, crate::SourceLanguage::Kerml).unwrap();
        let named = |name: &str| doc.elements.iter().find(|e| e.properties.get("declared_name") == Some(&json!(name))).unwrap();
        let before = serde_json::to_value(&doc).unwrap();
        let subset = stored_children(&doc.elements, named("y"), "owned_relationship").unwrap().into_iter().find(|e| metaclass_conforms(&e.kind, "Subsetting")).unwrap();
        assert_eq!(redefined_reference(&doc.elements, subset, "subsetted_feature").unwrap().id, named("marker").id);
        assert!(crate::definition_document::specializes(&doc, &named("leaf").id, &named("things").id).unwrap());
        assert_eq!(serde_json::to_value(&doc).unwrap(), before);
        assert!(doc.elements.iter().all(|e| e.properties.get("is_implied_included") != Some(&json!(true))));
        for (field, value) in [("is_end", json!(true)), ("direction", json!("in"))] {
            let mut graph = doc.elements.clone();
            graph.iter_mut().find(|e| e.id == named("outer").id).unwrap().properties.insert(field.into(), value);
            assert!(definition_feature_default_name(&graph, named("leaf")).unwrap_err().message.contains("non-end"));
        }
        for kind in ["FeatureValue", "CrossSubsetting", "Conjugation"] {
            let mut graph = doc.elements.clone();
            let owner = graph.iter_mut().find(|e| e.id == named("outer").id).unwrap();
            let mut relation = fresh_definition_element("excluded".into(), kind).unwrap();
            ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, owner, &mut relation).unwrap();
            graph.push(relation);
            assert!(definition_feature_default_name(&graph, named("leaf")).is_err(), "{kind}");
        }
        let mut graph = doc.elements.clone();
        graph.iter_mut().find(|e| e.id == named("outer").id).unwrap().kind = "SysML::Usage".into();
        assert!(definition_feature_default_name(&graph, named("leaf")).is_err());
        let mut graph = doc.elements.clone();
        let index = graph.iter().map(|e| (e.id.as_str(), e)).collect();
        let member_id = scope_container(&index, named("leaf")).unwrap().unwrap().id.clone();
        graph.iter_mut().find(|e| e.id == member_id).unwrap().kind = "SysML::OwningMembership".into();
        assert!(definition_feature_default_name(&graph, named("leaf")).is_err());
    }

    #[test]
    fn definition_feature_owned_defaults_reject_ownership_cycles() {
        let mut a = fresh_definition_element("a".into(), "Feature").unwrap();
        let mut b = fresh_definition_element("b".into(), "Feature").unwrap();
        let mut am = fresh_definition_element("am".into(), "FeatureMembership").unwrap();
        let mut bm = fresh_definition_element("bm".into(), "FeatureMembership").unwrap();
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS, &mut am, &mut a).unwrap();
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS, &mut bm, &mut b).unwrap();
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, &mut a, &mut bm).unwrap();
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, &mut b, &mut am).unwrap();
        let graph = vec![a.clone(), b, am, bm];
        assert!(definition_feature_default_name(&graph, &a).unwrap_err().message.contains("acyclic ownership"));
    }

