    #[test]
    fn definition_association_defaults_match_resolved_controls_and_boundaries() {
        let artifact: Value = serde_json::from_str(include_str!("../../../../resources/metamodels/sysml-2.0-pilot-2026-08/feature-defaults.extract.json")).unwrap();
        let library = crate::definition_document::parse_and_link(artifact["association_source_controls"][0]["source"].as_str().unwrap(), crate::SourceLanguage::Kerml).unwrap();
        let controls = artifact["association_controls"].as_array().unwrap();
        assert_eq!(controls.len(), 16);
        for control in controls {
            let mut graph = library.elements.clone();
            let mut association = fresh_definition_element("sample".into(), control["kind"].as_str().unwrap()).unwrap();
            for i in 0..control["owned_ends"].as_u64().unwrap() {
                let mut end = fresh_definition_element(format!("end{i}"), "Feature").unwrap(); end.properties.insert("is_end".into(), json!(true));
                let mut member = fresh_definition_element(format!("end-member{i}"), "EndFeatureMembership").unwrap();
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS, &mut member, &mut end).unwrap();
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, &mut association, &mut member).unwrap();
                graph.extend([end, member]);
            }
            if control["package_owned"] == true {
                let mut namespace = fresh_definition_element("package".into(), "Package").unwrap();
                let mut member = fresh_definition_element("package-member".into(), "OwningMembership").unwrap();
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS, &mut member, &mut association).unwrap();
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, &mut namespace, &mut member).unwrap();
                graph.extend([namespace, member]);
            }
            graph.push(association.clone());
            let before = serde_json::to_value(&graph).unwrap();
            let name = control["default_supertype"].as_str().unwrap();
            assert_eq!(definition_association_default_name(&graph, &association).unwrap(), name);
            let GeneratedLinkTarget::Local(id) = standard_default_binding(&graph, name).unwrap() else { panic!("unbound library") };
            let DefinitionGeneralTypes::Ready(ids) = definition_general_type_inputs(&graph, &association).unwrap() else { panic!("deferred association") };
            assert_eq!(ids, vec![id.clone()]);
            assert_eq!(serde_json::to_value(&graph).unwrap(), before);
            let target = graph.iter_mut().find(|e| e.id == id).unwrap(); target.properties.insert("declared_name".into(), json!("unavailable"));
            assert!(definition_general_type_inputs(&graph, &association).is_err());
        }
    }

