    #[test]
    fn definition_class_end_generalizations_match_pilot_source_queries() {
        let artifact: Value = serde_json::from_str(include_str!("../../../../resources/metamodels/sysml-2.0-pilot-2026-08/feature-defaults.extract.json")).unwrap();
        let controls = artifact["end_general_controls"].as_array().unwrap();
        assert_eq!(controls.len(), 2);
        let connectors = artifact["connector_participant_controls"].as_array().unwrap();
        assert_eq!(connectors.len(), 5);
        let associations = artifact["association_source_controls"].as_array().unwrap();
        let bindings=artifact["binding_connector_controls"].as_array().unwrap();assert_eq!(bindings.len(),4);
        for control in controls.iter().chain(connectors).chain(associations).chain(bindings) {
            let doc = crate::definition_document::parse_and_link(control["source"].as_str().unwrap(), crate::SourceLanguage::Kerml).unwrap();
            let before = serde_json::to_value(&doc).unwrap();
            for query in control["general_queries"].as_array().unwrap() {
                let feature = doc.elements.iter().find(|e| e.properties.get("declared_name") == Some(&query["feature"])).unwrap();
                let DefinitionGeneralTypes::Ready(ids) = definition_general_type_inputs(&doc.elements, feature).unwrap() else { panic!("deferred end controls") };
                let names = ids.iter().map(|id| doc.elements.iter().find(|e| &e.id == id).unwrap().properties["declared_name"].clone()).collect::<Vec<_>>();
                assert_eq!(json!(names), query["generals"]);
                for id in ids {
                    assert!(crate::definition_document::specializes(&doc, &feature.id, &id).unwrap());
                }
            }
            assert_eq!(serde_json::to_value(&doc).unwrap(), before);
            assert!(doc.elements.iter().all(|e| e.properties.get("is_implied_included") != Some(&json!(true))));
        }
    }

    #[test]
    fn definition_feature_defaults_match_resolved_pilot_controls() {
        let artifact: Value = serde_json::from_str(include_str!("../../../../resources/metamodels/sysml-2.0-pilot-2026-08/feature-defaults.extract.json")).unwrap();
        let controls = artifact["controls"].as_array().unwrap();
        assert_eq!(controls.len(), 384);
        let source = "standard library package Base { feature things; feature dataValues; } standard library package Objects { feature objects; struct Object { feature subobjects; } } standard library package Occurrences { feature occurrences; class Occurrence { feature portions; feature suboccurrences; } }";
        let library = crate::definition_document::parse_and_link(&source, crate::SourceLanguage::Kerml).unwrap();
        for control in controls {
            let mut graph = library.elements.clone();
            let mut connector = fresh_definition_element("connector".into(), "Feature").unwrap();
            let mut expected = Vec::new();
            connector.properties.insert("is_composite".into(), control["composite"].clone());
            connector.properties.insert("is_portion".into(), control["portion"].clone());
            for (bit, typing) in ["Class", "Structure", "DataType"].iter().enumerate() {
                if control["typing_mask"].as_u64().unwrap() & (1 << bit) == 0 { continue; }
                let id = format!("classifier{bit}");
                let classifier = fresh_definition_element(id.clone(), typing).unwrap();
                let mut relation = fresh_definition_element(format!("typing{bit}"), "FeatureTyping").unwrap();
                relation.properties.insert("typed_feature".into(), json!("connector"));
                relation.properties.insert("type".into(), json!(id));
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, &mut connector, &mut relation).unwrap();
                graph.extend([classifier, relation]); expected.push(id);
            }
            let owner_kind = control["owner"].as_str().unwrap();
            if owner_kind != "detached" {
                let mut owner = fresh_definition_element("context".into(), owner_kind).unwrap();
                for (bit, typing) in ["Class", "Structure", "DataType"].iter().enumerate() {
                    if control["owner_typing_mask"].as_u64().unwrap() & (1 << bit) == 0 { continue; }
                    let id = format!("owner-classifier{bit}");
                    let classifier = fresh_definition_element(id.clone(), typing).unwrap();
                    let mut relation = fresh_definition_element(format!("owner-typing{bit}"), "FeatureTyping").unwrap();
                    relation.properties.insert("typed_feature".into(), json!("context"));
                    relation.properties.insert("type".into(), json!(id));
                    ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, &mut owner, &mut relation).unwrap();
                    graph.extend([classifier, relation]);
                }
                let mut member = fresh_definition_element("context-member".into(), "FeatureMembership").unwrap();
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS, &mut member, &mut connector).unwrap();
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, &mut owner, &mut member).unwrap();
                graph.extend([owner, member]);
            }
            graph.push(connector.clone());
            let before = serde_json::to_value(&graph).unwrap();
            let name = control["default_supertype"].as_str().unwrap();
            assert_eq!(definition_feature_default_name(&graph, &connector).unwrap(), name, "{control}");
            let GeneratedLinkTarget::Local(default_id) = standard_default_binding(&graph, name).unwrap() else { panic!("unresolved fixture library") };
            expected.push(default_id);
            let DefinitionGeneralTypes::Ready(actual) = definition_general_type_inputs(&graph, &connector).unwrap() else { panic!("deferred fixture inputs") };
            assert_eq!(actual, expected, "{control}");
            assert_eq!(serde_json::to_value(&graph).unwrap(), before);
            let mut excluded = connector.clone(); excluded.properties.insert("direction".into(), json!("in"));
            assert!(definition_feature_default_name(&graph, &excluded).unwrap_err().message.contains("non-end"));
        }
    }

    #[test]
    fn definition_reference_transition_defaults_types_and_persistence_match_pilot() {
        let artifact:Value=serde_json::from_str(include_str!("../../../../../../docs/conformance/2026-08-support/reference-lifecycle-pilot-controls.json")).unwrap();
        let controls=artifact["controls"].as_array().unwrap();assert_eq!(controls.len(),256);
        let library=crate::definition_document::parse_and_link(controls[0]["source"].as_str().unwrap(),crate::SourceLanguage::Kerml).unwrap();
        for case in controls {
            assert_eq!(case["source"],controls[0]["source"]);
            let mut document=library.clone();
            let named=|name:&str| document.elements.iter().find(|e|e.properties.get("declared_name")==Some(&json!(name))).unwrap().id.clone();
            let package=named("P");let role=named("transitionLink");
            let own_types=(0..3).map(|bit|named(&format!("own{bit}"))).collect::<Vec<_>>();let role_types=(0..3).map(|bit|named(&format!("role{bit}"))).collect::<Vec<_>>();
            let mut transition=fresh_definition_element("transition".into(),"TransitionUsage").unwrap();
            let mut candidate=fresh_definition_element("candidate".into(),"ReferenceUsage").unwrap();
            let mut transition_member=fresh_definition_element("transition.member".into(),"OwningMembership").unwrap();
            ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS,&mut transition_member,&mut transition).unwrap();
            let parent=document.elements.iter_mut().find(|e|e.id==package).unwrap();ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,parent,&mut transition_member).unwrap();document.elements.push(transition_member);
            if case["preceding_parameter"]==true {
                let mut previous=fresh_definition_element("previous".into(),"ReferenceUsage").unwrap();let mut membership=fresh_definition_element("previous.member".into(),"ParameterMembership").unwrap();
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS,&mut membership,&mut previous).unwrap();ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,&mut transition,&mut membership).unwrap();document.elements.extend([previous,membership]);
            }
            let mut membership=fresh_definition_element("candidate.member".into(),"FeatureMembership").unwrap();
            ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS,&mut membership,&mut candidate).unwrap();ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,&mut transition,&mut membership).unwrap();document.elements.extend([transition,membership,candidate]);
            for (owner,mask,types) in [("candidate".to_owned(),case["owned_mask"].as_u64().unwrap(),own_types), (role.clone(),case["role_mask"].as_u64().unwrap(),role_types)] {
                for (bit,target) in types.iter().enumerate() {
                    if mask & (1<<bit)==0 {continue;}
                    let mut typing=fresh_definition_element(format!("{owner}.typing{bit}"),"FeatureTyping").unwrap();typing.properties.insert("typed_feature".into(),json!(owner));typing.properties.insert("type".into(),json!(target));
                    let feature=document.elements.iter_mut().find(|e|e.id==owner).unwrap();ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,feature,&mut typing).unwrap();document.elements.push(typing);
                }
            }
            if case["explicit_role"]==true {
                let mut relation=fresh_definition_element("explicit".into(),"Redefinition").unwrap();relation.properties.insert("redefining_feature".into(),json!("candidate"));relation.properties.insert("redefined_feature".into(),json!(role));
                let candidate=document.elements.iter_mut().find(|e|e.id=="candidate").unwrap();ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,candidate,&mut relation).unwrap();document.elements.push(relation);
            }
            let verify=|graph:&[KirElement]| {
                let candidate=graph.iter().find(|e|e.id=="candidate").unwrap();
                assert_eq!(definition_usage_default_name(graph,candidate).unwrap(),case["default_supertype"].as_str().unwrap(),"{case}");
                let names=|types:Vec<&KirElement>|json!(types.iter().map(|e|e.properties["declared_name"].as_str().unwrap()).collect::<Vec<_>>());
                assert_eq!(names(definition_feature_types(graph,candidate).unwrap()),case["types"],"{case}");
                assert_eq!(names(definition_reference_targets(graph,candidate,"definition").unwrap()),case["definitions"],"{case}");
                assert!(!scope_boolean(candidate,"is_implied_included").unwrap());
            };
            verify(&document.elements);
            if case==&controls[0] {
                for boundary in ["end","composite","portion","direction","payload","missing_role"] {
                    let mut rejected=document.clone();
                    let candidate=rejected.elements.iter_mut().find(|e|e.id=="candidate").unwrap();
                    match boundary {
                        "end"=>{candidate.properties.insert("is_end".into(),json!(true));},
                        "composite"=>{candidate.properties.insert("is_composite".into(),json!(true));},
                        "portion"=>{candidate.properties.insert("is_portion".into(),json!(true));},
                        "direction"=>{candidate.properties.insert("direction".into(),json!("in"));},
                        "payload"=>{rejected.elements.iter_mut().find(|e|e.id=="candidate.member").unwrap().kind="SysML::ParameterMembership".into();},
                        _=>{rejected.elements.iter_mut().find(|e|e.id==role).unwrap().properties.insert("declared_name".into(),json!("missingRole"));}
                    }
                    let before=serde_json::to_value(&rejected).unwrap();assert!(crate::definition_document::materialize_feature_defaults(&mut rejected,&[("candidate","rejected")]).is_err(),"{boundary}");assert_eq!(serde_json::to_value(rejected).unwrap(),before,"{boundary}");
                }
            }
            crate::definition_document::materialize_feature_defaults(&mut document,&[("candidate","reference.defaults")]).unwrap();
            verify(&document.elements);
            let exported=crate::abstract_syntax_json::export_sysml_abstract_syntax_value(&document,Default::default()).unwrap();assert!(!exported.has_errors());
            let imported=crate::abstract_syntax_json::import_sysml_abstract_syntax_value(exported.value,Default::default()).unwrap();assert!(!imported.has_errors());
            let mut restored=imported.document;restored.elements.reverse();verify(&restored.elements);
            let before=serde_json::to_value(&restored).unwrap();assert_eq!(crate::definition_document::materialize_feature_defaults(&mut restored,&[("candidate","replay")]).unwrap(),0);assert_eq!(serde_json::to_value(restored).unwrap(),before);
        }
    }

    #[test]
    fn definition_inherited_feature_types_match_resolved_pilot_controls() {
        let artifact:Value=serde_json::from_str(include_str!("../../../../resources/metamodels/sysml-2.0-pilot-2026-08/feature-defaults.extract.json")).unwrap();
        let controls=artifact["inherited_typing_controls"].as_array().unwrap();assert_eq!(controls.len(),576);
        for case in controls {
            let mut graph=Vec::new();
            // These factory controls supply completed inputs, exactly as Pilot;
            // they do not qualify construction or the complete fresh lifecycle.
            for id in ["candidate","leaf","left","right"] {
                let kind=if id=="candidate" {case["kind"].as_str().unwrap()} else {"Feature"};
                let mut feature=fresh_definition_element(id.into(),kind).unwrap();feature.properties.insert("is_implied_included".into(),json!(true));graph.push(feature);
            }
            for (i,edge) in case["edges"].as_array().unwrap().iter().enumerate() {
                let mut relation=fresh_definition_element(format!("edge{i}"),case["relationship"].as_str().unwrap()).unwrap();
                for (field,target) in [("specific",&edge[0]),("general",&edge[1])] {
                    let contract=ecore_model::redefined_feature(&relation.kind,field).unwrap();
                    if !contract.derived {relation.properties.insert(contract.field.into(),target.clone());}
                }
                let owner=graph.iter_mut().find(|e|e.id==edge[0].as_str().unwrap()).unwrap();
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,owner,&mut relation).unwrap();graph.push(relation);
            }
            for (bit,kind) in ["Class","Structure","DataType","Type"].iter().enumerate() {
                if case["typing_mask"].as_u64().unwrap() & (1<<bit)==0 {continue;}
                let mut classifier=fresh_definition_element(format!("type{bit}"),kind).unwrap();classifier.properties.insert("is_implied_included".into(),json!(true));
                let mut typing=fresh_definition_element(format!("typing{bit}"),"FeatureTyping").unwrap();typing.properties.insert("typed_feature".into(),json!("leaf"));typing.properties.insert("type".into(),json!(classifier.id));
                let leaf=graph.iter_mut().find(|e|e.id=="leaf").unwrap();ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,leaf,&mut typing).unwrap();graph.extend([classifier,typing]);
            }
            let before=serde_json::to_value(&graph).unwrap();
            for _ in 0..2 {
                let candidate=graph.iter().find(|e|e.id=="candidate").unwrap();
                let types=definition_feature_types(&graph,candidate).unwrap().iter().map(|e|e.id.clone()).collect::<Vec<_>>();assert_eq!(json!(types),case["types"],"{case}");
                assert_eq!(json!(definition_reference_targets(&graph,candidate,"type").unwrap().iter().map(|e|e.id.clone()).collect::<Vec<_>>()),case["projected_types"],"imported setting delegate {case}");
                graph=serde_json::from_value(serde_json::to_value(&graph).unwrap()).unwrap();graph.reverse();
            }
            assert_eq!(serde_json::to_value(graph).unwrap(),before);
        }
    }

    #[test]
    fn definition_usage_defaults_match_resolved_pilot_controls() {
        let artifact: Value = serde_json::from_str(include_str!("../../../../resources/metamodels/sysml-2.0-pilot-2026-08/feature-defaults.extract.json")).unwrap();
        let controls = artifact["usage_controls"].as_array().unwrap();
        assert_eq!(controls.len(), 192);
        let source = "standard library package Base { classifier Anything; datatype DataValue; feature things; feature dataValues; } standard library package Objects { struct Object; feature objects; } standard library package Occurrences { class Occurrence; feature occurrences; } standard library package Links { feature selfLinks; }";
        let library = crate::definition_document::parse_and_link(source, crate::SourceLanguage::Kerml).unwrap();
        for control in controls {
            let mut graph = library.elements.clone();
            let mut feature = fresh_definition_element("usage".into(), control["kind"].as_str().unwrap()).unwrap();
            feature.properties.insert("is_composite".into(), control["composite"].clone());
            feature.properties.insert("is_portion".into(), control["portion"].clone());
            let mut expected = Vec::new();
            for (bit, kind) in ["Class", "Structure", "DataType"].iter().enumerate() {
                if control["typing_mask"].as_u64().unwrap() & (1 << bit) == 0 { continue; }
                let classifier = fresh_definition_element(format!("type{bit}"), kind).unwrap();
                let mut typing = fresh_definition_element(format!("typing{bit}"), "FeatureTyping").unwrap();
                typing.properties.insert("typed_feature".into(), json!(feature.id));
                typing.properties.insert("type".into(), json!(classifier.id));
                expected.push(classifier.id.clone());
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, &mut feature, &mut typing).unwrap();
                graph.extend([classifier, typing]);
            }
            if control["package_owned"] == true {
                let mut namespace = fresh_definition_element("context".into(), "Package").unwrap();
                let mut member = fresh_definition_element("member".into(), "OwningMembership").unwrap();
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS, &mut member, &mut feature).unwrap();
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, &mut namespace, &mut member).unwrap();
                graph.extend([namespace, member]);
            }
            graph.push(feature.clone());
            let before = serde_json::to_value(&graph).unwrap();
            let name = control["default_supertype"].as_str().unwrap();
            let mask = control["typing_mask"].as_u64().unwrap();
            assert_eq!(feature_defaults_generated::usage_default_name(control["kind"].as_str().unwrap(), mask & 2 != 0, mask & 3 != 0, mask & 4 != 0), Some(name));
            if control["kind"] == "BindingConnectorAsUsage" && mask != 0 {
                assert!(definition_usage_default_name(&graph, &feature).unwrap_err().message.contains("normative selfLinks"));
                assert!(definition_general_type_inputs(&graph, &feature).is_err());
                assert_eq!(serde_json::to_value(&graph).unwrap(), before);
                continue;
            }
            assert_eq!(definition_usage_default_name(&graph, &feature).unwrap(), name);
            let GeneratedLinkTarget::Local(id) = standard_default_binding(&graph, name).unwrap() else { panic!("missing fixture default") };
            expected.push(id);
            let DefinitionGeneralTypes::Ready(actual) = definition_general_type_inputs(&graph, &feature).unwrap() else { panic!("deferred inputs") };
            assert_eq!(actual, expected, "{control}");
            if control["kind"] == "ReferenceUsage" {
                let mut persisted: Vec<KirElement> = serde_json::from_value(serde_json::to_value(&graph).unwrap()).unwrap();
                persisted.reverse();
                let target = persisted.iter().find(|e| e.id == feature.id).unwrap();
                assert_eq!(definition_usage_default_name(&persisted, target).unwrap(), name);
                let DefinitionGeneralTypes::Ready(replayed) = definition_general_type_inputs(&persisted, target).unwrap() else { panic!("persisted inputs deferred") };
                assert_eq!(replayed, expected);
                assert_eq!(definition_feature_types(&graph,&feature).unwrap().iter().map(|e|e.id.clone()).collect::<Vec<_>>(),expected[..expected.len()-1]);
                if control["package_owned"] == true {
                    let mut physical=graph.clone();
                    assert_eq!(definition_materialize_feature_defaults(&mut physical,&[(&feature.id,"reference.default")]).unwrap(),1);
                    let document=crate::KirDocument {metadata:std::collections::BTreeMap::new(),elements:physical};
                    let exported=crate::abstract_syntax_json::export_sysml_abstract_syntax_value(&document,Default::default()).unwrap();assert!(!exported.has_errors());
                    let imported=crate::abstract_syntax_json::import_sysml_abstract_syntax_value(exported.value,Default::default()).unwrap();assert!(!imported.has_errors());
                    let mut restored=imported.document.elements;restored.reverse();
                    let before=serde_json::to_value(&restored).unwrap();
                    assert_eq!(definition_materialize_feature_defaults(&mut restored,&[(&feature.id,"reference.replay")]).unwrap(),0);
                    assert_eq!(serde_json::to_value(&restored).unwrap(),before);
                    let restored_owner=restored.iter().find(|e|e.id==feature.id).unwrap();
                    assert!(!scope_boolean(restored_owner,"is_implied_included").unwrap());
                    let DefinitionGeneralTypes::Ready(replayed)=definition_general_type_inputs(&restored,restored_owner).unwrap() else {panic!("physical inputs deferred")};assert_eq!(replayed,expected);
                    for owner_kind in ["TransitionUsage", "SuccessionAsUsage"] {
                        let mut specialized = graph.clone();
                        specialized.iter_mut().find(|e| e.id == "context").unwrap().kind = format!("SysML::{owner_kind}");
                        specialized.iter_mut().find(|e| e.id == "member").unwrap().kind = if owner_kind=="TransitionUsage" {"SysML::ParameterMembership"} else {"SysML::FeatureMembership"}.into();
                        let target = specialized.iter().find(|e| e.id == feature.id).unwrap();
                        assert!(definition_usage_default_name(&specialized, target).unwrap_err().message.contains("positional contexts"));
                    }
                }
            }
            assert!(definition_no_additional_members(&feature).unwrap());
            assert_eq!(serde_json::to_value(&graph).unwrap(), before);
            assert!(graph.iter().all(|e| e.properties.get("is_implied_included") != Some(&json!(true))));
            let mut end = feature.clone(); end.properties.insert("is_end".into(), json!(true));
            assert!(!definition_no_additional_members(&end).unwrap());
            assert!(definition_usage_default_name(&graph, &end).is_err());
            if control["package_owned"] == true {
                let mut variant = graph.clone();
                variant.iter_mut().find(|e| e.id == "member").unwrap().kind = "SysML::VariantMembership".into();
                assert!(definition_usage_default_name(&variant, &feature).is_err());
            }
            for kind in ["FeatureValue", "CrossSubsetting", "Conjugation"] {
                let mut rejected = graph.clone();
                let mut target = feature.clone();
                let mut relationship = fresh_definition_element("unassessed".into(), kind).unwrap();
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, &mut target, &mut relationship).unwrap();
                *rejected.iter_mut().find(|e| e.id == target.id).unwrap() = target.clone(); rejected.push(relationship);
                assert!(definition_usage_default_name(&rejected, &target).is_err(), "{kind}");
            }
        }
    }

    #[test]
    fn definition_connector_defaults_match_resolved_pilot_controls() {
        let artifact: Value = serde_json::from_str(include_str!("../../../../resources/metamodels/sysml-2.0-pilot-2026-08/connector-defaults.extract.json")).unwrap();
        for record in [&artifact,&artifact["binding_connector"]] {
        let kind=record["binding"].as_str().unwrap();
        let controls = record["controls"].as_array().unwrap();
        assert_eq!(controls.len(), 36);
        let mut packages: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();
        for name in record["defaults"].as_object().unwrap().values() {
            let (package, member) = name.as_str().unwrap().split_once("::").unwrap();
            assert!(!member.contains("::"));
            packages.entry(package.into()).or_default().insert(member.into());
        }
        let source = packages.iter().map(|(package, members)| format!("standard library package {package} {{ {} }}", members.iter().map(|name| format!("feature {name};")).collect::<Vec<_>>().join(" "))).collect::<Vec<_>>().join(" ");
        let library = crate::definition_document::parse_and_link(&source, crate::SourceLanguage::Kerml).unwrap();
        for control in controls {
            let mut graph = library.elements.clone();
            let mut connector = fresh_definition_element("connector".into(), kind).unwrap();
            let mut expected = Vec::new();
            let typing = control["typing"].as_str().unwrap();
            if typing != "none" {
                let classifier = fresh_definition_element("classifier".into(), typing).unwrap();
                let mut relation = fresh_definition_element("typing".into(), "FeatureTyping").unwrap();
                relation.properties.insert("typed_feature".into(), json!("connector"));
                relation.properties.insert("type".into(), json!("classifier"));
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, &mut connector, &mut relation).unwrap();
                graph.extend([classifier, relation]); expected.push("classifier".to_owned());
            }
            for i in 0..control["owned_ends"].as_u64().unwrap() {
                let mut end = fresh_definition_element(format!("end{i}"), "Feature").unwrap();
                end.properties.insert("is_end".into(), json!(true));
                let mut member = fresh_definition_element(format!("member{i}"), "EndFeatureMembership").unwrap();
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS, &mut member, &mut end).unwrap();
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, &mut connector, &mut member).unwrap();
                graph.extend([end, member]);
            }
            let owner_kind = control["owner"].as_str().unwrap();
            if owner_kind != "detached" {
                let mut owner = fresh_definition_element("context".into(), owner_kind).unwrap();
                let mut member = fresh_definition_element("context-member".into(), "FeatureMembership").unwrap();
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS, &mut member, &mut connector).unwrap();
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, &mut owner, &mut member).unwrap();
                graph.extend([owner, member]);
            }
            graph.push(connector.clone());
            let before = serde_json::to_value(&graph).unwrap();
            if kind=="BindingConnector" && control["owned_ends"]!=2 {
                assert!(definition_connector_default_name(&graph,&connector).unwrap_err().message.contains("two owned ends"));
                continue;
            }
            let name = control["default_supertype"].as_str().unwrap();
            assert_eq!(definition_connector_default_name(&graph, &connector).unwrap(), name, "{control}");
            let GeneratedLinkTarget::Local(default_id) = standard_default_binding(&graph, name).unwrap() else { panic!("unresolved fixture library") };
            expected.push(default_id);
            let DefinitionGeneralTypes::Ready(actual) = definition_general_type_inputs(&graph, &connector).unwrap() else { panic!("deferred fixture inputs") };
            assert_eq!(actual, expected, "{control}");
            assert_eq!(serde_json::to_value(&graph).unwrap(), before);
            let mut excluded = connector.clone(); excluded.properties.insert("is_end".into(), json!(true));
            assert!(definition_connector_default_name(&graph, &excluded).unwrap_err().message.contains("non-end"));
        }
        }
    }

    #[test]
    fn definition_connector_default_provider_reaches_source_and_preserves_guards() {
        let library = "standard library package Occurrences { class Occurrence; } standard library package Links { feature links; feature binaryLinks; } standard library package Objects { struct Object; feature linkObjects; feature binaryLinkObjects; } ";
        for (structure, ends, default) in [(false, 0, "links"), (false, 2, "binaryLinks"), (true, 1, "linkObjects"), (true, 2, "binaryLinkObjects")] {
            let classifier = if structure { "struct" } else { "class" };
            let body = (0..ends).map(|i| format!("end feature e{i};")).collect::<Vec<_>>().join(" ");
            let source = format!("{library} package P {{ {classifier} T; connector x : T {{ {body} }} }}");
            let doc = crate::definition_document::parse_and_link(&source, crate::SourceLanguage::Kerml).unwrap();
            let connector = doc.elements.iter().find(|e| e.properties.get("declared_name") == Some(&json!("x"))).unwrap();
            let target = doc.elements.iter().find(|e| e.properties.get("declared_name") == Some(&json!(default))).unwrap();
            let before = serde_json::to_value(&doc).unwrap();
            assert!(crate::definition_document::specializes(&doc, &connector.id, &target.id).unwrap());
            assert_eq!(serde_json::to_value(&doc).unwrap(), before);
            assert!(doc.elements.iter().all(|e| e.properties.get("is_implied_included") != Some(&json!(true))));
            for field in ["is_end", "direction"] {
                let mut excluded = connector.clone();
                excluded.properties.insert(field.into(), if field == "direction" { json!("in") } else { json!(true) });
                assert!(definition_connector_default_name(&doc.elements, &excluded).is_err());
            }
            for kind in ["FeatureValue", "Conjugation", "CrossSubsetting"] {
                let mut graph = doc.elements.clone();
                let mut excluded = connector.clone();
                let mut relationship = fresh_definition_element("excluded".into(), kind).unwrap();
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, &mut excluded, &mut relationship).unwrap();
                *graph.iter_mut().find(|e| e.id == excluded.id).unwrap() = excluded.clone();
                graph.push(relationship);
                assert!(definition_connector_default_name(&graph, &excluded).is_err(), "{kind}");
            }
            let mut metadata_graph = doc.elements.clone();
            metadata_graph.push(fresh_definition_element("metadata".into(), "MetadataFeature").unwrap());
            assert!(definition_connector_default_name(&metadata_graph, connector).is_ok());
            metadata_test_annotate(&mut metadata_graph,&connector.id,&connector.id,"applied","MetadataFeature");
            let annotated=metadata_graph.iter().find(|e|e.id==connector.id).unwrap();
            assert!(definition_connector_default_name(&metadata_graph,annotated).unwrap_err().message.contains("base-type evaluation remains unsupported"));
            let missing = doc.elements.iter().filter(|e| e.id != target.id).cloned().collect::<Vec<_>>();
            assert!(definition_general_type_inputs(&missing, connector).is_err());
        }
    }

    #[test]
    fn definition_indexed_scalar_references_preserve_contracts_and_prerequisites() {
        let mut owner = fresh_definition_element("receiver".into(), "Feature").unwrap();
        let mut relation = fresh_definition_element("relation".into(), "Redefinition").unwrap();
        relation.properties.insert("redefining_feature".into(), json!("receiver"));
        relation.properties.insert("redefined_feature".into(), json!("target"));
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, &mut owner, &mut relation).unwrap();
        let baseline = vec![owner, relation, fresh_definition_element("target".into(), "Feature").unwrap(), fresh_definition_element("wrong".into(), "Namespace").unwrap()];
        let snapshot = |result: Result<&KirElement, QueryFailure>| match result {
            Ok(target) => json!({"target": target.id, "kind": target.kind}),
            Err(failure) => json!({"failure": format!("{failure:?}")}),
        };
        for case in 0..9 {
            let mut graph = baseline.clone();
            match case {
                0 => {graph[1].properties.remove("redefined_feature");},
                1 => {graph[1].properties.insert("redefined_feature".into(), Value::Null);},
                2 => {graph[1].properties.insert("redefined_feature".into(), json!(42));},
                3 => {graph[1].properties.insert("redefined_feature".into(), json!("absent"));},
                4 => {graph[1].properties.insert("redefined_feature".into(), json!("wrong"));},
                6 => {let mut duplicate = graph[2].clone(); duplicate.kind = "SysML::Namespace".into(); graph.push(duplicate);},
                7 => {graph[1].kind = "UnregisteredRelation".into();},
                8 => {graph[0].properties.insert("owned_relationship".into(), json!([]));},
                _ => {},
            }
            graph.extend((0..128).map(|i| fresh_definition_element(format!("padding{i}"), "Element").unwrap()));
            for reversed in [false, true] {
                if reversed {graph = serde_json::from_value(serde_json::to_value(&graph).unwrap()).unwrap(); graph.reverse();}
                let index = graph.iter().map(|e| (e.id.as_str(), e)).collect();
                let query = DefinitionNameQuery::new(&graph, &index);
                let relation = graph.iter().find(|e| e.id == "relation").unwrap();
                let before = serde_json::to_value(&graph).unwrap();
                for field in ["redefined_feature", "general", "specific", "owning_type", "owning_feature", "owned_related_element", "unknown_field"] {
                    for _ in 0..2 {
                        assert_eq!(snapshot(query_reference_in_view(&query, relation, field)), snapshot(query_reference(&graph, relation, field)), "case {case}, reversed {reversed}, field {field}");
                    }
                }
                assert!(query.names.borrow().is_empty());
                assert!(query.redefinition_closures.borrow().is_empty());
                assert_eq!(serde_json::to_value(&graph).unwrap(), before);
            }
        }
    }

    #[test]
    fn definition_specialization_owner_delegates_follow_canonical_containment() {
        for (kind, field, accepts_type) in [
            ("Specialization", "owning_type", true),
            ("Subsetting", "owning_feature", false),
            ("FeatureTyping", "owning_feature", false),
            ("ReferenceSubsetting", "referencing_feature", false),
        ] {
            let detached = fresh_definition_element("relation".into(), kind).unwrap();
            assert!(definition_reference_targets(&[detached.clone()], &detached, field).unwrap().is_empty());
            for parent_kind in ["Feature", "Class", "Package"] {
                let mut parent = fresh_definition_element("parent".into(), parent_kind).unwrap();
                let mut relation = detached.clone();
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, &mut parent, &mut relation).unwrap();
                let graph = vec![parent, relation.clone()];
                let before = serde_json::to_value(&graph).unwrap();
                let targets = definition_reference_targets(&graph, &relation, field).unwrap();
                let expected = parent_kind == "Feature" || (accepts_type && parent_kind == "Class");
                assert_eq!(targets.len(), usize::from(expected), "{kind}/{parent_kind}");
                if expected { assert_eq!(targets[0].id, "parent"); }
                assert_eq!(serde_json::to_value(&graph).unwrap(), before);
                let mut broken = graph.clone();
                broken[0].properties.insert("owned_relationship".into(), json!([]));
                assert!(definition_reference_targets(&broken, &relation, field).is_err());
            }
        }
    }

    #[test]
    fn definition_feature_redefinitions_match_independent_pilot_contexts() {
        use crate::abstract_syntax_json::{export_sysml_abstract_syntax_value, import_sysml_abstract_syntax_value};
        // Exercise the same definition-backed constructor used by candidate
        // semantic producers, rather than property-minimal test objects.
        let element = |id: &str, kind: &str| fresh_definition_element(id.into(), kind).unwrap();
        let artifact: Value = serde_json::from_str(include_str!("../../../../resources/metamodels/sysml-2.0-pilot-2026-08/feature-redefinitions.extract.json")).unwrap();
        assert_eq!(artifact["bindings"].as_array().unwrap().len(), 79);
        assert_eq!(artifact["controls"].as_array().unwrap().len(), 180);
        // A fixed matrix is the obligation denominator: duplicate observations
        // cannot hide an omitted concrete binding or required context.
        let admitted_kinds = artifact["bindings"].as_array().unwrap().iter().filter(|row|
            feature_redefinitions_generated::relevant(row["kind"].as_str().unwrap(), false, false, false, false).is_some())
            .map(|row| row["kind"].as_str().unwrap()).collect::<BTreeSet<_>>();
        let expected = admitted_kinds.iter().flat_map(|kind|
            ["detached", "Package", "Class"].into_iter().flat_map(move |owner|
                [0_u64, 2].into_iter().map(move |explicit| ((*kind).to_owned(), owner.to_owned(), explicit))))
            .collect::<BTreeSet<_>>();
        let observed = artifact["controls"].as_array().unwrap().iter().map(|case|
            (case["kind"].as_str().unwrap().to_owned(), case["owner_kind"].as_str().unwrap().to_owned(), case["explicit"].as_u64().unwrap()))
            .collect::<BTreeSet<_>>();
        assert_eq!(observed, expected);
        assert_eq!(observed.len(), 180);
        for case in artifact["controls"].as_array().unwrap() {
            let mut feature = element("feature", case["kind"].as_str().unwrap());
            feature.properties.insert("owned_relationship".into(), json!([]));
            let mut graph = Vec::new();
            for i in 0..case["explicit"].as_u64().unwrap() {
                let mut general = element(&format!("general{i}"), "Feature");
                general.properties.insert("declared_name".into(), json!(format!("General{i}")));
                let mut relation = element(&format!("redefinition{i}"), "Redefinition");
                relation.properties.insert("redefining_feature".into(), json!("feature"));
                relation.properties.insert("redefined_feature".into(), json!(general.id));
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, &mut feature, &mut relation).unwrap();
                graph.extend([relation, general]);
            }
            let owner_kind = case["owner_kind"].as_str().unwrap();
            if owner_kind != "detached" {
                let mut owner = element("owner", owner_kind);
                let mut member = element("membership", "FeatureMembership");
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS, &mut member, &mut feature).unwrap();
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, &mut owner, &mut member).unwrap();
                graph.extend([owner, member]);
            }
            graph.push(feature.clone());
            let before = serde_json::to_value(&graph).unwrap();
            assert_eq!(json!(definition_redefined_features(&graph, &feature, false).unwrap().iter().map(|e| &e.id).collect::<Vec<_>>()), case["redefined_features"], "{case}");
            let names = generated_effective_names(&graph, &feature).unwrap();
            assert_eq!(json!(names[0]), case["effective_name"], "{case}");
            assert_eq!(json!(names[1]), case["effective_short_name"], "{case}");
            assert_eq!(serde_json::to_value(&graph).unwrap(), before);
            graph.reverse();
            assert_eq!(json!(definition_redefined_features(&graph, &feature, false).unwrap().iter().map(|e| &e.id).collect::<Vec<_>>()), case["redefined_features"]);
            let issues = ecore_model::validate_publication(&graph, ecore_model::ReferenceCompleteness::Closed);
            assert!(issues.is_empty(), "{case}: {:?}", issues.iter().map(|i| &i.message).collect::<Vec<_>>());
            let document = crate::KirDocument { metadata: BTreeMap::new(), elements: graph.clone() };
            let exported = export_sysml_abstract_syntax_value(&document, Default::default()).unwrap();
            assert!(!exported.has_errors(), "{case}: {:?}", exported.diagnostics);
            let imported = import_sysml_abstract_syntax_value(exported.value, Default::default()).unwrap();
            assert!(!imported.has_errors(), "{case}: {:?}", imported.diagnostics);
            assert!(imported.publication_diagnostics(true).is_empty(), "{case}");
            let restored = imported.persistable_document().unwrap();
            let restored_feature = restored.elements.iter().find(|e| e.id == feature.id).unwrap();
            assert_eq!(json!(definition_redefined_features(&restored.elements, restored_feature, false).unwrap().iter().map(|e| &e.id).collect::<Vec<_>>()), case["redefined_features"]);
            assert_eq!(generated_effective_names(&restored.elements, restored_feature).unwrap(), names);
            let mut incomplete = feature.clone(); incomplete.properties.remove("owned_relationship");
            assert!(definition_redefined_features(&graph, &incomplete, false).is_err());
            if owner_kind != "detached" {
                let mut broken = graph.clone();
                broken.iter_mut().find(|e| e.id == "membership").unwrap().properties.insert("owned_related_element".into(), json!([]));
                assert!(definition_redefined_features(&broken, &feature, false).is_err());
            }
        }
        let admitted = artifact["bindings"].as_array().unwrap().iter().filter(|row|
            feature_redefinitions_generated::relevant(row["kind"].as_str().unwrap(), false, false, false, false).is_some()).count();
        assert_eq!(admitted, 30);
    }

