    #[test]
    fn definition_expression_guard_classification_and_boundaries() {
        let artifact: Value = serde_json::from_str(include_str!("../../../../../../docs/conformance/2026-08-support/expression-redefinition-pilot-controls.json")).unwrap();
        let controls = artifact["guard_controls"].as_array().unwrap();
        assert_eq!(controls.len(), 60);
        let observed = controls.iter().map(|row| (row["kind"].as_str().unwrap(), row["membership_kind"].as_str().unwrap())).collect::<BTreeSet<_>>();
        let expected = artifact["bindings"].as_array().unwrap().iter().flat_map(|kind|
            ["trigger", "guard", "effect"].into_iter().map(move |value| (kind.as_str().unwrap(), value))).collect::<BTreeSet<_>>();
        assert_eq!(observed, expected);
        for row in controls {
            let mut feature = fresh_definition_element("feature".into(), row["kind"].as_str().unwrap()).unwrap();
            let mut membership = fresh_definition_element("membership".into(), "TransitionFeatureMembership").unwrap();
            membership.properties.insert("kind".into(), row["membership_kind"].clone());
            let mut owner = fresh_definition_element("owner".into(), "TransitionUsage").unwrap();
            ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS, &mut membership, &mut feature).unwrap();
            ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, &mut owner, &mut membership).unwrap();
            assert_eq!(definition_expression_transition_guard(Some(&membership)).unwrap(), row["transition_guard"].as_bool().unwrap());
            if row["transition_guard"] == json!(true) {
                let graph = vec![feature.clone(), membership.clone(), owner];
                let failure = format!("{:?}", definition_redefined_features(&graph, &feature, false).unwrap_err());
                assert!(failure.contains("transition-guard general-type/library semantics"), "{failure}");
            }
            membership.properties.insert("kind".into(), json!("unknown"));
            assert!(definition_expression_transition_guard(Some(&membership)).is_err());
            membership.properties.remove("kind");
            assert!(definition_expression_transition_guard(Some(&membership)).is_err());
        }
        assert!(!definition_expression_transition_guard(None).unwrap());
        let ordinary = fresh_definition_element("member".into(), "FeatureMembership").unwrap();
        assert!(!definition_expression_transition_guard(Some(&ordinary)).unwrap());
        assert!(!expression_redefinitions_generated::supports("AcceptActionUsage"));
        // Admitting ordinary expressions must not admit their overridden
        // general-type algorithms into positional end/parameter strategies.
        for kind in artifact["bindings"].as_array().unwrap() {
            assert!(!feature_redefinitions_generated::end_strategy_supported(kind.as_str().unwrap()));
            assert!(!feature_redefinitions_generated::parameter_strategy_supported(kind.as_str().unwrap()));
        }
    }

    fn end_control_graph(case: &Value) -> Vec<KirElement> {
        let mut graph = Vec::new();
        for row in case["types"].as_array().unwrap() {
            let mut owner = element(row["id"].as_str().unwrap(), row["kind"].as_str().unwrap_or("Class"));
            owner.properties.insert("owned_relationship".into(), json!([]));
            owner.properties.insert("is_implied_included".into(), json!(true));
            for (i, parent) in row["parents"].as_array().unwrap().iter().enumerate() {
                let kind = row.get("general_kinds").and_then(Value::as_array)
                    .and_then(|kinds| kinds.get(i)).and_then(Value::as_str).unwrap_or("Subclassification");
                let mut relation = element(&format!("{}.general{i}", owner.id), kind);
                let specific = ecore_model::redefined_feature(&relation.kind, "specific").unwrap().field;
                let general = ecore_model::redefined_feature(&relation.kind, "general").unwrap().field;
                relation.properties.insert(specific.into(), json!(owner.id));
                relation.properties.insert(general.into(), parent.clone());
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, &mut owner, &mut relation).unwrap();
                graph.push(relation);
            }
            graph.push(owner);
        }
        for row in case["features"].as_array().unwrap() {
            let mut feature = element(row["id"].as_str().unwrap(), row["kind"].as_str().unwrap());
            feature.properties.insert("owned_relationship".into(), json!([]));
            feature.properties.insert("is_end".into(), row["is_end"].clone());
            if let Some(direction) = row.get("direction") { feature.properties.insert("direction".into(), direction.clone()); }
            if let Some(name) = row["name"].as_str() {
                feature.properties.insert("declared_name".into(), json!(name));
                feature.properties.insert("declared_short_name".into(), json!(format!("short_{name}")));
            }
            let mut member = element(&format!("{}.membership", feature.id), if row["result"].as_bool().unwrap_or(false) { "ReturnParameterMembership" } else { "FeatureMembership" });
            member.properties.insert("visibility".into(), row["visibility"].clone());
            ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS, &mut member, &mut feature).unwrap();
            let owner = graph.iter_mut().find(|e| Some(e.id.as_str()) == row["owner"].as_str()).unwrap();
            ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, owner, &mut member).unwrap();
            graph.extend([member, feature]);
        }
        for row in case["features"].as_array().unwrap() {
            if let Some(chain) = row["chain"].as_array() {
                for (i, target) in chain.iter().enumerate() {
                    let mut relation = element(&format!("{}.chain{i}", row["id"].as_str().unwrap()), "FeatureChaining");
                    relation.properties.insert("chaining_feature".into(), target.clone());
                    let owner = graph.iter_mut().find(|e| Some(e.id.as_str()) == row["id"].as_str()).unwrap();
                    ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, owner, &mut relation).unwrap();
                    graph.push(relation);
                }
            }
        }
        for (i, row) in case["explicit"].as_array().unwrap().iter().enumerate() {
            let mut relation = element(&format!("explicit{i}"), "Redefinition");
            relation.properties.insert("redefining_feature".into(), row["specific"].clone());
            relation.properties.insert("redefined_feature".into(), row["general"].clone());
            let owner = graph.iter_mut().find(|e| Some(e.id.as_str()) == row["specific"].as_str()).unwrap();
            ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, owner, &mut relation).unwrap();
            graph.push(relation);
        }
        graph
    }

    #[test]
    fn definition_positional_ends_match_independent_pilot_models() {
        let artifact: Value = serde_json::from_str(include_str!("../../../../resources/metamodels/sysml-2.0-pilot-2026-08/feature-redefinitions.extract.json")).unwrap();
        let controls = artifact["end_controls"].as_array().unwrap();
        assert_eq!(controls.len(), 990);
        let usage: Value = serde_json::from_str(include_str!("../../../../resources/metamodels/sysml-2.0-pilot-2026-08/feature-defaults.extract.json")).unwrap();
        let references = usage["reference_end_controls"].as_array().unwrap();
        assert_eq!(references.len(), 33);
        for case in controls.iter().chain(references) {
            let mut graph = end_control_graph(case);
            let before = serde_json::to_value(&graph).unwrap();
            for reversed in [false, true] {
                if reversed { graph.reverse(); }
                let target = graph.iter().find(|e| Some(e.id.as_str()) == case["target"].as_str()).unwrap();
                let result = definition_redefined_features(&graph, target, false)
                    .unwrap_or_else(|err| panic!("{} {} {}: {err:?}",case["kind"],case["shape"],case["position"]));
                assert_eq!(json!(result.iter().map(|e| &e.id).collect::<Vec<_>>()), case["redefined_features"],
                    "{} {} {}",case["kind"],case["shape"],case["position"]);
                let names = generated_effective_names(&graph, target).unwrap();
                assert_eq!(json!(names[0]), case["effective_name"]);
                assert_eq!(json!(names[1]), case["effective_short_name"]);
                for (id, expected) in case["effective_ends"].as_object().unwrap() {
                    let owner = graph.iter().find(|e| &e.id == id).unwrap();
                    let actual = definition_reference_targets(&graph, owner, "end_feature").unwrap();
                    assert_eq!(json!(actual.iter().map(|e| &e.id).collect::<Vec<_>>()), *expected,
                        "end_feature: {} {} {} {id}",case["kind"],case["shape"],case["position"]);
                }
            }
            graph.reverse();
            assert_eq!(serde_json::to_value(&graph).unwrap(), before, "Query must not materialize flags or relationships");
        }
    }

    #[test]
    fn definition_accept_trigger_generalizations_match_pilot_lifecycle() {
        let data:Value=serde_json::from_str(include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/../../docs/conformance/2026-08-support/accept-trigger-pilot-controls.json"))).unwrap();
        let library=crate::definition_document::parse_and_link("standard library package Base { classifier Anything; feature things; } standard library package Actions { class TransitionAction { feature accepter; } }",crate::SourceLanguage::Kerml).unwrap();
        let mut library=library.elements;
        // Identical supplied completed dependency stage; actual libraries remain open.
        for e in &mut library {if metaclass_conforms(&e.kind,"Type") {e.properties.insert("is_implied_included".into(),json!(true));}}
        let accepter=library.iter().find(|e|e.properties.get("declared_name")==Some(&json!("accepter"))).unwrap().id.clone();
        assert_eq!(data["controls"].as_array().unwrap().len(),9);
        for case in data["controls"].as_array().unwrap() {
            let mut graph=library.clone();let mut owner=fresh_definition_element("owner".into(),"TransitionUsage").unwrap();owner.properties.insert("is_implied_included".into(),json!(true));graph.push(owner);
            cross_test_own(&mut graph,"owner","TransitionFeatureMembership",fresh_definition_element("target".into(),"AcceptActionUsage").unwrap());
            graph.iter_mut().find(|e|metaclass_conforms(&e.kind,"TransitionFeatureMembership")).unwrap().properties.insert("kind".into(),json!("trigger"));
            for (owner,count,kind,field,prefix) in [("owner",case["owner_generals"].as_u64().unwrap(),"Subsetting","subsetted_feature","owner.general"),("target",case["explicit"].as_u64().unwrap(),"Redefinition","redefined_feature","explicit")] {
                for i in 0..count {
                    let id=format!("{prefix}{i}");let mut general=fresh_definition_element(id.clone(),"Feature").unwrap();general.properties.insert("is_implied_included".into(),json!(true));graph.push(general);
                    let mut relation=fresh_definition_element(format!("{id}.relation"),kind).unwrap();relation.properties.insert(if kind=="Subsetting" {"subsetting_feature"}else{"redefining_feature"}.into(),json!(owner));relation.properties.insert(field.into(),json!(id));
                    ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,graph.iter_mut().find(|e|e.id==owner).unwrap(),&mut relation).unwrap();graph.push(relation);
                }
            }
            let restored:Vec<KirElement>=serde_json::from_str(&serde_json::to_string(&graph).unwrap()).unwrap();
            for mut model in [graph,restored] {
                model.reverse();let before=serde_json::to_value(&model).unwrap();let target=model.iter().find(|e|e.id=="target").unwrap();
                let expected=case["general_types"].as_array().unwrap().iter().map(|v|if v=="accepter" {accepter.clone()}else{v.as_str().unwrap().into()}).collect::<Vec<String>>();
                assert_eq!(definition_general_type_inputs_query(&model,target).unwrap(),expected,"{case}");
                assert_eq!(definition_general_type_inputs_query(&model,target).unwrap(),expected);
                assert!(!scope_boolean(target,"is_implied_included").unwrap());assert_eq!(before,serde_json::to_value(&model).unwrap());
            }
        }
    }

