    #[test]
    fn definition_specialization_compatibility_preserve_pending_ancestor_fields() {
        let mut owner=fresh_definition_element("owner".into(),"TransitionUsage").unwrap();owner.properties.insert("is_implied_included".into(),json!(true));let mut graph=vec![owner];
        cross_test_own(&mut graph,"owner","TransitionFeatureMembership",fresh_definition_element("target".into(),"AcceptActionUsage").unwrap());
        let member=graph.iter().find(|e|metaclass_conforms(&e.kind,"TransitionFeatureMembership")).unwrap().id.clone();graph.iter_mut().find(|e|e.id==member).unwrap().properties.insert("kind".into(),json!("trigger"));
        let mut relation=fresh_definition_element("pending.general".into(),"Subsetting").unwrap();relation.properties.insert("subsetting_feature".into(),json!("owner"));relation.properties.remove("subsetted_feature");
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,&mut graph[0],&mut relation).unwrap();graph.push(relation);
        let mut goal=fresh_definition_element("goal".into(),"Feature").unwrap();goal.properties.insert("is_implied_included".into(),json!(true));graph.push(goal);
        let persisted:Vec<KirElement>=serde_json::from_value(serde_json::to_value(&graph).unwrap()).unwrap();
        for mut model in [graph,persisted] {
            for reversed in [false,true] {
                if reversed {model.reverse();}
                let target=model.iter().find(|e|e.id=="target").unwrap();let goal=model.iter().find(|e|e.id=="goal").unwrap();let before=serde_json::to_value(&model).unwrap();
                for _ in 0..2 {
                    for result in [definition_specializes_depth_query(&model,target,goal,0),definition_is_compatible_query(&model,target,goal)] {
                        assert!(matches!(result,Err(QueryFailure::Required(Prerequisite::ReadField {owner_id,field})) if owner_id=="pending.general" && field=="subsetted_feature"));
                    }
                }
                assert_eq!(serde_json::to_value(&model).unwrap(),before);
            }
            // A fresh explicit positive proof must not reuse the earlier pending result.
            let mut explicit=fresh_definition_element("resolved.proof".into(),"Subsetting").unwrap();explicit.properties.insert("subsetting_feature".into(),json!("target"));explicit.properties.insert("subsetted_feature".into(),json!("goal"));
            ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,model.iter_mut().find(|e|e.id=="target").unwrap(),&mut explicit).unwrap();model.push(explicit);
            let target=model.iter().find(|e|e.id=="target").unwrap();let goal=model.iter().find(|e|e.id=="goal").unwrap();
            assert!(definition_specializes_depth_query(&model,target,goal,0).unwrap());assert!(definition_is_compatible_query(&model,target,goal).unwrap());
            assert!(!scope_boolean(target,"is_implied_included").unwrap());
        }
    }

