    #[test]
    fn definition_pending_typing_diagnostic_records_its_external_boundary() {
        let mut feature=fresh_definition_element("feature".into(),"Feature").unwrap();
        let mut typing=fresh_definition_element("typing".into(),"FeatureTyping").unwrap();
        typing.properties.insert("typed_feature".into(),json!("feature"));
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,&mut feature,&mut typing).unwrap();
        let graph=vec![feature,typing];let before=serde_json::to_value(&graph).unwrap();
        assert!(matches!(definition_feature_types_query(&graph,&graph[0]),Err(QueryFailure::Required(Prerequisite::ReadField{owner_id,field})) if owner_id=="typing" && field=="type"));
        let diagnostic=definition_feature_types(&graph,&graph[0]).unwrap_err();
        assert!(diagnostic.message.contains("[native boundary: definition_feature_types; caller "));
        assert_eq!(before,serde_json::to_value(&graph).unwrap());
        let rejected=error("malformed endpoint");let original=rejected.message.clone();
        assert_eq!(QueryFailure::Rejected(rejected).into_diagnostic_at("test boundary").message,original);
    }

