                ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS,&mut member,&mut target).unwrap();ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,&mut owner,&mut member).unwrap();graph.extend([owner,member,target]);
