    #[test]
    fn definition_general_type_view_reuses_successes_with_scope_exclusions() {
        let doc=crate::definition_document::parse_and_link("package P { classifier G; classifier C specializes G; }",crate::SourceLanguage::Kerml).unwrap();
        for reverse in [false,true] {
            let mut graph:Vec<KirElement>=serde_json::from_value(serde_json::to_value(&doc.elements).unwrap()).unwrap();
            // This control supplies completed explicit inputs; it does not
            // claim construction of the omitted standard-library defaults.
            graph.iter_mut().find(|e|e.properties.get("declared_name")==Some(&json!("C"))).unwrap().properties.insert("is_implied_included".into(),json!(true));
            if reverse {graph.reverse();}
            let before=serde_json::to_value(&graph).unwrap();
            let owner=graph.iter().find(|e|e.properties.get("declared_name")==Some(&json!("C"))).unwrap();
            let index=graph.iter().map(|e|(e.id.as_str(),e)).collect();
            let hits=std::cell::Cell::new(0);
            let observe=|event:DefinitionConstructionEvent<'_>|if event.phase==DefinitionConstructionPhase::GeneralTypesCacheHit {hits.set(hits.get()+1)};
            let query=DefinitionNameQuery::observed(&graph,&index,&observe);
            for excluded in ["","unrelated.scope"] {
                let expected=definition_general_type_inputs_for_scope_query(&graph,owner,excluded).unwrap();
                assert_eq!(expected.len(),1);
                for _ in 0..4 {assert_eq!(definition_general_type_inputs_with_view(&query,owner,excluded).unwrap(),expected);}
            }
            assert_eq!(hits.get(),6);assert_eq!(query.general_types.borrow().len(),2);
            // A cloned same-ID object may carry different properties: never let
            // the canonical entry replace its own independently assessed result.
            let mut foreign=owner.clone();foreign.properties.insert("owned_relationship".into(),json!([]));
            foreign.properties.insert("is_implied_included".into(),json!(true));
            assert!(definition_general_type_inputs_with_view(&query,&foreign,"").unwrap().is_empty());
            assert_eq!(hits.get(),6);assert_eq!(query.general_types.borrow().len(),2);
            assert_eq!(before,serde_json::to_value(&graph).unwrap());
        }
    }

    #[test]
    fn definition_general_type_view_preserves_requirements_and_invalidates_on_edit() {
        let doc=crate::definition_document::parse_and_link("package P { classifier G; classifier C specializes G; }",crate::SourceLanguage::Kerml).unwrap();
        let owner_id=doc.elements.iter().find(|e|e.properties.get("declared_name")==Some(&json!("C"))).unwrap().id.clone();
        let mut graph=doc.elements;
        graph.iter_mut().find(|e|e.id==owner_id).unwrap().properties.insert("is_implied_included".into(),json!(true));
        let owner=graph.iter().find(|e|e.id==owner_id).unwrap();
        let relation=stored_children(&graph,owner,"owned_relationship").unwrap().into_iter().find(|e|metaclass_conforms(&e.kind,"Subclassification")).unwrap();
        let relation_id=relation.id.clone();let field=ecore_model::redefined_feature(&relation.kind,"general").unwrap().field;
        let saved=graph.iter_mut().find(|e|e.id==relation_id).unwrap().properties.remove(field).unwrap();
        {
            let index=graph.iter().map(|e|(e.id.as_str(),e)).collect();let query=DefinitionNameQuery::new(&graph,&index);
            let owner=graph.iter().find(|e|e.id==owner_id).unwrap();
            for _ in 0..2 {
                let failure=definition_general_type_inputs_with_view(&query,owner,"").unwrap_err();
                assert!(matches!(failure,QueryFailure::Required(Prerequisite::ReadField {owner_id,field:ref actual}) if owner_id==relation_id && actual==field));
                assert!(query.general_types.borrow().is_empty());
            }
        }
        graph.iter_mut().find(|e|e.id==relation_id).unwrap().properties.insert(field.into(),saved);
        {
            let index=graph.iter().map(|e|(e.id.as_str(),e)).collect();let query=DefinitionNameQuery::new(&graph,&index);
            let owner=graph.iter().find(|e|e.id==owner_id).unwrap();
            assert_eq!(definition_general_type_inputs_with_view(&query,owner,"").unwrap().len(),1);
            assert_eq!(query.general_types.borrow().len(),1);
        }
        graph.iter_mut().find(|e|e.id==relation_id).unwrap().properties.insert(field.into(),json!(false));
        let index=graph.iter().map(|e|(e.id.as_str(),e)).collect();let query=DefinitionNameQuery::new(&graph,&index);
        let owner=graph.iter().find(|e|e.id==owner_id).unwrap();
        for _ in 0..2 {assert!(matches!(definition_general_type_inputs_with_view(&query,owner,""),Err(QueryFailure::Rejected(_))));}
        assert!(query.general_types.borrow().is_empty());
    }

    #[test]
    fn definition_general_type_view_reuses_pilot_positional_inputs() {
        let artifact:Value=serde_json::from_str(include_str!("../../../../resources/metamodels/sysml-2.0-pilot-2026-08/feature-redefinitions.extract.json")).unwrap();
        let mut comparisons=0;let mut total_hits=0;
        for family in ["end_controls","parameter_controls"] {
            for case in artifact[family].as_array().unwrap().iter().filter(|case|!case["redefined_features"].as_array().unwrap().is_empty()).take(6) {
                let source=end_control_graph(case);
                for reverse in [false,true] {
                    let mut graph:Vec<KirElement>=serde_json::from_value(serde_json::to_value(&source).unwrap()).unwrap();if reverse {graph.reverse();}
                    let before=serde_json::to_value(&graph).unwrap();let index=graph.iter().map(|e|(e.id.as_str(),e)).collect();
                    let hits=std::cell::Cell::new(0);let observe=|event:DefinitionConstructionEvent<'_>|if event.phase==DefinitionConstructionPhase::GeneralTypesCacheHit {hits.set(hits.get()+1)};
                    let query=DefinitionNameQuery::observed(&graph,&index,&observe);
                    let target=graph.iter().find(|e|Some(e.id.as_str())==case["target"].as_str()).unwrap();
                    for _ in 0..3 {
                        let actual=definition_redefined_features_query(&query,target,false).unwrap();
                        assert_eq!(json!(actual.iter().map(|e|&e.id).collect::<Vec<_>>()),case["redefined_features"]);comparisons+=1;
                    }
                    assert!(hits.get()>0,"{family}: positional queries discarded reusable inputs");total_hits+=hits.get();
                    assert_eq!(before,serde_json::to_value(&graph).unwrap());
                }
            }
        }
        assert_eq!(comparisons,72);assert!(total_hits>=24);
    }

    #[test]
    fn definition_nested_query_trace_preserves_required_and_rejected_inputs() {
        let doc=crate::definition_document::parse_and_link("package P { classifier G; classifier C specializes G; }",crate::SourceLanguage::Kerml).unwrap();
        let owner_id=doc.elements.iter().find(|e|e.properties.get("declared_name")==Some(&json!("C"))).unwrap().id.clone();
        for required in [true,false] {
            let mut graph=doc.elements.clone();
            if required {
                let owner=graph.iter().find(|e|e.id==owner_id).unwrap();
                let relation_id=stored_children(&graph,owner,"owned_relationship").unwrap().into_iter().find(|e|metaclass_conforms(&e.kind,"Subclassification")).unwrap().id.clone();
                let relation=graph.iter_mut().find(|e|e.id==relation_id).unwrap();
                let field=ecore_model::redefined_feature(&relation.kind,"general").unwrap().field;
                relation.properties.remove(field);
            } else {graph.iter_mut().find(|e|e.id==owner_id).unwrap().kind="UnknownClass".into();}
            let before=serde_json::to_value(&graph).unwrap();
            let index=graph.iter().map(|e|(e.id.as_str(),e)).collect();
            let events=std::cell::RefCell::new(Vec::new());
            let observe=|event:DefinitionConstructionEvent<'_>|events.borrow_mut().push((event.phase,event.succeeded));
            let query=DefinitionNameQuery::observed(&graph,&index,&observe);
            let owner=graph.iter().find(|e|e.id==owner_id).unwrap();
            let actual=definition_general_type_inputs_with_view(&query,owner,"");
            let plain=definition_general_type_inputs_for_scope_query(&graph,owner,"");
            if required {assert!(matches!(actual,Err(QueryFailure::Required(_))));assert!(matches!(plain,Err(QueryFailure::Required(_))));}
            else {assert!(matches!(actual,Err(QueryFailure::Rejected(_))));assert!(matches!(plain,Err(QueryFailure::Rejected(_))));}
            let mut expected=vec![(DefinitionConstructionPhase::GeneralTypesStarted,None)];
            if required {
                expected.extend([
                    (DefinitionConstructionPhase::ContainmentReadStarted,None),
                    (DefinitionConstructionPhase::ContainerReadStarted,None),
                    (DefinitionConstructionPhase::ContainerReadFinished,Some(true)),
                    (DefinitionConstructionPhase::ContainmentReadFinished,Some(true)),
                    (DefinitionConstructionPhase::GeneralizationPrerequisite,Some(false)),
                ]);
            }
            expected.push((DefinitionConstructionPhase::GeneralTypesFinished,Some(false)));
            assert_eq!(*events.borrow(),expected);
            assert_eq!(serde_json::to_value(&graph).unwrap(),before);
        }
    }

    fn redefinition_view_fixture(count:usize,padding:usize) -> Vec<KirElement> {
        let mut owner=fresh_definition_element("view_owner".into(),"Class").unwrap();
        let mut graph=Vec::new();
        for i in 0..count {
            let mut feature=fresh_definition_element(format!("view_feature{i}"),"Feature").unwrap();
            let mut member=fresh_definition_element(format!("view_member{i}"),"FeatureMembership").unwrap();
            ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS,&mut member,&mut feature).unwrap();
            ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,&mut owner,&mut member).unwrap();
            graph.extend([feature,member]);
        }
        graph.push(owner);
        graph.extend((0..padding).map(|i|fresh_definition_element(format!("view_padding{i}"),"Element").unwrap()));
        graph
    }

    #[test]
    fn definition_type_relationship_scope_matches_pinned_pilot_contexts() {
        let data:Value=serde_json::from_str(include_str!("../../../../../../docs/conformance/2026-08-support/type-relationship-scope-pilot-controls.json")).unwrap();
        assert_eq!(data["cases"].as_array().unwrap().len(),33);
        let mut positives=0;
        for case in data["cases"].as_array().unwrap() {
            let source=case["units"][0]["source"].as_str().unwrap();
            let result=crate::definition_document::parse_and_link(source,crate::SourceLanguage::Kerml);
            if !case["assertion"]["resolved"].as_bool().unwrap() {assert!(result.is_err(),"negative {}",case["name"]);continue;}
            let doc=result.unwrap_or_else(|e|panic!("{}: {e:?}",case["name"]));positives+=1;
            let link=&case["links"][0];
            let relation=doc.elements.iter().find(|e|e.kind.rsplit("::").next()==link["kind"].as_str()).unwrap();
            let bindings:Value=serde_json::from_str(include_str!("../../../../resources/metamodels/sysml-2.0-pilot-2026-08/type-relationship-scope.extract.json")).unwrap();
            let field=bindings["bindings"].as_array().unwrap().iter().find(|b|b["kind"]==link["kind"] && b["ecore_feature"].as_str().unwrap().rsplit("/").next()==link["field"].as_str()).unwrap()["field"].as_str().unwrap();
            let field=ecore_model::feature(&relation.kind,field).unwrap().field;
            let target=relation.properties.get(field).and_then(Value::as_str).unwrap();
            let path=|graph:&[KirElement],target:&str| {
                let index=graph.iter().map(|e|(e.id.as_str(),e)).collect::<BTreeMap<_,_>>();
                let mut current=index.get(target).copied();let mut names=Vec::new();let mut visited=BTreeSet::new();
                while let Some(element)=current {
                    assert!(visited.insert(element.id.clone()));
                    if let Some(name)=element.properties.get("declared_name").and_then(Value::as_str) {names.push(name.to_owned());}
                    current=generated_parent_namespace_indexed(&index,&element.id).unwrap();
                }
                names.reverse();json!(names)
            };
            assert_eq!(path(&doc.elements,target),case["assertion"]["target_path"],"{}",case["name"]);
            if case["name"]=="Disjoining_standalone" {
                let target=relation.properties.get("type_disjoined").and_then(Value::as_str).unwrap();
                assert_eq!(path(&doc.elements,target),link["type_disjoined_path"]);
            }
            let mut reversed:Vec<KirElement>=serde_json::from_value(serde_json::to_value(&doc.elements).unwrap()).unwrap();reversed.reverse();
            assert_eq!(path(&reversed,target),case["assertion"]["target_path"]);
        }
        assert_eq!(positives,21);
        assert!(super::super::type_relationship_scope_generated::permits("SysML::Intersecting","intersecting_type"));
        assert!(!super::super::type_relationship_scope_generated::permits("Specialization","general"));
        assert!(!super::super::type_relationship_scope_generated::permits("Intersecting","type_intersected"));
    }

