    fn definition_redefinition_readiness_reuses_only_canonical_success() {
        let original=redefinition_view_fixture(2,128);
        let restored:Vec<KirElement>=serde_json::from_value(serde_json::to_value(&original).unwrap()).unwrap();
        for mut graph in [original,restored] {for _ in 0..2 {
            let index=graph.iter().map(|e|(e.id.as_str(),e)).collect();let evaluations=std::cell::Cell::new(0);
            let observer=|event:DefinitionConstructionEvent<'_>|if event.phase==DefinitionConstructionPhase::ExplicitRedefinitionReadinessStarted {evaluations.set(evaluations.get()+1);};
            let query=DefinitionNameQuery::observed(&graph,&index,&observer);let target=query.index.get("view_feature0").copied().unwrap();let before=serde_json::to_value(&graph).unwrap();
            for _ in 0..32 {assert!(pending_explicit_redefinition_indexed(&query,target).unwrap().is_none());}
            assert_eq!(evaluations.get(),1);assert_eq!(query.explicit_redefinition_ready.borrow().len(),1);
            let mut foreign=target.clone();foreign.properties.insert("is_implied_included".into(),json!("invalid"));
            assert!(pending_explicit_redefinition_indexed(&query,&foreign).is_err());assert_eq!(evaluations.get(),2);
            assert!(pending_explicit_redefinition_indexed(&query,target).unwrap().is_none());assert_eq!(evaluations.get(),2);
            assert_eq!(before,serde_json::to_value(&graph).unwrap());drop(query);graph.reverse();
        }}
    }

    #[test]
    fn definition_redefinition_readiness_preserves_pending_errors_and_edit_invalidation() {
        let mut graph=redefinition_view_fixture(2,64);
        let mut relation=fresh_definition_element("readiness.redefinition".into(),"Redefinition").unwrap();relation.properties.insert("redefining_feature".into(),json!("view_feature0"));
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,graph.iter_mut().find(|e|e.id=="view_feature0").unwrap(),&mut relation).unwrap();graph.push(relation);
        for value in [None,Some(json!(false)),Some(json!("view_feature1")),Some(json!("view_feature0")),None] {
            let relation=graph.iter_mut().find(|e|e.id=="readiness.redefinition").unwrap();if let Some(v)=&value {relation.properties.insert("redefined_feature".into(),v.clone());}else{relation.properties.remove("redefined_feature");}
            let restored:Vec<KirElement>=serde_json::from_value(serde_json::to_value(&graph).unwrap()).unwrap();
            for mut g in [graph.clone(),restored] {for _ in 0..2 {
                let index=g.iter().map(|e|(e.id.as_str(),e)).collect();let evaluations=std::cell::Cell::new(0);
                let observer=|event:DefinitionConstructionEvent<'_>|if event.phase==DefinitionConstructionPhase::ExplicitRedefinitionReadinessStarted {evaluations.set(evaluations.get()+1);};
                let query=DefinitionNameQuery::observed(&g,&index,&observer);let target=query.index.get("view_feature0").copied().unwrap();assert!(query.explicit_redefinition_ready.borrow().is_empty());
                for _ in 0..4 {match &value {
                    None=>assert!(matches!(pending_explicit_redefinition_indexed(&query,target).unwrap(),Some(GeneratedLinkTarget::Deferred{owner_id,field}) if owner_id=="readiness.redefinition" && field=="redefined_feature")),
                    Some(v) if v.is_boolean()=>assert!(pending_explicit_redefinition_indexed(&query,target).is_err()),
                    _=>assert!(pending_explicit_redefinition_indexed(&query,target).unwrap().is_none()),
                }}
                let ready=value.as_ref().is_some_and(Value::is_string);assert_eq!(evaluations.get(),if ready {1}else{4});assert_eq!(query.explicit_redefinition_ready.borrow().len(),usize::from(ready));drop(query);g.reverse();
            }}
        }
    }

