    #[test]
    fn definition_projection_query_views_reject_invalid_edits_and_duplicates() {
        let artifact: Value = serde_json::from_str(include_str!("../../../../resources/metamodels/sysml-2.0-pilot-2026-08/feature-redefinitions.extract.json")).unwrap();
        for family in ["end_controls", "parameter_controls"] {
            let case = artifact[family].as_array().unwrap().iter()
                .find(|case| !case["redefined_features"].as_array().unwrap().is_empty()).unwrap();
            let source = end_control_graph(case);
            for defect in ["duplicate", "missing member"] {
                let mut graph = source.clone();
                if defect == "duplicate" { graph.push(graph[0].clone()); }
                else {
                    let membership = graph.iter_mut().find(|e| metaclass_conforms(&e.kind, "FeatureMembership")
                        && e.properties.get("owned_related_element").is_some_and(|v| v.as_array().is_some_and(|ids| !ids.is_empty()))).unwrap();
                    membership.properties.insert("owned_related_element".into(), json!(["missing"]));
                }
                let index = graph.iter().map(|e| (e.id.as_str(), e)).collect();
                let query = DefinitionNameQuery::new(&graph, &index);
                let target = graph.iter().find(|e| Some(e.id.as_str()) == case["target"].as_str()).unwrap();
                for _ in 0..2 {
                    let actual = definition_redefined_features_query(&query, target, false).unwrap_err();
                    let expected = definition_redefined_features(&graph, target, false).unwrap_err();
                    assert_eq!(format!("{actual:?}"), format!("{expected:?}"));
                }
            }
        }
    }

