    #[test]
    fn definition_parameters_reject_missing_and_unassessed_dependencies() {
        let artifact: Value = serde_json::from_str(include_str!("../../../../resources/metamodels/sysml-2.0-pilot-2026-08/feature-redefinitions.extract.json")).unwrap();
        let case = artifact["parameter_controls"].as_array().unwrap().iter().find(|c| c["kind"] == "Feature" && c["shape"] == "direct" && c["position"] == 0).unwrap();
        let original = end_control_graph(case);
        for mutation in ["missing_general", "missing_list", "added_members", "invalid_direction", "cycle", "chain"] {
            let mut graph = original.clone();
            match mutation {
                "missing_general" => { graph.iter_mut().find(|e| e.id == "owner.general0").unwrap().properties.remove("superclassifier"); },
                "missing_list" => { graph.iter_mut().find(|e| e.id == "base").unwrap().properties.remove("owned_relationship"); },
                "added_members" => { let base = graph.iter_mut().find(|e| e.id == "base").unwrap(); base.kind = "SysML::InvocationExpression".into(); base.properties.insert("is_implied_included".into(), json!(false)); },
                "invalid_direction" => { graph.iter_mut().find(|e| e.id == "local0").unwrap().properties.insert("direction".into(),json!("invalid")); },
                "cycle" => {
                    let mut relation = element("cycle", "Subclassification");
                    relation.properties.insert("subclassifier".into(), json!("base"));
                    relation.properties.insert("superclassifier".into(), json!("owner"));
                    let base = graph.iter_mut().find(|e| e.id == "base").unwrap();
                    ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, base, &mut relation).unwrap();
                    graph.push(relation);
                },
                _ => {
                    let mut relation = element("chain", "FeatureChaining");
                    relation.properties.insert("chaining_feature".into(), json!("missing-chain-endpoint"));
                    let base = graph.iter_mut().find(|e| e.id == "base0").unwrap();
                    ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, base, &mut relation).unwrap();
                    graph.push(relation);
                },
            }
            let target = graph.iter().find(|e| e.id == "local0").unwrap();
            let before = serde_json::to_value(&graph).unwrap();
            assert!(definition_redefined_features(&graph, target, false).is_err(), "{mutation}");
            assert_eq!(serde_json::to_value(&graph).unwrap(), before);
        }
    }

    #[test]
    fn definition_positional_ends_reject_unresolved_and_cyclic_dependencies() {
        let artifact: Value = serde_json::from_str(include_str!("../../../../resources/metamodels/sysml-2.0-pilot-2026-08/feature-redefinitions.extract.json")).unwrap();
        let case = artifact["end_controls"].as_array().unwrap().iter().find(|c| c["kind"] == "Feature" && c["shape"] == "direct" && c["position"] == 0).unwrap();
        let graph = end_control_graph(case);
        for mutation in ["missing_general", "missing_list", "cycle", "chain", "conjugation"] {
            let mut graph = graph.clone();
            match mutation {
                "missing_general" => { graph.iter_mut().find(|e| e.id == "owner.general0").unwrap().properties.remove("superclassifier"); },
                "missing_list" => { graph.iter_mut().find(|e| e.id == "base").unwrap().properties.remove("owned_relationship"); },
                "cycle" => {
                    let mut relation = element("cycle", "Subclassification");
                    relation.properties.insert("subclassifier".into(), json!("base"));
                    relation.properties.insert("superclassifier".into(), json!("owner"));
                    let base = graph.iter_mut().find(|e| e.id == "base").unwrap();
                    ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, base, &mut relation).unwrap();
                    graph.push(relation);
                },
                "conjugation" => {
                    let mut relation = element("conjugator", "Conjugation");
                    relation.properties.insert("conjugated_type".into(), json!("base"));
                    relation.properties.insert("original_type".into(), json!("owner"));
                    let base = graph.iter_mut().find(|e| e.id == "base").unwrap();
                    ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, base, &mut relation).unwrap();
                    graph.push(relation);
                },
                _ => {
                    let mut relation = element("chain", "FeatureChaining");
                    relation.properties.insert("chaining_feature".into(), json!("missing-chain-endpoint"));
                    let base = graph.iter_mut().find(|e| e.id == "base0").unwrap();
                    ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, base, &mut relation).unwrap();
                    graph.push(relation);
                },
            }
            let target = graph.iter().find(|e| e.id == "local0").unwrap();
            let before = serde_json::to_value(&graph).unwrap();
            assert!(definition_redefined_features(&graph, target, false).is_err(), "{mutation}");
            assert_eq!(serde_json::to_value(&graph).unwrap(), before);
        }
    }

    #[test]
    fn definition_feature_redefinitions_preserve_positional_and_adapter_dependencies() {
        for (owner_kind, field, value, reason) in [
            ("Class", "is_end", json!(true), "missing standard library root"),
            ("Behavior", "direction", json!("in"), "missing standard library root"),
            ("Behavior", "direction", json!("invalid"), "Invalid"),
            ("AssignmentActionUsage", "is_end", json!(false), "assignment"),
        ] {
            let mut owner = element("owner", owner_kind);
            let mut member = element("membership", "FeatureMembership");
            let mut feature = element("feature", "Feature");
            feature.properties.insert("owned_relationship".into(), json!([]));
            feature.properties.insert(field.into(), value);
            ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS, &mut member, &mut feature).unwrap();
            ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, &mut owner, &mut member).unwrap();
            let graph = vec![owner, member, feature.clone()];
            let error = format!("{:?}", definition_redefined_features(&graph, &feature, false).unwrap_err());
            assert!(error.to_lowercase().contains(&reason.to_lowercase()), "{error}");
        }
        let mut reference = element("feature", "ReferenceUsage");
        reference.properties.insert("owned_relationship".into(), json!([]));
        assert!(definition_redefined_features(&[reference.clone()], &reference, false).unwrap().is_empty());
        let mut unsupported = reference.clone(); unsupported.kind = "SysML::RenderingUsage".into();
        assert!(definition_redefined_features(&[unsupported.clone()], &unsupported, false).unwrap_err().message.contains("adapter strategy"));
        let mut constructor = element("constructor", "ConstructorExpression");
        let mut result_member = element("return", "ReturnParameterMembership");
        let mut result = element("result", "Feature");
        let mut member = element("membership", "FeatureMembership");
        let mut feature = element("feature", "Feature");
        feature.properties.insert("owned_relationship".into(), json!([]));
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS, &mut member, &mut feature).unwrap();
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, &mut result, &mut member).unwrap();
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS, &mut result_member, &mut result).unwrap();
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, &mut constructor, &mut result_member).unwrap();
        let graph = vec![constructor,result_member,result,member,feature.clone()];
        assert!(definition_redefined_features(&graph, &feature, false).unwrap_err().message.contains("Constructor"));
        let mut unbound = element("feature", "Feature");
        unbound.properties.insert("owned_relationship".into(), json!([]));
        let mut relation = element("redefinition", "Redefinition");
        relation.properties.insert("redefining_feature".into(), json!("someone_else"));
        relation.properties.insert("redefined_feature".into(), json!("target"));
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, &mut unbound, &mut relation).unwrap();
        assert!(definition_redefined_features(&[unbound.clone(),relation], &unbound, false).is_err());
    }

    #[test]
    fn generated_definition_defaults_match_resolved_pilot_branches() {
        let artifact: Value = serde_json::from_str(include_str!("../../../../resources/metamodels/sysml-2.0-pilot-2026-08/definition-defaults.extract.json")).unwrap();
        assert_eq!(artifact["bindings"].as_array().unwrap().len(), 26);
        assert_eq!(artifact["controls"].as_array().unwrap().len(), 196);
        for case in artifact["controls"].as_array().unwrap() {
            let kind = case["kind"].as_str().unwrap();
            let mut owner = element("owner", kind);
            owner.properties.insert("owned_relationship".into(), json!([]));
            if ecore_model::feature(kind, "is_individual").is_some() {
                owner.properties.insert("is_individual".into(), case["individual"].clone());
            }
            let end_count = case["owned_ends"].as_u64().unwrap() as usize;
            let mut graph = Vec::new();
            for index in 0..end_count + case["non_end_features"].as_u64().unwrap() as usize {
                let mut member = element(&format!("member{index}"), "FeatureMembership");
                let mut feature = element(&format!("feature{index}"), "Feature");
                feature.properties.insert("is_end".into(), json!(index < end_count));
                feature.properties.insert("owned_relationship".into(), json!([]));
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS, &mut member, &mut feature).unwrap();
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, &mut owner, &mut member).unwrap();
                graph.extend([member, feature]);
            }
            let binding = artifact["bindings"].as_array().unwrap().iter().find(|b| b["kind"] == kind).unwrap();
            let mut library = BTreeMap::new();
            for name in binding["labels"].as_object().unwrap().values() {
                let name = name.as_str().unwrap();
                if library.insert(name.to_owned(), name.to_owned()).is_none() {
                    let mut target = element(name, "Classifier");
                    target.properties.insert("owned_relationship".into(), json!([]));
                    graph.push(target);
                }
            }
            graph.push(owner.clone());
            assert_eq!(definition_owned_features(&graph, &owner, true).unwrap().len() as u64, case["observed_owned_ends"].as_u64().unwrap(), "{case}");
            assert_eq!(json!(stored_definition_generalizations(&graph, &owner, &library).unwrap()), case["general_types"], "{case}");
            graph.reverse();
            assert_eq!(json!(stored_definition_generalizations(&graph, &owner, &library).unwrap()), case["general_types"], "Record order changed {case}");
            assert!(stored_definition_generalizations(&graph, &owner, &BTreeMap::new()).is_err());
            let mut wrong = graph.clone();
            for target in wrong.iter_mut().filter(|e| library.values().any(|id| id == &e.id)) { target.kind = "SysML::Feature".into(); }
            assert!(stored_definition_generalizations(&wrong, &owner, &library).is_err());
            let mut complete = owner.clone();
            complete.properties.insert("is_implied_included".into(), json!(true));
            assert!(stored_definition_generalizations(&graph, &complete, &BTreeMap::new()).unwrap().is_empty());
            let mut incomplete = owner.clone(); incomplete.properties.remove("owned_relationship");
            assert!(stored_definition_generalizations(&graph, &incomplete, &library).is_err());
        }
    }

    #[test]
    fn definition_owned_end_query_checks_canonical_ownership_and_flags() {
        let document = crate::definition_document::parse_and_link("package P { connection def C { end part a; part ordinary; end part b; } }", crate::SourceLanguage::Sysml).unwrap();
        let owner = document.elements.iter().find(|e| e.properties.get("declared_name") == Some(&json!("C"))).unwrap();
        let names = |field| crate::definition_document::reference_targets(&document, &owner.id, field).unwrap().iter()
            .map(|e| e.properties["declared_name"].clone()).collect::<Vec<_>>();
        assert_eq!(names("owned_feature"), vec![json!("a"),json!("ordinary"),json!("b")]);
        assert_eq!(names("owned_end_feature"), vec![json!("a"),json!("b")]);
        let mut graph = document.elements.clone();
        let index = graph.iter().position(|e| e.properties.get("declared_name") == Some(&json!("a"))).unwrap();
        graph[index].properties.insert("is_end".into(), json!("true"));
        assert!(definition_owned_features(&graph, owner, true).is_err());
        graph[index].properties.insert("is_end".into(), json!(true));
        graph[index].properties.remove("owning_relationship");
        assert!(definition_owned_features(&graph, owner, true).is_err());
    }

    fn has_reference(value: &Value) -> bool {
        match value {
            Value::Object(fields) => {
                fields.contains_key("references") || fields.values().any(has_reference)
            }
            Value::Array(children) => children.iter().any(has_reference),
            _ => false,
        }
    }

    fn scoped_tree(root: &KirElement, elements: &[KirElement]) -> Value {
        let mut graph = vec![root.clone()];
        graph.extend_from_slice(elements);
        project_tree(root, &graph, true)
    }

    fn tree(root: &KirElement, elements: &[KirElement]) -> Value {
        let mut graph = vec![root.clone()];
        graph.extend_from_slice(elements);
        project_tree(root, &graph, false)
    }

    fn project_tree(root: &KirElement, elements: &[KirElement], include_scope: bool) -> Value {
        let kind = root.kind.rsplit("::").next().unwrap();
        let mut row = serde_json::Map::new();
        row.insert("kind".into(), json!(kind));
        if include_scope
            && let Some(namespace) = generated_parent_namespace(elements, &root.id).unwrap()
        {
            row.insert(
                "parent_namespace_kind".into(),
                json!(namespace.kind.rsplit("::").next().unwrap()),
            );
        }
        for field in ["value", "operator", "visibility", "direction"] {
            if let Some(value) = root.properties.get(field) {
                row.insert(field.into(), value.clone());
            }
        }
        let mut references = serde_json::Map::new();
        for (field, value) in &root.properties {
            if !value.is_null()
                && ecore_model::feature(kind, field).is_some_and(|f| {
                    f.kind == ecore_model::FeatureKind::Reference
                        && !f.containment
                        && !f.container
                        && !f.derived
                })
            {
                references.insert(
                    field.clone(),
                    if value.is_array() {
                        value.clone()
                    } else {
                        json!([value])
                    },
                );
            }
        }
        if !references.is_empty() {
            row.insert("references".into(), Value::Object(references));
        }
        for (field, label, inverse) in [
            (
                "owned_relationship",
                "relationships",
                "owning_related_element",
            ),
            ("owned_related_element", "elements", "owning_relationship"),
        ] {
            if field == "owned_related_element" && !metaclass_conforms(kind, "Relationship") {
                continue;
            }
            let children: Vec<Value> = root
                .properties
                .get(field)
                .and_then(Value::as_array)
                .into_iter()
                .flatten()
                .map(|id| {
                    let child = elements
                        .iter()
                        .find(|e| Some(e.id.as_str()) == id.as_str())
                        .expect("child exists");
                    assert_eq!(child.properties[inverse], root.id);
                    project_tree(child, elements, include_scope)
                })
                .collect();
            row.insert(label.into(), json!(children));
        }
        Value::Object(row)
    }

    #[test]
    fn graph_construction_finishes_before_any_linker_callback() {
        let parsed = crate::xtext_fragment::experimental_expression("x + 1", true)
            .unwrap()
            .unwrap();
        let endpoint = element("external.x", "Feature");
        let calls = std::cell::Cell::new(0);
        let resolver = |site: &GeneratedReferenceSite<'_>| {
            calls.set(calls.get() + 1);
            assert!(site.graph.iter().any(|e| e.kind == "SysML::LiteralInteger"
                && e.properties.get("value") == Some(&json!(1))));
            assert!(site.graph.iter().any(|e| e.kind == "SysML::FeatureValue"));
            assert_eq!(
                generated_parent_namespace(site.graph, site.owner_id)?
                    .unwrap()
                    .kind,
                "SysML::FeatureReferenceExpression"
            );
            Ok(&endpoint)
        };
        let mut broken = parsed.clone();
        broken
            .construction_order
            .push(crate::xtext_fragment::ConstructionStep::Operand(999));
        assert!(materialize_generated_with_context(&broken, "expression", &resolver).is_err());
        assert_eq!(
            calls.get(),
            0,
            "no scope callbacks before successful construction"
        );
        materialize_generated_with_context(&parsed, "expression", &resolver).unwrap();
        assert_eq!(calls.get(), 1);
        assert!(endpoint.properties.is_empty());
    }

    #[test]
    fn inherited_result_parameters_match_pinned_pilot() {
        use ecore_ownership_generated::{OWNED_ELEMENTS, OWNED_RELATIONSHIPS};
        let corpus: Value = serde_json::from_str(include_str!(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../../docs/conformance/2026-08-support/expression-model-pilot-controls.json"
        )))
        .unwrap();
        let cases = corpus["inherited_result_controls"].as_array().unwrap();
        assert_eq!(cases.len(), 32);
        for case in cases {
            let mask = case["result_mask"].as_u64().unwrap();
            let mut graph = Vec::new();
            for i in 0..4 {
                let mut owner = element(&format!("type{i}"), "Behavior");
                if mask & (1 << i) != 0 {
                    let mut member = element(&format!("member{i}"), "ReturnParameterMembership");
                    let mut result = element(&format!("result{i}"), "Feature");
                    result.properties.insert("direction".into(), json!("out"));
                    ecore_ownership::attach(&OWNED_ELEMENTS, &mut member, &mut result).unwrap();
                    ecore_ownership::attach(&OWNED_RELATIONSHIPS, &mut owner, &mut member).unwrap();
                    graph.extend([member, result]);
                }
                for (j, general) in case["generals"][i].as_array().unwrap().iter().enumerate() {
                    let mut relation = element(&format!("general{i}.{j}"), "Subclassification");
                    relation
                        .properties
                        .insert("subclassifier".into(), json!(format!("type{i}")));
                    relation.properties.insert(
                        "superclassifier".into(),
                        json!(format!("type{}", general.as_u64().unwrap())),
                    );
                    ecore_ownership::attach(&OWNED_RELATIONSHIPS, &mut owner, &mut relation)
                        .unwrap();
                    graph.push(relation);
                }
                graph.push(owner);
            }
            let visits = std::cell::RefCell::new(BTreeSet::new());
            let ready = |owner: &KirElement| {
                assert!(
                    visits.borrow_mut().insert(owner.id.clone()),
                    "each type visited once"
                );
                // This fixture uses plain Behavior, whose pinned adapter does
                // not synthesize members. Production readiness remains external.
                assert_eq!(owner.kind, "SysML::Behavior");
                Ok(())
            };
            let generals =
                |owner: &KirElement| generated_general_types(&graph, owner, &|_| Ok(Vec::new()));
            let actual = generated_result_parameter(&graph, "type0", &ready, &generals).unwrap();
            let expected = case["selected"].as_i64().unwrap();
            assert_eq!(
                actual.map(|e| e.id.clone()),
                (expected >= 0).then(|| format!("result{expected}")),
                "{case}"
            );
        }
    }

    fn bind_expected(value: &mut Value) {
        match value {
            Value::Object(fields) => {
                if let Some(Value::Object(references)) = fields.get_mut("references") {
                    for values in references.values_mut() {
                        for v in values.as_array_mut().unwrap() {
                            *v = json!(format!(
                                "external.{}",
                                v.as_str().unwrap().trim_matches('\'')
                            ));
                        }
                    }
                }
                for child in fields.values_mut() {
                    bind_expected(child);
                }
            }
            Value::Array(values) => {
                for value in values {
                    bind_expected(value);
                }
            }
            _ => {}
        }
    }
    #[test]
    fn specialization_clauses_match_pinned_containing_models() {
        let corpus: Value = serde_json::from_str(include_str!(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../../docs/conformance/2026-08-support/expression-model-pilot-controls.json"
        )))
        .unwrap();
        let cases = corpus["specialization_clause_controls"].as_array().unwrap();
        assert_eq!(cases.len(), 28);
        let mut accepted = 0;
        for case in cases {
            let kerml = case["language"] == "kerml";
            let prefix = if kerml {
                "org.omg.kerml.xtext.KerML"
            } else {
                "org.omg.sysml.xtext.SysML"
            };
            let kind = if kerml { "Feature" } else { "ReferenceUsage" };
            let tokens = crate::xtext_terminal::lex(case["source"].as_str().unwrap()).unwrap();
            let parsed = crate::xtext_fragment::execute_in_context(
                &format!("{prefix}::FeatureSpecializationPart"),
                &tokens,
                kind,
                kerml,
            )
            .unwrap_or_else(|error| {
                assert_eq!(case["accepted"], false, "{case}: {error}");
                None
            })
            .filter(|m| m.consumed + 1 == tokens.len());
            assert_eq!(
                parsed.is_some(),
                case["accepted"].as_bool().unwrap(),
                "{case}"
            );
            let Some(parsed) = parsed else {
                continue;
            };
            let targets: BTreeMap<String, KirElement> = ["a", "b", "c"]
                .into_iter()
                .map(|name| (name.into(), element(&format!("external.{name}"), "Feature")))
                .collect();
            let (root, graph) = materialize_generated_with_links(&parsed, "feature", &|r| {
                targets
                    .get(&r.spelling)
                    .ok_or_else(|| error("missing clause target"))
            })
            .unwrap();
            let mut expected = case["tree"].clone();
            bind_expected(&mut expected);
            assert_eq!(scoped_tree(&root, &graph), expected, "{case}");
            for field in ["is_ordered", "is_unique"] {
                assert_eq!(root.properties[field], case[field], "{case}");
            }
            accepted += 1;
        }
        assert_eq!(accepted, 17);
    }

