        let before=serde_json::to_value(&graph).unwrap();
        for entries in [vec![("Subsetting","a"),("Subsetting","b")],vec![("Subsetting","a"),("Subsetting","a")],vec![("Conjugation","a")],vec![("Subsetting","owner")],vec![("Subsetting","missing")]] {
            assert!(definition_materialize_selected_generals(&mut graph,"owner","inserted",&entries).is_err());
            assert_eq!(serde_json::to_value(&graph).unwrap(),before);
        }
        graph.iter_mut().find(|e|e.id=="a").unwrap().properties.insert("is_implied_included".into(),json!(false));
        let before=serde_json::to_value(&graph).unwrap();
        assert!(definition_materialize_selected_generals(&mut graph,"owner","unknown",&[("Subsetting","a"),("Subsetting","b")]).is_err());
        assert_eq!(serde_json::to_value(&graph).unwrap(),before);
        let mut chains=compatibility_fixture(&fixture);
