            let mut doc=crate::definition_document::parse_and_link(&text,crate::SourceLanguage::Kerml).unwrap();
            let id=doc.elements.iter().find(|e|e.properties.get("declared_name")==Some(&json!("e"))).unwrap().id.clone();
            let before=serde_json::to_value(&doc).unwrap();
            let expression=doc.elements.iter().find(|e|e.id==id).unwrap();
            let selected=definition_expression_default_generals(&doc.elements,expression).unwrap();
