    #[test]
    fn definition_expression_generalization_queries_preserve_known_and_unknown_states() {
        let source="standard library package Base { feature things; } standard library package Performances { feature evaluations subsets Base::things; } package P { feature other; feature y; feature x = y; }";
        let mut doc=crate::definition_document::parse_and_link(source,crate::SourceLanguage::Kerml).unwrap();
        let expression=doc.elements.iter().find(|e|e.kind.ends_with("::FeatureReferenceExpression")).unwrap().id.clone();
        let named=|name:&str|doc.elements.iter().find(|e|e.properties.get("declared_name")==Some(&json!(name))).unwrap().id.clone();
        let things=named("things");let other=named("other");let evaluations=named("evaluations");
        for inserted in [false,true] {
            if inserted {assert_eq!(crate::definition_document::materialize_value_expression_defaults(&mut doc,&expression,"inserted").unwrap(),1);}
            let before=serde_json::to_value(&doc).unwrap();
            assert!(crate::definition_document::specializes(&doc,&expression,&evaluations).unwrap());
            assert!(crate::definition_document::specializes(&doc,&expression,&things).unwrap());
            assert!(!crate::definition_document::specializes(&doc,&expression,&other).unwrap());
            assert_eq!(before,serde_json::to_value(&doc).unwrap());
        }
        let exported=crate::abstract_syntax_json::export_sysml_abstract_syntax_value(&doc,Default::default()).unwrap();assert!(!exported.has_errors());
        let imported=crate::abstract_syntax_json::import_sysml_abstract_syntax_value(exported.value,Default::default()).unwrap();assert!(!imported.has_errors());
        assert!(crate::definition_document::specializes(&imported.persistable_document().unwrap(),&expression,&things).unwrap());
        for failure in ["unrelated_implied","missing_library","unsupported_ancestry"] {
            let mut graph=doc.clone();
            match failure {
                "unrelated_implied"=>{graph.elements.iter_mut().find(|e|e.id=="inserted.0").unwrap().properties.insert("subsetted_feature".into(),json!(other));},
                "missing_library"=>{graph.elements.iter_mut().find(|e|e.id==evaluations).unwrap().properties.insert("declared_name".into(),json!("absent"));},
                _=>{graph.elements.iter_mut().find(|e|e.id==evaluations).unwrap().kind="SysML::CalculationUsage".into();},
            }
            let before=serde_json::to_value(&graph).unwrap();
            assert!(crate::definition_document::specializes(&graph,&expression,&other).is_err(),"{failure}");
            assert_eq!(before,serde_json::to_value(&graph).unwrap());
        }
    }

    fn result_default_fixture(kind: &str, mask: u64) -> crate::KirDocument {
        static LIBRARY:std::sync::OnceLock<crate::KirDocument>=std::sync::OnceLock::new();
        let mut doc=LIBRARY.get_or_init(||crate::definition_document::parse_and_link("standard library package Base { feature things; feature dataValues; } standard library package Objects { feature objects; } standard library package Occurrences { feature occurrences; }",crate::SourceLanguage::Kerml).unwrap()).clone();
        let mut owner=fresh_definition_element("owner".into(),kind).unwrap();owner.properties.insert("is_implied_included".into(),json!(true));
        let mut result=fresh_definition_element("result".into(),"Feature").unwrap();result.properties.insert("direction".into(),json!("out"));
        let mut member=fresh_definition_element("return".into(),"ReturnParameterMembership").unwrap();
        for (bit,kind) in [(1,"Class"),(2,"Structure"),(4,"DataType")] {
            if mask&bit==0 {continue;}
            let mut target=fresh_definition_element(format!("typing.target.{bit}"),kind).unwrap();target.properties.insert("is_implied_included".into(),json!(true));
            let mut typing=fresh_definition_element(format!("typing.{bit}"),"FeatureTyping").unwrap();typing.properties.insert("typed_feature".into(),json!("result"));typing.properties.insert("type".into(),json!(target.id));
            ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,&mut result,&mut typing).unwrap();doc.elements.extend([target,typing]);
        }
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS,&mut member,&mut result).unwrap();ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,&mut owner,&mut member).unwrap();doc.elements.extend([owner,member,result]);doc
    }

    fn result_multiplicity_fixture(case:&Value)->crate::KirDocument {
        let mut doc=result_default_fixture(case["owner_kind"].as_str().unwrap(),case["mask"].as_u64().unwrap());
        let shape=case["shape"].as_str().unwrap();if shape=="absent" {return doc;}
        let range=fresh_definition_element("range".into(),"MultiplicityRange").unwrap();cross_test_own(&mut doc.elements,"result","OwningMembership",range);
        let count=match shape {"one"=>1,"two"|"infinite"=>2,_=>0};
        for i in 0..count {
            let mut bound=fresh_definition_element(format!("bound.{i}"),if shape=="infinite"&&i==1 {"LiteralInfinity"}else{"LiteralInteger"}).unwrap();
            if bound.kind.ends_with("::LiteralInteger") {bound.properties.insert("value".into(),json!(if i==0 {0}else{2}));}
            cross_test_own(&mut doc.elements,"range","OwningMembership",bound);
        }
        doc
    }

