    // A typed dependency fixture exercises the lifecycle service independently
    // of Pilot's completed model. These deliberately bounded declarations are
    // NOT the actual complete Performances/ScalarValues library corpus.
    fn cold_literal_source_text() -> &'static str {
        r#"
            standard library package Base {
                classifier Anything; datatype DataValue;
                feature things; feature dataValues;
            }
            standard library package ScalarValues {
                datatype ScalarValue; datatype Boolean; datatype Integer;
                datatype Real; datatype String;
            }
            standard library package Performances {
                behavior Performance { step enclosedPerformances : Performance; }
                step performances : Performance;
                function Evaluation specializes Performance { return result : Base::Anything; }
                function LiteralEvaluation specializes Evaluation { return result : ScalarValues::ScalarValue; }
                function BooleanEvaluation specializes Evaluation { return result : ScalarValues::Boolean; }
                function LiteralBooleanEvaluation specializes LiteralEvaluation, BooleanEvaluation { return result : ScalarValues::Boolean; }
                function LiteralIntegerEvaluation specializes LiteralEvaluation { return result : ScalarValues::Integer; }
                function LiteralRationalEvaluation specializes LiteralEvaluation { return result : ScalarValues::Real; }
                function LiteralStringEvaluation specializes LiteralEvaluation { return result : ScalarValues::String; }
                function NullEvaluation specializes Evaluation { return result : Base::Anything; }
                expr evaluations : Evaluation;
                expr literalEvaluations : LiteralEvaluation subsets evaluations;
                expr booleanEvaluations : BooleanEvaluation subsets evaluations;
                expr literalBooleanEvaluations : LiteralBooleanEvaluation subsets literalEvaluations, booleanEvaluations;
                expr literalIntegerEvaluations : LiteralIntegerEvaluation subsets literalEvaluations;
                expr literalRationalEvaluations : LiteralRationalEvaluation subsets literalEvaluations;
                expr literalStringEvaluations : LiteralStringEvaluation subsets literalEvaluations;
                expr nullEvaluations : NullEvaluation subsets evaluations;
            }
            package P { function F {
                return feature integerValue : ScalarValues::Integer = 1;
                feature booleanValue : ScalarValues::Boolean = true;
                feature rationalValue : ScalarValues::Real = 1.5;
                feature stringValue : ScalarValues::String = "value";
                feature infinityValue : ScalarValues::Integer = *;
                feature nullValue = null;
            } }
        "#
    }

    fn cold_literal_source_fixture() -> crate::KirDocument {
        crate::definition_document::parse_and_link(cold_literal_source_text(), crate::SourceLanguage::Kerml).unwrap()
    }

    fn cold_literal_ids(doc: &crate::KirDocument) -> Vec<String> {
        doc.elements.iter().filter(|e| cold_literal_values::supports(e.kind.rsplit("::").next().unwrap_or(&e.kind)))
            .map(|e| e.id.clone()).collect()
    }

    fn literal_value_binding_source(default: bool) -> String {
        // Typed, deliberately bounded dependencies. Genuine pinned library
        // lifecycle qualification is separate from this shared transaction test.
        let mut source = cold_literal_source_text().replace("feature nullValue = null", "feature nullValue : Base::Anything = null")
            .replace("classifier Anything; datatype DataValue;", "classifier Anything; datatype DataValue specializes Anything;")
            .replace("datatype ScalarValue; datatype Boolean; datatype Integer;\n                datatype Real; datatype String;", r#"datatype ScalarValue specializes Base::DataValue;
                datatype Boolean specializes ScalarValue; datatype String specializes ScalarValue;
                datatype NumericalValue specializes ScalarValue; datatype Complex specializes NumericalValue;
                datatype Real specializes Complex; datatype Rational specializes Real; datatype Integer specializes Rational;"#);
        if default { source = source.replace(" = ", " default = "); }
        source.push_str(r#"standard library package Links {
            assoc Link { feature participant; }
            assoc BinaryLink specializes Link { end feature source; end feature target; }
            assoc SelfLink specializes BinaryLink { end feature thisThing; end feature sameThing; }
            feature selfLinks : SelfLink { end feature thisThing; end feature sameThing; }
        }"#);
        source
    }

    fn literal_value_binding_fixture(default: bool) -> crate::KirDocument {
        crate::definition_document::parse_and_link(&literal_value_binding_source(default), crate::SourceLanguage::Kerml).unwrap()
    }




    #[test]
    fn definition_shared_cross_readiness_matches_cached_pilot_order_and_persistence() {
        let controls: Value=serde_json::from_str(include_str!("../../../../../../docs/conformance/2026-08-support/cross-feature-pilot-controls.json")).unwrap();
        let selected=controls["selection_controls"].as_array().unwrap();
        let ordered=controls["ordered_selection_controls"].as_array().unwrap();
        assert_eq!((selected.len(),ordered.len()),(72,3));
        for case in selected.iter().chain(ordered) {
            let mut graph=if case.get("kinds").is_some() {cross_test_graph(&[true],true)}
                else {cross_test_graph(&[case["is_end"].as_bool().unwrap()],case["type_owner"].as_bool().unwrap())};
            if let Some(kinds)=case["kinds"].as_array() {
                for (i,kind) in kinds.iter().enumerate() {
                    cross_test_own(&mut graph,"end0","OwningMembership",fresh_definition_element(format!("member{i}"),kind.as_str().unwrap()).unwrap());
                }
            } else {
                cross_test_own(&mut graph,"end0",case["membership_kind"].as_str().unwrap(),
                    fresh_definition_element("candidate".into(),case["candidate_kind"].as_str().unwrap()).unwrap());
            }
            let mut reordered=graph.clone();reordered.reverse();
            let persisted:Vec<KirElement>=serde_json::from_str(&serde_json::to_string(&graph).unwrap()).unwrap();
            for model in [&graph,&reordered,&persisted] {
                let before=serde_json::to_value(model).unwrap();
                let index=model.iter().map(|e|(e.id.as_str(),e)).collect();
                let events=std::cell::RefCell::new(Vec::new());
                let observer=|event:DefinitionConstructionEvent<'_>|events.borrow_mut().push(event.phase);
                let query=DefinitionNameQuery::observed(model,&index,&observer);
                for _ in 0..2 {
                    assert_eq!(json!(definition_owned_cross_feature_in_view(&query,index["end0"]).unwrap()
                        .into_iter().map(|e|e.id.clone()).collect::<Vec<_>>()),case["selected"],"{case}");
                }
                if case["selected"].as_array().unwrap().len()==1 {
                    assert!(events.borrow().contains(&DefinitionConstructionPhase::ContainmentCacheHit));
                }
                assert_eq!(before,serde_json::to_value(model).unwrap());
            }
        }
    }

    #[test]
    fn definition_shared_cross_readiness_preserves_typed_dependencies_and_repairs() {
        let mut graph=cross_test_graph(&[true,true],true);
        graph.iter_mut().find(|e|e.id=="context").unwrap().kind="SysML::Class".into();
        graph.extend(crate::definition_document::parse_and_link(
            "standard library package Base { classifier Anything; feature things; }",crate::SourceLanguage::Kerml).unwrap().elements);
        for element in &mut graph {element.properties.insert("is_implied_included".into(),json!(true));}
        // End transformation remains incomplete. This is a bounded dependency
        // fixture, not a certificate of the real library lifecycle.
        graph.iter_mut().find(|e|e.id=="end0").unwrap().properties.insert("is_implied_included".into(),json!(false));
        cross_test_own(&mut graph,"end0","OwningMembership",fresh_definition_element("cross".into(),"Feature").unwrap());
        for (id,kind) in [("target","Classifier"),("baseEnd","Feature")] {
            let mut e=fresh_definition_element(id.into(),kind).unwrap();
            e.properties.insert("is_implied_included".into(),json!(true));graph.push(e);
        }
        definition_append_implied_specialization(&mut graph,"typing","FeatureTyping","end0","target").unwrap();
        graph.iter_mut().find(|e|e.id=="typing").unwrap().properties.insert("is_implied".into(),json!(false));
        definition_append_implied_specialization(&mut graph,"redefinition","Redefinition","end0","baseEnd").unwrap();
        graph.iter_mut().find(|e|e.id=="redefinition").unwrap().properties.insert("is_implied".into(),json!(false));
        for (relation,field) in [("typing","type"),("redefinition","redefined_feature")] {
            let mut pending=graph.clone();
            let value=pending.iter_mut().find(|e|e.id==relation).unwrap().properties.remove(field).unwrap();
            let before=serde_json::to_value(&pending).unwrap();
            {
                let index=pending.iter().map(|e|(e.id.as_str(),e)).collect();
                let query=DefinitionNameQuery::new(&pending,&index);
                // Successful structural reads must not cache away an absent
                // semantic endpoint, even on a repeated recursive request.
                stored_children_projection_query(&query,index["cross"],"owned_relationship").unwrap();
                for _ in 0..2 {
                    assert!(matches!(definition_required_cross_specializations_in_view(&query,index["cross"]),
                        Err(QueryFailure::Required(Prerequisite::ReadField{owner_id,field:f}))
                        if owner_id==relation && f==field),"{relation}.{field}");
                    assert!(matches!(definition_pending_cross_specializations_in_view(&query,index["cross"]),
                        Err(QueryFailure::Required(Prerequisite::ReadField{owner_id,field:f}))
                        if owner_id==relation && f==field));
                }
                assert_eq!(before,serde_json::to_value(&pending).unwrap());
            }
            pending.iter_mut().find(|e|e.id==relation).unwrap().properties.insert(field.into(),value);
            let index=pending.iter().map(|e|(e.id.as_str(),e)).collect();
            let query=DefinitionNameQuery::new(&pending,&index);
            assert_eq!(definition_required_cross_specializations_in_view(&query,index["cross"]).unwrap(),
                Some(vec![("FeatureTyping","target".into())]));
            for bad in [json!(null),json!(false),json!("absent"),json!("typing")] {
                let mut invalid=graph.clone();
                invalid.iter_mut().find(|e|e.id==relation).unwrap().properties.insert(field.into(),bad);
                let index=invalid.iter().map(|e|(e.id.as_str(),e)).collect();
                let query=DefinitionNameQuery::new(&invalid,&index);
                let before=serde_json::to_value(&invalid).unwrap();
                assert!(matches!(definition_required_cross_specializations_in_view(&query,index["cross"]),
                    Err(QueryFailure::Rejected(_))),"{relation}.{field}");
                assert_eq!(before,serde_json::to_value(&invalid).unwrap());
            }
        }
        for boundary in ["duplicate_graph","missing_parent","nonreciprocal"] {
            let mut invalid=graph.clone();
            match boundary {
                "duplicate_graph"=>invalid.push(invalid[0].clone()),
                "missing_parent"=>{invalid.retain(|e|e.id!="cross.member");},
                _=>{invalid.iter_mut().find(|e|e.id=="cross.member").unwrap().properties.insert("owned_related_element".into(),json!([]));},
            }
            let before=serde_json::to_value(&invalid).unwrap();
            let index=invalid.iter().map(|e|(e.id.as_str(),e)).collect();
            let query=DefinitionNameQuery::new(&invalid,&index);
            assert!(matches!(definition_required_cross_specializations_in_view(&query,index["cross"]),
                Err(QueryFailure::Rejected(_))),"{boundary}");
            assert_eq!(before,serde_json::to_value(&invalid).unwrap());
        }
    }

    #[test]
    fn definition_canonical_reads_share_checked_inputs_across_order_and_persistence() {
        let template=crate::definition_document::parse_and_link(
            "standard library package Base { classifier Anything; feature things; } package P { classifier T; feature x : T; feature y : T; }",crate::SourceLanguage::Kerml).unwrap();
        let mut reversed=template.clone();reversed.elements.reverse();
        let exported=crate::abstract_syntax_json::export_sysml_abstract_syntax_value(&template,Default::default()).unwrap();
        assert!(!exported.has_errors());
        let imported=crate::abstract_syntax_json::import_sysml_abstract_syntax_value(exported.value,Default::default()).unwrap();
        let persisted=imported.persistable_document().unwrap();
        for document in [&template,&reversed,&persisted] {
            let graph=&document.elements;
            let before=serde_json::to_value(graph).unwrap();
            let index=graph.iter().map(|e|(e.id.as_str(),e)).collect();
            let events=std::cell::RefCell::new(Vec::new());
            let observer=|e:DefinitionConstructionEvent<'_>|events.borrow_mut().push(e.phase);
            let query=DefinitionNameQuery::observed(graph,&index,&observer);
            let mut projection_count=0;
            for owner in graph {
                for field in ["owned_relationship","owned_related_element"] {
                    if !ecore_model::feature(&owner.kind,field).is_some_and(|f|f.containment) {continue;}
                    projection_count+=1;
                    let expected=stored_children_indexed(&index,owner,field).unwrap();
                    for _ in 0..2 {
                        assert_eq!(stored_children_projection_query(&query,owner,field).unwrap().iter().map(|e|&e.id).collect::<Vec<_>>(),
                            expected.iter().map(|e|&e.id).collect::<Vec<_>>());
                    }
                }
                let expected=scope_container(&index,owner).unwrap().map(|e|&e.id);
                for _ in 0..2 {assert_eq!(scope_container_query(&query,owner).unwrap().map(|e|&e.id),expected);}
            }
            let phases=events.borrow();
            assert_eq!(phases.iter().filter(|p|**p==DefinitionConstructionPhase::ContainmentReadStarted).count(),projection_count);
            assert_eq!(phases.iter().filter(|p|**p==DefinitionConstructionPhase::ContainmentCacheHit).count(),projection_count);
            assert_eq!(phases.iter().filter(|p|**p==DefinitionConstructionPhase::ContainerReadStarted).count(),graph.len());
            assert!(phases.iter().filter(|p|**p==DefinitionConstructionPhase::ContainerCacheHit).count()>=graph.len());
            assert_eq!(before,serde_json::to_value(graph).unwrap());
        }
    }

    #[test]
    fn definition_canonical_reads_do_not_hide_rejections_foreign_owners_or_pending_fields() {
        let template=crate::definition_document::parse_and_link(
            "standard library package Base { classifier Anything; feature things; } package P { classifier T; feature x : T; feature y : T; }",crate::SourceLanguage::Kerml).unwrap();
        let owner=template.elements.iter().find(|e|e.properties.get("declared_name")==Some(&json!("x"))).unwrap();
        let owner_id=owner.id.clone();
        let relation_id=stored_children(&template.elements,owner,"owned_relationship").unwrap()[0].id.clone();
        for boundary in ["malformed","duplicate_child","missing_child","wrong_child","nonreciprocal","conflicting_container","duplicate_graph"] {
            let mut graph=template.elements.clone();
            let position=graph.iter().position(|e|e.id==owner_id).unwrap();
            match boundary {
                "malformed"=>{graph[position].properties.insert("owned_relationship".into(),json!(false));},
                "duplicate_child"=>{graph[position].properties.insert("owned_relationship".into(),json!([relation_id,relation_id]));},
                "missing_child"=>{graph.retain(|e|e.id!=relation_id);},
                "wrong_child"=>{graph[position].properties.insert("owned_relationship".into(),json!([owner_id]));},
                "nonreciprocal"=>{graph.iter_mut().find(|e|e.id==relation_id).unwrap().properties.remove("owning_related_element");},
                "conflicting_container"=>{graph.iter_mut().find(|e|e.id==relation_id).unwrap().properties.insert("owning_relationship".into(),json!(owner_id));},
                "duplicate_graph"=>{graph.push(graph[position].clone());},
                _=>unreachable!(),
            }
            let before=serde_json::to_value(&graph).unwrap();
            {
                let index=graph.iter().map(|e|(e.id.as_str(),e)).collect();
                let query=DefinitionNameQuery::new(&graph,&index);
                for _ in 0..2 {
                    assert!(stored_children_projection_query(&query,index[owner_id.as_str()],"owned_relationship").is_err(),"{boundary}");
                    assert!(!query.containments.borrow().contains_key(owner_id.as_str()),"{boundary}");
                }
                assert_eq!(before,serde_json::to_value(&graph).unwrap());
            }
            // Every repair, including duplicate/ownership repair, gets a new view.
            graph=template.elements.clone();
            let index=graph.iter().map(|e|(e.id.as_str(),e)).collect();
            let query=DefinitionNameQuery::new(&graph,&index);
            assert_eq!(stored_children_projection_query(&query,index[owner_id.as_str()],"owned_relationship").unwrap()[0].id,relation_id);
        }
        let index=template.elements.iter().map(|e|(e.id.as_str(),e)).collect();
        let query=DefinitionNameQuery::new(&template.elements,&index);
        let canonical=index[owner_id.as_str()];
        assert!(!stored_children_projection_query(&query,canonical,"owned_relationship").unwrap().is_empty());
        let mut foreign=canonical.clone();
        foreign.properties.insert("owned_relationship".into(),json!([]));
        assert!(stored_children_projection_query(&query,&foreign,"owned_relationship").unwrap().is_empty());
        foreign.properties.insert("owned_relationship".into(),json!(false));
        assert!(stored_children_projection_query(&query,&foreign,"owned_relationship").is_err());
        assert!(!stored_children_projection_query(&query,canonical,"owned_relationship").unwrap().is_empty());

        let mut changed=template.elements.clone();
        let typing=changed.iter_mut().find(|e|e.id==relation_id).unwrap();
        let endpoint=typing.properties.remove("type").unwrap();
        {
            let index=changed.iter().map(|e|(e.id.as_str(),e)).collect();
            let query=DefinitionNameQuery::new(&changed,&index);
            stored_children_projection_query(&query,index[owner_id.as_str()],"owned_relationship").unwrap();
            for _ in 0..2 {
                assert!(matches!(definition_feature_types_in_view(&query,index[owner_id.as_str()]),
                    Err(QueryFailure::Required(Prerequisite::ReadField{owner_id,field})) if owner_id==relation_id && field=="type"));
            }
        }
        changed.iter_mut().find(|e|e.id==relation_id).unwrap().properties.insert("type".into(),endpoint);
        let index=changed.iter().map(|e|(e.id.as_str(),e)).collect();
        let query=DefinitionNameQuery::new(&changed,&index);
        assert_eq!(definition_feature_types_in_view(&query,index[owner_id.as_str()]).unwrap().len(),1);
    }

    #[test]
    fn definition_link_commit_events_require_checked_writes_and_do_not_imply_publication() {
        for valid in [false,true] {
            let text=if valid {"standard library package Base { classifier Anything; feature things; } package P { classifier T; feature x : T; feature y : T; }"}
                else {"package P { classifier T; feature x : T; feature y : Missing; }"};
            let sources=[crate::definition_document::DefinitionSource{uri:"memory:/link-controls.kerml",text,language:crate::SourceLanguage::Kerml}];
            let events=std::cell::RefCell::new(Vec::new());
            let result=crate::definition_document::parse_and_link_sources_traced(&sources,|_,_|{},|event|{
                events.borrow_mut().push((event.phase,event.owner_id.to_owned(),event.field.map(str::to_owned),event.succeeded));
            });
            let observed=events.borrow();
            let committed=observed.iter().filter(|e|e.0==DefinitionConstructionPhase::LinkFieldCommitted).collect::<Vec<_>>();
            assert!(!committed.is_empty());
            let keys=committed.iter().map(|e|(&e.1,&e.2)).collect::<BTreeSet<_>>();
            assert_eq!(keys.len(),committed.len(),"one checked write per pending field");
            for event in &committed {
                assert_eq!(event.3,Some(true));
                assert!(observed.iter().any(|e|e.0==DefinitionConstructionPhase::LinkFieldStarted && e.1==event.1 && e.2==event.2));
            }
            if valid {
                let document=result.unwrap();
                for event in committed {
                    let owner=document.elements.iter().find(|e|e.id==event.1).unwrap();
                    assert!(owner.properties.contains_key(event.2.as_deref().unwrap()));
                }
                assert!(observed.iter().any(|e|e.0==DefinitionConstructionPhase::PublicationFinished && e.3==Some(true)));
            } else {
                assert!(result.is_err());
                assert!(!observed.iter().any(|e|e.0==DefinitionConstructionPhase::PublicationFinished && e.3==Some(true)));
            }
        }
    }

    #[test]
    fn definition_shared_default_views_reuse_imported_inputs_across_features_and_persistence() {
        let template=crate::definition_document::parse_and_link(
            "standard library package Base { classifier Anything; feature things; feature dataValues; } package P { datatype D; feature x : D; feature y : D; }",
            crate::SourceLanguage::Kerml).unwrap();
        let exported=crate::abstract_syntax_json::export_sysml_abstract_syntax_value(&template,Default::default()).unwrap();
        let loaded=crate::abstract_syntax_json::import_sysml_abstract_syntax_value(exported.value,Default::default()).unwrap().persistable_document().unwrap();
        let mut reversed=template.clone();reversed.elements.reverse();
        for document in [&template,&reversed,&loaded] {
            let before=serde_json::to_value(&document.elements).unwrap();
            let index=document.elements.iter().map(|e|(e.id.as_str(),e)).collect();
            let query=DefinitionNameQuery::new(&document.elements,&index);
            let named=|name:&str|document.elements.iter().find(|e|e.properties.get("declared_name")==Some(&json!(name))).unwrap();
            let expected=named("dataValues").id.clone();
            for name in ["x","y"] {
                let owner=named(name);
                assert_eq!(definition_feature_default_name_in_view(&query,owner).unwrap(),"Base::dataValues");
                for excluded in ["","first-unrelated","second-unrelated"] {
                    for _ in 0..2 {
                        let generals=definition_general_type_inputs_with_view(&query,owner,excluded).unwrap();
                        assert!(generals.contains(&expected));
                        assert!(query.standard_paths.borrow().contains_key("Base::dataValues"));
                        assert_eq!(definition_feature_types_in_view(&query,owner).unwrap().iter().map(|e|&e.id).collect::<Vec<_>>(),[&named("D").id]);
                    }
                }
            }
            assert_eq!(query.standard_paths.borrow().get("Base::dataValues"),Some(&expected));
            assert_eq!(before,serde_json::to_value(&document.elements).unwrap());
            assert!(document.elements.iter().all(|e|!scope_boolean(e,"is_implied_included").unwrap()));
        }
    }

    #[test]
    fn definition_shared_default_views_keep_cached_paths_separate_from_missing_and_invalid_fields() {
        let template=crate::definition_document::parse_and_link(
            "standard library package Base { classifier Anything; feature things; feature dataValues; } package P { datatype D; feature x : D; feature y : D; }",
            crate::SourceLanguage::Kerml).unwrap();
        let named=|name:&str|template.elements.iter().find(|e|e.properties.get("declared_name")==Some(&json!(name))).unwrap();
        let owner_id=named("y").id.clone();let ready_id=named("x").id.clone();
        let typing=stored_children(&template.elements,named("y"),"owned_relationship").unwrap().into_iter().find(|e|metaclass_conforms(&e.kind,"FeatureTyping")).unwrap().id.clone();
        let saved_type=template.elements.iter().find(|e|e.id==typing).unwrap().properties["type"].clone();
        for boundary in ["missing","wrong_target","broken_ownership","duplicate_graph"] {
            let mut graph=template.elements.clone();
            if boundary=="missing" {graph.iter_mut().find(|e|e.id==typing).unwrap().properties.remove("type");}
            if boundary=="wrong_target" {graph.iter_mut().find(|e|e.id==typing).unwrap().properties.insert("type".into(),json!(named("P").id));}
            if boundary=="broken_ownership" {graph.iter_mut().find(|e|e.id==typing).unwrap().properties.remove("owning_related_element");}
            if boundary=="duplicate_graph" {graph.push(graph.iter().find(|e|e.id==typing).unwrap().clone());}
            {
                let index=graph.iter().map(|e|(e.id.as_str(),e)).collect();
                let query=DefinitionNameQuery::new(&graph,&index);
                if boundary!="duplicate_graph" {
                    let ready=index[ready_id.as_str()];
                    definition_general_type_inputs_with_view(&query,ready,"").unwrap();
                    assert!(query.standard_paths.borrow().contains_key("Base::dataValues"));
                }
                for _ in 0..2 {
                    let failure=definition_feature_default_name_in_view(&query,index[owner_id.as_str()]).unwrap_err();
                    if boundary=="missing" {assert!(matches!(failure,QueryFailure::Required(Prerequisite::ReadField{owner_id,field}) if owner_id==typing && field=="type"));}
                    else {assert!(matches!(failure,QueryFailure::Rejected(_)),"{boundary}: {failure:?}");}
                    assert!(!query.general_types.borrow().contains_key(&(owner_id.clone(),"".into())));
                }
            }
            // Each repaired graph owns a fresh view. A previous cached library
            // identity never replaces the actual typed/ownership input checks.
            if boundary=="missing" || boundary=="wrong_target" {
                graph.iter_mut().find(|e|e.id==typing).unwrap().properties.insert("type".into(),saved_type.clone());
            } else {graph=template.elements.clone();}
            let index=graph.iter().map(|e|(e.id.as_str(),e)).collect();
            let query=DefinitionNameQuery::new(&graph,&index);
            assert_eq!(definition_feature_default_name_in_view(&query,index[owner_id.as_str()]).unwrap(),"Base::dataValues");
        }
    }

    #[test]
    fn definition_shared_semantic_views_preserve_literal_projection_and_persistence() {
        for default in [false,true] {
            let template=literal_value_binding_fixture(default);
            let saved=crate::abstract_syntax_json::export_sysml_abstract_syntax_value(&template,Default::default()).unwrap();
            assert!(!saved.has_errors());
            let loaded=crate::abstract_syntax_json::import_sysml_abstract_syntax_value(saved.value,Default::default()).unwrap();
            let persisted=loaded.persistable_document().unwrap();
            let mut reversed=template.clone();reversed.elements.reverse();
            for document in [&template,&reversed,&persisted] {
                let before=serde_json::to_value(&document.elements).unwrap();
                let index=document.elements.iter().map(|e|(e.id.as_str(),e)).collect();
                let events=std::cell::RefCell::new(Vec::new());
                let observer=|event:DefinitionConstructionEvent<'_>|events.borrow_mut().push(event.phase);
                let query=DefinitionNameQuery::observed(&document.elements,&index,&observer);
                for id in cold_literal_ids(document) {
                    let expression=index[id.as_str()];
                    let ids=|nodes:Vec<&KirElement>|nodes.into_iter().map(|e|e.id.clone()).collect::<Vec<_>>();
                    let expected=ids(definition_feature_types_query(&document.elements,expression).unwrap());
                    assert_eq!(ids(definition_feature_types_in_view(&query,expression).unwrap()),expected);
                    assert_eq!(ids(definition_reference_targets_typed_query(&query,expression,"type").unwrap()),expected);
                    assert_eq!(ids(definition_featuring_types_in_view(&query,expression).unwrap()),ids(definition_featuring_types_typed_query(&document.elements,expression).unwrap()));
                    let result=definition_result_parameter_typed_query(&query,expression).unwrap().unwrap();
                    assert_eq!(result.id,definition_result_parameter(&document.elements,expression).unwrap().unwrap().id);
                    for target in definition_feature_types_in_view(&query,expression).unwrap() {
                        assert_eq!(definition_specializes_depth_in_view(&query,target,target,0).unwrap(),definition_specializes_depth_query(&document.elements,target,target,0).unwrap());
                    }
                }
                assert!(events.borrow().contains(&DefinitionConstructionPhase::GeneralTypesCacheHit));
                assert_eq!(before,serde_json::to_value(&document.elements).unwrap());
            }
        }
    }

    #[test]
    fn definition_shared_semantic_views_retain_exact_type_prerequisites_and_edits() {
        let template=literal_value_binding_fixture(false);
        let id=cold_literal_ids(&template)[0].clone();
        let mut graph=template.elements.clone();
        let expression=graph.iter().find(|e|e.id==id).unwrap();
        let result=definition_result_parameter(&graph,expression).unwrap().unwrap();
        let typing=stored_children(&graph,result,"owned_relationship").unwrap().into_iter().find(|e|metaclass_conforms(&e.kind,"FeatureTyping")).unwrap().id.clone();
        let endpoint=graph.iter_mut().find(|e|e.id==typing).unwrap().properties.remove("type").unwrap();
        for invalid in [None,Some(json!(false))] {
            let mut model=graph.clone();
            if let Some(value)=&invalid {model.iter_mut().find(|e|e.id==typing).unwrap().properties.insert("type".into(),value.clone());}
            let before=serde_json::to_value(&model).unwrap();
            let index=model.iter().map(|e|(e.id.as_str(),e)).collect();
            let query=DefinitionNameQuery::new(&model,&index);
            let expression=index[id.as_str()];
            let result=definition_result_parameter_typed_query(&query,expression).unwrap().unwrap();
            for _ in 0..2 {
                let failure=definition_reference_targets_typed_query(&query,result,"type").unwrap_err();
                if invalid.is_none() {
                    assert!(matches!(failure,QueryFailure::Required(Prerequisite::ReadField {owner_id,field}) if owner_id==typing && field=="type"));
                } else {assert!(matches!(failure,QueryFailure::Rejected(_)));}
            }
            assert_eq!(before,serde_json::to_value(&model).unwrap());
        }
        graph.iter_mut().find(|e|e.id==typing).unwrap().properties.insert("type".into(),endpoint.clone());
        let index=graph.iter().map(|e|(e.id.as_str(),e)).collect();
        let query=DefinitionNameQuery::new(&graph,&index);
        let result=definition_result_parameter_typed_query(&query,index[id.as_str()]).unwrap().unwrap();
        let expected=endpoint.as_str().unwrap();
        assert!(definition_reference_targets_typed_query(&query,result,"type").unwrap().iter().any(|e|e.id==expected));
        let mut duplicate=graph.clone();duplicate.push(graph[0].clone());
        assert!(definition_feature_types_query(&duplicate,&duplicate[0]).is_err());
    }

    #[test]
    fn definition_literal_producer_source_pipeline_integrates_all_leaf_classes_and_persistence() {
        for default in [false,true] {
            let source=literal_value_binding_source(default);
            let sources=[crate::definition_document::DefinitionSource {uri:"memory:/literal-batch.kerml",text:&source,language:crate::SourceLanguage::Kerml}];
            let original=crate::definition_document::parse_and_link_sources(&sources).unwrap();
            let document=crate::definition_document::parse_and_link_sources_with_literal_value_bindings(&sources,&[sources[0].uri]).unwrap();
            let ids=cold_literal_ids(&document);assert_eq!(ids.len(),6);
            assert_eq!(document.metadata["semantic_validation"],json!("not_assessed"));
            assert_eq!(document.metadata["literal_value_binding_sources"],json!([sources[0].uri]));
            assert!(ecore_model::validate_publication(&document.elements,ecore_model::ReferenceCompleteness::Closed).is_empty());
            let exported=crate::abstract_syntax_json::export_sysml_abstract_syntax_value(&document,Default::default()).unwrap();assert!(!exported.has_errors());
            let imported=crate::abstract_syntax_json::import_sysml_abstract_syntax_value(exported.value,Default::default()).unwrap();assert!(!imported.has_errors());
            let persisted=imported.persistable_document().unwrap();
            for model in [&document,&persisted] {
                for id in &ids {
                    let expression=model.elements.iter().find(|e|e.id==*id).unwrap();
                    assert!(scope_boolean(expression,"is_implied_included").unwrap());
                    let result=definition_result_parameter(&model.elements,expression).unwrap().unwrap();
                    assert!(!scope_boolean(result,"is_implied_included").unwrap());
                    let owner=definition_value_expression_owner(&model.elements,expression).unwrap();
                    assert!(!scope_boolean(owner,"is_implied_included").unwrap());
                    let bindings=stored_children(&model.elements,owner,"owned_relationship").unwrap().into_iter()
                        .filter(|r|literal_value_binding::binding_contribution(&model.elements,owner,r).unwrap()).collect::<Vec<_>>();
                    assert_eq!(bindings.len(),usize::from(!default));
                    if default {continue;}
                    let binding=stored_children(&model.elements,bindings[0],"owned_related_element").unwrap()[0];
                    let chain=definition_reference_targets(&model.elements,binding,"source").unwrap()[0];
                    assert_eq!(definition_reference_targets(&model.elements,chain,"chaining_feature").unwrap().iter().map(|e|e.id.as_str()).collect::<Vec<_>>(),[expression.id.as_str(),result.id.as_str()]);
                    assert_eq!(definition_feature_types(&model.elements,chain).unwrap().iter().map(|e|e.id.as_str()).collect::<Vec<_>>(),definition_feature_types(&model.elements,result).unwrap().iter().map(|e|e.id.as_str()).collect::<Vec<_>>());
                }
            }
            for node in &original.elements {
                if ids.contains(&node.id) {continue;}
                let actual=document.elements.iter().find(|e|e.id==node.id).unwrap();
                assert_eq!(actual.properties.get("is_implied_included"),node.properties.get("is_implied_included"),"unselected lifecycle {}",node.id);
            }
        }
    }

    #[test]
    fn definition_literal_producer_scheduler_resolves_registered_fields_atomically() {
        let template=literal_value_binding_fixture(false);
        let receiver=cold_literal_ids(&template).into_iter().find(|id|template.elements.iter().find(|e|e.id==*id).unwrap().kind.ends_with("::LiteralInteger")).unwrap();
        let expression=template.elements.iter().find(|e|e.id==receiver).unwrap();
        let owner=definition_value_expression_owner(&template.elements,expression).unwrap();
        let receiver_typing=stored_children(&template.elements,owner,"owned_relationship").unwrap().into_iter().find(|e|metaclass_conforms(&e.kind,"FeatureTyping")).unwrap().id.clone();
        let result=definition_result_parameter(&template.elements,expression).unwrap().unwrap();
        let result_typing=stored_children(&template.elements,result,"owned_relationship").unwrap().into_iter().find(|e|metaclass_conforms(&e.kind,"FeatureTyping")).unwrap().id.clone();
        for typing_id in [&receiver_typing,&result_typing] {
            for boundary in ["success","unregistered","cycle","wrong_type","late_failure"] {
                let mut graph=template.elements.clone();
                let type_id=graph.iter_mut().find(|e|e.id==*typing_id).unwrap().properties.remove("type").unwrap().as_str().unwrap().to_owned();
                graph.push(fresh_definition_element("later.request".into(),"Membership").unwrap());
                let namespace=graph.iter().find(|e|e.kind.ends_with("::Package")).unwrap().id.clone();
                relative_fixture_attach(&mut graph,&namespace,"later.request",true);
                let source=[crate::xtext_fragment::PendingReference {span:None,spelling:"ScalarValues::Integer".into(),target_type:"https://www.omg.org/spec/SysML/20250201#//Type".into()}];
                let later=[crate::xtext_fragment::PendingReference {span:None,spelling:"result".into(),target_type:"https://www.omg.org/spec/SysML/20250201#//Feature".into()}];
                let mut pending=Vec::new();
                if boundary!="unregistered" {pending.push(PendingModelLink {owner_id:typing_id.clone(),owner_kind:"SysML::FeatureTyping".into(),feature:ecore_model::feature("FeatureTyping","type").unwrap(),references:&source,ancestors:vec![]});}
                pending.push(PendingModelLink {owner_id:"later.request".into(),owner_kind:"SysML::Membership".into(),feature:ecore_model::feature("Membership","member_element").unwrap(),references:&later,ancestors:vec![]});
                let before=serde_json::to_value(&graph).unwrap();
                let calls=std::cell::RefCell::new(Vec::new());
                let events=std::cell::RefCell::new(Vec::new());
                let answer=link_generated_graph_with_literal_jobs(graph.clone(),pending,&|site| {
                    calls.borrow_mut().push(site.owner_id.to_owned());
                    if site.owner_id==*typing_id {
                        if boundary=="cycle" {return Ok(GeneratedLinkTarget::Deferred {owner_id:typing_id.clone(),field:"type".into()});}
                        return Ok(GeneratedLinkTarget::Local(if boundary=="wrong_type" {"later.request".into()}else{type_id.clone()}));
                    }
                    if boundary=="late_failure" {return Err(error("explicit later source rejection"));}
                    Ok(GeneratedLinkTarget::Local(receiver.clone()))
                },true,&[receiver.clone()],&|event|events.borrow_mut().push((event.phase,event.owner_id.to_owned(),event.field.map(str::to_owned),event.succeeded)));
                let events=events.borrow();
                assert!(events.iter().any(|(phase,id,field,_)| *phase==DefinitionConstructionPhase::LiteralPrerequisite && id==typing_id && field.as_deref()==Some("type")),"exact typed dependency trace {typing_id}/{boundary}");
                assert!(events.iter().any(|(phase,id,field,success)| *phase==DefinitionConstructionPhase::LiteralStageFinished && id==&receiver && field.is_some() && *success==Some(false)));
                if matches!(boundary,"success"|"late_failure") {
                    assert!(events.iter().any(|(phase,id,_,success)| *phase==DefinitionConstructionPhase::LiteralProducerFinished && id==&receiver && *success==Some(true)));
                    assert!(events.iter().any(|(phase,_,field,success)| *phase==DefinitionConstructionPhase::LiteralStageFinished && field.as_deref()==Some("binding_lifecycle") && *success==Some(true)));
                } else {
                    assert!(!events.iter().any(|(phase,_,_,success)| *phase==DefinitionConstructionPhase::LiteralProducerFinished && *success==Some(true)));
                }
                assert_eq!(before,serde_json::to_value(&graph).unwrap(),"{typing_id}/{boundary}: supplied graph unchanged");
                if boundary=="success" {
                    let graph=answer.unwrap();
                    assert_eq!(*calls.borrow(),[typing_id.clone(),"later.request".into()]);
                    assert!(scope_boolean(graph.iter().find(|e|e.id==receiver).unwrap(),"is_implied_included").unwrap());
                    assert_eq!(graph.iter().find(|e|e.id==*typing_id).unwrap().properties["type"],json!(type_id));
                    assert!(ecore_model::validate_publication(&graph,ecore_model::ReferenceCompleteness::Closed).is_empty());
                } else {
                    let failure=answer.unwrap_err();
                    let expected=match boundary {"unregistered"=>"not pending","cycle"=>"dependency cycle","wrong_type"=>"violates Xtext target type",_=>"explicit later source rejection"};
                    assert!(failure.message.contains(expected),"{typing_id}/{boundary}: {failure:?}");
                }
            }
        }
    }

    #[test]
    fn definition_literal_scheduler_batches_generalizations_without_false_cycles() {
        for default in [false,true] {
            let template=literal_value_binding_fixture(default);
            let saved=crate::abstract_syntax_json::export_sysml_abstract_syntax_value(&template,Default::default()).unwrap();
            let loaded=crate::abstract_syntax_json::import_sysml_abstract_syntax_value(saved.value,Default::default()).unwrap().persistable_document().unwrap();
            let mut reversed=template.clone();reversed.elements.reverse();
            for document in [&template,&reversed,&loaded] {
                let index=document.elements.iter().map(|e|(e.id.as_str(),e)).collect();
                let query=DefinitionNameQuery::new(&document.elements,&index);
                let role_id=query_local_binding(standard_default_binding_query(&query,"Performances::literalIntegerEvaluations").unwrap()).unwrap();
                let relationships=stored_children(&document.elements,index[role_id.as_str()],"owned_relationship").unwrap();
                let typed=relationships.iter().find(|e|metaclass_conforms(&e.kind,"FeatureTyping")).unwrap().id.clone();
                let subset=relationships.iter().find(|e|e.kind.rsplit("::").next()==Some("Subsetting")).unwrap().id.clone();
                let receiver=cold_literal_ids(document).into_iter().find(|id|index[id.as_str()].kind.ends_with("::LiteralInteger")).unwrap();
                for mode in ["success","dependent","cycle","unregistered","wrong_target","late_failure"] {
                    let mut graph=document.elements.clone();
                    let type_id=graph.iter_mut().find(|e|e.id==typed).unwrap().properties.remove("type").unwrap().as_str().unwrap().to_owned();
                    let subset_id=graph.iter_mut().find(|e|e.id==subset).unwrap().properties.remove("subsetted_feature").unwrap().as_str().unwrap().to_owned();
                    let namespace=graph.iter().find(|e|e.kind.ends_with("::LibraryPackage")).unwrap().id.clone();
                    graph.push(fresh_definition_element("late.request".into(),"Membership").unwrap());relative_fixture_attach(&mut graph,&namespace,"late.request",true);
                    let type_ref=[crate::xtext_fragment::PendingReference {span:None,spelling:"prototype".into(),target_type:"https://www.omg.org/spec/SysML/20250201#//Type".into()}];
                    let subset_ref=[crate::xtext_fragment::PendingReference {span:None,spelling:"general".into(),target_type:"https://www.omg.org/spec/SysML/20250201#//Feature".into()}];
                    let mut pending=vec![PendingModelLink {owner_id:typed.clone(),owner_kind:"SysML::FeatureTyping".into(),feature:ecore_model::feature("FeatureTyping","type").unwrap(),references:&type_ref,ancestors:vec![]}];
                    if mode!="unregistered" {pending.push(PendingModelLink {owner_id:subset.clone(),owner_kind:"SysML::Subsetting".into(),feature:ecore_model::feature("Subsetting","subsetted_feature").unwrap(),references:&subset_ref,ancestors:vec![]});}
                    pending.push(PendingModelLink {owner_id:"late.request".into(),owner_kind:"SysML::Membership".into(),feature:ecore_model::feature("Membership","member_element").unwrap(),references:&subset_ref,ancestors:vec![]});
                    let before=serde_json::to_value(&graph).unwrap();let calls=std::cell::RefCell::new(Vec::new());let events=std::cell::RefCell::new(Vec::new());
                    let outcome=link_generated_graph_with_literal_jobs(graph.clone(),pending,&|site| {
                        calls.borrow_mut().push(site.owner_id.to_owned());
                        if site.owner_id==typed {
                            if matches!(mode,"dependent"|"cycle") && !site.graph.iter().find(|e|e.id==subset).unwrap().properties.contains_key("subsetted_feature") {
                                return Ok(GeneratedLinkTarget::Deferred {owner_id:subset.clone(),field:"subsetted_feature".into()});
                            }
                            return Ok(GeneratedLinkTarget::Local(type_id.clone()));
                        }
                        if site.owner_id==subset {
                            if mode=="cycle" {return Ok(GeneratedLinkTarget::Deferred {owner_id:typed.clone(),field:"type".into()});}
                            return Ok(GeneratedLinkTarget::Local(if mode=="wrong_target" {namespace.clone()} else {subset_id.clone()}));
                        }
                        if mode=="late_failure" {return Err(error("explicit failure after complete batched producer"));}
                        Ok(GeneratedLinkTarget::Local(receiver.clone()))
                    },true,&[receiver.clone()],&|event|events.borrow_mut().push((event.phase,event.owner_id.to_owned(),event.field.map(str::to_owned),event.succeeded)));
                    assert_eq!(before,serde_json::to_value(&graph).unwrap(),"supplied graph {mode}");
                    let events=events.borrow();
                    for (id,field) in [(&typed,"type"),(&subset,"subsetted_feature")] {
                        assert!(events.iter().any(|(phase,owner,name,_)|*phase==DefinitionConstructionPhase::GeneralizationPrerequisite && owner==id && name.as_deref()==Some(field)),"observed exact {mode}/{id}.{field}");
                        assert!(events.iter().any(|(phase,owner,name,_)|*phase==DefinitionConstructionPhase::LiteralPrerequisite && owner==id && name.as_deref()==Some(field)),"scheduled exact {mode}/{id}.{field}");
                    }
                    if matches!(mode,"success"|"dependent"|"late_failure") {
                        assert_eq!(events.iter().filter(|(phase,_,_,_)|*phase==DefinitionConstructionPhase::LiteralProducerStarted).count(),2,"one retry after whole declared batch {mode}");
                        assert_eq!(events.iter().filter(|(phase,_,_,success)|*phase==DefinitionConstructionPhase::LiteralProducerFinished && *success==Some(true)).count(),1);
                    }
                    if matches!(mode,"success"|"dependent") {
                        let linked=outcome.unwrap();assert!(ecore_model::validate_publication(&linked,ecore_model::ReferenceCompleteness::Closed).is_empty());
                        assert_eq!(linked.iter().find(|e|e.id==typed).unwrap().properties["type"],json!(type_id));
                        assert_eq!(linked.iter().find(|e|e.id==subset).unwrap().properties["subsetted_feature"],json!(subset_id));
                        if mode=="success" {assert_eq!(*calls.borrow(),[typed.clone(),subset.clone(),"late.request".into()]);}
                        else {assert_eq!(*calls.borrow(),[typed.clone(),subset.clone(),typed.clone(),"late.request".into()]);}
                    } else {
                        let failure=outcome.unwrap_err();let expected=match mode {"cycle"=>"dependency cycle","unregistered"=>"not pending","wrong_target"=>"violates Xtext target type",_=>"explicit failure after complete batched producer"};
                        assert!(failure.message.contains(expected),"{mode}: {failure:?}");
                    }
                }
            }
        }
    }

    #[test]
    fn definition_generalization_prerequisites_preserve_aliases_and_consumer_scope() {
        let mut owner=fresh_definition_element("owner".into(),"Classifier").unwrap();let mut graph=Vec::new();
        for (id,kind,specific) in [("subclass","Subclassification","subclassifier"),("conjugation","Conjugation","conjugated_type")] {
            let mut relation=fresh_definition_element(id.into(),kind).unwrap();relation.properties.insert(specific.into(),json!("owner"));
            ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,&mut owner,&mut relation).unwrap();graph.push(relation);
        }
        graph.push(owner);let index=graph.iter().map(|e|(e.id.as_str(),e)).collect();let events=std::cell::RefCell::new(Vec::new());
        let observer=|event:DefinitionConstructionEvent<'_>|if event.phase==DefinitionConstructionPhase::GeneralizationPrerequisite {events.borrow_mut().push((event.owner_id.to_owned(),event.field.unwrap().to_owned()));};
        let query=DefinitionNameQuery::observed(&graph,&index,&observer);
        assert!(matches!(definition_general_type_inputs_with_view(&query,index["owner"],""),Err(QueryFailure::Required(Prerequisite::ReadField {owner_id,field})) if owner_id=="subclass" && field=="superclassifier"));
        assert_eq!(*events.borrow(),[("subclass".into(),"superclassifier".into()),("conjugation".into(),"original_type".into())]);
        assert_eq!(literal_prerequisite_batch(&graph,("subclass".into(),"superclassifier".into()),&events.borrow()),*events.borrow());
        assert_eq!(literal_prerequisite_batch(&graph,("unobserved".into(),"type".into()),&events.borrow()),[("unobserved".into(),"type".into())]);
        let mut other=fresh_definition_element("other".into(),"Classifier").unwrap();let mut relation=fresh_definition_element("other.general".into(),"Subclassification").unwrap();relation.properties.insert("subclassifier".into(),json!("other"));
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,&mut other,&mut relation).unwrap();
        let mut changed=graph.clone();changed.extend([other,relation]);let mut observed=events.borrow().clone();observed.push(("other.general".into(),"superclassifier".into()));
        assert_eq!(literal_prerequisite_batch(&changed,("subclass".into(),"superclassifier".into()),&observed),*events.borrow());
        assert!(graph.iter().all(|e|!scope_boolean(e,"is_implied_included").unwrap()));
    }


    #[test]
    fn definition_value_result_read_plan_preserves_typed_pending_and_rejection() {
        let requirements = [
            Prerequisite::ReadField {owner_id: "typing".into(), field: "type".into()},
            Prerequisite::AdditionalMembers {owner_id: "expression".into()},
            Prerequisite::BinaryCrossing {owner_id: "end".into()},
            Prerequisite::CrossSpecialization {owner_id: "feature".into()},
            Prerequisite::ReferenceResultSubsetting {owner_id: "reference".into()},
            Prerequisite::ChainSpecialization {owner_id: "chain".into()},
            Prerequisite::ExpressionContributions {owner_id: "expression-defaults".into()},
            Prerequisite::ExpressionContributionBatch {owner_ids: vec!["a".into(),"b".into()]},
        ];
        let mut reads = TransformationReads::default();
        for requirement in requirements.iter().chain(requirements.iter()) {
            assert!(reads.capture::<()>(Err(QueryFailure::Required(requirement.clone()))).is_none());
        }
        let construction = std::cell::Cell::new(false);
        let outcome = reads.finish(|| {construction.set(true); Ok(7)}).unwrap();
        assert!(matches!(outcome, TransformationPlan::Required(actual) if actual == requirements));
        assert!(!construction.get(), "pending read wave cannot authorize construction");
        let mut reads = TransformationReads::default();
        reads.capture::<()>(Err(QueryFailure::Required(requirements[0].clone())));
        reads.capture::<()>(Err(query_failure("malformed independent provider")));
        reads.capture::<()>(Err(query_failure("later rejected provider")));
        assert!(matches!(reads.finish(|| Ok(7)), Err(QueryFailure::Rejected(d)) if d.message.contains("malformed independent provider")));
        let mut reads = TransformationReads::default();
        reads.capture_plan::<()>(Ok(TransformationPlan::Required(Vec::new())));
        assert!(matches!(reads.finish(|| Ok(7)), Err(QueryFailure::Rejected(_))));
        assert!(matches!(TransformationPlan::<()>::Required(Vec::new()).into_query_result(), Err(QueryFailure::Rejected(_))));
        assert_eq!(TransformationPlan::Ready(7).into_query_result().unwrap(), 7);
    }

    #[test]
    fn definition_value_result_read_plan_collects_binding_ports_across_leaf_states() {
        for default in [false, true] {
            let template = literal_value_binding_fixture(default);
            let saved = crate::abstract_syntax_json::export_sysml_abstract_syntax_value(&template, Default::default()).unwrap();
            let restored = crate::abstract_syntax_json::import_sysml_abstract_syntax_value(saved.value, Default::default()).unwrap().persistable_document().unwrap();
            let mut reversed = template.clone(); reversed.elements.reverse();
            for original in [&template, &reversed, &restored] {
                for receiver in cold_literal_ids(original) {
                    let index = original.elements.iter().map(|e| (e.id.as_str(), e)).collect();
                    let query = DefinitionNameQuery::new(&original.elements, &index);
                    let result = definition_result_parameter_typed_query(&query, index[receiver.as_str()]).unwrap().unwrap();
                    let default_name = connector_defaults_generated::default_for("BindingConnector", 2, false).unwrap();
                    let default_id = query_local_binding(standard_default_binding_query(&query, default_name).unwrap()).unwrap();
                    let typing = |owner: &KirElement| stored_children(&original.elements, owner, "owned_relationship").unwrap().into_iter()
                        .find(|e| metaclass_conforms(&e.kind, "FeatureTyping")).unwrap().id.clone();
                    let fields = [typing(index[default_id.as_str()]), typing(result)];
                    assert_ne!(fields[0], fields[1]);
                    let mut graph = original.elements.clone();
                    let values = fields.iter().map(|id| graph.iter_mut().find(|e| e.id == *id).unwrap().properties.remove("type").unwrap()).collect::<Vec<_>>();
                    let before = serde_json::to_value(&graph).unwrap();
                    let events = std::cell::RefCell::new(Vec::new());
                    let observer = |event: DefinitionConstructionEvent<'_>| events.borrow_mut().push((event.phase, event.field.map(str::to_owned)));
                    let outcome = literal_value_binding::complete_query_planned_observed(&mut graph, &[receiver.as_str()], "read-wave",
                        ecore_model::ReferenceCompleteness::Partial, &observer).unwrap();
                    if default {
                        assert!(matches!(outcome, TransformationPlan::Ready(0)), "default skips binding dependency ports");
                    } else {
                        assert!(matches!(outcome, TransformationPlan::Required(actual) if actual == fields.iter()
                            .map(|id| Prerequisite::ReadField {owner_id: id.clone(), field: "type".into()}).collect::<Vec<_>>()));
                        assert_eq!(before, serde_json::to_value(&graph).unwrap(), "no write before independent ports are ready");
                        assert!(!events.borrow().iter().any(|(phase, field)| *phase == DefinitionConstructionPhase::LiteralStageStarted
                            && matches!(field.as_deref(), Some("receiver_defaults" | "binding_chain" | "binding_structure"))));
                        // A pending first port cannot conceal a malformed second
                        // provider or permit scheduling its partial contribution.
                        graph.iter_mut().find(|e| e.id == fields[1]).unwrap().properties.insert("type".into(), json!(false));
                        assert!(matches!(literal_value_binding::complete_query_planned_observed(&mut graph, &[receiver.as_str()], "read-wave",
                            ecore_model::ReferenceCompleteness::Partial, &observer), Err(QueryFailure::Rejected(_))));
                        for (id, value) in fields.iter().zip(values) {
                            graph.iter_mut().find(|e| e.id == *id).unwrap().properties.insert("type".into(), value);
                        }
                        assert!(matches!(literal_value_binding::complete_query_planned_observed(&mut graph, &[receiver.as_str()], "read-wave",
                            ecore_model::ReferenceCompleteness::Closed, &observer).unwrap(), TransformationPlan::Ready(1)));
                        assert!(ecore_model::validate_publication(&graph, ecore_model::ReferenceCompleteness::Closed).is_empty());
                    }
                }
            }
        }
    }




    #[test]
    fn definition_value_result_provider_plan_preserves_work_and_reuses_nested_roots() {
        let tree = crate::xtext_fragment::candidate_document(
            "class A; class B; feature a : A; feature b : B; feature ignored : Missing;", true).unwrap();
        for mode in ["success", "cycle", "late_failure", "bad_wave", "all_fields"] {
            let mut pending = Vec::new();
            let (root, mut graph) = construct_generated_graph(&tree, "model", &[], &mut pending, true).unwrap();
            graph.insert(0, root);
            let before = serde_json::to_value(&graph).unwrap();
            let index = graph.iter().map(|e| (e.id.as_str(), e)).collect();
            let typed = |name| {
                let owner = graph.iter().find(|e|e.properties.get("declared_name")==Some(&json!(name))).unwrap();
                stored_children_indexed(&index, owner, "owned_relationship").unwrap().into_iter()
                    .find(|e|e.kind.ends_with("::FeatureTyping")).unwrap().id.clone()
            };
            let a = typed("a"); let b = typed("b"); let ignored = typed("ignored");
            let roots = vec![Prerequisite::ReadField {owner_id:b.clone(),field:"type".into()},
                Prerequisite::ReadField {owner_id:a.clone(),field:"type".into()}];
            let mut roots = roots;
            if mode=="bad_wave" { roots.push(Prerequisite::ReadField {owner_id:"unregistered".into(),field:"type".into()}); }
            let commits = std::cell::RefCell::new(Vec::new());
            let calls = std::cell::RefCell::new(Vec::new());
            let outcome = link_generated_graph_planned(graph.clone(), pending, &|site| {
                calls.borrow_mut().push(site.owner_id.to_owned());
                let index = site.graph.iter().map(|e| (e.id.as_str(), e)).collect();
                let query = DefinitionNameQuery::new(site.graph, &index);
                if site.owner_id==ignored {return Err(error("unrequested source is unresolved"));}
                if site.owner_id==b {
                    if let Err(failure)=query_reference_in_view(&query,index[a.as_str()],"type") {return query_link_target(failure);}
                    if mode=="late_failure" {return Err(error("late provider-plan failure"));}
                }
                if mode=="cycle" && site.owner_id==a {
                    if let Err(failure)=query_reference_in_view(&query,index[b.as_str()],"type") {return query_link_target(failure);}
                }
                let target=site.graph.iter().find(|e|e.properties.get("declared_name")
                    ==Some(&json!(if site.owner_id==a {"A"}else{"B"}))).unwrap();
                Ok(GeneratedLinkTarget::Local(target.id.clone()))
            }, true, &[], &|event| {
                if event.phase==DefinitionConstructionPhase::LinkFieldCommitted {commits.borrow_mut().push(event.owner_id.to_owned());}
            }, if mode=="all_fields" {None}else{Some(&roots)});
            assert_eq!(before,serde_json::to_value(&graph).unwrap(),"private plan never mutates supplied graph");
            if mode!="success" {
                let message=outcome.err().unwrap().message;
                assert!(message.contains(match mode {"cycle"=>"dependency cycle","late_failure"=>"late provider-plan",
                    "bad_wave"=>"completed read owner is absent",_=>"unrequested source"}),"{mode}: {message}");
                if mode=="bad_wave" {assert!(calls.borrow().is_empty());assert!(commits.borrow().is_empty());}
                continue;
            }
            let (graph,remaining)=outcome.unwrap();
            assert_eq!(*commits.borrow(),vec![a.clone(),b.clone()],"nested root completes once");
            assert_eq!(*calls.borrow(),vec![b.clone(),a.clone(),b.clone()]);
            assert_eq!(remaining.len(),1);assert_eq!(remaining[0].owner_id,ignored);
            assert_eq!(describe_pending_references(&remaining)[0].spelling,"Missing");
            assert_eq!(graph.len(),serde_json::from_value::<Vec<KirElement>>(before).unwrap().len(),"no resource pruning");
            let restored:Vec<KirElement>=serde_json::from_value(serde_json::to_value(&graph).unwrap()).unwrap();
            for model in [&graph,&restored] {
                let index=model.iter().map(|e|(e.id.as_str(),e)).collect();
                let query=DefinitionNameQuery::new(model,&index);
                assert_eq!(query_reference_in_view(&query,index[a.as_str()],"type").unwrap().properties["declared_name"],"A");
                assert_eq!(query_reference_in_view(&query,index[b.as_str()],"type").unwrap().properties["declared_name"],"B");
                assert!(matches!(query_reference_in_view(&query,index[ignored.as_str()],"type"),
                    Err(QueryFailure::Required(Prerequisite::ReadField {owner_id,field})) if owner_id==ignored && field=="type"));
                assert!(model.iter().all(|e|!scope_boolean(e,"is_implied_included").unwrap()));
            }
        }
    }

    #[test]
    fn definition_value_result_provider_plan_runs_constructions_and_validates_whole_wave() {
        let tree=crate::xtext_fragment::candidate_document("feature value = a; feature ignored : Missing;",true).unwrap();
        for mode in ["success","unregistered","missing_owner","empty","unsupported"] {
            let mut pending=Vec::new();
            let (root,mut graph)=construct_generated_graph(&tree,"model",&[],&mut pending,true).unwrap();
            graph.insert(0,root);
            let expression=graph.iter().find(|e|e.kind.ends_with("::FeatureReferenceExpression")).unwrap().id.clone();
            let ignored=graph.iter().find(|e|e.properties.get("declared_name")==Some(&json!("ignored"))).unwrap().id.clone();
            let mut roots=vec![Prerequisite::AdditionalMembers {owner_id:expression.clone()}];
            match mode {
                "unregistered"=>roots.push(Prerequisite::ReadField {owner_id:"absent".into(),field:"type".into()}),
                "missing_owner"=>roots.push(Prerequisite::AdditionalMembers {owner_id:"absent".into()}),
                "empty"=>roots.clear(),
                "unsupported"=>roots=vec![Prerequisite::AdditionalMembers {owner_id:ignored}],
                _=>{},
            }
            let before=serde_json::to_value(&graph).unwrap();
            let outcome=link_generated_graph_planned(graph.clone(),pending,&|_|Err(error("no source read requested")),
                true,&[],&|_|{},Some(&roots));
            assert_eq!(serde_json::to_value(&graph).unwrap(),before);
            if mode!="success" {assert!(outcome.is_err(),"{mode}");continue;}
            let (graph,remaining)=outcome.unwrap();
            assert_eq!(remaining.len(),2,"unrequested referent and typing retain their registry");
            let result=definition_result_parameter(&graph,graph.iter().find(|e|e.id==expression).unwrap()).unwrap().unwrap();
            assert_eq!(result.properties["direction"],"out");
            assert_eq!(graph.len(),serde_json::from_value::<Vec<KirElement>>(before).unwrap().len()+2);
            assert!(graph.iter().all(|e|!scope_boolean(e,"is_implied_included").unwrap()));
        }
    }

    #[test]
    fn definition_value_result_parameter_plan_all_imported_constructors() {
        let artifact: Value = serde_json::from_str(include_str!("../../../../resources/metamodels/sysml-2.0-pilot-2026-08/result-construction.extract.json")).unwrap();
        assert_eq!(artifact["bindings"].as_object().unwrap().len(), 7);
        for kind in artifact["bindings"].as_object().unwrap().keys() {
            for mode in ["success", "late_failure", "fragment", "collision"] {
                let mut graph = vec![fresh_definition_element("root".into(), "Package").unwrap()];
                cross_test_own(&mut graph, "root", "OwningMembership", fresh_definition_element("expression".into(), kind).unwrap());
                let mut probe = fresh_definition_element("probe".into(), "Membership").unwrap();
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, &mut graph[0], &mut probe).unwrap();
                graph.push(probe);
                if mode == "collision" { graph.push(fresh_definition_element("expression.implicit.additional-members.result".into(), "Feature").unwrap()); }
                if mode == "late_failure" {
                    let mut last = fresh_definition_element("last".into(), "Membership").unwrap();
                    ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, &mut graph[0], &mut last).unwrap();
                    graph.push(last);
                }
                let refs = [crate::xtext_fragment::PendingReference {span: None, spelling: "result".into(),
                    target_type: "https://www.omg.org/spec/SysML/20250201#//Feature".into()}];
                let mut pending = vec![PendingModelLink {owner_id: "probe".into(), owner_kind: "Membership".into(),
                    feature: ecore_model::feature("Membership", "member_element").unwrap(), references: &refs, ancestors: vec![]}];
                if mode == "late_failure" { pending.push(PendingModelLink {owner_id: "last".into(), owner_kind: "Membership".into(),
                    feature: ecore_model::feature("Membership", "member_element").unwrap(), references: &refs, ancestors: vec![]}); }
                let before = serde_json::to_value(&graph).unwrap();
                let requests = std::cell::Cell::new(0);
                let outcome = link_generated_graph(graph.clone(), pending, &|site| {
                    if site.owner_id == "last" { return Err(error("late parameter transaction failure")); }
                    let index = site.graph.iter().map(|e| (e.id.as_str(), e)).collect();
                    let query = DefinitionNameQuery::new(site.graph, &index);
                    match definition_result_parameter_typed_query(&query, index["expression"]) {
                        Ok(Some(result)) => Ok(GeneratedLinkTarget::Local(result.id.clone())),
                        Ok(None) => Err(error("result unexpectedly absent")),
                        Err(failure) => { requests.set(requests.get() + 1); query_link_target(failure) }
                    }
                }, mode != "fragment");
                assert_eq!(before, serde_json::to_value(&graph).unwrap(), "{kind} {mode}: supplied state");
                if mode != "success" {
                    let message = outcome.unwrap_err().message;
                    assert!(message.contains(match mode { "late_failure" => "late parameter transaction", "fragment" => "document linker", _ => "fresh distinct" }),
                        "{kind} {mode}: {message}");
                    continue;
                }
                let graph = outcome.unwrap();
                assert_eq!(requests.get(), 1, "{kind}: one actual typed constructor request");
                assert!(ecore_model::validate_publication(&graph, ecore_model::ReferenceCompleteness::Closed).is_empty(), "{kind}");
                let persisted: Vec<KirElement> = serde_json::from_value(serde_json::to_value(&graph).unwrap()).unwrap();
                for model in [&graph, &persisted] {
                    let index = model.iter().map(|e| (e.id.as_str(), e)).collect();
                    let query = DefinitionNameQuery::new(model, &index);
                    let result = definition_result_parameter_typed_query(&query, index["expression"]).unwrap().unwrap();
                    assert_eq!(result.id, index["probe"].properties["member_element"]);
                    assert_eq!(result.properties["direction"], artifact["cases"].as_array().unwrap().iter()
                        .find(|c| c["class"] == *kind && c["context"] == "empty").unwrap()["tree"]["relationships"][0]["elements"][0]["direction"]);
                    let parameters = definition_parameter_collection_typed_query(&query, index["expression"], true).unwrap();
                    assert_eq!(parameters.iter().map(|e| &e.id).collect::<Vec<_>>(), vec![&result.id]);
                    assert_eq!(parameter_members::owned_result(&query, "expression").unwrap().unwrap().id, result.id);
                    assert!(model.iter().all(|e| !scope_boolean(e, "is_implied_included").unwrap()));
                }
            }
        }
    }

    #[test]
    fn definition_value_result_parameter_plan_last_direct_chain_and_read_retry() {
        let mut graph = vec![fresh_definition_element("chain".into(), "Step").unwrap(),
            fresh_definition_element("earlier".into(), "Feature").unwrap(),
            fresh_definition_element("basic".into(), "Step").unwrap(),
            fresh_definition_element("nested".into(), "Step").unwrap()];
        for (id, direction, membership) in [("input", Some("in"), "ParameterMembership"),
            ("ordinary", Some("out"), "FeatureMembership"), ("undirected", None, "ReturnParameterMembership"),
            ("first", Some("out"), "ReturnParameterMembership"), ("second", Some("in"), "ReturnParameterMembership")] {
            let mut feature = fresh_definition_element(id.into(), "Feature").unwrap();
            if let Some(direction) = direction { feature.properties.insert("direction".into(), json!(direction)); }
            cross_test_own(&mut graph, "basic", membership, feature);
        }
        let mut other = fresh_definition_element("nested.result".into(), "Feature").unwrap();
        other.properties.insert("direction".into(), json!("out"));
        cross_test_own(&mut graph, "nested", "ReturnParameterMembership", other);
        for (owner, id, target) in [("chain", "earlier.chain", None),
            ("chain", "last.chain", None), ("basic", "nested.chain", Some("nested"))] {
            let mut relation = fresh_definition_element(id.into(), "FeatureChaining").unwrap();
            if let Some(target) = target { relation.properties.insert("chaining_feature".into(), json!(target)); }
            ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,
                graph.iter_mut().find(|e| e.id == owner).unwrap(), &mut relation).unwrap();
            graph.push(relation);
        }
        // Use raw owned queries: unlike result inheritance they do not invoke
        // the original receiver's added-member stage. Only the last target reads.
        let before = serde_json::to_value(&graph).unwrap();
        let index = graph.iter().map(|e| (e.id.as_str(), e)).collect();
        let query = DefinitionNameQuery::new(&graph, &index);
        assert!(matches!(parameter_members::owned_result(&query, "chain"),
            Err(QueryFailure::Required(Prerequisite::ReadField {owner_id, field}))
                if owner_id == "last.chain" && field == "chaining_feature"));
        assert!(matches!(parameter_members::owned_parameters(&query, index["chain"]),
            Err(QueryFailure::Required(Prerequisite::ReadField {owner_id, field}))
                if owner_id == "last.chain" && field == "chaining_feature"));
        assert_eq!(serde_json::to_value(&graph).unwrap(), before);
        drop(query); drop(index);
        graph.iter_mut().find(|e| e.id == "last.chain").unwrap().properties.insert("chaining_feature".into(), json!("basic"));
        let persisted: Vec<KirElement> = serde_json::from_value(serde_json::to_value(&graph).unwrap()).unwrap();
        for mut model in [graph.clone(), persisted] {
            for reversed in [false, true] {
                if reversed { model.reverse(); }
                let index = model.iter().map(|e| (e.id.as_str(), e)).collect();
                let query = DefinitionNameQuery::new(&model, &index);
                assert_eq!(parameter_members::owned_result(&query, "chain").unwrap().unwrap().id, "first",
                    "normalize once: do not follow basic's own chain to nested.result");
                assert_eq!(parameter_members::owned_parameters(&query, index["chain"]).unwrap().iter().map(|e|e.id.as_str()).collect::<Vec<_>>(),
                    vec!["input", "ordinary", "first", "second"]);
                assert!(definition_parameter_collection_typed_query(&query, index["chain"], false).is_err(),
                    "effective chaining is a separate semantic dependency");
            }
        }
        for defect in ["wrong_target", "missing_target", "duplicate", "broken_inverse"] {
            let mut model = graph.clone();
            match defect {
                "wrong_target" => {
                    model.push(fresh_definition_element("wrong".into(), "Class").unwrap());
                    model.iter_mut().find(|e| e.id == "last.chain").unwrap().properties.insert("chaining_feature".into(), json!("wrong"));
                },
                "missing_target" => { model.iter_mut().find(|e|e.id=="last.chain").unwrap().properties.insert("chaining_feature".into(),json!("absent")); },
                "duplicate" => model.push(model[0].clone()),
                _ => { model.iter_mut().find(|e|e.id=="first.member").unwrap().properties.insert("owning_related_element".into(),json!("nested")); },
            }
            let index = model.iter().map(|e| (e.id.as_str(), e)).collect();
            let query = DefinitionNameQuery::new(&model, &index);
            let before = serde_json::to_value(&model).unwrap();
            assert!(parameter_members::owned_result(&query, "chain").is_err(), "{defect}");
            assert_eq!(serde_json::to_value(model).unwrap(), before);
        }
    }

    #[test]
    fn definition_value_result_construction_plan_wave_and_typed_cycles() {
        let graph = vec![fresh_definition_element("owner".into(), "Feature").unwrap()];
        let before = serde_json::to_value(&graph).unwrap();
        let read = Prerequisite::ReadField {owner_id: "field".into(), field: "type".into()};
        let all = vec![
            read.clone(),
            Prerequisite::AdditionalMembers {owner_id: "owner".into()},
            Prerequisite::BinaryCrossing {owner_id: "owner".into()},
            Prerequisite::CrossSpecialization {owner_id: "owner".into()},
            Prerequisite::ReferenceResultSubsetting {owner_id: "owner".into()},
            Prerequisite::ChainSpecialization {owner_id: "owner".into()},
            Prerequisite::ExpressionContributions {owner_id: "owner".into()},
            Prerequisite::ExpressionContributionBatch {owner_ids: vec!["owner".into()]},
        ];
        let registered = |key: &(String, String)| key == &("field".into(), "type".into());
        let validate = |job: &Prerequisite| validate_transformation_job(job, &graph, &registered, true);
        for root in &all {
            for nested in &all {
                let mut jobs = transformation_jobs::Jobs::default();
                jobs.queue_wave(vec![root.clone(), nested.clone(), root.clone()], &validate).unwrap();
                assert!(jobs.begin_root(&|_| true));
                assert_eq!(jobs.current(), Some(root));
                if nested != root {
                    jobs.require(nested.clone(), &validate).unwrap();
                    assert_eq!(jobs.read_path().len(), usize::from(root == &read) + usize::from(nested == &read));
                }
                let error = jobs.require(root.clone(), &validate).unwrap_err();
                assert!(error.message.contains("dependency cycle"), "{root:?}/{nested:?}");
                if nested != root { jobs.complete().unwrap(); }
                jobs.complete().unwrap();
                assert!(!jobs.begin_root(&|_| true), "completed nested root is reused");
                assert!(!jobs.has_work());
                assert!(jobs.require(root.clone(), &validate).unwrap_err().message.contains("repeated"));
            }
        }
        for mode in ["unregistered", "missing_owner", "fragment", "empty"] {
            let mut jobs = transformation_jobs::Jobs::default();
            let mut wave = all.clone();
            match mode {
                "unregistered" => wave.push(Prerequisite::ReadField {owner_id: "absent".into(), field: "type".into()}),
                "missing_owner" => wave.push(Prerequisite::AdditionalMembers {owner_id: "absent".into()}),
                "empty" => wave.clear(),
                _ => {}
            }
            assert!(jobs.queue_wave(wave, &|job| validate_transformation_job(
                job, &graph, &registered, mode != "fragment")).is_err());
            assert!(!jobs.has_work(), "entire {mode} wave must fail before scheduling");
        }
        assert_eq!(before, serde_json::to_value(&graph).unwrap());
    }

    #[test]
    fn definition_value_result_construction_plan_nested_reference_transaction() {
        let source = "feature a; feature x : Missing; feature value = a; feature y : Missing;";
        let tree = crate::xtext_fragment::candidate_document(source, true).unwrap();
        let saved = tree.clone();
        for mode in ["success", "cycle", "repeated", "late_failure", "fragment"] {
            let mut pending = Vec::new();
            let (root, mut graph) = construct_generated_graph(&tree, "model", &[], &mut pending, true).unwrap();
            graph.insert(0, root);
            let before = serde_json::to_value(&graph).unwrap();
            let referent_calls = std::cell::Cell::new(0);
            let requests = std::cell::Cell::new(0);
            let outcome = link_generated_graph(graph.clone(), pending, &|site| {
                let expression = site.graph.iter().find(|e| e.kind.ends_with("::FeatureReferenceExpression")).unwrap();
                if site.feature.field == "member_element" {
                    referent_calls.set(referent_calls.get() + 1);
                    if mode == "cycle" {
                        return Ok(GeneratedLinkTarget::ConstructReferenceResultSubsetting {owner_id: expression.id.clone()});
                    }
                    let referent = site.graph.iter().find(|e| e.properties.get("declared_name") == Some(&json!("a"))).unwrap();
                    return Ok(GeneratedLinkTarget::Local(referent.id.clone()));
                }
                let owner = site.graph.iter().find(|e| e.id == site.owner_id).unwrap();
                let feature = scope_container(&site.graph.iter().map(|e| (e.id.as_str(), e)).collect(), owner).unwrap().unwrap();
                if mode == "late_failure" && feature.properties.get("declared_name") == Some(&json!("y")) {
                    return Err(error("late mixed construction failure"));
                }
                let index = site.graph.iter().map(|e| (e.id.as_str(), e)).collect();
                let query = DefinitionNameQuery::new(site.graph, &index);
                let ready = definition_additional_members_ready(site.graph, expression)?
                    && match reference_result_scope::ready(&query, expression) {
                        Ok(value) => value, Err(failure) => return query_link_target(failure),
                    };
                if mode == "repeated" || !ready {
                    requests.set(requests.get() + 1);
                    return Ok(GeneratedLinkTarget::ConstructReferenceResultSubsetting {owner_id: expression.id.clone()});
                }
                let result = definition_result_parameter_typed_query(&query, expression).map_err(QueryFailure::into_diagnostic)?.unwrap();
                Ok(GeneratedLinkTarget::Local(result.id.clone()))
            }, mode != "fragment");
            assert_eq!(saved, tree);
            assert_eq!(before, serde_json::to_value(&graph).unwrap(), "private transaction preserves supplied graph");
            if mode != "success" {
                let expected = match mode {
                    "cycle" => "dependency cycle", "repeated" => "repeated reference-result",
                    "late_failure" => "late mixed construction failure", _ => "document linker"
                };
                assert!(outcome.unwrap_err().message.contains(expected), "{mode}");
                continue;
            }
            let graph = outcome.unwrap();
            assert_eq!(referent_calls.get(), 1, "completed source read reused after construction");
            assert_eq!(requests.get(), 1, "one reference construction request owns its full nested bundle");
            assert!(ecore_model::validate_publication(&graph, ecore_model::ReferenceCompleteness::Closed).is_empty());
            let persisted: Vec<KirElement> = serde_json::from_value(serde_json::to_value(&graph).unwrap()).unwrap();
            for model in [&graph, &persisted] {
                let expression = model.iter().find(|e| e.kind.ends_with("::FeatureReferenceExpression")).unwrap();
                let index = model.iter().map(|e| (e.id.as_str(), e)).collect();
                let query = DefinitionNameQuery::new(model, &index);
                assert!(reference_result_scope::ready(&query, expression).unwrap());
                let result = definition_result_parameter_typed_query(&query, expression).unwrap().unwrap();
                let membership = scope_container(&index, result).unwrap().unwrap();
                assert!(membership.kind.ends_with("::ReturnParameterMembership"));
                assert_eq!(scope_container(&index, membership).unwrap().unwrap().id, expression.id);
                let referent = model.iter().find(|e| e.properties.get("declared_name") == Some(&json!("a"))).unwrap();
                let subsets = stored_children(model, result, "owned_relationship").unwrap().into_iter()
                    .filter(|e| e.kind.ends_with("::Subsetting")).collect::<Vec<_>>();
                assert_eq!(subsets.len(), 1);
                assert_eq!(redefined_reference(model, subsets[0], "general").unwrap().id, referent.id);
                assert!(model.iter().all(|e| !scope_boolean(e, "is_implied_included").unwrap()));
            }
        }
    }

    #[test]
    fn definition_value_result_read_plan_scheduler_handles_complete_multi_owner_wave() {
        let template = literal_value_binding_fixture(false);
        let receiver = cold_literal_ids(&template).into_iter().find(|id| template.elements.iter().find(|e| e.id == *id).unwrap().kind.ends_with("::LiteralInteger")).unwrap();
        let index = template.elements.iter().map(|e| (e.id.as_str(), e)).collect();
        let query = DefinitionNameQuery::new(&template.elements, &index);
        let result = definition_result_parameter_typed_query(&query, index[receiver.as_str()]).unwrap().unwrap();
        let default_id = query_local_binding(standard_default_binding_query(&query, connector_defaults_generated::default_for("BindingConnector", 2, false).unwrap()).unwrap()).unwrap();
        let typing = |owner: &KirElement| stored_children(&template.elements, owner, "owned_relationship").unwrap().into_iter()
            .find(|e| metaclass_conforms(&e.kind, "FeatureTyping")).unwrap().id.clone();
        let fields = [typing(index[default_id.as_str()]), typing(result)];
        for mode in ["success", "dependent", "cycle", "unregistered", "wrong_target", "late_failure"] {
            let mut graph = template.elements.clone();
            let targets = fields.iter().map(|id| graph.iter_mut().find(|e| e.id == *id).unwrap().properties.remove("type").unwrap().as_str().unwrap().to_owned()).collect::<Vec<_>>();
            let namespace = graph.iter().find(|e| e.kind.ends_with("::Package")).unwrap().id.clone();
            graph.push(fresh_definition_element("last.request".into(), "Membership").unwrap());
            relative_fixture_attach(&mut graph, &namespace, "last.request", true);
            let refs = [crate::xtext_fragment::PendingReference {span: None, spelling: "provider".into(),
                target_type: "https://www.omg.org/spec/SysML/20250201#//Type".into()}];
            let last = [crate::xtext_fragment::PendingReference {span: None, spelling: "receiver".into(),
                target_type: "https://www.omg.org/spec/SysML/20250201#//Feature".into()}];
            let mut pending = vec![PendingModelLink {owner_id: fields[0].clone(), owner_kind: "SysML::FeatureTyping".into(),
                feature: ecore_model::feature("FeatureTyping", "type").unwrap(), references: &refs, ancestors: vec![]}];
            if mode != "unregistered" { pending.push(PendingModelLink {owner_id: fields[1].clone(), owner_kind: "SysML::FeatureTyping".into(),
                feature: ecore_model::feature("FeatureTyping", "type").unwrap(), references: &refs, ancestors: vec![]}); }
            pending.push(PendingModelLink {owner_id: "last.request".into(), owner_kind: "SysML::Membership".into(),
                feature: ecore_model::feature("Membership", "member_element").unwrap(), references: &last, ancestors: vec![]});
            let before = serde_json::to_value(&graph).unwrap();
            let calls = std::cell::RefCell::new(Vec::new());
            let events = std::cell::RefCell::new(Vec::new());
            let outcome = link_generated_graph_with_literal_jobs(graph.clone(), pending, &|site| {
                calls.borrow_mut().push(site.owner_id.to_owned());
                if site.owner_id == fields[0] {
                    if matches!(mode, "dependent" | "cycle") && !site.graph.iter().find(|e| e.id == fields[1]).unwrap().properties.contains_key("type") {
                        return Ok(GeneratedLinkTarget::Deferred {owner_id: fields[1].clone(), field: "type".into()});
                    }
                    return Ok(GeneratedLinkTarget::Local(targets[0].clone()));
                }
                if site.owner_id == fields[1] {
                    if mode == "cycle" {return Ok(GeneratedLinkTarget::Deferred {owner_id: fields[0].clone(), field: "type".into()});}
                    return Ok(GeneratedLinkTarget::Local(if mode == "wrong_target" {"last.request".into()} else {targets[1].clone()}));
                }
                if mode == "late_failure" {return Err(error("late multi-owner wave failure"));}
                Ok(GeneratedLinkTarget::Local(receiver.clone()))
            }, true, &[receiver.clone()], &|event| events.borrow_mut().push((event.phase, event.owner_id.to_owned(), event.field.map(str::to_owned), event.succeeded)));
            assert_eq!(before, serde_json::to_value(&graph).unwrap());
            let events = events.borrow();
            for id in &fields {
                assert!(events.iter().any(|(phase, owner, field, _)| *phase == DefinitionConstructionPhase::LiteralPrerequisite
                    && owner == id && field.as_deref() == Some("type")), "{mode}/{id}");
            }
            if matches!(mode, "success" | "dependent" | "late_failure") {
                assert_eq!(events.iter().filter(|(phase, _, _, _)| *phase == DefinitionConstructionPhase::LiteralProducerStarted).count(), 2,
                    "one retry after all independent owners are resolved");
            }
            if matches!(mode, "success" | "dependent") {
                let graph = outcome.unwrap();
                assert!(ecore_model::validate_publication(&graph, ecore_model::ReferenceCompleteness::Closed).is_empty());
                for (id, target) in fields.iter().zip(&targets) {
                    assert_eq!(graph.iter().find(|e| e.id == *id).unwrap().properties["type"], json!(target));
                }
                assert_eq!(calls.borrow().iter().filter(|id| *id == &fields[1]).count(), 1, "completed prerequisite reused");
                let persisted: Vec<KirElement> = serde_json::from_value(serde_json::to_value(&graph).unwrap()).unwrap();
                for model in [&graph, &persisted] {
                    assert!(definition_result_parameter(model, model.iter().find(|e| e.id == receiver).unwrap()).unwrap().is_some());
                }
            } else {
                let expected = match mode {"cycle" => "dependency cycle", "unregistered" => "not pending",
                    "wrong_target" => "violates Xtext target type", _ => "late multi-owner wave failure"};
                assert!(outcome.unwrap_err().message.contains(expected), "{mode}");
                if mode == "unregistered" {assert!(calls.borrow().is_empty(), "whole pending wave validated before any field is resolved");}
            }
        }
    }

    #[test]
    fn definition_literal_binding_prerequisites_precede_writes_and_repair() {
        let template=literal_value_binding_fixture(false);
        let receiver=cold_literal_ids(&template).into_iter().find(|id|template.elements.iter().find(|e|e.id==*id).unwrap().kind.ends_with("::LiteralInteger")).unwrap();
        let index=template.elements.iter().map(|e|(e.id.as_str(),e)).collect();
        let query=DefinitionNameQuery::new(&template.elements,&index);
        let result=definition_result_parameter_typed_query(&query,index[receiver.as_str()]).unwrap().unwrap();
        let default_name=connector_defaults_generated::default_for("BindingConnector",2,false).unwrap();
        let default_id=query_local_binding(standard_default_binding_query(&query,default_name).unwrap()).unwrap();
        let default=index[default_id.as_str()];
        let typing=|owner:&KirElement|stored_children(&template.elements,owner,"owned_relationship").unwrap().into_iter()
            .find(|e|metaclass_conforms(&e.kind,"FeatureTyping")).unwrap().id.clone();
        let default_type=query_reference_in_view(&query,index[typing(default).as_str()],"type").unwrap();
        let general=stored_children(&template.elements,default_type,"owned_relationship").unwrap().into_iter()
            .find(|e|metaclass_conforms(&e.kind,"Subclassification")).unwrap().id.clone();
        for (owner_id,field) in [(typing(default),"type"),(typing(result),"type"),(general,"superclassifier")] {
            for malformed in [false,true] {
                let mut graph=template.elements.clone();
                let value=graph.iter_mut().find(|e|e.id==owner_id).unwrap().properties.remove(field).unwrap();
                if malformed {graph.iter_mut().find(|e|e.id==owner_id).unwrap().properties.insert(field.into(),json!(false));}
                let before=serde_json::to_value(&graph).unwrap();
                let events=std::cell::RefCell::new(Vec::new());
                let observer=|event:DefinitionConstructionEvent<'_>|events.borrow_mut().push((event.phase,event.field.map(str::to_owned),event.succeeded));
                let failure=literal_value_binding::complete_query_observed(&mut graph,&[receiver.as_str()],"plan",ecore_model::ReferenceCompleteness::Partial,&observer).unwrap_err();
                if !malformed {assert!(matches!(failure,QueryFailure::Required(Prerequisite::ReadField {owner_id:ref id,field:ref name}) if id==&owner_id && name==field),"{owner_id}.{field}: {failure:?}");}
                assert_eq!(before,serde_json::to_value(&graph).unwrap());
                assert!(!events.borrow().iter().any(|(phase,field,_)|*phase==DefinitionConstructionPhase::LiteralStageStarted
                    && matches!(field.as_deref(),Some("receiver_defaults"|"receiver_featuring"|"binding_chain"|"binding_structure"|"binding_defaults"))),"no physical writes before prerequisites {owner_id}.{field}");
                if !malformed {assert!(events.borrow().iter().any(|(phase,field,success)|*phase==DefinitionConstructionPhase::LiteralStageFinished && field.as_deref()==Some("binding_prerequisites") && *success==Some(false)));}
                graph.iter_mut().find(|e|e.id==owner_id).unwrap().properties.insert(field.into(),value);
                events.borrow_mut().clear();
                assert_eq!(literal_value_binding::complete_query_observed(&mut graph,&[receiver.as_str()],"plan",ecore_model::ReferenceCompleteness::Closed,&observer).unwrap(),1);
                for stage in ["binding_prerequisites","binding_structure","binding_defaults","binding_featuring","binding_projection"] {
                    assert!(events.borrow().iter().any(|(phase,field,success)|*phase==DefinitionConstructionPhase::LiteralStageFinished && field.as_deref()==Some(stage) && *success==Some(true)),"{stage}");
                }
                assert!(ecore_model::validate_publication(&graph,ecore_model::ReferenceCompleteness::Closed).is_empty());
            }
        }
    }

    #[test]
    fn definition_literal_default_prerequisites_skip_binding_library() {
        for default in [false,true] {
            let source=literal_value_binding_source(default);
            let source=source.split("standard library package Links").next().unwrap();
            let template=crate::definition_document::parse_and_link(source,crate::SourceLanguage::Kerml).unwrap();
            let receivers=cold_literal_ids(&template);let mut graph=template.elements.clone();
            let before=serde_json::to_value(&graph).unwrap();
            let events=std::cell::RefCell::new(Vec::new());
            let observer=|event:DefinitionConstructionEvent<'_>|events.borrow_mut().push((event.phase,event.field.map(str::to_owned)));
            let result=literal_value_binding::complete_query_observed(&mut graph,&receivers.iter().map(String::as_str).collect::<Vec<_>>(),"default",ecore_model::ReferenceCompleteness::Closed,&observer);
            if default {assert_eq!(result.unwrap(),0);assert!(receivers.iter().all(|id|scope_boolean(graph.iter().find(|e|e.id==*id).unwrap(),"is_implied_included").unwrap()));}
            else {assert!(result.is_err());assert_eq!(before,serde_json::to_value(&graph).unwrap());}
            assert!(!events.borrow().iter().any(|(phase,field)|*phase==DefinitionConstructionPhase::LiteralStageStarted
                && matches!(field.as_deref(),Some("binding_chain"|"binding_structure"|"binding_defaults"))));
        }
    }

    #[test]
    fn definition_literal_producer_boundaries_preserve_public_closed_and_source_scope() {
        let source=literal_value_binding_source(false);
        let sources=[crate::definition_document::DefinitionSource {uri:"memory:/literal-scope.kerml",text:&source,language:crate::SourceLanguage::Kerml}];
        for scope in [vec![sources[0].uri,sources[0].uri],vec!["memory:/absent.kerml"]] {
            assert!(matches!(crate::definition_document::parse_and_link_sources_with_literal_value_bindings(&sources,&scope),Err(crate::definition_document::DefinitionDocumentError::Unsupported(_))));
        }
        let template=literal_value_binding_fixture(false);let ids=cold_literal_ids(&template);
        let mut graph=template.elements.clone();
        let typing=graph.iter_mut().find(|e|e.kind.ends_with("::FeatureTyping")).unwrap();typing.properties.insert("type".into(),json!("missing.public.type"));
        let before=serde_json::to_value(&graph).unwrap();
        assert!(definition_complete_literal_value_bindings(&mut graph,&ids.iter().map(String::as_str).collect::<Vec<_>>(),"closed").is_err());
        assert_eq!(serde_json::to_value(&graph).unwrap(),before);
        for mode in ["initial","variable","untyped"] {
            let source=match mode {
                "initial"=>source.replace(" = "," := "),
                "variable"=>source.replace("feature booleanValue","var feature booleanValue"),
                _=>source.replace("feature nullValue : Base::Anything","feature nullValue"),
            };
            let sources=[crate::definition_document::DefinitionSource {uri:"memory:/literal-boundary.kerml",text:&source,language:crate::SourceLanguage::Kerml}];
            assert!(crate::definition_document::parse_and_link_sources_with_literal_value_bindings(&sources,&[sources[0].uri]).is_err(),"{mode}");
        }
    }

    #[test]
    fn definition_literal_value_bindings_complete_shared_transaction_and_persistence() {
        for default in [false, true] {
            let template = literal_value_binding_fixture(default);
            for reverse in [false, true] {
                let mut doc = template.clone();
                let ids = cold_literal_ids(&doc); assert_eq!(ids.len(), 6);
                let supplied = doc.elements.clone();
                if reverse { doc.elements.reverse(); }
                assert_eq!(crate::definition_document::complete_literal_value_bindings(&mut doc,
                    &ids.iter().map(String::as_str).collect::<Vec<_>>(), "batch").unwrap(), if default {0} else {6});
                let exported = crate::abstract_syntax_json::export_sysml_abstract_syntax_value(&doc, Default::default()).unwrap(); assert!(!exported.has_errors());
                let restored = crate::abstract_syntax_json::import_sysml_abstract_syntax_value(exported.value, Default::default()).unwrap(); assert!(!restored.has_errors());
                let replay = restored.persistable_document().unwrap();
                for model in [&doc, &replay] {
                    for id in &ids {
                        let expression = model.elements.iter().find(|e| e.id == *id).unwrap();
                        let owner = definition_value_expression_owner(&model.elements, expression).unwrap();
                        assert!(scope_boolean(expression, "is_implied_included").unwrap());
                        assert!(!scope_boolean(owner, "is_implied_included").unwrap());
                        let bindings = stored_children(&model.elements, owner, "owned_relationship").unwrap().into_iter()
                            .filter(|r| literal_value_binding::binding_contribution(&model.elements, owner, r).unwrap()).collect::<Vec<_>>();
                        assert_eq!(bindings.len(), usize::from(!default));
                        if default { continue; }
                        let binding = stored_children(&model.elements, bindings[0], "owned_related_element").unwrap()[0];
                        assert!(scope_boolean(binding, "is_implied_included").unwrap());
                        let source = definition_reference_targets(&model.elements, binding, "source").unwrap(); assert_eq!(source.len(), 1);
                        assert_eq!(definition_reference_targets(&model.elements, binding, "target").unwrap().iter().map(|e| e.id.as_str()).collect::<Vec<_>>(), [owner.id.as_str()]);
                        let result = definition_result_parameter(&model.elements, expression).unwrap().unwrap();
                        assert_eq!(definition_reference_targets(&model.elements, source[0], "chaining_feature").unwrap().iter().map(|e| e.id.as_str()).collect::<Vec<_>>(), [expression.id.as_str(), result.id.as_str()]);
                        assert_eq!(definition_feature_types(&model.elements, source[0]).unwrap().iter().map(|e| e.id.as_str()).collect::<Vec<_>>(), definition_feature_types(&model.elements, result).unwrap().iter().map(|e| e.id.as_str()).collect::<Vec<_>>());
                        for end in definition_owned_features(&model.elements, binding, true).unwrap() { assert!(scope_boolean(end, "is_implied_included").unwrap()); }
                        // Return default queries must remain available after
                        // non-typing binding containment, without completing it.
                        if definition_is_result_parameter(&model.elements, owner).unwrap() { definition_result_feature_generals(&model.elements, owner).unwrap(); }
                    }
                }
                for old in &supplied {
                    let current = doc.elements.iter().find(|e| e.id == old.id).unwrap();
                    if !ids.contains(&old.id) {
                        assert_eq!(current.properties.get("is_implied_included"), old.properties.get("is_implied_included"));
                        let mut actual = current.clone(); let mut expected = old.clone();
                        actual.properties.remove("owned_relationship"); expected.properties.remove("owned_relationship");
                        assert_eq!(actual, expected, "supplied object changes only its own added containment");
                    }
                }
                assert_eq!(doc.metadata["semantic_validation"], json!("not_assessed"));
            }
        }
    }

    #[test]
    fn definition_literal_value_bindings_match_frozen_binding_fields() {
        // Independent field observations, not a claim that the bounded fixture
        // represents the complete real resource/owner lifecycle.
        let expected: Value = serde_json::from_str(include_str!("../../../../../../docs/conformance/2026-08-support/value-service-literal-field-contract.json")).unwrap();
        let mut doc = literal_value_binding_fixture(false);
        let ids = cold_literal_ids(&doc);
        crate::definition_document::complete_literal_value_bindings(&mut doc, &ids.iter().map(String::as_str).collect::<Vec<_>>(), "fields").unwrap();
        let exported = crate::abstract_syntax_json::export_sysml_abstract_syntax_value(&doc, Default::default()).unwrap(); assert!(!exported.has_errors());
        let imported = crate::abstract_syntax_json::import_sysml_abstract_syntax_value(exported.value, Default::default()).unwrap(); assert!(!imported.has_errors());
        let replay = imported.persistable_document().unwrap();
        for case in expected["field_expectations"].as_array().unwrap().iter().filter(|c| matches!(c["id"].as_str(), Some("valuation-source-00"|"valuation-source-01"))) {
            let observation = &case["feature_value_owner_binding"];
            let expected_binding = &observation["bindings"][0];
            let kind = case["literal_receiver_lifecycle"]["kind"].as_str().unwrap();
            for model in [&doc, &replay] {
                let graph = &model.elements;
                let expression = graph.iter().find(|e| e.kind.rsplit("::").next() == Some(kind)).unwrap();
                let owner = definition_value_expression_owner(graph, expression).unwrap();
                let contributions = stored_children(graph, owner, "owned_relationship").unwrap().into_iter().filter(|m| literal_value_binding::binding_contribution(graph, owner, m).unwrap()).collect::<Vec<_>>();
                assert_eq!(contributions.len(), observation["binding_count"].as_u64().unwrap() as usize);
                let binding = stored_children(graph, contributions[0], "owned_related_element").unwrap()[0];
                for (field, expected) in expected_binding["attributes"].as_object().unwrap() { assert_eq!(definition_attribute_value(graph, binding, field).unwrap(), expected["value"], "{kind}.{field}"); }
                let names = |targets: Vec<&KirElement>| json!(targets.iter().map(|e| snapshot_qualified_name(graph, e, &mut BTreeSet::new()).unwrap().unwrap()).collect::<Vec<_>>());
                assert_eq!(names(definition_feature_types(graph, binding).unwrap()), expected_binding["derived_edges"]["type"]);
                let source = definition_reference_targets(graph, binding, "source").unwrap(); assert_eq!(source.len(), 1);
                assert_eq!(names(definition_feature_types(graph, source[0]).unwrap()), observation["generated_result_chains"][0]["derived_edges"]["type"]);
                let chains = stored_children(graph, source[0], "owned_relationship").unwrap();
                assert_eq!(chains.len(), observation["physical_feature_chaining_count"].as_u64().unwrap() as usize);
                assert!(chains.iter().all(|r| r.kind.rsplit("::").next()==Some("FeatureChaining") && !scope_boolean(r,"is_implied").unwrap()));
                let canonical = graph.iter().find(|e| Some(e.id.as_str()) == source[0].properties.get("owning_relationship").and_then(Value::as_str)).unwrap();
                assert_eq!(canonical.kind.rsplit("::").next(), Some("ReferenceSubsetting"));
                for (end, control) in definition_owned_features(graph, binding, true).unwrap().iter().zip(expected_binding["ends"].as_array().unwrap()) {
                    assert_eq!(names(definition_feature_types(graph, end).unwrap()), control["derived_edges"]["type"]);
                }
            }
        }
    }

    #[test]
    fn definition_literal_value_bindings_reject_boundaries_and_late_failures_atomically() {
        let template = literal_value_binding_fixture(false);
        for boundary in ["initial", "variable_owner", "missing_typing", "missing_library", "late_collision", "multiple_values"] {
            let mut doc = template.clone(); let ids = cold_literal_ids(&doc); let mut sorted = ids.clone(); sorted.sort();
            let expression = doc.elements.iter().find(|e| e.id == sorted[0]).unwrap();
            let owner_id = definition_value_expression_owner(&doc.elements, expression).unwrap().id.clone();
            let value_id = expression.properties["owning_relationship"].as_str().unwrap().to_owned();
            match boundary {
                "initial" => { doc.elements.iter_mut().find(|e| e.id == value_id).unwrap().properties.insert("is_initial".into(), json!(true)); },
                "variable_owner" => { doc.elements.iter_mut().find(|e| e.id == owner_id).unwrap().properties.insert("is_variable".into(), json!(true)); },
                "missing_typing" => { let relation = doc.elements.iter().find(|e| e.kind.rsplit("::").next() == Some("FeatureTyping") && e.properties.get("owning_related_element")==Some(&json!(owner_id))).unwrap().id.clone(); doc.elements.iter_mut().find(|e| e.id == relation).unwrap().properties.remove("type"); },
                "missing_library" => { doc.elements.iter_mut().find(|e| e.properties.get("declared_name")==Some(&json!("selfLinks"))).unwrap().properties.insert("declared_name".into(), json!("unavailable")); },
                "late_collision" => doc.elements.push(fresh_definition_element(format!("batch.{}.value-binding.end.1.featuring", sorted.last().unwrap()), "Feature").unwrap()),
                "multiple_values" => {
                    let mut value=fresh_definition_element("extra.value".into(),"FeatureValue").unwrap();
                    let mut child=fresh_definition_element("extra.literal".into(),"LiteralInteger").unwrap();
                    ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS,&mut value,&mut child).unwrap();
                    value.properties.insert("member_element".into(),json!(child.id));
                    ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,doc.elements.iter_mut().find(|e|e.id==owner_id).unwrap(),&mut value).unwrap();doc.elements.extend([value,child]);
                }, _ => unreachable!(),
            }
            let before = serde_json::to_value(&doc).unwrap();
            if boundary == "late_collision" {
                let events = std::cell::RefCell::new(Vec::new());
                let observer = |event: DefinitionConstructionEvent<'_>| {
                    events.borrow_mut().push((event.phase, event.owner_id.to_owned(),
                        event.field.map(str::to_owned), event.succeeded));
                };
                let failure = literal_value_binding::complete_query_observed(&mut doc.elements,
                    &ids.iter().map(String::as_str).collect::<Vec<_>>(), "batch",
                    ecore_model::ReferenceCompleteness::Closed, &observer).unwrap_err();
                assert!(matches!(failure, QueryFailure::Rejected(_)), "{failure:?}");
                let events = events.borrow();
                let finished = |receiver: &str, stage: &str, success: bool| events.iter().any(
                    |(phase, owner, field, succeeded)| *phase == DefinitionConstructionPhase::LiteralStageFinished
                        && owner == receiver && field.as_deref() == Some(stage) && *succeeded == Some(success));
                for receiver in &sorted {
                    assert!(finished(receiver, "receiver_defaults", true), "{receiver}");
                    assert!(finished(receiver, "receiver_featuring", true), "{receiver}");
                }
                for receiver in &sorted[..sorted.len() - 1] {
                    assert!(finished(receiver, "binding_lifecycle", true), "{receiver}");
                    assert!(finished(receiver, "binding_projection", true), "{receiver}");
                }
                assert!(finished(sorted.last().unwrap(), "binding_chain", true));
                assert!(finished(sorted.last().unwrap(), "binding_lifecycle", false),
                    "collision must follow completed cold receivers and earlier bindings");
                assert_eq!(serde_json::to_value(&doc).unwrap(), before,
                    "late physical failure must discard every preceding stage");
            }
            let failure = crate::definition_document::complete_literal_value_bindings(&mut doc, &ids.iter().map(String::as_str).collect::<Vec<_>>(), "batch").unwrap_err();
            if boundary == "late_collision" { let message = failure.to_string(); assert!(message.contains("duplicate") || message.contains("collision") || message.contains("unique nonempty model identities"), "late test must reach the intended identity failure: {message}"); }
            assert_eq!(serde_json::to_value(&doc).unwrap(), before, "{boundary}");
        }
    }

    #[test]
    fn definition_cold_literal_lifecycle_composes_typed_source_and_persistence() {
        for reverse in [false, true] {
            let mut doc = cold_literal_source_fixture();
            let ids = cold_literal_ids(&doc); assert_eq!(ids.len(), 6);
            assert!(doc.elements.iter().filter(|e| metaclass_conforms(&e.kind, "Type"))
                .all(|e| !scope_boolean(e, "is_implied_included").unwrap()), "no prepared completion flags");
            let before = doc.clone();
            let expected = ids.iter().map(|id| {
                let expression = doc.elements.iter().find(|e| e.id == *id).unwrap();
                let result = definition_result_parameter(&doc.elements, expression).unwrap().unwrap().id.clone();
                let generals = definition_general_type_inputs_query(&doc.elements, expression).unwrap();
                let featuring = definition_featuring_types(&doc.elements, expression).unwrap().iter().map(|e| e.id.clone()).collect::<Vec<_>>();
                (id.clone(), result, generals, featuring)
            }).collect::<Vec<_>>();
            if reverse { doc.elements.reverse(); }
            assert_eq!(crate::definition_document::complete_literal_value_expressions(&mut doc,
                &ids.iter().map(String::as_str).collect::<Vec<_>>(), "cold").unwrap(), 6);
            for old in &before.elements {
                if !ids.contains(&old.id) { assert_eq!(doc.elements.iter().find(|e| e.id == old.id).unwrap(), old, "supplied dependencies stay unchanged"); }
            }
            let exported = crate::abstract_syntax_json::export_sysml_abstract_syntax_value(&doc, Default::default()).unwrap(); assert!(!exported.has_errors());
            let imported = crate::abstract_syntax_json::import_sysml_abstract_syntax_value(exported.value, Default::default()).unwrap(); assert!(!imported.has_errors());
            for model in [&doc, &imported.persistable_document().unwrap()] {
                for (id, result, generals, featuring) in &expected {
                    let expression = model.elements.iter().find(|e| e.id == *id).unwrap();
                    assert!(scope_boolean(expression, "is_implied_included").unwrap());
                    assert_eq!(definition_result_parameter(&model.elements, expression).unwrap().unwrap().id, *result);
                    assert_eq!(definition_general_type_inputs_query(&model.elements, expression).unwrap(), *generals);
                    assert_eq!(definition_featuring_types(&model.elements, expression).unwrap().iter().map(|e| e.id.clone()).collect::<Vec<_>>(), *featuring);
                    assert!(!stored_children(&model.elements, expression, "owned_relationship").unwrap().iter()
                        .any(|r| metaclass_conforms(&r.kind, "ReturnParameterMembership")), "inherited results are never fabricated");
                    assert_eq!(stored_children(&model.elements, expression, "owned_relationship").unwrap().iter()
                        .map(|r| r.kind.rsplit("::").next().unwrap()).collect::<Vec<_>>(), ["Subsetting", "TypeFeaturing"]);
                }
                assert!(model.metadata.get("semantic_validation").is_none_or(|v| v == &json!("not_assessed")));
                // Abstract-syntax persistence does not carry the candidate's
                // qualification metadata; absence cannot mean validated.
                assert!(!model.metadata.get("semantic_validation").is_some_and(|v| v == "passed"));
            }
            let snapshot = serde_json::to_value(&doc).unwrap();
            assert!(crate::definition_document::complete_literal_value_expressions(&mut doc, &[&ids[0]], "repeated").is_err());
            assert_eq!(serde_json::to_value(&doc).unwrap(), snapshot);
        }
    }

    #[test]
    fn definition_expression_typing_consumes_computed_positional_redefinitions() {
        let mut doc = cold_literal_source_fixture();
        let named = |doc: &crate::KirDocument, name: &str| doc.elements.iter().find(|e| e.properties.get("declared_name") == Some(&json!(name))).unwrap().id.clone();
        let package = named(&doc, "P"); let owner = named(&doc, "F"); let integer = named(&doc, "Integer");
        let mut general = fresh_definition_element("typing.function".into(), "Function").unwrap();
        general.properties.insert("declared_name".into(), json!("G"));
        cross_test_own(&mut doc.elements, &package, "OwningMembership", general);
        let mut inherited = fresh_definition_element("typing.parameter".into(), "Feature").unwrap();
        inherited.properties.insert("direction".into(), json!("in"));
        let mut typing = fresh_definition_element("typing.parameter.type".into(), "FeatureTyping").unwrap();
        typing.properties.insert("typed_feature".into(), json!(inherited.id)); typing.properties.insert("type".into(), json!(integer));
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, &mut inherited, &mut typing).unwrap();
        doc.elements.push(typing); cross_test_own(&mut doc.elements, "typing.function", "ParameterMembership", inherited);
        let mut specialization = fresh_definition_element("typing.owner.general".into(), "Subclassification").unwrap();
        specialization.properties.insert("subclassifier".into(), json!(owner)); specialization.properties.insert("superclassifier".into(), json!("typing.function"));
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, doc.elements.iter_mut().find(|e| e.id == owner).unwrap(), &mut specialization).unwrap(); doc.elements.push(specialization);
        let mut parameter = fresh_definition_element("typing.expression".into(), "Expression").unwrap(); parameter.properties.insert("direction".into(), json!("in"));
        cross_test_own(&mut doc.elements, &owner, "ParameterMembership", parameter);
        let parameter = doc.elements.iter().find(|e| e.id == "typing.expression").unwrap();
        assert_eq!(definition_redefined_features(&doc.elements, parameter, false).unwrap().iter().map(|e| e.id.as_str()).collect::<Vec<_>>(), ["typing.parameter"]);
        let before = serde_json::to_value(&doc).unwrap();
        assert!(definition_feature_types_query(&doc.elements, parameter).unwrap().iter().any(|e| e.id == integer), "computed parameter typing must not disappear");
        assert_eq!(serde_json::to_value(&doc).unwrap(), before);
        // An unavailable inherited typing field must remain a concrete typed
        // prerequisite, not silently become an empty parameter type set.
        doc.elements.iter_mut().find(|e| e.id == "typing.parameter.type").unwrap().properties.remove("type");
        let parameter = doc.elements.iter().find(|e| e.id == "typing.expression").unwrap();
        assert!(matches!(definition_feature_types_query(&doc.elements, parameter), Err(QueryFailure::Required(Prerequisite::ReadField { owner_id, field }))
            if owner_id == "typing.parameter.type" && field == "type"));
    }

    #[test]
    fn definition_cold_literals_match_frozen_receiver_field_expectations() {
        let expected: Value = serde_json::from_str(include_str!("../../../../../../docs/conformance/2026-08-support/value-service-literal-field-contract.json")).unwrap();
        let mut doc = cold_literal_source_fixture();
        let ids = cold_literal_ids(&doc);
        definition_complete_literal_value_expressions(&mut doc.elements, &ids.iter().map(String::as_str).collect::<Vec<_>>(), "fields").unwrap();
        let selected = expected["field_expectations"].as_array().unwrap().iter().filter(|c|
            matches!(c["id"].as_str(), Some("valuation-source-00" | "valuation-source-01"))).collect::<Vec<_>>();
        assert_eq!(selected.len(), 2);
        for case in selected {
            let control = &case["literal_receiver_lifecycle"];
            let kind = control["kind"].as_str().unwrap();
            let expression = doc.elements.iter().find(|e| e.kind.rsplit("::").next() == Some(kind)).unwrap();
            for (field, value) in control["attributes"].as_object().unwrap() {
                assert!(value["present"].as_bool().unwrap());
                assert_eq!(definition_attribute_value(&doc.elements, expression, field).unwrap(), value["value"], "{kind}.{field}");
            }
            for field in ["function", "parameter", "result", "chaining_feature"] {
                let targets = definition_reference_targets(&doc.elements, expression, field).unwrap().iter()
                    .map(|e| snapshot_qualified_name(&doc.elements, e, &mut BTreeSet::new()).unwrap().unwrap()).collect::<Vec<_>>();
                assert_eq!(json!(targets), control["reference_sequences"][field]["targets"], "{kind}.{field}");
            }
            let types = definition_feature_types_query(&doc.elements, expression).unwrap().iter()
                .map(|e| snapshot_qualified_name(&doc.elements, e, &mut BTreeSet::new()).unwrap().unwrap()).collect::<Vec<_>>();
            assert_eq!(json!(types), control["derived_edges"]["type"]);
            let relationships = stored_children(&doc.elements, expression, "owned_relationship").unwrap();
            let actual = relationships.iter().map(|r| json!({"kind": r.kind.rsplit("::").next().unwrap(), "is_implied": scope_boolean(r, "is_implied").unwrap()})).collect::<Vec<_>>();
            let expected = control["ordered_owned_relationships"].as_array().unwrap().iter()
                .map(|r| json!({"kind": r["kind"], "is_implied": r["is_implied"]})).collect::<Vec<_>>();
            assert_eq!(actual, expected);
            assert_eq!(relationships.iter().filter(|r| metaclass_conforms(&r.kind, "ReturnParameterMembership")).count(), control["owned_return_parameter_membership_count"].as_u64().unwrap() as usize);
        }
        // Comparison is for the receiver over a bounded native typed fixture.
        // Full real-library source and owner/binding qualification remain open.
        assert_eq!(doc.metadata["semantic_validation"], json!("not_assessed"));
    }

    #[test]
    fn definition_cold_literal_lifecycle_admits_verified_partial_stages_and_rejects_owned_subtrees() {
        let original = cold_literal_source_fixture();
        let ids = cold_literal_ids(&original);
        for order in [false, true] {
            let mut doc = original.clone();
            if order {
                definition_materialize_value_expression_featuring(&mut doc.elements, &ids[0], "partial.featuring").unwrap();
                definition_materialize_value_expression_defaults(&mut doc.elements, &ids[0], "partial.generals").unwrap();
            } else {
                definition_materialize_value_expression_defaults(&mut doc.elements, &ids[0], "partial.generals").unwrap();
                definition_materialize_value_expression_featuring(&mut doc.elements, &ids[0], "partial.featuring").unwrap();
            }
            let length = doc.elements.len();
            definition_complete_literal_value_expressions(&mut doc.elements, &[&ids[0]], "finish").unwrap();
            assert_eq!(doc.elements.len(), length, "partial producers must not be duplicated");
            let expression = doc.elements.iter().find(|e| e.id == ids[0]).unwrap();
            assert_eq!(stored_children(&doc.elements, expression, "owned_relationship").unwrap().iter()
                .map(|r| r.kind.rsplit("::").next().unwrap()).collect::<Vec<_>>(), ["Subsetting", "TypeFeaturing"]);
        }
        for kind in ["Subsetting", "TypeFeaturing"] {
            let mut doc = original.clone();
            definition_materialize_value_expression_defaults(&mut doc.elements, &ids[0], "partial.generals").unwrap();
            definition_materialize_value_expression_featuring(&mut doc.elements, &ids[0], "partial.featuring").unwrap();
            let expression = doc.elements.iter().find(|e| e.id == ids[0]).unwrap();
            let relation = stored_children(&doc.elements, expression, "owned_relationship").unwrap().into_iter()
                .find(|r| r.kind.rsplit("::").next() == Some(kind)).unwrap().id.clone();
            let mut child = fresh_definition_element("untransformed.subtree".into(), "Class").unwrap();
            ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS, doc.elements.iter_mut().find(|e| e.id == relation).unwrap(), &mut child).unwrap();
            doc.elements.push(child);
            let before = serde_json::to_value(&doc).unwrap();
            assert!(definition_complete_literal_value_expressions(&mut doc.elements, &[&ids[0]], "finish").is_err(), "{kind}");
            assert_eq!(serde_json::to_value(&doc).unwrap(), before);
        }
    }

    #[test]
    fn definition_cold_literal_completion_keeps_value_flags_and_semantic_validity_separate() {
        let original = cold_literal_source_fixture();
        let id = cold_literal_ids(&original)[0].clone();
        for default in [false, true] { for initial in [false, true] {
            let mut doc = original.clone();
            let index = doc.elements.iter().map(|e| (e.id.as_str(), e)).collect::<BTreeMap<_, _>>();
            let expression = index[id.as_str()];
            let value = scope_container(&index, expression).unwrap().unwrap().id.clone();
            let feature = scope_container(&index, index[value.as_str()]).unwrap().unwrap().id.clone();
            let value_node = doc.elements.iter_mut().find(|e| e.id == value).unwrap();
            value_node.properties.insert("is_default".into(), json!(default));
            value_node.properties.insert("is_initial".into(), json!(initial));
            let before = doc.elements.iter().find(|e| e.id == id).unwrap().clone();
            definition_complete_literal_value_expressions(&mut doc.elements, &[&id], "flags").unwrap();
            let mut after = doc.elements.iter().find(|e| e.id == id).unwrap().clone();
            after.properties.insert("owned_relationship".into(), before.properties["owned_relationship"].clone());
            after.properties.insert("is_implied_included".into(), before.properties["is_implied_included"].clone());
            assert_eq!(after, before, "every original literal property survives");
            let value_node = doc.elements.iter().find(|e| e.id == value).unwrap();
            assert_eq!((scope_boolean(value_node, "is_default").unwrap(), scope_boolean(value_node, "is_initial").unwrap()), (default, initial));
            assert!(!scope_boolean(doc.elements.iter().find(|e| e.id == feature).unwrap(), "is_implied_included").unwrap());
            let issues = crate::definition_document::assess_feature_values(&doc).unwrap();
            assert_eq!(issues.iter().any(|i| i.valuation_id == value && i.constraint == "validateFeatureValueIsInitial" && !i.unverified), initial,
                "a completed literal cannot make initialization of a fixed Feature valid");
            assert_eq!(doc.metadata["semantic_validation"], json!("not_assessed"));
        } }
    }

    #[test]
    fn definition_cold_literal_lifecycle_rejects_unassessed_producers_atomically() {
        let original = cold_literal_source_fixture();
        let ids = cold_literal_ids(&original);
        for boundary in ["empty_prefix", "duplicate", "variable", "direction", "wrong_provider", "child", "snapshot", "metadata", "late_collision", "untyped_role", "missing_return", "detached_featuring"] {
            let mut doc = original.clone();
            let id = &ids[0];
            match boundary {
                "variable" => { doc.elements.iter_mut().find(|e| e.id == *id).unwrap().properties.insert("is_variable".into(), json!(true)); },
                "direction" => { doc.elements.iter_mut().find(|e| e.id == *id).unwrap().properties.insert("direction".into(), json!("in")); },
                "wrong_provider" => doc.elements.iter_mut().find(|e| e.id == *id).unwrap().kind = "SysML::OperatorExpression".into(),
                "child" => { let child = fresh_definition_element("unexpected.child".into(), "Feature").unwrap(); cross_test_own(&mut doc.elements, id, "FeatureMembership", child); },
                "snapshot" => { doc.elements.iter_mut().find(|e| e.id == *id).unwrap().properties.insert("result".into(), json!(id)); },
                "metadata" => metadata_test_annotate(&mut doc.elements, id, id, "cold.metadata", "MetadataFeature"),
                "late_collision" => { let last = ids.iter().max().unwrap(); doc.elements.push(fresh_definition_element(format!("cold.{last}.featuring.0"), "Feature").unwrap()); },
                "detached_featuring" => {
                    let index = doc.elements.iter().map(|e| (e.id.as_str(), e)).collect::<BTreeMap<_, _>>();
                    let value = scope_container(&index, index[id.as_str()]).unwrap().unwrap();
                    let feature = scope_container(&index, value).unwrap().unwrap().id.clone();
                    doc.elements.push(fresh_definition_element("detached.context".into(), "Class").unwrap());
                    let mut relation = fresh_definition_element("detached.featuring".into(), "TypeFeaturing").unwrap();
                    relation.properties.insert("feature_of_type".into(), json!(feature)); relation.properties.insert("featuring_type".into(), json!("detached.context"));
                    ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, doc.elements.iter_mut().find(|e| e.id == feature).unwrap(), &mut relation).unwrap(); doc.elements.push(relation);
                },
                "untyped_role" | "missing_return" => {
                    let expression = doc.elements.iter().find(|e| e.id == *id).unwrap();
                    let result = definition_result_parameter(&doc.elements, expression).unwrap().unwrap();
                    let (member, function) = definition_feature_owner(&doc.elements, result).unwrap().unwrap();
                    let target = if boundary == "untyped_role" { function.id.clone() } else { member.id.clone() };
                    if boundary == "untyped_role" {
                        doc.elements.iter_mut().find(|e| e.id == target).unwrap().kind = "SysML::Class".into();
                    } else {
                        // Removing one owned return correctly falls back to an
                        // inherited return; the negative removes the full closure.
                        for member in doc.elements.iter_mut().filter(|e| metaclass_conforms(&e.kind, "ReturnParameterMembership")) {
                            member.kind = "SysML::FeatureMembership".into();
                        }
                    }
                },
                _ => {},
            }
            let before = serde_json::to_value(&doc).unwrap();
            let selected = if boundary == "duplicate" { vec![ids[0].as_str(), ids[0].as_str()] } else { ids.iter().map(String::as_str).collect() };
            assert!(crate::definition_document::complete_literal_value_expressions(&mut doc, &selected,
                if boundary == "empty_prefix" { "" } else { "cold" }).is_err(), "{boundary}");
            assert_eq!(serde_json::to_value(&doc).unwrap(), before, "{boundary}");
        }
    }

    #[test]
    fn definition_directed_result_valuations_match_cached_selector_controls() {
        let artifact: Value = serde_json::from_str(include_str!("../../../../../../docs/conformance/2026-08-support/result-valuation-pilot-controls.json")).unwrap();
        let mut observed = 0;
        for case in artifact["controls"].as_array().unwrap().iter().filter(|c| c["status"] == "observed_component") {
            let mut doc = result_default_fixture(case["owner_kind"].as_str().unwrap(), case["mask"].as_u64().unwrap());
            let mode = case["mode"].as_u64().unwrap();
            let mut value = fresh_definition_element("value".into(), "FeatureValue").unwrap();
            value.properties.insert("is_default".into(), json!(mode & 1 != 0));
            value.properties.insert("is_initial".into(), json!(mode & 2 != 0));
            let mut expression = fresh_definition_element("value.expression".into(), case["shape"].as_str().unwrap()).unwrap();
            // The selector must not need a transformed body or an invented
            // completion flag; this does not qualify that expression's lifecycle.
            ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS, &mut value, &mut expression).unwrap();
            ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,
                doc.elements.iter_mut().find(|e| e.id == "result").unwrap(), &mut value).unwrap();
            doc.elements.extend([value, expression]);
            if observed % 2 == 0 { doc.elements.reverse(); }
            assert_eq!(crate::definition_document::materialize_result_feature_defaults(&mut doc, "result", "defaults").unwrap(), 1, "{case}");
            let exported = crate::abstract_syntax_json::export_sysml_abstract_syntax_value(&doc, Default::default()).unwrap();
            assert!(!exported.has_errors());
            let imported = crate::abstract_syntax_json::import_sysml_abstract_syntax_value(exported.value, Default::default()).unwrap();
            assert!(!imported.has_errors());
            for mut model in [doc, imported.persistable_document().unwrap()] {
                let relation = model.elements.iter().find(|e| e.id == "defaults.0").unwrap();
                let general = redefined_reference(&model.elements, relation, "general").unwrap();
                let name = snapshot_qualified_name(&model.elements, general, &mut BTreeSet::new()).unwrap().unwrap();
                assert_eq!(json!([{"kind": "Subsetting", "target": name}]), case["generals"], "{case}");
                let value = model.elements.iter().find(|e| e.id == "value").unwrap();
                assert_eq!((scope_boolean(value, "is_default").unwrap(), scope_boolean(value, "is_initial").unwrap()), (mode & 1 != 0, mode & 2 != 0));
                assert_eq!(definition_reference_targets(&model.elements, value, "value").unwrap()[0].id, "value.expression");
                assert!(!scope_boolean(model.elements.iter().find(|e| e.id == "value.expression").unwrap(), "is_implied_included").unwrap());
                let before = serde_json::to_value(&model).unwrap();
                assert_eq!(crate::definition_document::materialize_result_feature_defaults(&mut model, "result", "replay").unwrap(), 0);
                assert_eq!(serde_json::to_value(&model).unwrap(), before);
            }
            observed += 1;
        }
        assert_eq!(observed, 704); // 64 reference fixture failures stay excluded.
    }

    #[test]
    fn definition_directed_result_valuation_from_source_composes_with_positional_redefinition() {
        for valuation in ["= seed", "default = seed", ":= seed", "default := seed"] {
            let source = format!("standard library package Base {{ feature things; }} standard library package Performances {{ function Evaluation; }} package P {{ feature seed; function G {{ return feature gp; }} function F specializes G {{ return feature fp {valuation}; }} }}");
            let mut doc = crate::definition_document::parse_and_link(&source, crate::SourceLanguage::Kerml).unwrap();
            let named = |name: &str| doc.elements.iter().find(|e| e.properties.get("declared_name") == Some(&json!(name))).unwrap().id.clone();
            let fp = named("fp"); let gp = named("gp"); let things = named("things");
            let feature = doc.elements.iter().find(|e| e.id == fp).unwrap();
            let before = definition_general_type_inputs_query(&doc.elements, feature).unwrap();
            assert_eq!(before, vec![gp.clone(), things]);
            let value = stored_children(&doc.elements, feature, "owned_relationship").unwrap().into_iter().find(|e| metaclass_conforms(&e.kind, "FeatureValue")).unwrap();
            let expression = definition_reference_targets(&doc.elements, value, "value").unwrap()[0].id.clone();
            let expression_before = doc.elements.iter().find(|e| e.id == expression).unwrap().clone();
            assert_eq!(crate::definition_document::materialize_result_feature_defaults(&mut doc, &fp, "result.defaults").unwrap(), 1);
            let exported = crate::abstract_syntax_json::export_sysml_abstract_syntax_value(&doc, Default::default()).unwrap(); assert!(!exported.has_errors());
            let imported = crate::abstract_syntax_json::import_sysml_abstract_syntax_value(exported.value, Default::default()).unwrap(); assert!(!imported.has_errors());
            for mut model in [doc, imported.persistable_document().unwrap()] {
                let feature = model.elements.iter().find(|e| e.id == fp).unwrap();
                assert_eq!(definition_redefined_features(&model.elements, feature, false).unwrap().iter().map(|e| &e.id).collect::<Vec<_>>(), vec![&gp]);
                let mut actual_expression = model.elements.iter().find(|e| e.id == expression).unwrap().clone();
                // The JSON importer adds its own non-Ecore provenance metadata.
                // Every Ecore property, identity, kind and ordered reference is
                // compared unchanged; provenance is assessed by the importer.
                actual_expression.properties.remove("metadata");
                assert_eq!(serde_json::to_value(&actual_expression).unwrap(), serde_json::to_value(&expression_before).unwrap());
                assert!(!scope_boolean(feature, "is_implied_included").unwrap());
                assert_eq!(crate::definition_document::materialize_result_feature_defaults(&mut model, &fp, "replay").unwrap(), 0);
            }
        }
    }

    #[test]
    fn definition_directed_valuation_selection_rejects_malformed_storage_atomically() {
        for membership in ["ParameterMembership", "ReturnParameterMembership"] {
            for boundary in ["missing", "two_expressions", "multiple_values", "wrong_owner", "implied", "invalid_flag"] {
                let mut doc = result_default_fixture("Function", 0);
                doc.elements.iter_mut().find(|e| e.id == "return").unwrap().kind = format!("SysML::{membership}");
                if membership == "ParameterMembership" { doc.elements.iter_mut().find(|e| e.id == "result").unwrap().properties.insert("direction".into(), json!("in")); }
                let mut value = fresh_definition_element("value".into(), "FeatureValue").unwrap();
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, doc.elements.iter_mut().find(|e| e.id == "result").unwrap(), &mut value).unwrap();
                doc.elements.push(value);
                if boundary != "missing" {
                    let mut expression = fresh_definition_element("expression".into(), "LiteralInteger").unwrap();
                    ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS, doc.elements.iter_mut().find(|e| e.id == "value").unwrap(), &mut expression).unwrap();
                    doc.elements.push(expression);
                }
                match boundary {
                    "two_expressions" => { let mut e = fresh_definition_element("second.expression".into(), "LiteralInteger").unwrap(); ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS, doc.elements.iter_mut().find(|e| e.id == "value").unwrap(), &mut e).unwrap(); doc.elements.push(e); },
                    "multiple_values" => { let mut v = fresh_definition_element("second.value".into(), "FeatureValue").unwrap(); ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, doc.elements.iter_mut().find(|e| e.id == "result").unwrap(), &mut v).unwrap(); doc.elements.push(v); },
                    "wrong_owner" => { doc.elements.iter_mut().find(|e| e.id == "value").unwrap().properties.insert("owning_related_element".into(), json!("owner")); },
                    "implied" => { doc.elements.iter_mut().find(|e| e.id == "value").unwrap().properties.insert("is_implied".into(), json!(true)); },
                    "invalid_flag" => { doc.elements.iter_mut().find(|e| e.id == "value").unwrap().properties.insert("is_initial".into(), json!("true")); },
                    _ => {},
                }
                let before = serde_json::to_value(&doc).unwrap();
                let result = if membership == "ReturnParameterMembership" { crate::definition_document::materialize_result_feature_defaults(&mut doc, "result", "defaults") }
                    else { definition_materialize_feature_defaults(&mut doc.elements, &[("result", "defaults")]).map_err(|e| crate::definition_document::DefinitionDocumentError::ConstructionOrLinking(e.message)) };
                assert!(result.is_err(), "{membership} {boundary}");
                assert_eq!(before, serde_json::to_value(&doc).unwrap());
            }
        }
    }

    #[test]
    fn definition_feature_value_constraints_preserve_missing_dependencies_and_storage() {
        for default in [false, true] {
            for variable in [false, true] {
                let source = if default { "package P { feature seed; feature v default := seed; }" } else { "package P { feature seed; feature v := seed; }" };
                let mut doc = crate::definition_document::parse_and_link(source, crate::SourceLanguage::Kerml).unwrap();
                doc.elements.iter_mut().find(|e| e.properties.get("declared_name") == Some(&json!("v"))).unwrap().properties.insert("is_variable".into(), json!(variable));
                let before = serde_json::to_value(&doc).unwrap();
                let issues = crate::definition_document::assess_feature_values(&doc).unwrap();
                assert_eq!(issues.iter().filter(|i| i.constraint == "validateFeatureValueIsInitial" && !i.unverified).count(), if variable { 0 } else { 1 });
                assert!(!issues.iter().any(|i| i.constraint == "validateFeatureValueOverriding"), "a package-owned Feature has no computed owning-type redefinitions");
                assert_eq!(before, serde_json::to_value(&doc).unwrap());
                let exported = crate::abstract_syntax_json::export_sysml_abstract_syntax_value(&doc, Default::default()).unwrap(); assert!(!exported.has_errors());
                let imported = crate::abstract_syntax_json::import_sysml_abstract_syntax_value(exported.value, Default::default()).unwrap(); assert!(!imported.has_errors());
                assert_eq!(issues, crate::definition_document::assess_feature_values(&imported.persistable_document().unwrap()).unwrap());
            }
        }
        let mut dependency_graph = vec![fresh_definition_element("context".into(), "OperatorExpression").unwrap()];
        let mut parameter = fresh_definition_element("parameter".into(), "Feature").unwrap(); parameter.properties.insert("direction".into(), json!("in"));
        cross_test_own(&mut dependency_graph, "context", "ParameterMembership", parameter);
        let mut value = fresh_definition_element("value".into(), "FeatureValue").unwrap();
        let mut literal = fresh_definition_element("literal".into(), "LiteralInteger").unwrap();
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS, &mut value, &mut literal).unwrap();
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, dependency_graph.iter_mut().find(|e| e.id == "parameter").unwrap(), &mut value).unwrap();
        dependency_graph.extend([value, literal]);
        let unknown = definition_assess_feature_values(&dependency_graph).unwrap();
        assert!(unknown.iter().any(|i| i.constraint == "validateFeatureValueOverriding" && i.unverified), "unavailable redefinition algorithm must not pass: {unknown:?}");
        let mut graph = bound_value_fixture("first_default");
        let issues = definition_assess_feature_values(&graph).unwrap();
        assert_eq!(issues.iter().filter(|i| i.constraint == "FeatureValue.singleValuation" && !i.unverified).count(), 2);
        graph.iter_mut().find(|e| e.id == "value").unwrap().properties.insert("owning_related_element".into(), json!("expression"));
        assert!(definition_assess_feature_values(&graph).is_err());
    }

    #[test]
    fn definition_feature_value_overriding_reads_transitive_native_redefinitions() {
        for default in [false, true] {
            let source = format!("package P {{ feature seed; feature base {}= seed; feature middle redefines base default = seed; feature v redefines middle = seed; }}", if default { "default " } else { "" });
            let doc = crate::definition_document::parse_and_link(&source, crate::SourceLanguage::Kerml).unwrap();
            let named = |name: &str| doc.elements.iter().find(|e| e.properties.get("declared_name") == Some(&json!(name))).unwrap().id.clone();
            let middle = named("middle"); let v = named("v");
            let issues = crate::definition_document::assess_feature_values(&doc).unwrap();
            assert!(!issues.iter().any(|i| i.unverified), "{issues:?}");
            let violations = issues.iter().filter(|i| i.constraint == "validateFeatureValueOverriding").map(|i| i.feature_id.clone()).collect::<BTreeSet<_>>();
            assert_eq!(violations, if default { BTreeSet::new() } else { BTreeSet::from([middle, v]) });
            let exported = crate::abstract_syntax_json::export_sysml_abstract_syntax_value(&doc, Default::default()).unwrap(); assert!(!exported.has_errors());
            let imported = crate::abstract_syntax_json::import_sysml_abstract_syntax_value(exported.value, Default::default()).unwrap(); assert!(!imported.has_errors());
            assert_eq!(issues, crate::definition_document::assess_feature_values(&imported.persistable_document().unwrap()).unwrap());
        }
    }

