    // Prepared result storage and resolved owner dispatch are one query stage.
    // These controls do not assert expression transformation or validation.
    #[test]
    fn definition_result_feature_defaults_generated_owner_dispatch_preserves_storage_and_replay() {
        let definition: Value = serde_json::from_str(include_str!("../../../../resources/metamodels/sysml-2.0-pilot-2026-08/result-construction.extract.json")).unwrap();
        let kinds = definition["cases"].as_array().unwrap().iter()
            .map(|case| case["class"].as_str().unwrap()).collect::<BTreeSet<_>>();
        assert_eq!(kinds.len(), 7);
        for kind in kinds { for mask in 0..8 {
            let template = result_default_fixture(kind, mask);
            let mut reversed = template.clone(); reversed.elements.reverse();
            let persisted: crate::KirDocument = serde_json::from_value(serde_json::to_value(&template).unwrap()).unwrap();
            for original in [&template, &reversed, &persisted] {
                let before = serde_json::to_value(original).unwrap();
                let index = original.elements.iter().map(|e| (e.id.as_str(), e)).collect();
                let query = DefinitionNameQuery::new(&original.elements, &index);
                let selected = definition_result_feature_generals_query(&query, index["result"]).unwrap();
                assert_eq!(selected.len(), 1, "{kind} {mask}");
                let expected = feature_defaults_generated::feature_default_name(mask & 2 != 0, mask & 1 != 0, mask & 4 != 0, false, false, false);
                assert_eq!(snapshot_qualified_name(&original.elements, index[selected[0].1.as_str()], &mut BTreeSet::new()).unwrap().as_deref(), Some(expected));
                assert_eq!(definition_result_feature_generals_query(&query, index["result"]).unwrap(), selected);
                assert_eq!(serde_json::to_value(original).unwrap(), before, "getter cannot write storage or completion flags");
                assert!(!scope_boolean(index["result"], "is_implied_included").unwrap());
            }
        }}
    }

    #[test]
    fn definition_result_feature_defaults_generated_dispatch_preserves_dependency_and_rejection() {
        // Chain construction still requires its actual feature target; extending
        // result admission must expose that port rather than invent a target.
        let mut chain = result_default_fixture("FeatureChainExpression", 0);
        let mut reference = fresh_definition_element("chain.reference".into(), "FeatureChaining").unwrap();
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,
            chain.elements.iter_mut().find(|e| e.id == "owner").unwrap(), &mut reference).unwrap();
        chain.elements.push(reference);
        let before = serde_json::to_value(&chain).unwrap();
        let index = chain.elements.iter().map(|e| (e.id.as_str(), e)).collect();
        let query = DefinitionNameQuery::new(&chain.elements, &index);
        assert!(matches!(definition_result_feature_generals_query(&query, index["result"]),
            Err(QueryFailure::Required(Prerequisite::ReadField { owner_id, field }))
                if owner_id == "chain.reference" && field == "chaining_feature"));
        assert_eq!(serde_json::to_value(&chain).unwrap(), before);
        for kind in ["OperatorExpression", "InvocationExpression", "IndexExpression", "CollectExpression", "SelectExpression", "TriggerInvocationExpression"] {
            let template = result_default_fixture(kind, 4);
            for mutation in ["pending_type", "wrong_type", "direction", "end", "variable", "composite", "portion", "membership", "owner"] {
                let mut doc = template.clone();
                match mutation {
                    "pending_type" => { doc.elements.iter_mut().find(|e| e.id == "typing.4").unwrap().properties.remove("type"); },
                    "wrong_type" => { doc.elements.iter_mut().find(|e| e.id == "typing.4").unwrap().properties.insert("type".into(), json!(false)); },
                    "direction" => { doc.elements.iter_mut().find(|e| e.id == "result").unwrap().properties.insert("direction".into(), json!("in")); },
                    "end" | "variable" | "composite" | "portion" => { doc.elements.iter_mut().find(|e| e.id == "result").unwrap().properties.insert(format!("is_{mutation}"), json!(true)); },
                    "membership" => { doc.elements.iter_mut().find(|e| e.id == "return").unwrap().kind = "SysML::ParameterMembership".into(); },
                    _ => { doc.elements.iter_mut().find(|e| e.id == "owner").unwrap().kind = "SysML::ConstructorExpression".into(); },
                }
                let before = serde_json::to_value(&doc).unwrap();
                let index = doc.elements.iter().map(|e| (e.id.as_str(), e)).collect();
                let query = DefinitionNameQuery::new(&doc.elements, &index);
                let failure = definition_result_feature_generals_query(&query, index["result"]).unwrap_err();
                if mutation == "pending_type" {
                    assert!(matches!(failure, QueryFailure::Required(Prerequisite::ReadField { owner_id, field }) if owner_id == "typing.4" && field == "type"));
                } else { assert!(matches!(failure, QueryFailure::Rejected(_)), "{kind} {mutation}"); }
                assert_eq!(serde_json::to_value(&doc).unwrap(), before);
            }
        }
    }

    // Prepared bounded query controls; they do not qualify real prototype lifecycle.
    #[test]
    fn definition_value_result_queries_preserve_pending_typing_and_reject_invalid_storage() {
        for owner_kind in ["Function", "Predicate", "Expression", "FeatureReferenceExpression"] {
            for bit in [1, 2, 4] {
                let template = result_default_fixture(owner_kind, bit);
                let typing_id = format!("typing.{bit}");
                for storage in [None, Some(Value::Null), Some(json!(false)), Some(json!("absent")), Some(json!("return"))] {
                    let mut doc = template.clone();
                    let typing = doc.elements.iter_mut().find(|e| e.id == typing_id).unwrap();
                    if let Some(value) = &storage { typing.properties.insert("type".into(), value.clone()); }
                    else { typing.properties.remove("type"); }
                    let index = doc.elements.iter().map(|e| (e.id.as_str(), e)).collect::<BTreeMap<_, _>>();
                    let query = DefinitionNameQuery::new(&doc.elements, &index);
                    let result = index["result"];
                    let before = serde_json::to_value(&doc).unwrap();
                    for _ in 0..2 {
                        let failures = [
                            definition_result_feature_generals_query(&query, result).unwrap_err(),
                            definition_general_type_inputs_with_view(&query, result, "").unwrap_err(),
                            definition_feature_types_query(&doc.elements, result).unwrap_err(),
                        ];
                        for failure in failures {
                            if storage.is_none() {
                                assert!(matches!(failure, QueryFailure::Required(Prerequisite::ReadField { owner_id, field })
                                    if owner_id == typing_id && field == "type"), "{owner_kind} {bit}");
                            } else { assert!(matches!(failure, QueryFailure::Rejected(_)), "{owner_kind} {bit}"); }
                        }
                    }
                    assert_eq!(before, serde_json::to_value(&doc).unwrap(), "query failure cannot mutate or cache completion");
                }
            }
        }
    }

    #[test]
    fn definition_value_result_queries_preserve_positional_and_library_alias_dependencies() {
        for library_alias in [false, true] {
            let mut doc = result_default_fixture("Function", 4);
            let (dependency, field, target) = if library_alias {
                let role_id = doc.elements.iter().find(|e| e.properties.get("declared_name") == Some(&json!("dataValues"))).unwrap().id.clone();
                let member_id = doc.elements.iter().find(|e| e.id == role_id).unwrap().properties["owning_relationship"].as_str().unwrap().to_owned();
                let member = doc.elements.iter_mut().find(|e| e.id == member_id).unwrap();
                member.kind = "SysML::Membership".into(); member.properties.remove("owned_related_element");
                member.properties.insert("member_name".into(), json!("dataValues"));
                member.properties.remove("member_element");
                doc.elements.iter_mut().find(|e| e.id == role_id).unwrap().properties.remove("owning_relationship");
                (member_id, "member_element", role_id)
            } else {
                let mut general = fresh_definition_element("general".into(), "Function").unwrap();
                general.properties.insert("is_implied_included".into(), json!(true));
                doc.elements.push(general);
                let mut result = fresh_definition_element("general.result".into(), "Feature").unwrap();
                result.properties.insert("direction".into(), json!("out"));
                let mut member = fresh_definition_element("general.return".into(), "ReturnParameterMembership").unwrap();
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS, &mut member, &mut result).unwrap();
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, doc.elements.iter_mut().find(|e| e.id == "general").unwrap(), &mut member).unwrap();
                doc.elements.extend([member, result]);
                let mut relation = fresh_definition_element("owner.general".into(), "Subclassification").unwrap();
                relation.properties.insert("subclassifier".into(), json!("owner"));
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, doc.elements.iter_mut().find(|e| e.id == "owner").unwrap(), &mut relation).unwrap();
                doc.elements.push(relation);
                ("owner.general".into(), "superclassifier", "general".into())
            };
            let before = serde_json::to_value(&doc).unwrap();
            let index = doc.elements.iter().map(|e| (e.id.as_str(), e)).collect::<BTreeMap<_, _>>();
            let query = DefinitionNameQuery::new(&doc.elements, &index);
            for _ in 0..2 {
                let failure = definition_result_feature_generals_query(&query, index["result"]).unwrap_err();
                assert!(matches!(failure, QueryFailure::Required(Prerequisite::ReadField { owner_id, field: required })
                    if owner_id == dependency && required == field), "library_alias={library_alias}; expected {dependency}.{field}");
            }
            assert_eq!(before, serde_json::to_value(&doc).unwrap());
            drop(query); drop(index);
            doc.elements.iter_mut().find(|e| e.id == dependency).unwrap().properties.insert(field.into(), json!(target));
            let index = doc.elements.iter().map(|e| (e.id.as_str(), e)).collect::<BTreeMap<_, _>>();
            let query = DefinitionNameQuery::new(&doc.elements, &index);
            let generals = definition_result_feature_generals_query(&query, index["result"]).unwrap();
            if library_alias { assert_eq!(generals, [("Subsetting", target)]); }
            else { assert_eq!(generals[0], ("Redefinition", "general.result".into())); }
            assert!(!scope_boolean(index["result"], "is_implied_included").unwrap());
            if let Some(prototype_result) = index.get("general.result") { assert!(!scope_boolean(prototype_result, "is_implied_included").unwrap(), "no prototype result completion is inferred"); }
        }
    }

    #[test]
    fn definition_value_result_scheduler_resolves_exact_pending_field_atomically() {
        for boundary in ["success", "unregistered", "cycle", "wrong_type", "late_failure"] {
            let mut doc = result_default_fixture("Function", 4);
            doc.elements.iter_mut().find(|e| e.id == "typing.4").unwrap().properties.remove("type");
            for id in if boundary == "late_failure" { vec!["request", "later"] } else { vec!["request"] } {
                doc.elements.push(fresh_definition_element(id.into(), "Membership").unwrap());
                relative_fixture_attach(&mut doc.elements, "owner", id, true);
            }
            let wanted = [crate::xtext_fragment::PendingReference { span: None, spelling: "result".into(), target_type: "https://www.omg.org/spec/SysML/20250201#//Feature".into() }];
            let typing = [crate::xtext_fragment::PendingReference { span: None, spelling: "Data".into(), target_type: "https://www.omg.org/spec/SysML/20250201#//Type".into() }];
            let request = |id: &str| PendingModelLink { owner_id: id.into(), owner_kind: "SysML::Membership".into(), feature: ecore_model::feature("Membership", "member_element").unwrap(), references: &wanted, ancestors: vec![] };
            let mut pending = vec![request("request")];
            if boundary != "unregistered" { pending.push(PendingModelLink { owner_id: "typing.4".into(), owner_kind: "SysML::FeatureTyping".into(), feature: ecore_model::feature("FeatureTyping", "type").unwrap(), references: &typing, ancestors: vec![] }); }
            if boundary == "late_failure" { pending.push(request("later")); }
            let events = std::cell::RefCell::new(Vec::new());
            let before = serde_json::to_value(&doc).unwrap();
            let answer = link_generated_graph(doc.elements.clone(), pending, &|site| {
                events.borrow_mut().push(site.owner_id.to_owned());
                if site.owner_id == "typing.4" {
                    if boundary == "cycle" { return Ok(GeneratedLinkTarget::Deferred { owner_id: "request".into(), field: "member_element".into() }); }
                    return Ok(GeneratedLinkTarget::Local(if boundary == "wrong_type" { "return" } else { "typing.target.4" }.into()));
                }
                if site.owner_id == "later" { return Err(error("explicit late rejection")); }
                let index = site.graph.iter().map(|e| (e.id.as_str(), e)).collect::<BTreeMap<_, _>>();
                let query = DefinitionNameQuery::new(site.graph, &index);
                match definition_result_feature_generals_query(&query, index["result"]) {
                    Ok(_) => Ok(GeneratedLinkTarget::Local("result".into())),
                    Err(failure) => query_link_target(failure),
                }
            }, false);
            assert_eq!(before, serde_json::to_value(&doc).unwrap(), "{boundary}: staging cannot mutate supplied graph");
            if boundary == "success" {
                let graph = answer.unwrap();
                assert_eq!(*events.borrow(), ["request", "typing.4", "request"]);
                assert_eq!(graph.iter().find(|e| e.id == "request").unwrap().properties["member_element"], json!("result"));
                assert_eq!(graph.iter().find(|e| e.id == "typing.4").unwrap().properties["type"], json!("typing.target.4"));
                assert!(!scope_boolean(graph.iter().find(|e| e.id == "result").unwrap(), "is_implied_included").unwrap());
                assert!(ecore_model::validate_publication(&graph, ecore_model::ReferenceCompleteness::Closed).is_empty());
                let document = crate::KirDocument { metadata: BTreeMap::new(), elements: graph };
                let exported = crate::abstract_syntax_json::export_sysml_abstract_syntax_value(&document, Default::default()).unwrap();
                assert!(!exported.has_errors());
                let imported = crate::abstract_syntax_json::import_sysml_abstract_syntax_value(exported.value, Default::default()).unwrap();
                assert!(!imported.has_errors());
                let persisted = imported.persistable_document().unwrap();
                let result = persisted.elements.iter().find(|e| e.id == "result").unwrap();
                assert_eq!(definition_feature_types_query(&persisted.elements, result).unwrap()[0].id, "typing.target.4");
            } else {
                let failure = answer.unwrap_err();
                let expected = match boundary { "unregistered" => "not pending", "cycle" => "dependency cycle", "wrong_type" => "violates Xtext target type", _ => "explicit late rejection" };
                assert!(failure.message.contains(expected), "{boundary}: {failure:?}");
            }
        }
    }

    #[test]
    fn definition_result_default_rejection_preserves_dependency_and_request_identities_atomically() {
        let mut doc = result_default_fixture("Function", 1);
        cross_test_own(&mut doc.elements, "result", "OwningMembership",
            fresh_definition_element("unsupported".into(), "Feature").unwrap());
        let before = serde_json::to_value(&doc).unwrap();
        let failure = definition_materialize_result_feature_defaults(&mut doc.elements, "result", "defaults").unwrap_err();
        assert_eq!(before, serde_json::to_value(&doc).unwrap());
        assert_eq!(failure.subjects, ["result", "unsupported.member"]);
        for context in ["service=result-feature-defaults", "owner_id=result", "owner_kind=SysML::Feature",
            "field=owned_relationship ordinal=1", "relationship_id=unsupported.member",
            "relationship_kind=SysML::OwningMembership"] {
            assert!(failure.message.contains(context), "missing {context}: {failure:?}");
        }

        for id in ["early.request", "original.request", "request"] {
            doc.elements.push(fresh_definition_element(id.into(), "Membership").unwrap());
            relative_fixture_attach(&mut doc.elements, "owner", id, true);
        }
        let references = [crate::xtext_fragment::PendingReference {
            span: None, spelling: "result".into(),
            target_type: "https://www.omg.org/spec/SysML/20250201#//Feature".into(),
        }];
        let before = serde_json::to_value(&doc).unwrap();
        for deferred in [false, true] {
            let requests = if deferred { vec!["early.request", "original.request", "request"] }
                else { vec!["early.request", "request"] };
            let pending = requests.into_iter().map(|id| PendingModelLink {
                owner_id: id.into(), owner_kind: "SysML::Membership".into(),
                feature: ecore_model::feature("Membership", "member_element").unwrap(),
                references: &references, ancestors: vec![],
            }).collect();
            let calls = std::cell::Cell::new(0);
            let linked = link_generated_graph(doc.elements.clone(), pending, &|site| {
                calls.set(calls.get() + 1);
                if site.owner_id == "early.request" { return Ok(GeneratedLinkTarget::Local("result".into())); }
                if site.owner_id == "original.request" {
                    return Ok(GeneratedLinkTarget::Deferred { owner_id: "request".into(), field: "member_element".into() });
                }
                assert_eq!(site.graph.iter().find(|e| e.id == "early.request").unwrap().properties["member_element"], json!("result"));
                let result = site.graph.iter().find(|e| e.id == "result").unwrap();
                Err(definition_validate_result_feature_inputs(site.graph, result).unwrap_err().with_subject("result"))
            }, false).unwrap_err();
            assert_eq!(calls.get(), if deferred { 3 } else { 2 }, "the rejected prerequisite must not schedule another attempt");
            assert_eq!(before, serde_json::to_value(&doc).unwrap(), "a late linker rejection must not publish staged writes");
            let mut subjects = vec!["result", "unsupported.member", "request"];
            let mut message = format!("{}; generated link requester_id=request requester_kind=SysML::Membership requester_field=member_element", failure.message);
            if deferred {
                subjects.push("original.request");
                message.push_str("; original_requester_id=original.request original_requester_kind=SysML::Membership original_requester_field=member_element");
            }
            assert_eq!(linked.subjects, subjects);
            assert_eq!(linked.kind, failure.kind);
            assert_eq!(linked.span, failure.span);
            assert_eq!(linked.message, message);
        }
    }

