    #[test]
    fn definition_expression_owned_binding_preserves_dependency_boundaries() {
        let artifact:Value=serde_json::from_str(include_str!("../../../../resources/metamodels/sysml-2.0-pilot-2026-08/compatibility.extract.json")).unwrap();
        let case=&artifact["expression_defaults"]["library_result_case"];
        let mut original=crate::definition_document::parse_and_link(case["source"].as_str().unwrap(),crate::SourceLanguage::Kerml).unwrap();
        let expression=original.elements.iter().find(|e|e.kind.ends_with("::FeatureReferenceExpression")).unwrap().id.clone();
        crate::definition_document::materialize_expression_result(&mut original,&expression,"result.member","result").unwrap();
        for shape in ["end_namespace","variable_binding","composite_binding","feature_membership","unknown_binding_general","unknown_end_general"] {
            let mut doc=original.clone();
            if shape.starts_with("unknown") {
                crate::definition_document::materialize_reference_binding_defaults(&mut doc,&expression,"binding").unwrap();
                let wrong=doc.elements.iter().find(|e|e.properties.get("declared_name")==Some(&json!("libraryResult"))).unwrap().id.clone();
                let owner=if shape=="unknown_binding_general" {"binding"}else{"binding.end.0"};
                let mut relation=fresh_definition_element("unknown".into(),"Subsetting").unwrap();
                relation.properties.insert("is_implied".into(),json!(true));relation.properties.insert("subsetting_feature".into(),json!(owner));relation.properties.insert("subsetted_feature".into(),json!(wrong));
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,doc.elements.iter_mut().find(|e|e.id==owner).unwrap(),&mut relation).unwrap();doc.elements.push(relation);
                let before=serde_json::to_value(&doc).unwrap();
                if shape=="unknown_end_general" {
                    let end=doc.elements.iter().find(|e|e.id==owner).unwrap();
                    assert!(definition_redefined_features(&doc.elements,end,false).is_err(),"{shape}");
                } else {
                    let binding=doc.elements.iter().find(|e|e.id=="binding").unwrap();
                    assert!(definition_reference_targets(&doc.elements,binding,"related_feature").is_err(),"{shape}");
                }
                assert_eq!(before,serde_json::to_value(&doc).unwrap());
            } else {
                crate::definition_document::materialize_reference_binding(&mut doc,&expression,"binding").unwrap();
                match shape {
                    "end_namespace"=>{doc.elements.iter_mut().find(|e|e.id==expression).unwrap().properties.insert("is_end".into(),json!(true));},
                    "variable_binding"|"composite_binding"=>{doc.elements.iter_mut().find(|e|e.id=="binding").unwrap().properties.insert(if shape=="variable_binding" {"is_variable"}else{"is_composite"}.into(),json!(true));},
                    _=>doc.elements.iter_mut().find(|e|e.id=="binding.membership").unwrap().kind="SysML::FeatureMembership".into(),
                }
                let before=serde_json::to_value(&doc).unwrap();
                assert!(definition_materialize_feature_defaults(&mut doc.elements,&[("binding","defaults")]).is_err(),"{shape}");
                assert_eq!(before,serde_json::to_value(&doc).unwrap());
            }
        }
    }

