    #[test]
    fn definition_value_expression_featuring_rejects_unready_and_rolls_back() {
        for shape in ["variable_owner","complete_expression","wrong_expression","wrong_membership","collision","late_collision","cycle"] {
            let mut document=crate::KirDocument {elements:expression_featuring_fixture("FeatureReferenceExpression","two"),metadata:BTreeMap::new()};
            match shape {
                "variable_owner"=>{let mut owner=document.elements.iter().find(|e|e.id=="owner").unwrap().clone();owner.properties.insert("is_implied_included".into(),json!(false));owner.properties.insert("is_variable".into(),json!(true));document.elements.retain(|e|e.id!="owner");cross_test_own(&mut document.elements,"a","FeatureMembership",owner);},
                "complete_expression"=>{document.elements.iter_mut().find(|e|e.id=="expression").unwrap().properties.insert("is_implied_included".into(),json!(true));},
                "wrong_expression"=>document.elements.iter_mut().find(|e|e.id=="expression").unwrap().kind="SysML::Feature".into(),
                "wrong_membership"=>document.elements.iter_mut().find(|e|e.id=="value").unwrap().kind="SysML::OwningMembership".into(),
                "collision"|"late_collision"=>document.elements.push(fresh_definition_element(if shape=="collision" {"inserted.0"}else{"inserted.1"}.into(),"Feature").unwrap()),
                _=>{document.elements.iter_mut().find(|e|e.id=="owner.featuring.1").unwrap().properties.insert("featuring_type".into(),json!("owner"));},
            }
            let before=serde_json::to_value(&document).unwrap();
            assert!(crate::definition_document::materialize_value_expression_featuring(&mut document,"expression","inserted").is_err(),"{shape}");
            assert_eq!(before,serde_json::to_value(&document).unwrap(),"{shape}");
        }
        let mut document=crate::definition_document::parse_and_link("package P { class A { feature y; feature x = y; } }",crate::SourceLanguage::Kerml).unwrap();
        let id=document.elements.iter().find(|e|e.kind.ends_with("::FeatureReferenceExpression")).unwrap().id.clone();
        assert_eq!(crate::definition_document::materialize_value_expression_featuring(&mut document,&id,"inserted").unwrap(),1);
        let exported=crate::abstract_syntax_json::export_sysml_abstract_syntax_value(&document,Default::default()).unwrap();assert!(!exported.has_errors());
        let imported=crate::abstract_syntax_json::import_sysml_abstract_syntax_value(exported.value,Default::default()).unwrap();assert!(!imported.has_errors());
        for doc in [&document,&imported.persistable_document().unwrap()] {
            let class=doc.elements.iter().find(|e|e.properties.get("declared_name")==Some(&json!("A"))).unwrap();
            let expression=doc.elements.iter().find(|e|e.id==id).unwrap();
            let featuring=definition_owned_type_featuring(&doc.elements,expression).unwrap();
            assert_eq!(featuring.len(),1);
            assert_eq!(redefined_reference(&doc.elements,featuring[0],"featuring_type").unwrap().id,class.id);
            assert!(!scope_boolean(expression,"is_implied_included").unwrap());
            let owner=doc.elements.iter().find(|e|e.properties.get("declared_name")==Some(&json!("x"))).unwrap();
            assert!(!scope_boolean(owner,"is_implied_included").unwrap());
        }
    }

    #[test]
    fn definition_valuation_assessment_checks_written_all_value_rule() {
        for shape in ["none","ordinary","default","initial","explicit_general","implied_general","directional"] {
            let mut graph=bound_value_fixture(shape);
            // Controlled complete ancestry isolates the written predicate from
            // the still-open expression/Feature transformation algorithms.
            for node in &mut graph {if metaclass_conforms(&node.kind,"Type") {
                node.properties.insert("is_implied_included".into(),json!(true));
            }}
            let expected=if matches!(shape,"ordinary"|"default"|"initial"|"implied_general") {1} else {0};
            let mut document=crate::KirDocument {elements:graph,metadata:BTreeMap::new()};
            let before=serde_json::to_value(&document).unwrap();
            let issues=crate::definition_document::assess_valuation_specialization(&document).unwrap();
            assert_eq!(issues.len(),expected,"{shape}");
            if expected==1 {
                assert_eq!((&*issues[0].feature_id,&*issues[0].valuation_id,&*issues[0].result_id),("owner","value","result"));
                definition_append_implied_specialization(&mut document.elements,"satisfied","Subsetting","owner","result").unwrap();
                assert!(crate::definition_document::assess_valuation_specialization(&document).unwrap().is_empty());
            } else {assert_eq!(before,serde_json::to_value(&document).unwrap());}
            let exported=crate::abstract_syntax_json::export_sysml_abstract_syntax_value(&document,Default::default()).unwrap();
            assert!(!exported.has_errors());
            let imported=crate::abstract_syntax_json::import_sysml_abstract_syntax_value(exported.value,Default::default()).unwrap();
            assert!(!imported.has_errors());
            assert!(crate::definition_document::assess_valuation_specialization(&imported.persistable_document().unwrap()).unwrap().is_empty());
        }
        let mut graph=bound_value_fixture("default");
        let mut second=fresh_definition_element("second".into(),"FeatureValue").unwrap();
        let mut expression=fresh_definition_element("second.expression".into(),"FeatureReferenceExpression").unwrap();
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS,&mut second,&mut expression).unwrap();
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,graph.iter_mut().find(|e|e.id=="owner").unwrap(),&mut second).unwrap();
        graph.extend([second,expression]);
        definition_materialize_expression_result(&mut graph,"second.expression","second.return","second.result").unwrap();
        for node in &mut graph {if metaclass_conforms(&node.kind,"Type") {node.properties.insert("is_implied_included".into(),json!(true));}}
        let mut document=crate::KirDocument {elements:graph,metadata:BTreeMap::new()};
        assert_eq!(crate::definition_document::assess_valuation_specialization(&document).unwrap().len(),2);
        definition_append_implied_specialization(&mut document.elements,"first.satisfied","Subsetting","owner","result").unwrap();
        let issues=crate::definition_document::assess_valuation_specialization(&document).unwrap();
        assert_eq!(issues.len(),1);assert_eq!(issues[0].valuation_id,"second");
        definition_append_implied_specialization(&mut document.elements,"second.satisfied","Subsetting","owner","second.result").unwrap();
        assert!(crate::definition_document::assess_valuation_specialization(&document).unwrap().is_empty());
    }

