    #[test]
    fn definition_ordinary_completion_is_transactional_and_context_bounded() {
        let document=crate::definition_document::parse_and_link("standard library package Base { feature things; } package P { class A { feature x; feature y; } }",crate::SourceLanguage::Kerml).unwrap();
        let named=|name: &str|document.elements.iter().find(|e|e.properties.get("declared_name")==Some(&json!(name))).unwrap().id.clone();
        let x=named("x");let y=named("y");let owner=named("A");let library=named("things");
        for context in ["is_variable","is_end","is_implied_included","direction","owner","library","late_collision","duplicate"] {
            let mut graph=document.elements.clone();
            match context {
                "direction"=>{graph.iter_mut().find(|e|e.id==y).unwrap().properties.insert("direction".into(),json!("in"));},
                "owner"=>graph.iter_mut().find(|e|e.id==owner).unwrap().kind="SysML::Structure".into(),
                "library"=>{graph.iter_mut().find(|e|e.id==library).unwrap().properties.insert("declared_name".into(),json!("missing"));},
                "late_collision"=>graph.push(fresh_definition_element("y.complete.featuring".into(),"Feature").unwrap()),
                "duplicate"=>{},
                field=>{graph.iter_mut().find(|e|e.id==y).unwrap().properties.insert(field.into(),json!(true));},
            }
            let before=serde_json::to_value(&graph).unwrap();
            let second=if context=="duplicate" {x.as_str()}else{y.as_str()};
            assert!(definition_complete_ordinary_features(&mut graph,&[(&x,"x.complete"),(second,"y.complete")]).is_err(),"{context}");
            assert_eq!(serde_json::to_value(&graph).unwrap(),before,"{context}");
        }
        let mut graph=document.elements.clone();
        definition_complete_ordinary_features(&mut graph,&[(&x,"x.complete"),(&y,"y.complete")]).unwrap();
        for id in [&x,&y] {
            let feature=graph.iter().find(|e|e.id==*id).unwrap();
            assert!(scope_boolean(feature,"is_implied_included").unwrap());
            assert!(definition_specializes(&graph,feature,graph.iter().find(|e|e.id==library).unwrap()).unwrap());
        }
        assert!(!scope_boolean(graph.iter().find(|e|e.id==owner).unwrap(),"is_implied_included").unwrap());
    }

    #[test]
    fn definition_complete_binding_preserves_existing_state_and_rejects_unqualified_branches() {
        let source="standard library package Base { feature things; } standard library package Links { assoc Link { feature participant; } feature selfLinks; } package P { class A { feature x; feature y; } class B; }";
        let doc=crate::definition_document::parse_and_link(source,crate::SourceLanguage::Kerml).unwrap();
        let named=|name: &str|doc.elements.iter().find(|e|e.properties.get("declared_name")==Some(&json!(name))).unwrap().id.clone();
        let owner=named("B");let x=named("x");let y=named("y");let library=named("selfLinks");
        for excluded in ["FeatureValue","CrossSubsetting","Conjugation","MetadataFeature","Annotation","Expression","AssignmentActionUsage",
            "variable","endpoint_kind","owner_kind","missing_library","late_collision","nested_feature"] {
            let mut graph=doc.elements.clone();
            match excluded {
                "variable"=>{graph.iter_mut().find(|e|e.id==x).unwrap().properties.insert("is_variable".into(),json!(true));},
                "endpoint_kind"=>graph.iter_mut().find(|e|e.id==x).unwrap().kind="SysML::ReferenceUsage".into(),
                "owner_kind"=>graph.iter_mut().find(|e|e.id==owner).unwrap().kind="SysML::Type".into(),
                "missing_library"=>{graph.iter_mut().find(|e|e.id==library).unwrap().properties.insert("declared_name".into(),json!("missing"));},
                "late_collision"=>graph.push(fresh_definition_element("binding.end.1.featuring".into(),"Feature").unwrap()),
                "nested_feature"=>{
                    let mut member=fresh_definition_element("nested.member".into(),"FeatureMembership").unwrap();
                    let mut feature=fresh_definition_element("nested.feature".into(),"Feature").unwrap();
                    ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS,&mut member,&mut feature).unwrap();
                    ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,graph.iter_mut().find(|e|e.id==x).unwrap(),&mut member).unwrap();
                    graph.extend([member,feature]);
                },
                kind=>graph.push(fresh_definition_element("excluded".into(),kind).unwrap()),
            }
            let before=serde_json::to_value(&graph).unwrap();
            assert!(definition_materialize_complete_binding(&mut graph,&owner,"binding",&x,&y).is_err(),"{excluded}");
            assert_eq!(serde_json::to_value(&graph).unwrap(),before,"{excluded}");
        }
        let mut graph=doc.elements.clone();
        definition_materialize_complete_binding(&mut graph,&owner,"binding",&x,&y).unwrap();
        for original in &doc.elements {
            let actual=graph.iter().find(|e|e.id==original.id).unwrap();
            if original.id==owner {
                assert_eq!(scope_boolean(actual,"is_implied_included").unwrap(),scope_boolean(original,"is_implied_included").unwrap());
            } else {assert_eq!(serde_json::to_value(actual).unwrap(),serde_json::to_value(original).unwrap());}
        }
        let connector=graph.iter().find(|e|e.id=="binding").unwrap();
        assert_eq!(definition_reference_targets(&graph,connector,"source").unwrap().iter().map(|e|e.id.as_str()).collect::<Vec<_>>(),[x.as_str()]);
        assert_eq!(definition_reference_targets(&graph,connector,"target").unwrap().iter().map(|e|e.id.as_str()).collect::<Vec<_>>(),[y.as_str()]);
    }

    #[test]
    fn definition_implied_inclusion_rejects_invalid_inputs_without_mutation() {
        let root=fresh_definition_element("root".into(),"Namespace").unwrap();
        let document=crate::KirDocument { elements:vec![root], metadata:BTreeMap::new() };
        assert!(crate::definition_document::assess_implied_inclusion(&document).unwrap().is_empty());
        for shape in ["boolean", "missing", "duplicate", "unknown"] {
            let mut invalid=document.clone();
            match shape {
                "boolean"=>{invalid.elements[0].properties.insert("is_implied_included".into(),json!("true"));},
                "missing"=>{invalid.elements[0].properties.insert("owned_relationship".into(),json!(["missing"]));},
                "duplicate"=>invalid.elements.push(invalid.elements[0].clone()),
                _=>invalid.elements[0].kind="SysML::NotAnElement".into(),
            }
            let before=serde_json::to_value(&invalid).unwrap();
            assert!(crate::definition_document::assess_implied_inclusion(&invalid).is_err(),"{shape}");
            assert_eq!(serde_json::to_value(&invalid).unwrap(),before);
        }
    }

    #[test]
    fn definition_implied_inclusion_matches_pilot_across_concrete_classes() {
        let artifact: Value=serde_json::from_str(include_str!("../../../../resources/metamodels/sysml-2.0-pilot-2026-08/compatibility.extract.json")).unwrap();
        let cases=artifact["inclusion_cases"].as_array().unwrap();
        assert_eq!(cases.len(),1670);
        for case in cases {
            let mut owner=fresh_definition_element("owner".into(),case["kind"].as_str().unwrap()).unwrap();
            owner.properties.insert("is_implied_included".into(),case["complete"].clone());
            let shape=case["shape"].as_str().unwrap();
            let mut graph=Vec::new();
            if shape!="empty" {
                let mut relation=fresh_definition_element("relation".into(),"Membership").unwrap();
                relation.properties.insert("is_implied".into(),json!(matches!(shape,"implied"|"mixed")));
                if shape=="nested" {
                    let mut nested=fresh_definition_element("nested".into(),"Membership").unwrap();
                    nested.properties.insert("is_implied".into(),json!(true));
                    ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,&mut relation,&mut nested).unwrap();
                    graph.push(nested);
                }
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,&mut owner,&mut relation).unwrap();
                graph.push(relation);
                if shape=="mixed" {
                    let mut explicit=fresh_definition_element("explicit".into(),"Membership").unwrap();
                    ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,&mut owner,&mut explicit).unwrap();
                    graph.push(explicit);
                }
            }
            graph.push(owner);
            let document=crate::KirDocument { elements:graph, metadata:BTreeMap::new() };
            let before=serde_json::to_value(&document).unwrap();
            let issues=crate::definition_document::assess_implied_inclusion(&document).unwrap();
            let owner_issues=issues.iter().filter(|i|i.element_id=="owner").map(|_|"validateElementIsImpliedIncluded").collect::<Vec<_>>();
            assert_eq!(json!(owner_issues),case["issues"],"{case}");
            if shape=="nested" {
                assert_eq!(issues.len(),1);
                assert_eq!(issues[0].element_id,"relation");
                assert_eq!(issues[0].implied_relationship_ids,["nested"]);
            }
            assert_eq!(serde_json::to_value(&document).unwrap(),before);
        }
    }

    fn binding_stage_snapshot(graph: &[KirElement], feature: &KirElement, root: &str, result_id: Option<&str>) -> Value {
            let relationships=stored_children(graph,feature,"owned_relationship").unwrap();
            let generals=relationships.iter().filter(|r|metaclass_conforms(&r.kind,"Specialization")).map(|r| {
                let target=redefined_reference(graph,r,"general").unwrap();
                json!({"kind":r.kind.rsplit("::").next().unwrap(),"target":if result_id==Some(target.id.as_str()) {json!("$result")}else{target.properties["declared_name"].clone()},"implied":r.properties.get("is_implied").and_then(Value::as_bool).unwrap_or(false)})
            }).collect::<Vec<_>>();
            let featuring=definition_owned_type_featuring(graph,feature).unwrap().iter().map(|r| {
                let target=redefined_reference(graph,r,"featuring_type").unwrap();
                if target.id==root {json!("$binding")}else{target.properties["declared_name"].clone()}
            }).collect::<Vec<_>>();
            json!({"kind":feature.kind.rsplit("::").next().unwrap(),"complete":scope_boolean(feature,"is_implied_included").unwrap(),"implied":feature.properties.get("is_implied").and_then(Value::as_bool).unwrap_or(false),"end":scope_boolean(feature,"is_end").unwrap(),"generals":generals,"featuring":featuring,"relationships":relationships.iter().map(|r|r.kind.rsplit("::").next().unwrap()).collect::<Vec<_>>()})
        }

    fn resolved_binding_fixture(template: &crate::KirDocument, case: &Value) -> (crate::KirDocument, String, String, String) {
        let mut doc = template.clone();
        for e in &mut doc.elements { if metaclass_conforms(&e.kind, "Type") { e.properties.insert("is_implied_included".into(), json!(true)); } }
        let named = |doc: &crate::KirDocument, name: &str| doc.elements.iter().find(|e| e.properties.get("declared_name") == Some(&json!(name))).unwrap().id.clone();
        // Same physically completed library input as the independent producer.
        // These are bounded role fixtures, not the actual pinned library corpus.
        let things = named(&doc, "things");
        for name in ["participant", "selfLinks"] {
            let id = named(&doc, name);
            definition_append_implied_specialization(&mut doc.elements, &format!("library.{name}.base"), "Subsetting", &id, &things).unwrap();
        }
        let participant = named(&doc, "participant"); let link = named(&doc, "Link");
        let mut featuring = fresh_definition_element("library.participant.featuring".into(), "TypeFeaturing").unwrap();
        featuring.properties.insert("feature_of_type".into(), json!(participant)); featuring.properties.insert("featuring_type".into(), json!(link));
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, doc.elements.iter_mut().find(|e|e.id==participant).unwrap(), &mut featuring).unwrap();doc.elements.push(featuring);
        let owner = named(&doc, "Owner");
        if case["owner_kind"] == "TransitionUsage" {
            let index = doc.elements.iter().position(|e| e.id == owner).unwrap();
            let mut fresh = fresh_definition_element(owner.clone(), "TransitionUsage").unwrap();
            for field in ["owning_relationship", "owning_related_element", "owned_relationship", "declared_name"] { if let Some(v) = doc.elements[index].properties.get(field) { fresh.properties.insert(field.into(), v.clone()); } }
            fresh.properties.insert("is_implied_included".into(), json!(true)); doc.elements[index] = fresh;
        }
        let x = named(&doc, "x"); let y = named(&doc, "y");
        for (id, kind) in [(&x,case["first"].as_str().unwrap()),(&y,case["second"].as_str().unwrap())] {
            let index = doc.elements.iter().position(|e| &e.id == id).unwrap();
            let mut fresh = fresh_definition_element(id.clone(), kind).unwrap();
            for field in ["owning_relationship", "owning_related_element", "declared_name"] { if let Some(v) = doc.elements[index].properties.get(field) { fresh.properties.insert(field.into(), v.clone()); } }
            fresh.properties.insert("is_implied_included".into(), json!(true)); fresh.properties.insert("is_portion".into(), json!(true)); fresh.properties.insert("is_composite".into(), json!(false));
            let mut featuring = fresh_definition_element(format!("{id}.explicit.featuring"), "TypeFeaturing").unwrap();
            featuring.properties.insert("feature_of_type".into(), json!(id)); featuring.properties.insert("featuring_type".into(), json!(owner));
            ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, &mut fresh, &mut featuring).unwrap();
            doc.elements[index] = fresh; doc.elements.push(featuring);
        }
        let caller = if case["placement"] == "same" { owner } else { named(&doc, "Other") };
        (doc,caller,x,y)
    }

