    fn definition_fresh_fixed_transition_links_match_full_pilot_lifecycle_and_persistence() {
        let data:Value=serde_json::from_str(include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/../../docs/conformance/2026-08-support/fresh-transition-link-pilot-controls.json"))).unwrap();let cases=data["controls"].as_array().unwrap();assert_eq!(cases.len(),16);let template=crate::definition_document::parse_and_link(cases[0]["source"].as_str().unwrap(),crate::SourceLanguage::Kerml).unwrap();
        for case in cases {
            let mut doc=fresh_transition_link_fixture(&template,case);let old=doc.elements.clone();
            definition_complete_fresh_transition_link(&mut doc.elements,"candidate","fresh").unwrap_or_else(|e|panic!("{case}: {e:?}"));
            let exported=crate::abstract_syntax_json::export_sysml_abstract_syntax_value(&doc,Default::default()).unwrap();assert!(!exported.has_errors());let imported=crate::abstract_syntax_json::import_sysml_abstract_syntax_value(exported.value,Default::default()).unwrap();assert!(!imported.has_errors());let mut restored=imported.persistable_document().unwrap();restored.elements.reverse();
            for model in [&doc,&restored] {
                let target=model.elements.iter().find(|e|e.id=="candidate").unwrap();assert_eq!(binding_stage_snapshot(&model.elements,target,"unused",None),case["after"],"{case}");assert_eq!(json!(generated_effective_names(&model.elements,target).unwrap()[0]),case["name"]);assert_eq!(json!(definition_may_time_vary(&model.elements,target).unwrap()),case["may_time_vary"]);assert_eq!(json!(definition_feature_types(&model.elements,target).unwrap().iter().map(|t|t.properties["declared_name"].clone()).collect::<Vec<_>>()),case["definition"]);
            }
            for e in old {if e.id!="candidate" {assert_eq!(serde_json::to_value(doc.elements.iter().find(|f|f.id==e.id).unwrap()).unwrap(),serde_json::to_value(e).unwrap());}}
            let before=serde_json::to_value(&doc).unwrap();assert!(definition_complete_fresh_transition_link(&mut doc.elements,"candidate","repeat").is_err());assert_eq!(serde_json::to_value(&doc).unwrap(),before);
        }
    }
