    #[test]
    fn definition_fixed_transition_parent_contexts_reject_unproved_dependencies_atomically() {
        let data:Value=serde_json::from_str(include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/../../docs/conformance/2026-08-support/transition-owner-context-pilot-controls.json"))).unwrap();
        let template=crate::definition_document::parse_and_link(data["controls"][0]["source"].as_str().unwrap(),crate::SourceLanguage::Kerml).unwrap();
        for parent_kind in ["ActionDefinition","StateDefinition","ActionUsage","StateUsage"] {
            let case=data["controls"].as_array().unwrap().iter().find(|c|c["parent_kind"]==parent_kind && c["source_action"]==true && c["succession"]==true && c["existing_link"]==false && c["parameters"]==2).unwrap();
            for failure in ["parent_incomplete","missing_performance","incomplete_performance","composite_receiver"] {
                let mut doc=transition_owner_fixture(&template,case);
                let parent=doc.elements.iter().find(|e|e.properties.get("declared_name")==Some(&json!("Owner"))).unwrap().id.clone();
                match failure {
                    "parent_incomplete"=>{doc.elements.iter_mut().find(|e|e.id==parent).unwrap().properties.insert("is_implied_included".into(),json!(false));},
                    "missing_performance"|"incomplete_performance"=>{let role=doc.elements.iter_mut().find(|e|e.properties.get("declared_name")==Some(&json!("enclosedPerformances"))).unwrap();if failure=="missing_performance"{role.properties.insert("declared_name".into(),json!("missing"));}else{role.properties.insert("is_implied_included".into(),json!(false));}},
                    _=>{doc.elements.iter_mut().find(|e|e.id=="transition").unwrap().properties.insert("is_composite".into(),json!(true));},
                }
                let before=serde_json::to_value(&doc).unwrap();assert!(crate::definition_document::complete_fixed_transition_stored_tree(&mut doc,"transition","context").is_err(),"{parent_kind}/{failure}");assert_eq!(serde_json::to_value(&doc).unwrap(),before,"{parent_kind}/{failure}");
            }
        }
    }
    fn verify_transition_stored_cases(data:&Value,contexts:usize,original_children:usize) {
        let cases=data["controls"].as_array().unwrap();assert_eq!(cases.len(),contexts);
        let template=crate::definition_document::parse_and_link(cases[0]["source"].as_str().unwrap(),crate::SourceLanguage::Kerml).unwrap();let mut children=0;
        for case in cases {
            let mut doc=transition_owner_fixture(&template,case);let original=doc.clone();
            for (name,expected) in case["children_before"].as_object().unwrap() {
                let f=doc.elements.iter().find(|e|e.properties.get("declared_name")==Some(&json!(name))).unwrap();
                assert_eq!(binding_stage_snapshot(&doc.elements,f,"unused",None),*expected);children+=1;
            }
            crate::definition_document::complete_fixed_transition_stored_tree(&mut doc,"transition","tree").unwrap_or_else(|e|panic!("{case}: {e:?}"));
            for e in &mut doc.elements {if e.kind.rsplit("::").next()==Some("ReferenceUsage") && !original.elements.iter().any(|old|old.id==e.id){e.properties.insert("declared_name".into(),json!("generatedLink"));}}
            let exported=crate::abstract_syntax_json::export_sysml_abstract_syntax_value(&doc,Default::default()).unwrap();assert!(!exported.has_errors());
            let imported=crate::abstract_syntax_json::import_sysml_abstract_syntax_value(exported.value,Default::default()).unwrap();assert!(!imported.has_errors());let mut persisted=imported.persistable_document().unwrap();persisted.elements.reverse();
            for model in [&doc,&persisted] {
                let owner=model.elements.iter().find(|e|e.id=="transition").unwrap();assert_eq!(binding_stage_snapshot(&model.elements,owner,"unused",None),case["owner_after"],"{case}");
                for (name,expected) in case["children_after"].as_object().unwrap() {let f=model.elements.iter().find(|e|e.properties.get("declared_name")==Some(&json!(name))).unwrap();assert_eq!(binding_stage_snapshot(&model.elements,f,"unused",None),*expected,"child {name}: {case}");}
                assert_eq!(json!(definition_transition_link_feature(&model.elements,owner).unwrap().map(|f|binding_stage_snapshot(&model.elements,f,"unused",None))),case["link_snapshot"]);
                let connectors=stored_children(&model.elements,owner,"owned_relationship").unwrap().iter().filter_map(|m|match stored_membership_endpoint(&model.elements,m,"member_element"){Ok(StoredMembershipEndpoint::Resolved(f)) if metaclass_conforms(&f.kind,"BindingConnector")=>Some(f),_=>None}).collect::<Vec<_>>();assert_eq!(connectors.len(),case["connectors"].as_array().unwrap().len());
                for (b,expected) in connectors.iter().zip(case["connectors"].as_array().unwrap()) {
                    assert_eq!(binding_stage_snapshot(&model.elements,b,&b.id,None),expected["connector"]);
                    for field in ["source","target"] {assert_eq!(json!(definition_reference_targets(&model.elements,b,field).unwrap().iter().map(|e|e.properties["declared_name"].clone()).collect::<Vec<_>>()),expected[field]);}
                    let ends=definition_owned_features(&model.elements,b,true).unwrap();assert_eq!(ends.len(),expected["ends"].as_array().unwrap().len());for (end,expected) in ends.iter().zip(expected["ends"].as_array().unwrap()){assert_eq!(binding_stage_snapshot(&model.elements,end,&b.id,None),*expected);}
                }
                assert!(ecore_model::validate_publication(&model.elements,ecore_model::ReferenceCompleteness::Closed).is_empty());
            }
            let before=serde_json::to_value(&doc).unwrap();assert!(crate::definition_document::complete_fixed_transition_stored_tree(&mut doc,"transition","repeat").is_err());assert_eq!(serde_json::to_value(&doc).unwrap(),before);
        }
        assert_eq!(children,original_children);
    }
