    #[test]
    fn definition_transition_members_match_pilot_connector_branches_and_persist() {
        let data:Value=serde_json::from_str(include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/../../docs/conformance/2026-08-support/transition-members-pilot-controls.json"))).unwrap();let cases=data["controls"].as_array().unwrap();assert_eq!(cases.len(),24);
        let template=crate::definition_document::parse_and_link(cases[0]["source"].as_str().unwrap(),crate::SourceLanguage::Kerml).unwrap();
        for case in cases {
            let mut doc=transition_members_fixture(&template,case);
            definition_materialize_transition_members(&mut doc.elements,"transition","generated").unwrap_or_else(|e|panic!("{case}: {e:?}"));
            if let Some(link)=doc.elements.iter_mut().find(|e|e.id=="generated.link") {link.properties.insert("declared_name".into(),json!("generatedLink"));assert!(!scope_boolean(link,"is_implied_included").unwrap());}
            let exported=crate::abstract_syntax_json::export_sysml_abstract_syntax_value(&doc,Default::default()).unwrap();assert!(!exported.has_errors());
            let imported=crate::abstract_syntax_json::import_sysml_abstract_syntax_value(exported.value,Default::default()).unwrap();assert!(!imported.has_errors());let restored=imported.persistable_document().unwrap();
            for document in [&doc,&restored] {
                let graph=&document.elements;let owner=graph.iter().find(|e|e.id=="transition").unwrap();let link=definition_transition_link_feature(graph,owner).unwrap();assert_eq!(json!(link.and_then(|e|e.properties.get("declared_name"))),case["link"]);
                let bindings=stored_children(graph,owner,"owned_relationship").unwrap().into_iter().filter_map(|m|match stored_membership_endpoint(graph,m,"member_element") {Ok(StoredMembershipEndpoint::Resolved(f)) if metaclass_conforms(&f.kind,"BindingConnector")=>Some((m,f)),_=>None}).collect::<Vec<_>>();assert_eq!(bindings.len(),case["connectors"].as_array().unwrap().len(),"{case}");
                for ((membership,binding),control) in bindings.iter().zip(case["connectors"].as_array().unwrap()) {
                    assert_eq!(membership.kind.rsplit("::").next().unwrap(),control["membership"].as_str().unwrap());
                    for field in ["source","target"] {assert_eq!(json!(definition_reference_targets(graph,binding,field).unwrap().iter().map(|e|e.properties["declared_name"].clone()).collect::<Vec<_>>()),control[field]);}
                    let ends=definition_owned_features(graph,binding,true).unwrap();for (f,expected) in std::iter::once((*binding,&control["connector"])).chain(ends.iter().enumerate().map(|(i,e)|(*e,&control["ends"][i]))) {
                        let actual=binding_stage_snapshot(graph,f,&binding.id,None);assert_eq!(actual,*expected,"{case}");
                    }
                }
                assert!(ecore_model::validate_publication(graph,ecore_model::ReferenceCompleteness::Closed).is_empty());
            }
            let before=serde_json::to_value(&doc).unwrap();definition_materialize_transition_members(&mut doc.elements,"transition","repeat").unwrap();
            let owner=doc.elements.iter().find(|e|e.id=="transition").unwrap();let repeat=stored_children(&doc.elements,owner,"owned_relationship").unwrap().iter().filter(|m|matches!(stored_membership_endpoint(&doc.elements,m,"member_element"),Ok(StoredMembershipEndpoint::Resolved(f)) if metaclass_conforms(&f.kind,"BindingConnector"))).count();assert_eq!(repeat,case["repeat_connector_count"].as_u64().unwrap() as usize);
            if !case["link"].is_null() {assert_eq!(serde_json::to_value(&doc).unwrap(),before);}
        }
    }

    #[test]
    fn definition_transition_linker_structure_matches_pilot_branches_without_completion() {
        let data:Value=serde_json::from_str(include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/../../docs/conformance/2026-08-support/transition-members-pilot-controls.json"))).unwrap();
        let cases=data["controls"].as_array().unwrap();assert_eq!(cases.len(),24);
        let template=crate::definition_document::parse_and_link(cases[0]["source"].as_str().unwrap(),crate::SourceLanguage::Kerml).unwrap();
        for case in cases {
            for reordered in [false,true] {
                let mut doc=transition_members_fixture(&template,case);
                let mut pending=fresh_definition_element("unrelated.pending".into(),"Membership").unwrap();pending.properties.insert("member_element".into(),json!("not.materialized"));doc.elements.push(pending);
                if reordered {doc.elements.reverse();}
                transition_members::materialize_for_linker_query(&mut doc.elements,"transition","private").unwrap_or_else(|e|panic!("{case}: {e:?}"));
                if let Some(link)=doc.elements.iter_mut().find(|e|e.id=="private.link") {link.properties.insert("declared_name".into(),json!("generatedLink"));assert!(!scope_boolean(link,"is_implied_included").unwrap());}
                let restored:crate::KirDocument=serde_json::from_value(serde_json::to_value(&doc).unwrap()).unwrap();
                for document in [&doc,&restored] {
                    let graph=&document.elements;let owner=graph.iter().find(|e|e.id=="transition").unwrap();
                    assert!(scope_boolean(owner,"is_implied_included").unwrap(),"fixture input completion must be preserved, not newly established");
                    let link=definition_transition_link_feature(graph,owner).unwrap();assert_eq!(json!(link.and_then(|e|e.properties.get("declared_name"))),case["link"]);
                    let bindings=stored_children(graph,owner,"owned_relationship").unwrap().into_iter().filter_map(|m|match stored_membership_endpoint(graph,m,"member_element") {Ok(StoredMembershipEndpoint::Resolved(f)) if metaclass_conforms(&f.kind,"BindingConnector")=>Some((m,f)),_=>None}).collect::<Vec<_>>();
                    assert_eq!(bindings.len(),case["connectors"].as_array().unwrap().len(),"{case}");
                    for ((membership,binding),control) in bindings.iter().zip(case["connectors"].as_array().unwrap()) {
                        assert_eq!(membership.kind.rsplit("::").next().unwrap(),control["membership"].as_str().unwrap());
                        for field in ["source","target"] {assert_eq!(json!(definition_reference_targets(graph,binding,field).unwrap().iter().map(|e|e.properties["declared_name"].clone()).collect::<Vec<_>>()),control[field]);}
                        assert!(!scope_boolean(binding,"is_implied_included").unwrap());
                        for end in definition_owned_features(graph,binding,true).unwrap() {assert!(!scope_boolean(end,"is_implied_included").unwrap());}
                    }
                    assert!(ecore_model::validate_publication(graph,ecore_model::ReferenceCompleteness::Partial).is_empty());
                    assert!(!ecore_model::validate_publication(graph,ecore_model::ReferenceCompleteness::Closed).is_empty(),"pending endpoint must still block final publication");
                }
                if !case["link"].is_null() {
                    let before=serde_json::to_value(&doc).unwrap();assert_eq!(transition_members::materialize_for_linker_query(&mut doc.elements,"transition","repeat").unwrap(),0);assert_eq!(serde_json::to_value(&doc).unwrap(),before);
                }
            }
        }
    }

    #[test]
    fn definition_transition_linker_structure_preserves_prerequisites_and_rollback() {
        let data:Value=serde_json::from_str(include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/../../docs/conformance/2026-08-support/transition-members-pilot-controls.json"))).unwrap();
        let case=data["controls"].as_array().unwrap().iter().find(|c|c["source_action"]==true && c["succession"]==true && c["existing_link"]==false && c["parameters"]==1).unwrap();
        let template=crate::definition_document::parse_and_link(case["source"].as_str().unwrap(),crate::SourceLanguage::Kerml).unwrap();
        for failure in ["pending_source","duplicate","direction","prefix","late_identity"] {
            let mut doc=transition_members_fixture(&template,case);doc.elements.iter_mut().find(|e|e.id=="transition").unwrap().properties.insert("is_implied_included".into(),json!(false));
            match failure {
                "pending_source"=>{doc.elements.iter_mut().find(|e|e.id=="source.alias").unwrap().properties.remove("member_element");},
                "duplicate"=>doc.elements.push(doc.elements[0].clone()),
                "direction"=>{doc.elements.iter_mut().find(|e|e.id=="parameter0").unwrap().properties.insert("direction".into(),json!("invalid"));},
                "late_identity"=>{doc.elements.iter_mut().find(|e|e.id=="transition").unwrap().properties.insert("is_implied_included".into(),json!(true));doc.elements.push(fresh_definition_element("private.source-binding".into(),"Feature").unwrap());},_=>{}
            }
            let before=serde_json::to_value(&doc).unwrap();
            for _ in 0..2 {
                let failure_result=transition_members::materialize_for_linker_query(&mut doc.elements,"transition",if failure=="prefix" {""}else{"private"}).unwrap_err();
                if failure=="pending_source" {assert!(matches!(failure_result,QueryFailure::Required(Prerequisite::ReadField {owner_id,field}) if owner_id=="source.alias" && field=="member_element"));}
                assert_eq!(serde_json::to_value(&doc).unwrap(),before,"{failure}");
            }
        }
    }

