    #[test]
    fn definition_resolved_binding_matches_independent_transformation_and_persistence() {
        let artifact: Value = serde_json::from_str(include_str!("../../../../../../docs/conformance/2026-08-support/resolved-binding-pilot-controls.json")).unwrap();
        let cases = artifact["controls"].as_array().unwrap(); assert_eq!(cases.len(),64);
        let template = crate::definition_document::parse_and_link(cases[0]["source"].as_str().unwrap(), crate::SourceLanguage::Kerml).unwrap();
        for case in cases {
            assert_eq!(case["source"],cases[0]["source"]);
            let (mut doc,owner,x,y) = resolved_binding_fixture(&template,case);
            let old = doc.elements.clone();
            for name in ["participant", "selfLinks"] {
                let library = doc.elements.iter().find(|e| e.properties.get("declared_name") == Some(&json!(name))).unwrap();
                assert_eq!(binding_stage_snapshot(&doc.elements, library, "binding", None), case["library_inputs"][name], "{name} library input");
            }
            crate::definition_document::materialize_resolved_binding(&mut doc,&owner,"binding",&x,&y).unwrap_or_else(|e|panic!("{}: {e}",case));
            let exported = crate::abstract_syntax_json::export_sysml_abstract_syntax_value(&doc,Default::default()).unwrap();assert!(!exported.has_errors());
            let imported = crate::abstract_syntax_json::import_sysml_abstract_syntax_value(exported.value,Default::default()).unwrap();assert!(!imported.has_errors());
            let mut replay = imported.persistable_document().unwrap(); replay.elements.reverse();
            for model in [&doc,&replay] {
                let graph = &model.elements;
                assert_eq!(graph.iter().find(|e|e.id=="binding.membership").unwrap().kind.rsplit("::").next().unwrap(),case["membership"].as_str().unwrap());
                for (id,expected) in [("binding",&case["connector"]),("binding.end.0",&case["ends"][0]),("binding.end.1",&case["ends"][1])] {
                    assert_eq!(binding_stage_snapshot(graph,graph.iter().find(|e|e.id==id).unwrap(),"binding",None),*expected,"{case} element={id}");
                }
                let binding = graph.iter().find(|e|e.id=="binding").unwrap();
                for (field,expected) in [("source",&case["source_endpoint"]),("target",&case["target_endpoint"])] {
                    assert_eq!(json!(definition_reference_targets(graph,binding,field).unwrap().iter().map(|e|e.properties["declared_name"].clone()).collect::<Vec<_>>()),*expected);
                }
            }
            for original in old { let actual = doc.elements.iter().find(|e|e.id==original.id).unwrap();
                if original.id != owner { assert_eq!(serde_json::to_value(actual).unwrap(),serde_json::to_value(&original).unwrap()); }
                else { assert_eq!(actual.properties["is_implied_included"],original.properties["is_implied_included"]); }
            }
        }
    }

    #[test]
    fn definition_resolved_binding_rejects_unresolved_inputs_and_rolls_back() {
        let artifact: Value = serde_json::from_str(include_str!("../../../../../../docs/conformance/2026-08-support/resolved-binding-pilot-controls.json")).unwrap();
        let case = &artifact["controls"][0];let template = crate::definition_document::parse_and_link(case["source"].as_str().unwrap(),crate::SourceLanguage::Kerml).unwrap();
        for excluded in ["owner_pending","endpoint_pending","missing_featuring","missing_library","collision","duplicate","variable","metadata"] {
            let (mut doc,owner,x,y) = resolved_binding_fixture(&template,case);
            match excluded {
                "owner_pending"=>{doc.elements.iter_mut().find(|e|e.id==owner).unwrap().properties.insert("is_implied_included".into(),json!(false));},
                "endpoint_pending"=>{doc.elements.iter_mut().find(|e|e.id==x).unwrap().properties.insert("is_implied_included".into(),json!(false));},
                "missing_featuring"=>{let id=format!("{x}.explicit.featuring");doc.elements.retain(|e|e.id!=id);doc.elements.iter_mut().find(|e|e.id==x).unwrap().properties.insert("owned_relationship".into(),json!([]));},
                "missing_library"=>{doc.elements.iter_mut().find(|e|e.properties.get("declared_name")==Some(&json!("selfLinks"))).unwrap().properties.insert("declared_name".into(),json!("unavailable"));},
                "collision"=>doc.elements.push(fresh_definition_element("binding.end.1.featuring".into(),"Feature").unwrap()),
                "duplicate"=>doc.elements.push(doc.elements[0].clone()),
                "variable"=>{let e=doc.elements.iter_mut().find(|e|e.id==x).unwrap();e.kind="SysML::Feature".into();e.properties.insert("is_variable".into(),json!(true));},
                "metadata"=>doc.elements.push(fresh_definition_element("unsupported".into(),"MetadataFeature").unwrap()),
                _=>unreachable!(),
            }
            let before=serde_json::to_value(&doc).unwrap();
            assert!(crate::definition_document::materialize_resolved_binding(&mut doc,&owner,"binding",&x,&y).is_err(),"{excluded}");
            assert_eq!(serde_json::to_value(&doc).unwrap(),before,"{excluded}");
        }
    }

    #[test]
    fn definition_binding_stage_matches_pilot_except_completion_boundary() {
        let artifact: Value=serde_json::from_str(include_str!("../../../../resources/metamodels/sysml-2.0-pilot-2026-08/compatibility.extract.json")).unwrap();
        assert_eq!(artifact["binding_stages"].as_array().unwrap().len(),4);
        for case in artifact["binding_stages"].as_array().unwrap() {
            let mut doc=crate::definition_document::parse_and_link(case["source"].as_str().unwrap(),crate::SourceLanguage::Kerml).unwrap();
            let find=|name: &str|doc.elements.iter().find(|e|e.properties.get("declared_name")==Some(&json!(name))).unwrap().id.clone();
            let owner=find(case["owner"].as_str().unwrap());let source=find("x");let target=find(case["target"].as_str().unwrap());
            definition_materialize_binding_defaults(&mut doc.elements,&owner,"binding",&source,&target).unwrap();
            let exported=crate::abstract_syntax_json::export_sysml_abstract_syntax_value(&doc,Default::default()).unwrap();assert!(!exported.has_errors());
            let restored=crate::abstract_syntax_json::import_sysml_abstract_syntax_value(exported.value,Default::default()).unwrap();assert!(!restored.has_errors());
            for document in [&doc,&restored.persistable_document().unwrap()] {
                let graph=&document.elements;
                assert_eq!(graph.iter().find(|e|e.id=="binding.membership").unwrap().kind.rsplit("::").next().unwrap(),case["membership"].as_str().unwrap());
                for (id,expected) in [("binding",&case["connector"]),("binding.end.0",&case["ends"][0]),("binding.end.1",&case["ends"][1])] {
                    let mut actual=binding_stage_snapshot(graph,graph.iter().find(|e|e.id==id).unwrap(),"binding",None);let mut expected=expected.clone();
                    // Record the one explicit lifecycle difference per Type.
                    // This comparison does not qualify a fully transformed model.
                    assert_eq!(actual.as_object_mut().unwrap().remove("complete"),Some(json!(false)));
                    assert_eq!(expected.as_object_mut().unwrap().remove("complete"),Some(json!(true)));
                    assert_eq!(actual,expected,"owner={} target={} element={id}",case["owner"],case["target"]);
                }
            }
        }
    }

