    #[test]
    fn definition_multiplicity_defaults_match_all_pilot_owner_contexts() {
        let controls:Value=serde_json::from_str(include_str!("../../../../../../docs/conformance/2026-08-support/multiplicity-defaults-pilot-controls.json")).unwrap();
        assert_eq!(controls["controls"].as_array().unwrap().len(),20);
        for case in controls["controls"].as_array().unwrap() {
            let mut target=fresh_definition_element("multiplicity".into(),case["kind"].as_str().unwrap()).unwrap();let mut graph=Vec::new();
            if case["context"]!="detached" {
                let mut owner=fresh_definition_element("owner".into(),case["context"].as_str().unwrap()).unwrap();
                let mut member=fresh_definition_element("member".into(),case["membership"].as_str().unwrap()).unwrap();
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS,&mut member,&mut target).unwrap();
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,&mut owner,&mut member).unwrap();graph.extend([owner,member]);
            }
            graph.push(target);
            let before=serde_json::to_value(&graph).unwrap();
            let mut reversed:Vec<KirElement>=serde_json::from_value(before.clone()).unwrap();reversed.reverse();
            for model in [&graph,&reversed] {
                let target=model.iter().find(|e|e.id=="multiplicity").unwrap();
                assert_eq!(definition_multiplicity_default_name(model,target).unwrap(),case["default_name"].as_str().unwrap());
                let index=model.iter().map(|e|(e.id.as_str(),e)).collect();
                let query=DefinitionNameQuery::new(model,&index);
                for _ in 0..2 {assert_eq!(definition_multiplicity_default_name_in_view(&query,target).unwrap(),case["default_name"].as_str().unwrap());}
                assert_eq!(case["relevant_count"],0);
                assert!(materialized_redefined_features(model,target).unwrap().is_empty());
            }
            assert_eq!(serde_json::to_value(graph).unwrap(),before);
        }
    }

    #[test]
    fn definition_multiplicity_defaults_reject_broken_and_unassessed_dependencies() {
        for mutation in ["absent_owner","wrong_member","wrong_inverse","duplicate","chaining","valuation","conjugation","crossing"] {
            let mut owner=fresh_definition_element("owner".into(),"Feature").unwrap();
            let mut member=fresh_definition_element("member".into(),"OwningMembership").unwrap();
            let mut target=fresh_definition_element("multiplicity".into(),"MultiplicityRange").unwrap();
            ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS,&mut member,&mut target).unwrap();
            ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,&mut owner,&mut member).unwrap();
            let mut graph=vec![owner,member,target];
            match mutation {
                "absent_owner"=>{graph.remove(0);},
                "wrong_member"=>graph[1].kind="Annotation".into(),
                "wrong_inverse"=>{graph[0].properties.insert("owned_relationship".into(),json!([]));},
                "duplicate"=>graph.push(graph[0].clone()),
                _=>{
                    let kind=match mutation {"chaining"=>"FeatureChaining","valuation"=>"FeatureValue","conjugation"=>"Conjugation",_=>"CrossSubsetting"};
                    let mut relation=fresh_definition_element("dependency".into(),kind).unwrap();
                    ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,&mut graph[2],&mut relation).unwrap();graph.push(relation);
                },
            }
            let before=serde_json::to_value(&graph).unwrap();
            assert!(definition_multiplicity_default_name(&graph,graph.iter().find(|e|e.id=="multiplicity").unwrap()).is_err(),"{mutation}");
            assert_eq!(serde_json::to_value(graph).unwrap(),before);
        }
    }

    #[test]
    fn definition_owned_result_batch_matches_all_pilot_bindings_and_contexts() {
        let artifact: Value = serde_json::from_str(include_str!("../../../../resources/metamodels/sysml-2.0-pilot-2026-08/result-construction.extract.json")).unwrap();
        let mut graph=Vec::new();
        for (i,case) in artifact["cases"].as_array().unwrap().iter().enumerate() {
            let id=format!("owner.{i:02}");
            let mut owner=fresh_definition_element(id.clone(),case["class"].as_str().unwrap()).unwrap();
            let context=case["context"].as_str().unwrap();
            if context!="empty" {
                let mut member=fresh_definition_element(format!("{id}.existing"),if context=="ordinary_member" {"FeatureMembership"} else {"ReturnParameterMembership"}).unwrap();
                if context!="empty_return" {
                    let mut result=fresh_definition_element(format!("{id}.existing.result"),"Feature").unwrap();
                    result.properties.insert("direction".into(),json!("in"));
                    ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS,&mut member,&mut result).unwrap();graph.push(result);
                }
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,&mut owner,&mut member).unwrap();graph.push(member);
            }
            graph.push(owner);
        }
        for kind in ["LiteralInteger","ConstructorExpression"] {graph.push(fresh_definition_element(kind.into(),kind).unwrap());}
        let mut reversed:Vec<KirElement>=serde_json::from_value(serde_json::to_value(&graph).unwrap()).unwrap();reversed.reverse();
        for model in [&mut graph,&mut reversed] {
            assert_eq!(definition_materialize_owned_expression_results(model,"batch").unwrap(),14);
            for (i,case) in artifact["cases"].as_array().unwrap().iter().enumerate() {
                let owner=model.iter().find(|e|e.id==format!("owner.{i:02}")).unwrap();
                let memberships=stored_children(model,owner,"owned_relationship").unwrap();
                let observed=memberships.iter().map(|member| {
                    let children=stored_children(model,member,"owned_related_element").unwrap();
                    json!({"kind":member.kind.rsplit("::").next().unwrap(),"relationships":[],"elements":children.iter().map(|e|json!({"kind":"Feature","relationships":[],"direction":e.properties["direction"]})).collect::<Vec<_>>(),"visibility":ecore_defaults::read_attribute(member,"visibility").unwrap()})
                }).collect::<Vec<_>>();
                assert_eq!(json!(observed),case["tree"]["relationships"],"{case}");
            }
            for kind in ["LiteralInteger","ConstructorExpression"] {assert!(stored_children(model,model.iter().find(|e|e.id==kind).unwrap(),"owned_relationship").unwrap().is_empty());}
            let before=serde_json::to_value(&*model).unwrap();
            assert_eq!(definition_materialize_owned_expression_results(model,"another.prefix").unwrap(),0);
            assert_eq!(serde_json::to_value(&*model).unwrap(),before);
            assert!(model.iter().all(|e|e.properties.get("is_implied_included")!=Some(&json!(true))));
        }
        graph.sort_by(|a,b|a.id.cmp(&b.id));reversed.sort_by(|a,b|a.id.cmp(&b.id));
        assert_eq!(serde_json::to_value(graph).unwrap(),serde_json::to_value(reversed).unwrap());
    }

