    #[test]
    fn definition_result_construction_matches_pilot_and_is_idempotent() {
        let artifact: Value = serde_json::from_str(include_str!("../../../../resources/metamodels/sysml-2.0-pilot-2026-08/result-construction.extract.json")).unwrap();
        let cases = artifact["cases"].as_array().unwrap();
        assert_eq!(cases.len(), 28);
        for case in cases {
            let mut owner = fresh_definition_element("owner".into(), case["class"].as_str().unwrap()).unwrap();
            let mut graph = Vec::new();
            let context = case["context"].as_str().unwrap();
            if context != "empty" {
                let mut member = fresh_definition_element("existing".into(), if context == "ordinary_member" { "FeatureMembership" } else { "ReturnParameterMembership" }).unwrap();
                if context != "empty_return" {
                    let mut feature = fresh_definition_element("existing.result".into(), "Feature").unwrap();
                    feature.properties.insert("direction".into(), json!("in"));
                    ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS, &mut member, &mut feature).unwrap();
                    graph.push(feature);
                }
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, &mut owner, &mut member).unwrap();
                graph.push(member);
            }
            graph.push(owner);
            let changed = definition_materialize_expression_result(&mut graph, "owner", "new.member", "new.result").unwrap();
            assert_eq!(changed, matches!(context, "empty" | "ordinary_member"));
            fn projected(graph: &[KirElement], id: &str) -> Value {
                let owner = graph.iter().find(|e| e.id == id).unwrap();
                let mut value = json!({"kind": owner.kind.rsplit("::").next().unwrap(), "relationships": stored_children(graph, owner, "owned_relationship").unwrap().iter().map(|e| projected(graph, &e.id)).collect::<Vec<_>>()});
                if metaclass_conforms(&owner.kind, "Relationship") { value["elements"] = json!(stored_children(graph, owner, "owned_related_element").unwrap().iter().map(|e| projected(graph, &e.id)).collect::<Vec<_>>()); }
                if metaclass_conforms(&owner.kind, "Membership") { value["visibility"] = super::super::super::ecore_defaults::read_attribute(owner, "visibility").unwrap(); }
                if let Some(direction) = owner.properties.get("direction").filter(|v| !v.is_null()) { value["direction"] = direction.clone(); }
                value
            }
            assert_eq!(projected(&graph, "owner"), case["tree"], "{} {context}", case["class"]);
            let before = serde_json::to_value(&graph).unwrap();
            assert!(!definition_materialize_expression_result(&mut graph, "owner", "unused", "unused.result").unwrap());
            assert_eq!(serde_json::to_value(&graph).unwrap(), before);
            let reloaded: Vec<KirElement> = serde_json::from_value(before).unwrap();
            assert_eq!(projected(&reloaded, "owner"), case["tree"]);
        }
    }

