    #[test]
    fn definition_reference_index_context_preserves_nested_parameters_and_names() {
        let t = element("external.T", "Function");
        let u = element("external.U", "Function");
        let parameter_t = element("external.T.x", "Feature");
        let parameter_u = element("external.U.x", "Feature");
        let lexical_x = element("lexical.x", "Feature");
        for kerml in [true, false] {
            let parsed = crate::xtext_fragment::experimental_expression("T(x=U(x=x))", kerml)
                .unwrap()
                .unwrap();
            let saved = parsed.clone();
            let visits = std::cell::RefCell::new(Vec::new());
            // Controlled scope policy: this tests delivery of graph context,
            // not Pilot's namespace/visibility/inheritance algorithms.
            let resolver = |site: &GeneratedReferenceSite<'_>| {
                assert!(site.owner_id.starts_with("expression."));
                let view = site.graph_view.unwrap();
                assert!(view.is_for(site.graph));
                assert!(std::ptr::eq(*view.index.get(site.owner_id).unwrap(),
                    site.graph.iter().find(|e| e.id == site.owner_id).unwrap()));
                let endpoint = if site.feature.field == "redefined_feature" {
                    assert_eq!(site.owner_kind, "Redefinition");
                    let argument = generated_parent_namespace(site.graph, site.owner_id)?
                        .ok_or_else(|| error("missing argument namespace"))?;
                    assert_eq!(argument.kind, "SysML::Feature");
                    let invocation = generated_parent_namespace(site.graph, &argument.id)?
                        .ok_or_else(|| error("missing invocation namespace"))?;
                    assert_eq!(invocation.kind, "SysML::InvocationExpression");
                    let member_id = invocation.properties["owned_relationship"][0]
                        .as_str()
                        .unwrap();
                    let member = site.graph.iter().find(|e| e.id == member_id).unwrap();
                    // The callee binding is available from an earlier link.
                    // Its parameter namespace is supplied by this controlled policy.
                    match member.properties["member_element"].as_str().unwrap() {
                        "external.T" => &parameter_t,
                        "external.U" => &parameter_u,
                        _ => return Err(error("unsupported test scope")),
                    }
                } else {
                    match site.reference.spelling.as_str() {
                        "T" => &t,
                        "U" => &u,
                        "x" => &lexical_x,
                        _ => return Err(error("unresolved test name")),
                    }
                };
                visits
                    .borrow_mut()
                    .push((site.feature.field.to_owned(), endpoint.id.clone()));
                Ok(endpoint)
            };
            let (_, graph) =
                materialize_generated_with_context(&parsed, "expression", &resolver).unwrap();
            let bindings: BTreeSet<_> = graph
                .iter()
                .filter_map(|e| {
                    e.properties
                        .get("redefined_feature")
                        .and_then(Value::as_str)
                })
                .collect();
            assert_eq!(bindings, BTreeSet::from(["external.T.x", "external.U.x"]));
            assert!(
                visits
                    .borrow()
                    .contains(&("member_element".into(), "lexical.x".into()))
            );
            assert_eq!(visits.borrow().len(), 5);
            assert_eq!(parsed, saved);
        }
        for endpoint in [&t, &u, &parameter_t, &parameter_u, &lexical_x] {
            assert!(endpoint.properties.is_empty());
        }
    }

    #[test]
    fn complete_finite_models_materialize_ecore_fields_links_and_inverses() {
        fn endpoints(
            tree: &crate::xtext_fragment::Match,
            symbols: &mut BTreeMap<String, KirElement>,
        ) {
            for reference in tree.links.values().flatten() {
                let kind = reference.target_type.rsplit("#//").next().unwrap();
                let target = element(&format!("external:{}", reference.spelling), kind);
                if let Some(previous) = symbols.insert(reference.spelling.clone(), target.clone()) {
                    assert_eq!(previous.kind, target.kind);
                }
            }
            for child in tree
                .children
                .values()
                .flatten()
                .chain(tree.captured_operands.iter())
            {
                endpoints(child, symbols);
            }
        }
        fn verify(actual: &KirElement, graph: &[KirElement], expected: &Value) {
            assert_eq!(actual.kind.rsplit("::").next().unwrap(), expected["kind"]);
            for (field, value) in expected["attributes"].as_object().unwrap() {
                assert_eq!(
                    actual.properties.get(field),
                    Some(value),
                    "{}.{}",
                    actual.kind,
                    field
                );
            }
            for (field, spellings) in expected["references"].as_object().unwrap() {
                let targets: Vec<Value> = spellings
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|v| json!(format!("external:{}", v.as_str().unwrap())))
                    .collect();
                let actual_value = &actual.properties[field];
                let actual_targets = if actual_value.is_array() {
                    actual_value.clone()
                } else {
                    json!([actual_value])
                };
                assert_eq!(actual_targets, json!(targets), "{}.{}", actual.kind, field);
            }
            for (field, children) in expected["children"].as_object().unwrap() {
                let actual_children = stored_children(graph, actual, field).unwrap();
                let expected_children = children.as_array().unwrap();
                assert_eq!(
                    actual_children.len(),
                    expected_children.len(),
                    "{}.{}",
                    actual.kind,
                    field
                );
                for (actual_child, expected_child) in
                    actual_children.into_iter().zip(expected_children)
                {
                    verify(actual_child, graph, expected_child);
                }
            }
        }
        let evidence: Value = serde_json::from_str(include_str!(
            "../../../../resources/metamodels/sysml-2.0-pilot-2026-08/xtext-prediction-nfa.experimental.json"
        )).unwrap();
        let mut accepted = 0;
        for case in evidence["complete_model_controls"].as_array().unwrap() {
            if case["accepted"] != true {
                continue;
            }
            let source = case["source"].as_str().unwrap();
            let entry = format!(
                "{}::{}",
                case["context"].as_str().unwrap(),
                case["entry"].as_str().unwrap()
            );
            let parsed = crate::xtext_fragment::experimental_model(
                source,
                &entry,
                case["context"].as_str().unwrap().ends_with("KerML"),
            )
            .unwrap_or_else(|e| panic!("{source}: {e}"));
            let saved = parsed.clone();
            let mut symbols = BTreeMap::new();
            endpoints(&parsed, &mut symbols);
            let (root, elements) =
                materialize_generated_with_links(&parsed, "model", &|reference| {
                    symbols
                        .get(&reference.spelling)
                        .ok_or_else(|| error("missing controlled endpoint"))
                })
                .unwrap_or_else(|e| panic!("{source}: {e:?}"));
            let mut graph = vec![root.clone()];
            graph.extend(elements);
            verify(&root, &graph, &case["stored_model"]);
            graph.extend(symbols.values().cloned());
            assert!(
                ecore_model::validate_explicit_model(&graph).is_empty(),
                "{source}"
            );
            assert_eq!(parsed, saved);
            if !symbols.is_empty() {
                assert!(
                    materialize_generated_with_links(&parsed, "model", &|_| Err(error(
                        "unresolved reference"
                    )))
                    .is_err()
                );
                assert_eq!(parsed, saved);
            }
            accepted += 1;
        }
        assert_eq!(accepted, 22);
    }

    #[test]
    fn generated_construction_events_reject_missing_duplicate_and_invalid_entries() {
        let parsed = crate::xtext_fragment::experimental_expression("1 + 2", true)
            .unwrap()
            .unwrap();
        for variant in 0..3 {
            let mut damaged = parsed.clone();
            match variant {
                0 => {
                    damaged.construction_order.pop();
                }
                1 => {
                    let step = damaged.construction_order[0].clone();
                    damaged.construction_order.push(step);
                }
                _ => {
                    damaged.construction_order[0] =
                        crate::xtext_fragment::ConstructionStep::Operand(100);
                }
            }
            assert!(materialize_generated_expression(&damaged, "expression").is_err());
        }
        for (kind, expected) in [
            ("CollectExpression", "collect"),
            ("SelectExpression", "select"),
        ] {
            let mut constructed = element("expression", kind);
            initialize_expression_constructor(&mut constructed).unwrap();
            assert_eq!(constructed.properties["operator"], json!(expected));
        }
    }

    #[test]
    fn generated_reference_models_use_explicit_typed_linking() {
        let x = element("external.x", "Feature");
        let qualified = element("external.qualified", "PartUsage");
        let ty = element("external.type", "Class");
        let thing = element("external.thing", "Feature");
        let symbols = BTreeMap::from([
            ("x", vec![&x]),
            ("P::x", vec![&qualified]),
            ("T", vec![&ty]),
            ("U", vec![&ty]),
            ("thing", vec![&thing]),
        ]);
        let resolve = |link: &crate::xtext_fragment::PendingReference| match symbols
            .get(link.spelling.as_str())
            .map(Vec::as_slice)
        {
            Some([endpoint]) => Ok(*endpoint),
            Some(_) => Err(error("ambiguous reference")),
            None => Err(error("unresolved reference")),
        };
        fn bind_expected(value: &mut Value, symbols: &BTreeMap<&str, Vec<&KirElement>>) {
            match value {
                Value::Object(fields) => {
                    if let Some(Value::Object(references)) = fields.get_mut("references") {
                        for values in references.values_mut() {
                            for spelling in values.as_array_mut().unwrap() {
                                *spelling = json!(symbols[spelling.as_str().unwrap()][0].id);
                            }
                        }
                    }
                    for child in fields.values_mut() {
                        bind_expected(child, symbols);
                    }
                }
                Value::Array(children) => {
                    for child in children {
                        bind_expected(child, symbols);
                    }
                }
                _ => (),
            }
        }
        let evidence: Value = serde_json::from_str(include_str!(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../../docs/conformance/2026-08-support/expression-model-pilot-controls.json"
        )))
        .unwrap();
        let mut count = 0;
        for case in evidence["cases"].as_array().unwrap() {
            let source = case["source"].as_str().unwrap();
            if !has_reference(&case["tree"]) {
                continue;
            }
            count += 1;
            let captured =
                crate::xtext_fragment::experimental_expression(source, case["language"] == "kerml")
                    .unwrap_or_else(|e| panic!("{source}: {e}"))
                    .unwrap();
            let saved = captured.clone();
            let (root, elements) =
                materialize_generated_with_links(&captured, "expression", &resolve).unwrap();
            let mut expected = case["tree"].clone();
            bind_expected(&mut expected, &symbols);
            assert_eq!(scoped_tree(&root, &elements), expected, "{source}");
            assert_eq!(captured, saved);
            assert!(
                !elements
                    .iter()
                    .any(|e| e.id == x.id || e.id == qualified.id)
            );
        }
        assert_eq!(count, 40);
        let bad = element("external.bad", "Package");
        let parsed = crate::xtext_fragment::experimental_expression("1 + x", true)
            .unwrap()
            .unwrap();
        let saved = parsed.clone();
        assert!(materialize_generated_with_links(&parsed, "expression", &|_| Ok(&bad)).is_err());
        for message in ["unresolved reference", "ambiguous reference"] {
            assert!(
                materialize_generated_with_links(&parsed, "expression", &|_| Err(error(message)))
                    .is_err()
            );
        }
        let empty = element("", "Feature");
        assert!(materialize_generated_with_links(&parsed, "expression", &|_| Ok(&empty)).is_err());
        let collision = element("expression", "Feature");
        assert!(
            materialize_generated_with_links(&parsed, "expression", &|_| Ok(&collision)).is_err()
        );
        assert_eq!(parsed, saved);
        assert!(x.properties.is_empty());
        assert!(qualified.properties.is_empty());
    }

