    #[test]
    fn every_pinned_capture_action_constructs_its_declared_class() {
        let program: Value = serde_json::from_str(include_str!(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/resources/metamodels/sysml-2.0-pilot-2026-08/xtext-fragment-programs.json"
        )))
        .unwrap();
        let evidence: Value = serde_json::from_str(include_str!(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../../docs/conformance/2026-08-support/operand-construction-pilot-controls.json"
        )))
        .unwrap();
        let actions = program["capture_actions"].as_object().unwrap();
        assert_eq!(actions.len(), 26);
        for (id, action) in actions {
            let mut current = element("left", "LiteralInteger");
            current.properties.insert("value".into(), json!(2));
            let saved = serde_json::to_value(&current).unwrap();
            let mut elements = Vec::new();
            let mut result = capture(id, "result", current.clone(), &mut elements).unwrap();
            let classifier = action["classifier"]
                .as_str()
                .unwrap()
                .rsplit('/')
                .next()
                .unwrap();
            assert_eq!(result.kind, format!("SysML::{classifier}"));
            assert_eq!(result.properties["metadata"]["xtext_capture_action"], *id);
            assert_eq!(serde_json::to_value(&current).unwrap(), saved);
            let mut right = element("right", "LiteralInteger");
            right.properties.insert("value".into(), json!(2));
            append(&mut result, right, &mut elements).unwrap();
            let expected = evidence["cases"]
                .as_array()
                .unwrap()
                .iter()
                .find(|case| case["class"] == classifier)
                .unwrap();
            assert_eq!(tree(&result, &elements), expected["tree"], "{id}");
            let before = serde_json::to_value(&elements).unwrap();
            assert!(capture(id, "bad", element("wrong", "Package"), &mut elements).is_err());
            assert_eq!(serde_json::to_value(&elements).unwrap(), before);
        }
    }

    #[test]
    fn operand_adapter_rejects_invalid_construction_without_partial_changes() {
        for mode in [
            "owner",
            "child",
            "contained",
            "duplicate",
            "stored_operand",
            "malformed",
        ] {
            let mut owner = element(
                "owner",
                if mode == "owner" {
                    "Package"
                } else {
                    "OperatorExpression"
                },
            );
            let mut child = element(
                "child",
                if mode == "child" {
                    "Package"
                } else {
                    "LiteralInteger"
                },
            );
            let mut elements = Vec::new();
            match mode {
                "contained" => {
                    child
                        .properties
                        .insert("owning_relationship".into(), json!("prior"));
                }
                "duplicate" => elements.push(element("owner.operand.0.value", "FeatureValue")),
                "stored_operand" => {
                    owner.properties.insert("operand".into(), json!([]));
                }
                "malformed" => {
                    owner
                        .properties
                        .insert("owned_relationship".into(), json!("bad"));
                }
                _ => {}
            }
            let before = serde_json::to_value((&owner, &elements)).unwrap();
            assert!(append(&mut owner, child, &mut elements).is_err(), "{mode}");
            assert_eq!(
                serde_json::to_value((&owner, &elements)).unwrap(),
                before,
                "{mode}"
            );
        }
    }

