    #[test]
    fn eager_operand_graph_reaches_strict_compiled_kir() {
        let source = "package P { inv valid { (1 + 2) > -3 } }";
        let parsed = crate::kerml::parse_kerml(source).unwrap();
        let library = crate::load_sysml_baseline().unwrap();
        let document = crate::kerml::compile_kerml_module_strict_with_context(
            &parsed,
            "operands.kerml",
            std::slice::from_ref(&parsed),
            &library,
        )
        .unwrap();
        let root = document
            .elements
            .iter()
            .find(|e| e.id.ends_with(".result-expression"))
            .unwrap();
        assert_eq!(root.properties["operator"], ">");
        assert!(
            root.properties["metadata"]["xtext_capture_action"]
                .as_str()
                .unwrap()
                .contains("::RelationalExpression/")
        );
        let addition = document
            .elements
            .iter()
            .find(|e| e.properties.get("operator") == Some(&json!("+")))
            .unwrap();
        assert!(
            addition.properties["metadata"]["xtext_capture_action"]
                .as_str()
                .unwrap()
                .contains("::AdditiveExpression/")
        );
        let projection = tree(root, &document.elements);
        assert_eq!(projection["relationships"].as_array().unwrap().len(), 2);
        let nested =
            &projection["relationships"][0]["elements"][0]["relationships"][0]["elements"][0];
        assert_eq!(nested["kind"], "OperatorExpression");
        assert_eq!(nested["relationships"].as_array().unwrap().len(), 2);
        assert_eq!(
            document
                .elements
                .iter()
                .filter(|e| e.kind.ends_with("ParameterMembership"))
                .count(),
            5
        );
        for node in &document.elements {
            assert!(!node.properties.contains_key("operand"));
        }
    }
    #[test]
    fn definition_chain_scope_matches_independent_pilot_controls() {
        let controls: Value = serde_json::from_str(include_str!("../../../../../../docs/conformance/2026-08-support/chain-link-pilot-controls.json")).unwrap();
        let cases = controls["candidate_scope_controls"].as_array().unwrap();
        assert_eq!(cases.len(), 21);
        for case in cases {
            let source = case["source"].as_str().unwrap();
            let observed = case["links"].as_array().unwrap();
            let result = crate::definition_document::parse_and_link(source, crate::SourceLanguage::Kerml);
            if observed.iter().any(|link| link["resolved"] == false) {
                assert!(matches!(result, Err(crate::definition_document::DefinitionDocumentError::ConstructionOrLinking(_))), "unresolved Pilot chain must fail in linking: {source}: {result:?}");
                continue;
            }
            let document = result.unwrap_or_else(|e| panic!("{source}: {e}"));
            let restored: crate::KirDocument = serde_json::from_str(&serde_json::to_string(&document).unwrap()).unwrap();
            for model in [&document, &restored] {
                let chains: Vec<_> = model.elements.iter().filter(|e| metaclass_conforms(&e.kind, "FeatureChaining")).collect();
                assert_eq!(chains.len(), observed.len(), "{source}");
                for (chain, expected) in chains.iter().zip(observed) {
                    let target = redefined_reference(&model.elements, chain, "chaining_feature").unwrap();
                    assert_eq!(target.kind, format!("SysML::{}", expected["target_kind"].as_str().unwrap()));
                    let mut path = Vec::new();
                    let mut cursor = Some(target);
                    while let Some(element) = cursor {
                        if let Some(name) = element.properties.get("declared_name").and_then(Value::as_str) { path.push(name.to_owned()); }
                        cursor = generated_parent_namespace(&model.elements, &element.id).unwrap();
                    }
                    path.reverse();
                    assert_eq!(serde_json::json!(path), expected["target_path"], "{source}");
                }
                let redefinitions: Vec<_> = model.elements.iter().filter(|e| metaclass_conforms(&e.kind, "Redefinition")).collect();
                let expected = case["redefinitions"].as_array().unwrap();
                assert_eq!(redefinitions.len(), expected.len());
                let index = model.elements.iter().map(|e| (e.id.as_str(), e)).collect();
                for (relation, observation) in redefinitions.iter().zip(expected) {
                    assert_eq!(observation["resolved"], true);
                    let owner = scope_container(&index, relation).unwrap().unwrap();
                    let target = redefined_reference(&model.elements, relation, "redefined_feature").unwrap();
                    for (element, field) in [(owner, "owner_path"), (target, "target_path")] {
                        let mut path = Vec::new();
                        let mut cursor = Some(element);
                        while let Some(element) = cursor {
                            if let Some(name) = element.properties.get("declared_name").and_then(Value::as_str) { path.push(name.to_owned()); }
                            cursor = generated_parent_namespace(&model.elements, &element.id).unwrap();
                        }
                        path.reverse();
                        assert_eq!(json!(path), observation[field], "{source}: {field}");
                    }
                }
            }
        }
    }

