    #[test]
    fn definition_enum_family_canonical_models_preserve_values_and_report_dependencies() {
        let artifact: Value = serde_json::from_str(include_str!("../../../../../../docs/conformance/2026-08-support/enum-family-pilot-controls.json")).unwrap();
        let cases = artifact["model_controls"].as_array().unwrap().iter().filter(|case|case["primary"]==true).collect::<Vec<_>>();
        assert_eq!(cases.len(), 24);
        for case in cases {
            let language = case["language"].as_str().unwrap();
            let kerml = language == "org.omg.kerml.xtext.KerML";
            let field = if case["field"] == "portionKind" { "portion_kind" } else { case["field"].as_str().unwrap() };
            let tree = crate::xtext_fragment::experimental_model(case["source"].as_str().unwrap(), &format!("{language}::{}",case["carrier_rule"].as_str().unwrap()), kerml).unwrap();
            if case["rule"] == "TriggerFeatureKind" {
                let result = crate::definition_document::parse_and_link("attribute x; state s { state a; state b; transition first a accept x then b; }",crate::SourceLanguage::Sysml);
                assert!(matches!(result,Err(crate::definition_document::DefinitionDocumentError::ConstructionOrLinking(ref message)) if message.contains("missing standard library root States")), "{result:?}");
                continue; // Required integrated trigger context remains open.
            }
            if case["rule"] == "ExposeVisibilityKind" {
                let result=crate::definition_document::parse_and_link("package P; view v { expose P::*; }",crate::SourceLanguage::Sysml);
                assert!(matches!(result,Err(crate::definition_document::DefinitionDocumentError::ConstructionOrLinking(ref message)) if message.contains("Views") && !message.contains("no document generalization provider for ViewUsage")));
                continue; // Required integrated expose context remains open.
            }
            let (root,mut graph) = materialize_generated_expression(&tree,"enum.model").unwrap_or_else(|e|panic!("{case}: {e:?}"));
            graph.insert(0,root);
            let root=graph.iter().find(|e|e.kind.rsplit("::").next()==case["kind"].as_str() && e.properties.get(field)==Some(&case["literal"])).unwrap();
            let contract=ecore_model::feature(&root.kind,field).unwrap();
            assert!(contract.enum_literals.unwrap().contains(&case["literal"].as_str().unwrap()));
            assert!(ecore_model::validate_publication(&graph,ecore_model::ReferenceCompleteness::Closed).is_empty(),"{case}");
            let restored:Vec<KirElement>=serde_json::from_str(&serde_json::to_string(&graph).unwrap()).unwrap();
            assert_eq!(serde_json::to_value(&restored).unwrap(),serde_json::to_value(&graph).unwrap());
            assert!(ecore_model::validate_publication(&restored,ecore_model::ReferenceCompleteness::Closed).is_empty());
            let mut invalid=restored;invalid.iter_mut().find(|e|e.id==root.id).unwrap().properties.insert(field.into(),json!("unsupported-literal"));
            assert!(!ecore_model::validate_publication(&invalid,ecore_model::ReferenceCompleteness::Closed).is_empty());
        }
    }

    #[test]
    fn definition_parameter_defaults_match_all_pilot_selector_controls() {
        let artifact:Value=serde_json::from_str(include_str!("../../../../../../docs/conformance/2026-08-support/parameter-defaults-pilot-controls.json")).unwrap();
        assert_eq!(artifact["controls"].as_array().unwrap().len(),540);
        for case in artifact["controls"].as_array().unwrap() {
            let mut owner=fresh_definition_element("context".into(),case["owner"].as_str().unwrap()).unwrap();
            let mut parameter=fresh_definition_element("parameter".into(),"Feature").unwrap();parameter.properties.insert("direction".into(),case["direction"].clone());
            let mut graph=Vec::new();let typing=case["typing"].as_str().unwrap();
            if typing!="none" {
                let target=fresh_definition_element("type".into(),typing).unwrap();let mut relation=fresh_definition_element("typing".into(),"FeatureTyping").unwrap();
                relation.properties.insert("typed_feature".into(),json!(parameter.id));relation.properties.insert("type".into(),json!(target.id));
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,&mut parameter,&mut relation).unwrap();graph.extend([target,relation]);
            }
            if case["valuation"]!="absent" {
                let mut value=fresh_definition_element("value".into(),"FeatureValue").unwrap();value.properties.insert("is_default".into(),json!(case["valuation"]=="default"));
                let mut literal=fresh_definition_element("literal".into(),"LiteralInteger").unwrap();literal.properties.insert("value".into(),json!(1));
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS,&mut value,&mut literal).unwrap();
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,&mut parameter,&mut value).unwrap();graph.extend([literal,value]);
            }
            let mut member=fresh_definition_element("membership".into(),case["membership"].as_str().unwrap()).unwrap();
            ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS,&mut member,&mut parameter).unwrap();
            ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,&mut owner,&mut member).unwrap();graph.extend([owner,member,parameter]);
            let restored:Vec<KirElement>=serde_json::from_str(&serde_json::to_string(&graph).unwrap()).unwrap();
            for mut model in [graph,restored] {
                model.reverse();let parameter=model.iter().find(|e|e.id=="parameter").unwrap();let before=serde_json::to_value(&model).unwrap();
                assert!(definition_fixed_parameter_owner(&model,parameter).unwrap().is_some());
                assert_eq!(definition_feature_default_name(&model,parameter).unwrap(),case["default_name"].as_str().unwrap(),"{case}");
                assert_eq!(before,serde_json::to_value(&model).unwrap());
            }
        }
    }

    #[test]
    fn definition_parameter_defaults_compose_source_redefinitions_and_replay() {
        let source="standard library package Base { feature things; } standard library package Performances { function Evaluation; } package P { function G { in feature gp; } function F specializes G { in feature fp = 1; } }";
        let original=crate::definition_document::parse_and_link(source,crate::SourceLanguage::Kerml).unwrap();
        for reverse in [false,true] {
            let mut document=original.clone();if reverse {document.elements.reverse();}
            let named=|name:&str|document.elements.iter().find(|e|e.properties.get("declared_name")==Some(&json!(name))).unwrap().id.clone();
            let parameter_id=named("fp");let gp=named("gp");let base=named("things");
            let before=definition_general_type_inputs_query(&document.elements,document.elements.iter().find(|e|e.id==parameter_id).unwrap()).unwrap();
            assert_eq!(before,vec![gp.clone(),base.clone()]);
            // The shared implicit reduction removes Base::things: gp already
            // specializes it. Physical insertion retains the positional redefinition.
            assert_eq!(definition_materialize_feature_defaults(&mut document.elements,&[(&parameter_id,"parameter.default")]).unwrap(),1);
            assert_eq!(document.elements.iter().filter(|e|e.id.starts_with("parameter.default.") && metaclass_conforms(&e.kind,"Specialization")).map(|e|e.kind.rsplit("::").next().unwrap()).collect::<Vec<_>>(),vec!["Redefinition"]);
            let restored:crate::KirDocument=serde_json::from_str(&serde_json::to_string(&document).unwrap()).unwrap();
            for mut model in [document,restored] {
                let parameter=model.elements.iter().find(|e|e.id==parameter_id).unwrap();
                assert_eq!(definition_general_type_inputs_query(&model.elements,parameter).unwrap(),before);
                assert_eq!(definition_redefined_features(&model.elements,parameter,false).unwrap().iter().map(|e|e.id.clone()).collect::<Vec<_>>(),vec![gp.clone()]);
                assert!(model.elements.iter().all(|e|e.properties.get("is_implied_included")!=Some(&json!(true))));
                let snapshot=serde_json::to_value(&model).unwrap();
                assert_eq!(definition_materialize_feature_defaults(&mut model.elements,&[(&parameter_id,"replay")]).unwrap(),0);
                assert_eq!(snapshot,serde_json::to_value(&model).unwrap());
                assert!(!model.elements.iter().any(|e|metaclass_conforms(&e.kind,"FeatureChaining")),"directed valuation must not introduce bound-value chains");
            }
        }
    }

    #[test]
    fn definition_parameter_defaults_preserve_typed_requirements_and_guards() {
        let mut graph=vec![fresh_definition_element("context".into(),"OperatorExpression").unwrap()];
        let mut parameter=fresh_definition_element("parameter".into(),"Feature").unwrap();parameter.properties.insert("direction".into(),json!("in"));
        cross_test_own(&mut graph,"context","ParameterMembership",parameter);
        let before=serde_json::to_value(&graph).unwrap();let parameter=graph.iter().find(|e|e.id=="parameter").unwrap();
        assert!(matches!(definition_general_type_inputs_query(&graph,parameter),Err(QueryFailure::Required(Prerequisite::AdditionalMembers {owner_id})) if owner_id=="context"));
        assert_eq!(before,serde_json::to_value(&graph).unwrap());
        graph[0].kind="SysML::Function".into();let mut specialization=fresh_definition_element("pending".into(),"Specialization").unwrap();specialization.properties.insert("specific".into(),json!("context"));
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,&mut graph[0],&mut specialization).unwrap();graph.push(specialization);
        let parameter=graph.iter().find(|e|e.id=="parameter").unwrap();
        assert!(matches!(definition_general_type_inputs_query(&graph,parameter),Err(QueryFailure::Required(Prerequisite::ReadField {owner_id,field})) if owner_id=="pending" && field=="general"));
        for shape in ["detached","package","variable","composite","end","invalid_direction","crossing","malformed_valuation"] {
            let mut graph=vec![fresh_definition_element("context".into(),if shape=="package" {"Package"} else {"Function"}).unwrap()];
            let mut parameter=fresh_definition_element("parameter".into(),"Feature").unwrap();parameter.properties.insert("direction".into(),json!(if shape=="invalid_direction" {"invalid"}else{"in"}));
            if matches!(shape,"variable"|"composite"|"end") {parameter.properties.insert(format!("is_{shape}"),json!(true));}
            if shape=="detached" {graph.push(parameter);} else {cross_test_own(&mut graph,"context","ParameterMembership",parameter);}
            if matches!(shape,"crossing"|"malformed_valuation") {
                let mut relation=fresh_definition_element("unassessed".into(),if shape=="crossing" {"CrossSubsetting"}else{"FeatureValue"}).unwrap();
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,graph.iter_mut().find(|e|e.id=="parameter").unwrap(),&mut relation).unwrap();graph.push(relation);
            }
            let parameter=graph.iter().find(|e|e.id=="parameter").unwrap();assert!(definition_feature_default_name(&graph,parameter).is_err(),"{shape}");
        }
    }

    #[test]
    fn definition_relationship_memberships_preserve_pilot_direct_projections() {
        let controls: Value = serde_json::from_str(include_str!("../../../../../../docs/conformance/2026-08-support/relationship-membership-pilot-controls.json")).unwrap();
        assert_eq!(controls["bindings"].as_array().unwrap().len(), 10);
        assert_eq!(controls["controls"].as_array().unwrap().len(), 50);
        for case in controls["controls"].as_array().unwrap() {
            let mut owner=fresh_definition_element("subject".into(),"Feature").unwrap();
            let mut graph=Vec::new();
            let kind=case["typing"].as_str().unwrap();
            if kind!="none" {
                let target=fresh_definition_element("type".into(),kind).unwrap();
                let mut typing=fresh_definition_element("typing".into(),"FeatureTyping").unwrap();
                typing.properties.insert("typed_feature".into(),json!(owner.id));
                typing.properties.insert("type".into(),json!(target.id));
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,&mut owner,&mut typing).unwrap();
                graph.extend([target,typing]);
            }
            graph.push(owner);
            let before=definition_feature_default_name(&graph,graph.last().unwrap()).unwrap();
            cross_test_own(&mut graph,"subject","OwningMembership",
                fresh_definition_element("declaration".into(),case["kind"].as_str().unwrap()).unwrap());
            for mut model in [graph.clone(),serde_json::from_str::<Vec<KirElement>>(&serde_json::to_string(&graph).unwrap()).unwrap()] {
                model.reverse();
                let owner=model.iter().find(|e|e.id=="subject").unwrap();
                let snapshot=serde_json::to_value(&model).unwrap();
                assert_eq!(before,case["before"].as_str().unwrap());
                assert_eq!(definition_feature_default_name(&model,owner).unwrap(),case["after"].as_str().unwrap(),"{case}");
                assert_eq!(stored_children(&model,owner,"owned_relationship").unwrap().iter().filter(|r|metaclass_conforms(&r.kind,"Specialization")).count(),case["owned_specialization"].as_u64().unwrap() as usize);
                assert_eq!(definition_owned_features(&model,owner,false).unwrap().len(),case["owned_feature"].as_u64().unwrap() as usize);
                assert_eq!(snapshot,serde_json::to_value(&model).unwrap());
            }
        }
    }

    #[test]
    fn definition_relationship_memberships_reach_pinned_source_construction_and_linking() {
        let cache:Value=serde_json::from_str(include_str!("../../../../../../docs/conformance/2026-08-support/relationship-membership-scope-pilot-controls.json")).unwrap();
        assert_eq!(cache["cases"].as_array().unwrap().len(),3);
        for case in cache["cases"].as_array().unwrap() {
            let source=case["units"][0]["source"].as_str().unwrap();
            let kind=case["links"][0]["kind"].as_str().unwrap();
            if !case["assertion"]["resolved"].as_bool().unwrap() {
                assert!(crate::definition_document::parse_and_link(source,crate::SourceLanguage::Kerml).is_err(),"{case}");
                continue;
            }
            let (first,second)=if kind=="Subsetting" {("subsetting_feature","subsetted_feature")} else {("type_disjoined","disjoining_type")};
            let document=crate::definition_document::parse_and_link(source,crate::SourceLanguage::Kerml).unwrap_or_else(|e|panic!("{source}: {e}"));
            let restored=serde_json::from_str::<crate::KirDocument>(&serde_json::to_string(&document).unwrap()).unwrap();
            for model in [&document,&restored] {
                let graph=&model.elements;
                let host=graph.iter().find(|e|e.properties.get("declared_name")==Some(&json!("host"))).unwrap();
                let declared=graph.iter().find(|e|e.kind.rsplit("::").next()==Some(kind)).unwrap();
                let index=graph.iter().map(|e|(e.id.as_str(),e)).collect();
                let membership=scope_container(&index,declared).unwrap().unwrap();
                assert_eq!(membership.kind.rsplit("::").next(),Some("OwningMembership"));
                assert_eq!(scope_container(&index,membership).unwrap().unwrap().id,host.id);
                assert_eq!(definition_feature_default_name(graph,host).unwrap(),"Base::things");
                for (field,name) in [(first,"a"),(second,"b")] {
                    let id=declared.properties[field].as_str().unwrap();
                    assert_eq!(graph.iter().find(|e|e.id==id).unwrap().properties["declared_name"],json!(name));
                }
            }
        }
    }

    #[test]
    fn definition_relationship_memberships_preserve_lifecycle_and_containment_guards() {
        for kind in ["Subsetting","Disjoining","FeatureInverting"] {
            let mut graph=vec![fresh_definition_element("subject".into(),"Feature").unwrap()];
            cross_test_own(&mut graph,"subject","OwningMembership",fresh_definition_element("declaration".into(),kind).unwrap());
            graph.iter_mut().find(|e|e.id=="declaration").unwrap().properties.insert("is_implied".into(),json!(true));
            assert!(definition_feature_default_name(&graph,&graph[0]).unwrap_err().message.contains("contribution assessment"));
            graph.iter_mut().find(|e|e.id=="declaration").unwrap().properties.remove("is_implied");
            graph.iter_mut().find(|e|e.id=="declaration.member").unwrap().properties.insert("owned_related_element".into(),json!([]));
            assert!(definition_feature_default_name(&graph,&graph[0]).is_err());
        }
        let mut graph=vec![fresh_definition_element("subject".into(),"Feature").unwrap()];
        cross_test_own(&mut graph,"subject","OwningMembership",fresh_definition_element("valuation".into(),"FeatureValue").unwrap());
        assert!(definition_feature_default_name(&graph,&graph[0]).is_err());
    }

    fn cross_test_own(graph: &mut Vec<KirElement>, owner_id: &str, kind: &str, mut child: KirElement) {
        child.properties.insert("declared_name".into(), json!(child.id));
        let mut membership = fresh_definition_element(format!("{}.member", child.id), kind).unwrap();
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS, &mut membership, &mut child).unwrap();
        let owner = graph.iter_mut().find(|e| e.id == owner_id).unwrap();
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, owner, &mut membership).unwrap();
        graph.extend([membership, child]);
    }

    fn metadata_test_annotate(graph: &mut Vec<KirElement>, owner: &str, target: &str,
        name: &str, kind: &str) {
        let mut value=fresh_definition_element(name.into(),kind).unwrap();
        value.properties.insert("declared_name".into(),json!(name));
        let mut annotation=fresh_definition_element(format!("annotation.{name}"),"Annotation").unwrap();
        annotation.properties.insert("annotated_element".into(),json!(target));
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS,&mut annotation,&mut value).unwrap();
        let owner=graph.iter_mut().find(|e|e.id==owner).unwrap();
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,owner,&mut annotation).unwrap();
        graph.extend([annotation,value]);
    }

    fn metadata_test_graph(shape: &str) -> Vec<KirElement> {
        let mut graph=vec![fresh_definition_element("subject".into(),"Class").unwrap(),
            fresh_definition_element("other".into(),"Package").unwrap()];
        for e in &mut graph { e.properties.insert("declared_name".into(),json!(e.id)); }
        match shape {
            "documentation"=>metadata_test_annotate(&mut graph,"subject","subject","doc","Documentation"),
            "unrelated"=>cross_test_own(&mut graph,"other","OwningMembership",fresh_definition_element("unrelated".into(),"MetadataFeature").unwrap()),
            "annotation_owned"=>metadata_test_annotate(&mut graph,"subject","subject","applied","MetadataFeature"),
            "annotation_external"|"member_other"=> {
                let external=shape=="annotation_external";
                let name=if external {"external"} else {"member"};
                cross_test_own(&mut graph,if external {"other"}else{"subject"},"OwningMembership",fresh_definition_element(name.into(),"MetadataFeature").unwrap());
                let mut ann=fresh_definition_element(format!("annotation.{name}"),"Annotation").unwrap();
                ann.properties.insert("annotated_element".into(),json!(if external {"subject"}else{"other"}));
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,graph.iter_mut().find(|e|e.id==name).unwrap(),&mut ann).unwrap();
                graph.push(ann);
            },
            "member_implicit"=>cross_test_own(&mut graph,"subject","OwningMembership",fresh_definition_element("member".into(),"MetadataFeature").unwrap()),
            "alias"=> {
                cross_test_own(&mut graph,"other","OwningMembership",fresh_definition_element("alias".into(),"MetadataFeature").unwrap());
                let mut alias=fresh_definition_element("alias.link".into(),"Membership").unwrap();
                alias.properties.insert("member_element".into(),json!("alias"));
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,&mut graph[0],&mut alias).unwrap();graph.push(alias);
            },
            "ordered"=> {
                metadata_test_annotate(&mut graph,"subject","subject","first","MetadataFeature");
                metadata_test_annotate(&mut graph,"subject","subject","second","MetadataFeature");
                cross_test_own(&mut graph,"subject","OwningMembership",fresh_definition_element("third".into(),"MetadataFeature").unwrap());
            },
            "empty"=>{},
            _=>panic!("unknown control"),
        }
        graph
    }

    #[test]
    fn definition_metadata_query_reuses_view_for_broad_owned_members_and_persistence() {
        let controls: Value = serde_json::from_str(include_str!("../../../../../../docs/conformance/2026-08-support/metadata-selection-pilot-controls.json")).unwrap();
        for case in controls["cases"].as_array().unwrap() {
            let mut source = metadata_test_graph(case["shape"].as_str().unwrap());
            for i in 0..160 {
                cross_test_own(&mut source, "subject", "OwningMembership", fresh_definition_element(format!("ordinary{i}"), "Feature").unwrap());
            }
            for reverse in [false, true] {
                let mut graph: Vec<KirElement> = serde_json::from_value(serde_json::to_value(&source).unwrap()).unwrap();
                if reverse { graph.reverse(); }
                let before = serde_json::to_value(&graph).unwrap();
                let index = graph.iter().map(|e| (e.id.as_str(), e)).collect();
                let observed = std::cell::Cell::new(0);
                let observer = |event: DefinitionConstructionEvent<'_>| {
                    if event.phase == DefinitionConstructionPhase::MetadataSelectionStarted { observed.set(observed.get() + 1); }
                };
                let query = DefinitionNameQuery::observed(&graph, &index, &observer);
                let owner = graph.iter().find(|e| e.id == "subject").unwrap();
                for _ in 0..2 {
                    let selected = definition_projection::metadata_features_query(&query, owner).unwrap();
                    assert_eq!(json!(selected.iter().map(|e| e.properties["declared_name"].as_str().unwrap()).collect::<Vec<_>>()), case["metadata"]);
                }
                assert_eq!(observed.get(), 2, "metadata selection discarded caller view");
                assert_eq!(before, serde_json::to_value(&graph).unwrap());
            }
        }
    }

    #[test]
    fn definition_metadata_query_checks_late_nonmetadata_endpoints_on_every_attempt() {
        let mut graph = metadata_test_graph("empty");
        for i in 0..160 {
            cross_test_own(&mut graph, "subject", "OwningMembership", fresh_definition_element(format!("ordinary{i}"), "Feature").unwrap());
        }
        let late = graph.iter_mut().find(|e| e.properties.get("owned_related_element") == Some(&json!(["ordinary159"]))).unwrap();
        late.properties.insert("owned_related_element".into(), json!(["missing"]));
        let index = graph.iter().map(|e| (e.id.as_str(), e)).collect();
        let query = DefinitionNameQuery::new(&graph, &index);
        for _ in 0..2 {
            let failure = definition_projection::metadata_features_query(&query, &graph[0]).unwrap_err();
            assert!(failure.message.contains("missing contained element"), "{failure:?}");
        }
    }

    #[test]
    fn definition_reference_query_retains_first_stored_target_for_duplicate_graphs() {
        let mut relation = element("typing", "FeatureTyping");
        relation.properties.insert("type".into(), json!("target"));
        let graph = vec![relation, element("target", "Class"), element("target", "Feature")];
        let index = graph.iter().map(|e| (e.id.as_str(), e)).collect();
        let query = DefinitionNameQuery::new(&graph, &index);
        assert!(std::ptr::eq(definition_reference_targets_query(&query, &graph[0], "type").unwrap()[0], &graph[1]));
        assert!(std::ptr::eq(definition_reference_targets(&graph, &graph[0], "type").unwrap()[0], &graph[1]));
    }

    #[test]
    fn definition_metadata_selection_matches_pilot_and_persistence() {
        let controls:Value=serde_json::from_str(include_str!("../../../../../../docs/conformance/2026-08-support/metadata-selection-pilot-controls.json")).unwrap();
        assert_eq!(controls["cases"].as_array().unwrap().len(),9);
        for case in controls["cases"].as_array().unwrap() {
            let graph=metadata_test_graph(case["shape"].as_str().unwrap());
            let restored:Vec<KirElement>=serde_json::from_str(&serde_json::to_string(&graph).unwrap()).unwrap();
            for mut model in [graph,restored] {
                model.reverse(); // Collection order comes from containment, never graph storage.
                let owner=model.iter().find(|e|e.id=="subject").unwrap();
                let before=serde_json::to_value(&model).unwrap();
                let selected=definition_projection::metadata_features(&model,owner).unwrap();
                assert_eq!(json!(selected.iter().map(|e|e.properties["declared_name"].as_str().unwrap()).collect::<Vec<_>>()),case["metadata"],"{case}");
                let annotations=definition_reference_targets(&model,owner,"owned_annotation").unwrap();
                let observed=annotations.into_iter().map(|a| {
                    let target=definition_reference_targets(&model,a,"annotated_element").unwrap();
                    let value=definition_reference_targets(&model,a,"annotating_element").unwrap();
                    json!({"target":target[0].properties["declared_name"],"annotating":value.first().map(|e|e.properties["declared_name"].clone())})
                }).collect::<Vec<_>>();
                assert_eq!(json!(observed),case["owned_annotations"]);
                let empty=case["metadata"].as_array().unwrap().is_empty();
                assert_eq!(definition_projection::require_empty_metadata_bases(&model,owner).is_ok(),empty);
                assert_eq!(before,serde_json::to_value(&model).unwrap());
            }
        }
    }

    #[test]
    fn definition_metadata_selection_rejects_unresolved_invalid_and_stale_inputs() {
        for field in ["annotated_element","owned_related_element"] {
            let mut graph=metadata_test_graph("annotation_owned");
            graph.iter_mut().find(|e|e.id=="annotation.applied").unwrap().properties.remove(field);
            let before=serde_json::to_value(&graph).unwrap();
            assert!(definition_projection::metadata_features(&graph,&graph[0]).is_err());
            assert_eq!(before,serde_json::to_value(&graph).unwrap());
        }
        let mut graph=metadata_test_graph("member_implicit");
        graph.iter_mut().find(|e|e.id=="member").unwrap().properties.insert("owning_relationship".into(),json!("missing"));
        assert!(definition_projection::metadata_features(&graph,&graph[0]).is_err());
        let mut graph=metadata_test_graph("annotation_owned");
        graph[0].properties.insert("owned_annotation".into(),json!([]));
        graph.iter_mut().find(|e|e.id=="annotation.applied").unwrap().properties.insert("annotating_element".into(),Value::Null);
        assert_eq!(definition_projection::metadata_features(&graph,&graph[0]).unwrap()[0].id,"applied");
        assert!(definition_projection::require_empty_metadata_bases(&graph,&graph[0]).unwrap_err().message.contains("base-type evaluation remains unsupported"));
    }

    fn cross_test_graph(ends: &[bool], type_owner: bool) -> Vec<KirElement> {
        let mut graph = vec![fresh_definition_element("context".into(), if type_owner { "Classifier" } else { "Package" }).unwrap()];
        for (i, is_end) in ends.iter().enumerate() {
            let mut feature = fresh_definition_element(format!("end{i}"), "Feature").unwrap();
            feature.properties.insert("is_end".into(), json!(is_end));
            cross_test_own(&mut graph, "context", if type_owner { "FeatureMembership" } else { "OwningMembership" }, feature);
        }
        graph
    }

    #[test]
    fn definition_cross_readiness_passive_annotations_match_independent_endpoints() {
        let controls: Value = serde_json::from_str(include_str!("../../../../../../docs/conformance/2026-08-support/crossing-annotation-pilot-controls.json")).unwrap();
        assert_eq!(controls["cases"].as_array().unwrap().len(), 10);
        for case in controls["cases"].as_array().unwrap() {
            let kind = case["kind"].as_str().unwrap();
            let mut source = vec![fresh_definition_element("subject".into(), "Class").unwrap(),
                fresh_definition_element("receiver".into(), "Feature").unwrap()];
            if kind == "absent" {
                let mut ann = fresh_definition_element("annotation.endpoint".into(), "Annotation").unwrap();
                ann.properties.insert("annotated_element".into(), json!("subject"));
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, &mut source[0], &mut ann).unwrap();
                source.push(ann);
            } else if case["ownership"] == "owned" {
                metadata_test_annotate(&mut source, "subject", "subject", "endpoint", kind);
            } else {
                let mut endpoint = fresh_definition_element("endpoint".into(), kind).unwrap();
                endpoint.properties.insert("declared_name".into(), json!("endpoint"));
                let mut ann = fresh_definition_element("annotation.endpoint".into(), "Annotation").unwrap();
                ann.properties.insert("annotated_element".into(), json!("subject"));
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, &mut endpoint, &mut ann).unwrap();
                source.extend([endpoint, ann]);
            }
            let restored: Vec<KirElement> = serde_json::from_value(serde_json::to_value(&source).unwrap()).unwrap();
            let mut reversed = source.clone(); reversed.reverse();
            for graph in [&source, &reversed, &restored] {
                let before = serde_json::to_value(graph).unwrap();
                let index = graph.iter().map(|e| (e.id.as_str(), e)).collect();
                let query = DefinitionNameQuery::new(graph, &index);
                let receiver = index["receiver"]; let annotation = index["annotation.endpoint"];
                let endpoints = definition_reference_targets_query(&query, annotation, "annotating_element").unwrap();
                assert_eq!(endpoints.first().map(|e| e.kind.rsplit("::").next().unwrap()), case["annotating_kind"].as_str());
                for _ in 0..2 {
                    if kind == "absent" {
                        assert!(query.has_semantic_metadata().is_err());
                        assert!(query.semantic_metadata_present.get().is_none(), "failed assessment was cached");
                    } else {
                        assert_eq!(query.has_semantic_metadata().unwrap(), kind == "MetadataFeature");
                        // Conservatively retain actual metadata even when this
                        // owner-specific independent selection is empty.
                        assert_eq!(json!(definition_projection::metadata_features_query(&query, index["subject"]).unwrap()
                            .iter().map(|e| e.properties["declared_name"].as_str().unwrap()).collect::<Vec<_>>()), case["metadata"]);
                        let outcome = definition_cross_feature_in_view(&query, receiver);
                        if kind == "MetadataFeature" {
                            assert!(matches!(outcome, Err(QueryFailure::Rejected(d)) if d.message.contains("semantic metadata evaluation") && d.message.contains("receiver")));
                        } else { assert!(outcome.unwrap().is_none()); }
                    }
                }
                assert_eq!(before, serde_json::to_value(graph).unwrap());
            }
        }
    }

    #[test]
    fn definition_cross_readiness_binary_queries_construct_retry_and_replay() {
        let controls: Value = serde_json::from_str(include_str!("../../../../../../docs/conformance/2026-08-support/cross-feature-pilot-controls.json")).unwrap();
        for case in controls["cross_feature_controls"].as_array().unwrap() {
            for kind in ["Documentation", "Comment", "TextualRepresentation"] {
                let mut original = cross_test_graph(&[case["is_end"].as_bool().unwrap(), true], case["type_owner"].as_bool().unwrap());
                if case["candidate"].as_bool().unwrap() {
                    cross_test_own(&mut original, "end0", "OwningMembership", fresh_definition_element("cross".into(), "Feature").unwrap());
                }
                metadata_test_annotate(&mut original, "context", "context", "passive", kind);
                for mode in ["original", "reversed", "persisted"] {
                    let mut graph = if mode == "persisted" {
                        serde_json::from_value(serde_json::to_value(&original).unwrap()).unwrap()
                    } else { original.clone() };
                    if mode == "reversed" { graph.reverse(); }
                    let initial = serde_json::to_value(&graph).unwrap();
                    let expected_construction = !case["cross_feature"].as_array().unwrap().is_empty();
                    for _ in 0..2 {
                        let owner = graph.iter().find(|e| e.id == "end0").unwrap();
                        let read = definition_cross_feature_query(&graph, owner);
                        if expected_construction {
                            assert!(matches!(read, Err(QueryFailure::Required(Prerequisite::BinaryCrossing { owner_id })) if owner_id == "end0"));
                        } else { assert!(read.unwrap().is_none()); }
                    }
                    assert_eq!(initial, serde_json::to_value(&graph).unwrap());
                    assert_eq!(definition_materialize_binary_crossing_query(&mut graph, "end0", "generated").unwrap(), expected_construction);
                    let before_replay = serde_json::to_value(&graph).unwrap();
                    let owner = graph.iter().find(|e| e.id == "end0").unwrap();
                    assert_eq!(json!(definition_cross_feature_query(&graph, owner).unwrap().into_iter().map(|e| e.id.clone()).collect::<Vec<_>>()), case["cross_feature"]);
                    assert!(!scope_boolean(owner, "is_implied_included").unwrap());
                    assert!(!definition_materialize_binary_crossing_query(&mut graph, "end0", "replay").unwrap());
                    assert_eq!(before_replay, serde_json::to_value(&graph).unwrap());
                    assert!(ecore_model::validate_publication(&graph, ecore_model::ReferenceCompleteness::Closed).is_empty());
                }
            }
        }
    }

    #[test]
    fn definition_cross_readiness_missing_chaining_fields_stay_typed() {
        let mut source = cross_test_graph(&[true, true], true);
        cross_test_own(&mut source, "end0", "OwningMembership", fresh_definition_element("cross".into(), "Feature").unwrap());
        let mut relation = fresh_definition_element("pending.chain".into(), "FeatureChaining").unwrap();
        relation.properties.remove("chaining_feature");
        let other = source.iter_mut().find(|e| e.id == "end1").unwrap();
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, other, &mut relation).unwrap();
        source.push(relation);
        for reverse in [false, true] {
            let mut graph: Vec<KirElement> = serde_json::from_value(serde_json::to_value(&source).unwrap()).unwrap();
            if reverse { graph.reverse(); }
            let initial = serde_json::to_value(&graph).unwrap();
            for _ in 0..2 {
                let owner = graph.iter().find(|e| e.id == "end0").unwrap();
                assert!(matches!(definition_cross_feature_query(&graph, owner),
                    Err(QueryFailure::Required(Prerequisite::ReadField { owner_id, field }))
                    if owner_id == "pending.chain" && field == "chaining_feature"));
                assert!(matches!(definition_materialize_binary_crossing_query(&mut graph, "end0", "generated"),
                    Err(QueryFailure::Required(Prerequisite::ReadField { owner_id, field }))
                    if owner_id == "pending.chain" && field == "chaining_feature"));
                assert_eq!(initial, serde_json::to_value(&graph).unwrap());
            }
            graph.iter_mut().find(|e| e.id == "pending.chain").unwrap().properties.insert("chaining_feature".into(), json!("cross"));
            let repaired = serde_json::to_value(&graph).unwrap();
            let owner = graph.iter().find(|e| e.id == "end0").unwrap();
            assert!(matches!(definition_cross_feature_query(&graph, owner), Err(QueryFailure::Rejected(d)) if d.message.contains("compound end/cross") && d.message.contains("end0")));
            assert!(definition_materialize_binary_crossing_query(&mut graph, "end0", "generated").is_err());
            assert_eq!(repaired, serde_json::to_value(&graph).unwrap());
        }
    }

    #[test]
    fn definition_cross_readiness_annotation_failures_and_edits_recompute() {
        let mut original = vec![fresh_definition_element("subject".into(), "Class").unwrap(),
            fresh_definition_element("receiver".into(), "Feature").unwrap()];
        metadata_test_annotate(&mut original, "subject", "subject", "passive", "Documentation");
        for failure in ["missing_field", "missing_endpoint", "wrong_kind", "foreign_owner", "empty_endpoint", "duplicate_identity"] {
            let mut graph = original.clone();
            match failure {
                "missing_field" => { graph.iter_mut().find(|e| e.id == "annotation.passive").unwrap().properties.remove("owned_related_element"); },
                "missing_endpoint" => { graph.retain(|e| e.id != "passive"); },
                "wrong_kind" => { graph.iter_mut().find(|e| e.id == "passive").unwrap().kind = "SysML::Feature".into(); },
                "foreign_owner" => { graph.iter_mut().find(|e| e.id == "passive").unwrap().properties.insert("owning_relationship".into(), json!("missing")); },
                "empty_endpoint" => { graph.iter_mut().find(|e| e.id == "annotation.passive").unwrap().properties.insert("owned_related_element".into(), json!([])); graph.retain(|e| e.id != "passive"); },
                _ => { graph.push(graph.iter().find(|e| e.id == "passive").unwrap().clone()); },
            }
            let index = graph.iter().map(|e| (e.id.as_str(), e)).collect();
            let query = DefinitionNameQuery::new(&graph, &index);
            for _ in 0..2 {
                assert!(query.has_semantic_metadata().is_err(), "{failure}");
                assert!(query.semantic_metadata_present.get().is_none());
                assert!(definition_cross_feature_in_view(&query, index["receiver"]).is_err(), "{failure}");
            }
            let repaired: Vec<KirElement> = serde_json::from_value(serde_json::to_value(&original).unwrap()).unwrap();
            let index = repaired.iter().map(|e| (e.id.as_str(), e)).collect();
            let query = DefinitionNameQuery::new(&repaired, &index);
            assert!(!query.has_semantic_metadata().unwrap());
        }
        original.iter_mut().find(|e| e.id == "passive").unwrap().kind = "SysML::MetadataFeature".into();
        let index = original.iter().map(|e| (e.id.as_str(), e)).collect();
        let query = DefinitionNameQuery::new(&original, &index);
        assert!(query.has_semantic_metadata().unwrap());
        assert!(definition_cross_feature_in_view(&query, index["receiver"]).is_err());
    }

    #[test]
    fn definition_cross_readiness_unassessed_contexts_identify_receiver() {
        for mode in ["nonbinary", "adapter", "metadata"] {
            let mut graph = cross_test_graph(&[true, true, mode == "nonbinary"], true);
            cross_test_own(&mut graph, "end0", "OwningMembership", fresh_definition_element("cross".into(), "Feature").unwrap());
            if mode == "adapter" { graph.iter_mut().find(|e| e.id == "end0").unwrap().kind = "SysML::ReferenceUsage".into(); }
            if mode == "metadata" { graph.push(fresh_definition_element("metadata".into(), "MetadataFeature").unwrap()); }
            let before = serde_json::to_value(&graph).unwrap();
            let owner = graph.iter().find(|e| e.id == "end0").unwrap();
            let Err(QueryFailure::Rejected(issue)) = definition_cross_feature_query(&graph, owner) else { panic!("{mode}: expected rejection"); };
            let expected = match mode { "nonbinary" => "nonbinary crossing", "adapter" => "unassessed adapter", _ => "semantic metadata evaluation" };
            assert!(issue.message.contains(expected) && issue.message.contains("end0") && issue.message.contains(&owner.kind), "{}", issue.message);
            assert_eq!(before, serde_json::to_value(&graph).unwrap());
        }
    }

    #[test]
    fn definition_cross_readiness_source_pipeline_preserves_reference_controls_with_docs() {
        let controls: Value = serde_json::from_str(include_str!("../../../../../../docs/conformance/2026-08-support/chain-link-pilot-controls.json")).unwrap();
        let cases = &controls["candidate_scope_controls"].as_array().unwrap()[13..];
        assert_eq!(cases.len(), 8);
        for case in cases {
            let source = format!("doc /* passive crossing context */\n{}", case["source"].as_str().unwrap());
            let result = crate::definition_document::parse_and_link(&source, crate::SourceLanguage::Kerml);
            if case["links"].as_array().unwrap().iter().any(|link| link["resolved"] == false) {
                assert!(matches!(result, Err(crate::definition_document::DefinitionDocumentError::ConstructionOrLinking(_))));
                continue;
            }
            let document = result.unwrap();
            let restored: crate::KirDocument = serde_json::from_value(serde_json::to_value(&document).unwrap()).unwrap();
            for model in [&document, &restored] {
                assert!(model.elements.iter().any(|e| metaclass_conforms(&e.kind, "Documentation")));
                let index = model.elements.iter().map(|e| (e.id.as_str(), e)).collect();
                let query = DefinitionNameQuery::new(&model.elements, &index);
                assert!(!query.has_semantic_metadata().unwrap());
                assert!(ecore_model::validate_publication(&model.elements, ecore_model::ReferenceCompleteness::Closed).is_empty());
                let owner = model.elements.iter().find(|e| e.properties.get("declared_name") == Some(&json!("e"))).unwrap();
                let cross = definition_owned_cross_feature_in_view(&query, owner).unwrap().unwrap();
                assert!(definition_pending_cross_specializations_in_view(&query, cross).unwrap().is_empty());
                assert!(!scope_boolean(cross, "is_implied_included").unwrap());
            }
        }
    }

