    #[test]
    fn definition_explicit_crossing_providers_match_pilot() {
        let artifact: Value = serde_json::from_str(include_str!("../../../../../../docs/conformance/2026-08-support/cross-feature-pilot-controls.json")).unwrap();
        let cases = artifact["explicit_controls"].as_array().unwrap();
        assert_eq!(cases.len(), 6);
        for case in cases {
            let document = crate::definition_document::parse_and_link("standard library package Base { feature things; }", crate::SourceLanguage::Kerml).unwrap();
            let mut graph = document.elements;
            graph.iter_mut().find(|e| e.properties.get("declared_name") == Some(&json!("things"))).unwrap().properties.insert("is_implied_included".into(), json!(true));
            let mut context = fresh_definition_element("context".into(), "Class").unwrap();
            context.properties.insert("is_implied_included".into(), json!(true));
            graph.push(context);
            let mut owner = fresh_definition_element("owner".into(), "Feature").unwrap();
            owner.properties.insert("is_end".into(), case["is_end"].clone());
            cross_test_own(&mut graph, "context", "FeatureMembership", owner);
            let length = case["chain_length"].as_u64().unwrap() as usize;
            let ids: Vec<_> = (0..length).map(|i| format!("part{i}")).collect();
            for id in &ids {
                let mut part = fresh_definition_element(id.clone(), "Feature").unwrap();
                part.properties.insert("is_implied_included".into(), json!(true));
                graph.push(part);
            }
            let mut target = fresh_definition_element("targetType".into(), "Classifier").unwrap();
            target.properties.insert("is_implied_included".into(), json!(true));
            graph.push(target);
            definition_append_implied_specialization(&mut graph, "typing", "FeatureTyping", ids.last().unwrap(), "targetType").unwrap();
            definition_append_feature_chain(&mut graph, "chain", &ids.iter().map(String::as_str).collect::<Vec<_>>()).unwrap();
            definition_append_implied_specialization(&mut graph, "crossing", "CrossSubsetting", "owner", "chain").unwrap();
            graph.iter_mut().find(|e| e.id == "crossing").unwrap().properties.insert("is_implied".into(), json!(false));
            let restored: Vec<KirElement> = serde_json::from_str(&serde_json::to_string(&graph).unwrap()).unwrap();
            for model in [&graph, &restored] {
                let before = serde_json::to_value(model).unwrap();
                for (id, defaults, types) in [("owner", "owner_default", "owner_types"), ("chain", "chain_default", "chain_types")] {
                    let element = model.iter().find(|e| e.id == id).unwrap();
                    assert_eq!(definition_feature_default_name(model, element).unwrap(), case[defaults].as_str().unwrap());
                    assert_eq!(json!(definition_feature_types(model, element).unwrap().iter().map(|e| e.id.clone()).collect::<Vec<_>>()), case[types]);
                    assert!(!scope_boolean(element, "is_implied_included").unwrap());
                }
                assert_eq!(before, serde_json::to_value(model).unwrap());
            }
            let mut pending_navigation = graph.clone();
            let chaining = pending_navigation.iter_mut().find(|e| metaclass_conforms(&e.kind, "FeatureChaining")).unwrap();
            let pending_id = chaining.id.clone();
            chaining.properties.remove("chaining_feature");
            let owner = pending_navigation.iter().find(|e| e.id == "owner").unwrap();
            let before = serde_json::to_value(&pending_navigation).unwrap();
            assert_eq!(json!(definition_feature_types_query(&pending_navigation, owner).unwrap().iter().map(|e| e.id.clone()).collect::<Vec<_>>()), case["owner_types"]);
            let chain = pending_navigation.iter().find(|e| e.id == "chain").unwrap();
            assert!(matches!(definition_feature_types_query(&pending_navigation, chain),
                Err(QueryFailure::Required(Prerequisite::ReadField { owner_id, field }))
                if owner_id == pending_id && field == "chaining_feature"));
            assert_eq!(before, serde_json::to_value(&pending_navigation).unwrap());
            for failure in ["implied", "extra_chain_member", "duplicate"] {
                let mut invalid = graph.clone();
                match failure {
                    "implied" => { invalid.iter_mut().find(|e| e.id == "crossing").unwrap().properties.insert("is_implied".into(), json!(true)); },
                    "extra_chain_member" => cross_test_own(&mut invalid, "chain", "OwningMembership", fresh_definition_element("extra".into(), "Feature").unwrap()),
                    _ => { definition_append_implied_specialization(&mut invalid, "duplicate", "CrossSubsetting", "owner", "chain").unwrap(); },
                }
                let owner = invalid.iter().find(|e| e.id == "owner").unwrap();
                let before = serde_json::to_value(&invalid).unwrap();
                assert!(definition_feature_default_name(&invalid, owner).is_err(), "{failure}");
                assert_eq!(before, serde_json::to_value(&invalid).unwrap());
            }
        }
    }

