    #[test]
    fn definition_feature_query_prerequisites_remain_typed() {
        let mut graph = cross_test_graph(&[true, true], true);
        for element in &mut graph { element.properties.insert("is_implied_included".into(), json!(true)); }
        let mut chain = fresh_definition_element("pending.chain".into(), "FeatureChaining").unwrap();
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,
            graph.iter_mut().find(|e| e.id == "end0").unwrap(), &mut chain).unwrap();
        graph.push(chain);
        let source = graph.iter().find(|e| e.id == "end0").unwrap();
        let before = serde_json::to_value(&graph).unwrap();
        assert!(matches!(definition_feature_types_query(&graph, source),
            Err(QueryFailure::Required(Prerequisite::ReadField { owner_id, field }))
            if owner_id == "pending.chain" && field == "chaining_feature"));
        assert!(matches!(definition_general_type_inputs(&graph, source).unwrap(),
            DefinitionGeneralTypes::Deferred(GeneratedLinkTarget::Deferred { owner_id, field })
            if owner_id == "pending.chain" && field == "chaining_feature"));
        assert!(definition_general_type_inputs_for_scope_query(&graph, source, "pending.chain").is_ok());
        assert!(matches!(definition_general_type_inputs_for_scope_query(&graph, source, "unrelated.chain"),
            Err(QueryFailure::Required(Prerequisite::ReadField { .. }))));
        assert!(definition_feature_types(&graph, source).is_err(), "immutable query cannot complete a pending field");
        assert_eq!(before, serde_json::to_value(&graph).unwrap());
        for malformed in [json!(4), json!(null), json!("absent.target")] {
            let mut invalid = graph.clone();
            invalid.iter_mut().find(|e| e.id == "pending.chain").unwrap().properties.insert("chaining_feature".into(), malformed);
            let source = invalid.iter().find(|e| e.id == "end0").unwrap();
            assert!(matches!(definition_feature_types_query(&invalid, source), Err(QueryFailure::Rejected(_))));
            assert!(matches!(definition_general_type_inputs_for_scope_query(&invalid, source, "pending.chain"), Err(QueryFailure::Rejected(_))));
        }
    }

    #[test]
    fn definition_source_cross_queries_schedule_prerequisites() {
        let controls: Value = serde_json::from_str(include_str!("../../../../../../docs/conformance/2026-08-support/chain-link-pilot-controls.json")).unwrap();
        let cases = &controls["candidate_scope_controls"].as_array().unwrap()[13..];
        assert_eq!(cases.len(), 8);
        for case in cases {
            let result = crate::definition_document::parse_and_link(case["source"].as_str().unwrap(), crate::SourceLanguage::Kerml);
            if case["links"].as_array().unwrap().iter().any(|link| link["resolved"] == false) {
                assert!(matches!(result, Err(crate::definition_document::DefinitionDocumentError::ConstructionOrLinking(_))));
                continue;
            }
            let document = result.unwrap();
            let restored: crate::KirDocument = serde_json::from_str(&serde_json::to_string(&document).unwrap()).unwrap();
            for model in [&document, &restored] {
                let owner = model.elements.iter().find(|e| e.properties.get("declared_name") == Some(&json!("e"))).unwrap();
                let cross = definition_owned_cross_feature(&model.elements, owner).unwrap().unwrap();
                assert!(definition_pending_cross_specializations_query(&model.elements, cross).unwrap().is_empty());
                let target = model.elements.iter().find(|e| e.properties.get("declared_name") == Some(&json!("T"))).unwrap();
                let types = stored_children(&model.elements, cross, "owned_relationship").unwrap().into_iter()
                    .filter(|r| metaclass_conforms(&r.kind, "FeatureTyping"))
                    .map(|r| redefined_reference(&model.elements, r, "general").unwrap().id.clone()).collect::<Vec<_>>();
                assert_eq!(types, vec![target.id.clone()]);
                let member = model.elements.iter().find(|e| e.properties.get("declared_name") == Some(&json!("m"))).unwrap();
                assert!(model.elements.iter().any(|e| metaclass_conforms(&e.kind, "FeatureChaining")
                    && e.properties.get("chaining_feature") == Some(&json!(member.id))));
                assert!(!scope_boolean(cross, "is_implied_included").unwrap());
                assert!(ecore_model::validate_publication(&model.elements, ecore_model::ReferenceCompleteness::Closed).is_empty());
            }
        }
    }

    #[test]
    fn definition_reciprocal_scope_matches_pilot_without_completion_flags() {
        let controls: Value = serde_json::from_str(include_str!("../../../../../../docs/conformance/2026-08-support/chain-link-pilot-controls.json")).unwrap();
        let cases = controls["reciprocal_scope_controls"].as_array().unwrap();
        assert_eq!(cases.len(), 8);
        for case in cases {
            let result = crate::definition_document::parse_and_link(case["source"].as_str().unwrap(), crate::SourceLanguage::Kerml);
            if case["links"].as_array().unwrap().iter().any(|link| link["resolved"] == false) {
                assert!(matches!(result, Err(crate::definition_document::DefinitionDocumentError::ConstructionOrLinking(_))));
                continue;
            }
            let document = result.unwrap();
            let restored: crate::KirDocument = serde_json::from_str(&serde_json::to_string(&document).unwrap()).unwrap();
            for model in [&document, &restored] {
                let index = model.elements.iter().map(|e| (e.id.as_str(), e)).collect::<BTreeMap<_, _>>();
                // Pilot observes source-owned chains; separately constructed
                // implied crossing chains are not source reference observations.
                let chain = model.elements.iter().filter(|e| metaclass_conforms(&e.kind, "FeatureChaining"))
                    .filter(|e| {
                        let feature = scope_container(&index, e).unwrap().unwrap();
                        let relation = scope_container(&index, feature).unwrap().unwrap();
                        !scope_boolean(relation, "is_implied").unwrap()
                    }).collect::<Vec<_>>();
                assert_eq!(chain.len(), 2);
                for (relation, observation) in chain.iter().zip(case["links"].as_array().unwrap()) {
                    let target = query_reference(&model.elements, relation, "chaining_feature").unwrap();
                    let mut path = Vec::new();
                    let mut cursor = Some(target);
                    while let Some(element) = cursor {
                        if let Some(name) = element.properties.get("declared_name").and_then(Value::as_str) { path.push(name.to_owned()); }
                        cursor = generated_parent_namespace(&model.elements, &element.id).unwrap();
                    }
                    path.reverse();
                    assert_eq!(json!(path), observation["target_path"]);
                }
                assert!(model.elements.iter().filter(|e| metaclass_conforms(&e.kind, "Type"))
                    .all(|e| !scope_boolean(e, "is_implied_included").unwrap()));
                assert!(ecore_model::validate_publication(&model.elements, ecore_model::ReferenceCompleteness::Closed).is_empty());
            }
        }
    }

    #[test]
    fn definition_linker_schedules_cross_specialization() {
        let source = "standard library package Base { feature things; classifier Anything; } standard library package Occurrences { feature occurrences; class Occurrence; } classifier T; class C { end cross feature e : T; end feature other; } feature x : Missing;";
        let tree = crate::xtext_fragment::candidate_document(source, true).unwrap();
        let saved = tree.clone();
        let calls = std::cell::Cell::new(0);
        let (root, mut graph) = materialize_generated_with_postprocessing(&tree, "model", &|site| {
            calls.set(calls.get()+1);
            let target = site.graph.iter().find(|e| e.properties.get("declared_name") == Some(&json!("T"))).unwrap();
            if calls.get() == 1 { return Ok(GeneratedLinkTarget::Local(target.id.clone())); }
            let owner = site.graph.iter().find(|e| e.properties.get("declared_name") == Some(&json!("e"))).unwrap();
            let cross = definition_owned_cross_feature(site.graph, owner)?.unwrap();
            if !definition_pending_cross_specializations(site.graph, cross)?.is_empty() {
                Ok(GeneratedLinkTarget::ConstructCrossSpecialization { owner_id: cross.id.clone() })
            } else { Ok(GeneratedLinkTarget::Local(cross.id.clone())) }
        }, true).unwrap();
        graph.insert(0, root);
        assert_eq!(calls.get(), 3);
        let owner = graph.iter().find(|e| e.properties.get("declared_name") == Some(&json!("e"))).unwrap();
        let cross = definition_owned_cross_feature(&graph, owner).unwrap().unwrap();
        let types = stored_children(&graph, cross, "owned_relationship").unwrap().into_iter()
            .filter(|r| metaclass_conforms(&r.kind, "FeatureTyping"))
            .map(|r| redefined_reference(&graph, r, "general").unwrap().id.clone()).collect::<Vec<_>>();
        let target = graph.iter().find(|e| e.properties.get("declared_name") == Some(&json!("T"))).unwrap();
        assert_eq!(types, vec![target.id.clone()]);
        assert!(!scope_boolean(cross, "is_implied_included").unwrap());
        assert!(ecore_model::validate_publication(&graph, ecore_model::ReferenceCompleteness::Closed).is_empty());
        assert_eq!(tree, saved);
        let restored: Vec<KirElement> = serde_json::from_str(&serde_json::to_string(&graph).unwrap()).unwrap();
        assert_eq!(graph, restored);
        for failure in ["late", "repeated", "no_progress", "fragment"] {
            let calls = std::cell::Cell::new(0);
            let result = materialize_generated_with_postprocessing(&tree, "model", &|site| {
                calls.set(calls.get()+1);
                let target = site.graph.iter().find(|e| e.properties.get("declared_name") == Some(&json!("T"))).unwrap();
                if calls.get() == 1 { return Ok(GeneratedLinkTarget::Local(target.id.clone())); }
                let owner = site.graph.iter().find(|e| e.properties.get("declared_name") == Some(&json!("e"))).unwrap();
                let cross = definition_owned_cross_feature(site.graph, owner)?.unwrap();
                if failure == "no_progress" { return Ok(GeneratedLinkTarget::ConstructCrossSpecialization { owner_id: target.id.clone() }); }
                if calls.get() == 2 || failure == "repeated" || failure == "fragment" {
                    return Ok(GeneratedLinkTarget::ConstructCrossSpecialization { owner_id: cross.id.clone() });
                }
                Err(error("late failure after cross specialization"))
            }, failure != "fragment");
            let issue = result.unwrap_err();
            let expected = match failure { "late" => "late failure", "repeated" => "repeated cross specialization", "no_progress" => "assessed Feature adapter", _ => "document linker" };
            assert!(issue.message.contains(expected), "{failure}: {}", issue.message);
            assert!(calls.get() <= 3);
            assert_eq!(tree, saved);
        }
    }

