    #[test]
    fn definition_linker_schedules_additional_members_transactionally() {
        let source="feature a; feature value = a; feature x : Missing; feature y : Missing;";
        let tree=crate::xtext_fragment::candidate_document(source,true).unwrap();let saved=tree.clone();
        for failure in ["none","late","repeated","fragment","unsupported"] {
            let calls=std::cell::Cell::new(0);
            let linked=materialize_generated_with_postprocessing(&tree,"model",&|site| {
                calls.set(calls.get()+1);
                let expression=site.graph.iter().find(|e|e.kind.rsplit("::").next()==Some("FeatureReferenceExpression")).unwrap();
                if calls.get()==1 || failure=="repeated" {
                    let owner=if failure=="unsupported" {site.graph.iter().find(|e|e.properties.get("declared_name")==Some(&json!("a"))).unwrap()} else {expression};
                    return Ok(GeneratedLinkTarget::ConstructAdditionalMembers {owner_id:owner.id.clone()});
                }
                if failure=="late" {return Err(error("late failure after additional members"));}
                let target=if site.feature.field=="referent" {
                    site.graph.iter().find(|e|e.properties.get("declared_name")==Some(&json!("a"))).unwrap().id.clone()
                } else {format!("{}.implicit.additional-members.result",expression.id)};
                Ok(GeneratedLinkTarget::Local(target))
            },failure!="fragment");
            assert_eq!(tree,saved,"failed/successful construction must preserve imported parse tree");
            if failure!="none" {
                let message=linked.unwrap_err().message;
                let expected=match failure {"late"=>"late failure","repeated"=>"repeated additional-member","fragment"=>"document linker",_=>"unsupported additional-member strategy"};
                assert!(message.contains(expected),"{failure}: {message}");continue;
            }
            let (root,mut graph)=linked.unwrap();graph.insert(0,root);
            assert!(ecore_model::validate_publication(&graph,ecore_model::ReferenceCompleteness::Closed).is_empty());
            let expression=graph.iter().find(|e|e.kind.rsplit("::").next()==Some("FeatureReferenceExpression")).unwrap();
            assert!(definition_additional_members_ready(&graph,expression).unwrap());
            assert_eq!(stored_children(&graph,expression,"owned_relationship").unwrap().iter().filter(|e|metaclass_conforms(&e.kind,"ReturnParameterMembership")).count(),1);
            assert!(graph.iter().all(|e|e.properties.get("is_implied_included")!=Some(&json!(true))));
            let snapshot=serde_json::to_value(&graph).unwrap();
            assert_eq!(definition_materialize_owned_expression_results(&mut graph,"replay").unwrap(),0);
            assert_eq!(serde_json::to_value(&graph).unwrap(),snapshot);
        }
    }

    #[test]
    fn definition_transition_context_stage_matches_prepared_pilot_observations() {
        let artifact:Value=serde_json::from_str(include_str!("../../../../resources/metamodels/sysml-2.0-pilot-2026-08/transition-context-stage.extract.json")).unwrap();
        assert_eq!(artifact["controls"].as_array().unwrap().len(),24);
        let mut physical=0;let mut queries=0;
        for case in artifact["controls"].as_array().unwrap() {
            let mut graph=vec![fresh_definition_element("root".into(),"Namespace").unwrap()];
            for id in ["a","b"] {cross_test_own(&mut graph,"root","OwningMembership",fresh_definition_element(id.into(),"Class").unwrap());}
            cross_test_own(&mut graph,"root","OwningMembership",fresh_definition_element("parent".into(),case["parent"].as_str().unwrap()).unwrap());
            cross_test_own(&mut graph,"parent","OwningMembership",fresh_definition_element("child".into(),"SuccessionAsUsage").unwrap());
            let shape=case["shape"].as_str().unwrap();
            if case["parent"]!="Namespace" && shape!="empty" {
                for (i,id) in (if shape=="one" {vec!["a"]}else if shape=="two" {vec!["a","b"]}else {vec!["a","a"]}).iter().enumerate() {
                    let mut r=fresh_definition_element(format!("parent.featuring.{i}"),"TypeFeaturing").unwrap();r.properties.insert("feature_of_type".into(),json!("parent"));r.properties.insert("featuring_type".into(),json!(id));
                    ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,graph.iter_mut().find(|e|e.id=="parent").unwrap(),&mut r).unwrap();graph.push(r);
                }
            }
            if case["existing"]==true {
                let mut r=fresh_definition_element("child.existing".into(),"TypeFeaturing").unwrap();r.properties.insert("feature_of_type".into(),json!("child"));r.properties.insert("featuring_type".into(),json!("a"));
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,graph.iter_mut().find(|e|e.id=="child").unwrap(),&mut r).unwrap();graph.push(r);
            }
            let restored:Vec<KirElement>=serde_json::from_str(&serde_json::to_string(&graph).unwrap()).unwrap();
            for model in [graph,restored] {for reverse in [false,true] {
                let mut model=model.clone();if reverse {model.reverse();}let before=serde_json::to_value(&model).unwrap();
                if case["parent"]=="TransitionUsage" {
                    let child=model.iter().find(|e|e.id=="child").unwrap();
                    assert_eq!(json!(definition_featuring_types_typed_query(&model,child).unwrap().iter().map(|e|e.id.as_str()).collect::<Vec<_>>()),case["query"]);queries+=1;
                    assert_eq!(before,serde_json::to_value(&model).unwrap());
                }
                transition_context_stage::append(&mut model,"child","context").unwrap();
                let child=model.iter().find(|e|e.id=="child").unwrap();
                let actual=definition_owned_type_featuring(&model,child).unwrap().iter().map(|r|json!({"target":query_reference(&model,r,"featuring_type").unwrap().id,"implied":scope_boolean(r,"is_implied").unwrap()})).collect::<Vec<_>>();
                assert_eq!(json!(actual),case["physical"],"{case}");physical+=1;
                assert!(model.iter().all(|e|e.properties.get("is_implied_included")!=Some(&json!(true))));
                assert!(ecore_model::validate_publication(&model,ecore_model::ReferenceCompleteness::Closed).is_empty());
                let replay=serde_json::to_value(&model).unwrap();assert_eq!(transition_context_stage::append(&mut model,"child","context").unwrap(),0);assert_eq!(replay,serde_json::to_value(&model).unwrap());
            }}
        }
        assert_eq!(physical,96);assert_eq!(queries,32);
    }

    #[test]
    fn definition_transition_context_stage_retains_pending_fields_and_atomicity() {
        let mut graph=vec![fresh_definition_element("root".into(),"Namespace").unwrap()];
        cross_test_own(&mut graph,"root","OwningMembership",fresh_definition_element("parent".into(),"TransitionUsage").unwrap());
        cross_test_own(&mut graph,"parent","OwningMembership",fresh_definition_element("child".into(),"SuccessionAsUsage").unwrap());
        let mut r=fresh_definition_element("pending".into(),"TypeFeaturing").unwrap();r.properties.insert("feature_of_type".into(),json!("parent"));
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,graph.iter_mut().find(|e|e.id=="parent").unwrap(),&mut r).unwrap();graph.push(r);
        let restored:Vec<KirElement>=serde_json::from_str(&serde_json::to_string(&graph).unwrap()).unwrap();
        for model in [graph,restored] {for reverse in [false,true] {
            let mut model=model.clone();if reverse {model.reverse();}let before=serde_json::to_value(&model).unwrap();
            for _ in 0..2 {
                let child=model.iter().find(|e|e.id=="child").unwrap();
                assert!(matches!(definition_featuring_types_typed_query(&model,child),Err(QueryFailure::Required(Prerequisite::ReadField{owner_id,field})) if owner_id=="pending" && field=="featuring_type"));
                assert!(matches!(transition_context_stage::append(&mut model,"child","context"),Err(QueryFailure::Required(Prerequisite::ReadField{owner_id,field})) if owner_id=="pending" && field=="featuring_type"));
                assert_eq!(before,serde_json::to_value(&model).unwrap());
            }
            model.iter_mut().find(|e|e.id=="pending").unwrap().properties.insert("featuring_type".into(),json!("a"));model.push(fresh_definition_element("a".into(),"Class").unwrap());
            // The imported physical insertion adopts a detached target into the
            // new TypeFeaturing; this does not complete or change the parent.
            assert_eq!(transition_context_stage::append(&mut model,"child","context").unwrap(),1);
            assert_eq!(model.iter().find(|e|e.id=="a").unwrap().properties["owning_relationship"],json!("context.0"));
            assert!(model.iter().all(|e|e.properties.get("is_implied_included")!=Some(&json!(true))));
            let stable=model.clone();model.iter_mut().find(|e|e.id=="pending").unwrap().properties.insert("featuring_type".into(),json!(false));let before=serde_json::to_value(&model).unwrap();
            assert!(matches!(transition_context_stage::append(&mut model,"child","context"),Err(QueryFailure::Rejected(_))));assert_eq!(before,serde_json::to_value(&model).unwrap());
            model=stable;let mut chain=fresh_definition_element("cycle".into(),"FeatureChaining").unwrap();chain.properties.insert("chaining_feature".into(),json!("child"));ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,model.iter_mut().find(|e|e.id=="parent").unwrap(),&mut chain).unwrap();model.push(chain);let before=serde_json::to_value(&model).unwrap();
            assert!(matches!(transition_context_stage::append(&mut model,"child","context"),Err(QueryFailure::Rejected(_))));assert_eq!(before,serde_json::to_value(&model).unwrap());
        }}
    }

    #[test]
    fn definition_cold_transition_construction_preserves_lifecycle_dependencies() {
        for source in ["state s { state a; state b; transition first a then b; }", "attribute x; state s { state a; state b; transition first a accept x then b; }"] {
            let tree=crate::xtext_fragment::candidate_document(source,false).unwrap();
            let saved=tree.clone();let mut pending=Vec::new();
            let (root,mut graph)=construct_generated_graph(&tree,"cold",&[],&mut pending,true).unwrap();
            graph.insert(0,root);
            assert_eq!(graph[0].kind,"SysML::Namespace");
            assert!(!pending.is_empty());
            let transition=graph.iter().find(|e|e.kind=="SysML::TransitionUsage").unwrap();
            let transition_id=transition.id.clone();
            let first=stored_children(&graph,transition,"owned_relationship").unwrap()[0];
            assert!(matches!(transition_source::membership_stable_query(&graph,transition),Err(QueryFailure::Required(Prerequisite::ReadField {owner_id,field})) if owner_id==first.id && field=="member_element"));
            let succession=graph.iter().find(|e|e.kind=="SysML::SuccessionAsUsage").unwrap();
            assert_eq!(generated_parent_namespace(&graph,&succession.id).unwrap().unwrap().id,transition.id);
            assert_eq!(definition_reference_targets(&graph,transition,"succession").unwrap()[0].id,succession.id);
            // Resolve only explicitly named source links through the normal private
            // linking transaction. This control supplies lexical endpoints; it does
            // not qualify the production scope algorithm or implicit lifecycle.
            let (root,mut graph)=materialize_generated_with_postprocessing(&tree,"cold",&|site| {
                let targets=site.graph.iter().filter(|e|e.properties.get("declared_name").and_then(Value::as_str)==Some(site.reference.spelling.as_str())).collect::<Vec<_>>();
                assert_eq!(targets.len(),1);
                Ok(GeneratedLinkTarget::Local(targets[0].id.clone()))
            },true).unwrap();graph.insert(0,root);
            assert_eq!(tree,saved);
            assert!(ecore_model::validate_publication(&graph,ecore_model::ReferenceCompleteness::Closed).is_empty());
            let restored:Vec<KirElement>=serde_json::from_str(&serde_json::to_string(&graph).unwrap()).unwrap();
            for model in [graph,restored] {for reverse in [false,true] {
                let mut model=model.clone();if reverse {model.reverse();}
                let before=serde_json::to_value(&model).unwrap();
                assert!(model.iter().all(|e|e.properties.get("is_implied_included")!=Some(&json!(true))));
                let state=model.iter().find(|e|e.properties.get("declared_name")==Some(&json!("s"))).unwrap();
                assert!(definition_featuring_types_typed_query(&model,state).unwrap().is_empty());
                let transition=model.iter().find(|e|e.id==transition_id).unwrap();
                assert!(scope_boolean(transition,"is_composite").unwrap());
                assert!(!scope_boolean(transition,"is_portion").unwrap());
                assert!(!transition_owner::stable_inputs(&model,transition).unwrap());
                assert!(transition_source::membership_stable_query(&model,transition).unwrap());
                assert_eq!(transition_source_query::ready_query(&model,transition).unwrap(),Some(false));
                let succession=model.iter().find(|e|e.kind=="SysML::SuccessionAsUsage").unwrap();
                assert!(matches!(definition_featuring_types_typed_query(&model,succession),Err(QueryFailure::Rejected(_))));
                assert!(transition_owner::definition_complete_fixed_transition_owner(&mut model,&transition_id,"cold.lifecycle").is_err());
                assert_eq!(before,serde_json::to_value(&model).unwrap());
            }}
        }
    }

    #[test]
    fn definition_linker_transition_prerequisites_retry_without_publishing_unproved_inputs() {
        let source="attribute x : Missing; state s { state a; state b; transition first a then b; }";
        let tree=crate::xtext_fragment::candidate_document(source,false).unwrap();let saved=tree.clone();
        for failure in ["library","cycle","hard"] {
            let source_reads=std::cell::Cell::new(0);
            let result=materialize_generated_with_postprocessing(&tree,"model",&|site| {
                let transition=site.graph.iter().find(|e|e.kind.rsplit("::").next()==Some("TransitionUsage")).unwrap();
                if site.feature.field=="member_element" {
                    source_reads.set(source_reads.get()+1);
                    if failure=="cycle" {return Ok(GeneratedLinkTarget::ConstructAdditionalMembers {owner_id:transition.id.clone()});}
                    if failure=="hard" {return Err(error("independent source endpoint failure"));}
                    let source=site.graph.iter().find(|e|e.properties.get("declared_name")==Some(&json!("a"))).unwrap();
                    return Ok(GeneratedLinkTarget::Local(source.id.clone()));
                }
                Ok(GeneratedLinkTarget::ConstructAdditionalMembers {owner_id:transition.id.clone()})
            },true).unwrap_err();
            assert_eq!(tree,saved,"failed private construction must preserve the imported tree");
            assert_eq!(source_reads.get(),1,"concrete pending source must be scheduled before retry");
            let expected=match failure {"cycle"=>"dependency cycle","hard"=>"independent source endpoint failure",_=>"missing standard library root Occurrences"};
            assert!(result.message.contains(expected),"{failure}: {}",result.message);
        }
    }

