    #[test]
    fn definition_linker_schedules_crossing_edits_transactionally() {
        let source = "class C { end cross feature e; end feature other; } feature x : Missing; feature y : Missing;";
        let tree = crate::xtext_fragment::candidate_document(source, true).unwrap();
        let saved = tree.clone();
        let calls = std::cell::Cell::new(0);
        let resolve = |site: &GeneratedReferenceSite<'_>| {
            calls.set(calls.get() + 1);
            let owner = site.graph.iter().find(|e| e.properties.get("declared_name") == Some(&json!("e"))).unwrap();
            let chain = format!("{}.implicit.binary-crossing.chain", owner.id);
            if site.graph.iter().any(|e| e.id == chain) { Ok(GeneratedLinkTarget::Local(chain)) }
            else { Ok(GeneratedLinkTarget::ConstructBinaryCrossing { owner_id: owner.id.clone() }) }
        };
        let (root, mut graph) = materialize_generated_with_postprocessing(&tree, "model", &resolve, true).unwrap();
        graph.insert(0, root);
        assert_eq!(calls.get(), 3);
        let owner = graph.iter().find(|e| e.properties.get("declared_name") == Some(&json!("e"))).unwrap();
        let crossing = definition_assessed_binary_crossing(&graph, owner).unwrap().unwrap();
        let chain = redefined_reference(&graph, crossing, "general").unwrap();
        let typings: Vec<_> = graph.iter().filter(|e| metaclass_conforms(&e.kind, "FeatureTyping")).collect();
        assert_eq!(typings.len(), 2);
        for typing in typings { assert_eq!(redefined_reference(&graph, typing, "type").unwrap().id, chain.id); }
        assert!(!scope_boolean(owner, "is_implied_included").unwrap());
        assert!(ecore_model::validate_publication(&graph, ecore_model::ReferenceCompleteness::Closed).is_empty());
        assert_eq!(tree, saved);
        for failure in ["late", "repeated", "no_progress", "fragment"] {
            let calls = std::cell::Cell::new(0);
            let result = materialize_generated_with_postprocessing(&tree, "model", &|site| {
                calls.set(calls.get()+1);
                let owner = site.graph.iter().find(|e| e.properties.get("declared_name") == Some(&json!("e"))).unwrap();
                if calls.get() == 1 || failure == "repeated" || failure == "fragment" {
                    return Ok(GeneratedLinkTarget::ConstructBinaryCrossing { owner_id: owner.id.clone() });
                }
                if failure == "no_progress" {
                    let other = site.graph.iter().find(|e| e.properties.get("declared_name") == Some(&json!("other"))).unwrap();
                    return Ok(GeneratedLinkTarget::ConstructBinaryCrossing { owner_id: other.id.clone() });
                }
                if calls.get() == 3 { return Err(error("late link failure after staged construction")); }
                Ok(GeneratedLinkTarget::Local(format!("{}.implicit.binary-crossing.chain", owner.id)))
            }, failure != "fragment");
            let issue = result.unwrap_err();
            let expected = match failure { "late" => "late link failure", "repeated" => "repeated crossing", "no_progress" => "no progress", _ => "document linker" };
            assert!(issue.message.contains(expected), "{failure}: {}", issue.message);
            assert!(calls.get() <= 3);
            assert_eq!(tree, saved, "failed linking must not mutate the imported parse tree");
        }
    }

    #[test]
    fn definition_binary_crossing_contributions_are_structurally_assessed() {
        for reverse in [false, true] {
            let ends = if reverse { "end feature other; end cross feature e;" } else { "end cross feature e; end feature other;" };
            let source = format!("standard library package Base {{ feature things; }} package P {{ class C {{ {ends} }} }}");
            let document = crate::definition_document::parse_and_link(&source, crate::SourceLanguage::Kerml).unwrap();
            let named = |name: &str| document.elements.iter().find(|e| e.properties.get("declared_name") == Some(&json!(name))).unwrap().id.clone();
            let owner_id = named("e");
            let mut graph = document.elements.clone();
            for name in ["C", "things", "other"] { graph.iter_mut().find(|e| e.id == named(name)).unwrap().properties.insert("is_implied_included".into(), json!(true)); }
            assert!(matches!(definition_general_type_inputs(&graph, graph.iter().find(|e| e.id == owner_id).unwrap()).unwrap(), DefinitionGeneralTypes::Deferred(GeneratedLinkTarget::ConstructBinaryCrossing { .. })));
            definition_materialize_binary_crossing(&mut graph, &owner_id, "generated").unwrap();
            let restored: Vec<KirElement> = serde_json::from_str(&serde_json::to_string(&graph).unwrap()).unwrap();
            for model in [&graph, &restored] {
                let owner = model.iter().find(|e| e.id == owner_id).unwrap();
                let before = serde_json::to_value(model).unwrap();
                assert!(!scope_boolean(owner, "is_implied_included").unwrap());
                assert_eq!(definition_assessed_binary_crossing(model, owner).unwrap().unwrap().id, "generated.crossing");
                let DefinitionGeneralTypes::Ready(generals) = definition_general_type_inputs(model, owner).unwrap() else { panic!("unexpected pending inputs") };
                assert!(generals.contains(&"generated.chain".into()));
                assert!(generals.contains(&named("things")));
                let chain = model.iter().find(|e| e.id == "generated.chain").unwrap();
                let oracle: Value = serde_json::from_str(include_str!("../../../../../../docs/conformance/2026-08-support/cross-feature-pilot-controls.json")).unwrap();
                let control = oracle["binary_controls"].as_array().unwrap().iter().find(|c| c["is_end"] == true && c["existing"] == false).unwrap();
                assert_eq!(definition_feature_default_name(model, chain).unwrap(), control["chain_defaults"][0].as_str().unwrap());
                assert!(matches!(definition_general_type_inputs(model, chain).unwrap(), DefinitionGeneralTypes::Ready(_)));
                assert_eq!(before, serde_json::to_value(model).unwrap());
            }
            for failure in ["reversed", "wrong_target", "extra_member", "nonbinary", "extra_crossing"] {
                let mut invalid = graph.clone();
                let chains: Vec<_> = stored_children(&invalid, invalid.iter().find(|e| e.id == "generated.chain").unwrap(), "owned_relationship").unwrap().iter().map(|e| e.id.clone()).collect();
                match failure {
                    "reversed" => {
                        let first = invalid.iter().find(|e| e.id == chains[0]).unwrap().properties["chaining_feature"].clone();
                        let second = invalid.iter().find(|e| e.id == chains[1]).unwrap().properties["chaining_feature"].clone();
                        invalid.iter_mut().find(|e| e.id == chains[0]).unwrap().properties.insert("chaining_feature".into(), second);
                        invalid.iter_mut().find(|e| e.id == chains[1]).unwrap().properties.insert("chaining_feature".into(), first);
                    },
                    "wrong_target" => { invalid.iter_mut().find(|e| e.id == chains[1]).unwrap().properties.insert("chaining_feature".into(), json!(named("things"))); },
                    "extra_member" => cross_test_own(&mut invalid, "generated.chain", "OwningMembership", fresh_definition_element("extra".into(), "Feature").unwrap()),
                    "nonbinary" => {
                        let mut end = fresh_definition_element("third".into(), "Feature").unwrap();
                        end.properties.insert("is_end".into(), json!(true));
                        cross_test_own(&mut invalid, &named("C"), "FeatureMembership", end);
                    },
                    _ => { definition_append_implied_specialization(&mut invalid, "extraCrossing", "CrossSubsetting", &owner_id, "generated.chain").unwrap(); },
                }
                let before = serde_json::to_value(&invalid).unwrap();
                let owner = invalid.iter().find(|e| e.id == owner_id).unwrap();
                assert!(definition_assessed_binary_crossing(&invalid, owner).unwrap().is_none(), "{failure}");
                assert!(definition_general_type_inputs(&invalid, owner).is_err(), "{failure}");
                assert_eq!(before, serde_json::to_value(&invalid).unwrap());
            }
        }
    }

    #[test]
    fn definition_cross_end_type_queries_do_not_require_crossing_construction() {
        let artifact: Value = serde_json::from_str(include_str!("../../../../../../docs/conformance/2026-08-support/cross-feature-pilot-controls.json")).unwrap();
        let cases = artifact["typing_controls"].as_array().unwrap();
        assert_eq!(cases.len(), 6);
        for case in cases {
            let document = crate::definition_document::parse_and_link("standard library package Base { feature things; } package P { class C { end cross feature e; end feature other; } }", crate::SourceLanguage::Kerml).unwrap();
            let named = |name: &str| document.elements.iter().find(|e| e.properties.get("declared_name") == Some(&json!(name))).unwrap().id.clone();
            let owner_id = named("e");
            let mut graph = document.elements.clone();
            for name in ["C", "things", "other"] { graph.iter_mut().find(|e| e.id == named(name)).unwrap().properties.insert("is_implied_included".into(), json!(true)); }
            for i in 0..case["type_count"].as_u64().unwrap() {
                let mut target = fresh_definition_element(format!("type{i}"), "Classifier").unwrap();
                target.properties.insert("is_implied_included".into(), json!(true));
                graph.push(target);
                // Explicit canonical typing, so this control tests the pending
                // crossing dependency rather than unassessed implied typing.
                let mut relation = fresh_definition_element(format!("typing{i}"), "FeatureTyping").unwrap();
                relation.properties.insert("typed_feature".into(), json!(owner_id));
                relation.properties.insert("type".into(), json!(format!("type{i}")));
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, graph.iter_mut().find(|e| e.id == owner_id).unwrap(), &mut relation).unwrap();
                graph.push(relation);
            }
            if case["stored_crossing"].as_bool().unwrap() {
                graph.push(fresh_definition_element("crossed".into(), "Feature").unwrap());
                definition_append_implied_specialization(&mut graph, "crossing", "CrossSubsetting", &owner_id, "crossed").unwrap();
            }
            let restored: Vec<KirElement> = serde_json::from_str(&serde_json::to_string(&graph).unwrap()).unwrap();
            for model in [&graph, &restored] {
                let owner = model.iter().find(|e| e.id == owner_id).unwrap();
                let before = serde_json::to_value(model).unwrap();
                assert_eq!(json!(definition_feature_types(model, owner).unwrap().iter().map(|e| e.id.clone()).collect::<Vec<_>>()), case["types"], "{case}");
                if case["stored_crossing"].as_bool().unwrap() { assert!(definition_general_type_inputs(model, owner).is_err()); }
                else { assert!(matches!(definition_general_type_inputs(model, owner).unwrap(), DefinitionGeneralTypes::Deferred(GeneratedLinkTarget::ConstructBinaryCrossing { .. }))); }
                assert_eq!(before, serde_json::to_value(model).unwrap());
            }
            let mut unsupported = graph.clone();
            cross_test_own(&mut unsupported, &owner_id, "OwningMembership", fresh_definition_element("extraOwnedFeature".into(), "Feature").unwrap());
            let before = serde_json::to_value(&unsupported).unwrap();
            assert!(definition_feature_types(&unsupported, unsupported.iter().find(|e| e.id == owner_id).unwrap()).is_err());
            assert_eq!(before, serde_json::to_value(&unsupported).unwrap());
            let cross_id = definition_owned_cross_feature(&graph, graph.iter().find(|e| e.id == owner_id).unwrap()).unwrap().unwrap().id.clone();
            if case["type_count"].as_u64().unwrap() > 0 {
                let cross = graph.iter().find(|e| e.id == cross_id).unwrap();
                assert!(definition_feature_default_name(&graph, cross).is_err());
            }
            // Type and redefinition dependencies can run before or after the
            // crossing stage, without a transformation-completeness flag.
            assert_eq!(definition_materialize_owned_cross_specialization(&mut graph, &cross_id, "specialization").unwrap(), case["specialization_types"].as_array().unwrap().len());
            let cross = graph.iter().find(|e| e.id == cross_id).unwrap();
            let selected = stored_children(&graph, cross, "owned_relationship").unwrap().into_iter()
                .filter(|r| metaclass_conforms(&r.kind, "FeatureTyping"))
                .map(|r| redefined_reference(&graph, r, "type").unwrap().id.clone()).collect::<Vec<_>>();
            assert_eq!(json!(selected), case["specialization_types"]);
            assert_eq!(definition_feature_default_name(&graph, cross).unwrap(), case["default"].as_str().unwrap());
            assert!(matches!(definition_general_type_inputs(&graph, cross).unwrap(), DefinitionGeneralTypes::Ready(_)));
            let mut unexpected = graph.clone();
            unexpected.push(fresh_definition_element("unexpectedType".into(), "Classifier").unwrap());
            definition_append_implied_specialization(&mut unexpected, "unexpectedTyping", "FeatureTyping", &cross_id, "unexpectedType").unwrap();
            let cross = unexpected.iter().find(|e| e.id == cross_id).unwrap();
            assert!(definition_feature_default_name(&unexpected, cross).is_err());
        }
    }

    #[test]
    fn definition_binary_cross_featuring_matches_pilot_and_is_atomic() {
        let artifact: Value = serde_json::from_str(include_str!("../../../../../../docs/conformance/2026-08-support/cross-feature-pilot-controls.json")).unwrap();
        let cases = artifact["featuring_controls"].as_array().unwrap();
        assert_eq!(cases.len(), 24);
        for case in cases {
            let inherited = case["inherited"].as_bool().unwrap();
            let position = case["position"].as_u64().unwrap() as usize;
            let mut graph = vec![fresh_definition_element("context".into(), "Classifier").unwrap(), fresh_definition_element("base".into(), "Classifier").unwrap()];
            for element in &mut graph { element.properties.insert("is_implied_included".into(), json!(true)); }
            if inherited {
                let mut anchor = fresh_definition_element("anchor".into(), "Feature").unwrap();
                anchor.properties.insert("is_end".into(), json!(true));
                anchor.properties.insert("is_implied_included".into(), json!(true));
                cross_test_own(&mut graph, "base", "FeatureMembership", anchor);
                definition_append_implied_specialization(&mut graph, "inherits", "Subclassification", "context", "base").unwrap();
            }
            for i in 0..2 {
                let mut end = fresh_definition_element(format!("end{i}"), "Feature").unwrap();
                end.properties.insert("is_end".into(), json!(true));
                end.properties.insert("is_implied_included".into(), json!(true));
                cross_test_own(&mut graph, if inherited && i != position { "base" } else { "context" }, "FeatureMembership", end);
            }
            let owner_id = format!("end{position}");
            if inherited { definition_append_implied_specialization(&mut graph, "replaces", "Redefinition", &owner_id, "anchor").unwrap(); }
            cross_test_own(&mut graph, &owner_id, "OwningMembership", fresh_definition_element("cross".into(), "Feature").unwrap());
            for i in 0..case["type_count"].as_u64().unwrap() {
                let mut target = fresh_definition_element(format!("type{i}"), "Classifier").unwrap();
                target.properties.insert("is_implied_included".into(), json!(true));
                graph.push(target);
                definition_append_implied_specialization(&mut graph, &format!("typing{i}"), "FeatureTyping", &format!("end{}", 1-position), &format!("type{i}")).unwrap();
            }
            if case["existing"].as_bool().unwrap() {
                graph.push(fresh_definition_element("existingType".into(), "Classifier").unwrap());
                let mut relation = fresh_definition_element("existingFeaturing".into(), "TypeFeaturing").unwrap();
                relation.properties.insert("feature_of_type".into(), json!("cross"));
                relation.properties.insert("featuring_type".into(), json!("existingType"));
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, graph.iter_mut().find(|e| e.id == "cross").unwrap(), &mut relation).unwrap();
                graph.push(relation);
            }
            let original = graph.clone();
            let expected = case["targets"].as_array().unwrap().len();
            assert_eq!(definition_materialize_binary_cross_featuring(&mut graph, "cross", "generated").unwrap(), expected, "{case}");
            let restored: Vec<KirElement> = serde_json::from_str(&serde_json::to_string(&graph).unwrap()).unwrap();
            for model in [&graph, &restored] {
                let cross = model.iter().find(|e| e.id == "cross").unwrap();
                assert!(!scope_boolean(cross, "is_implied_included").unwrap());
                let targets = definition_owned_type_featuring(model, cross).unwrap().into_iter()
                    .filter(|r| scope_boolean(r, "is_implied").unwrap())
                    .map(|r| redefined_reference(model, r, "featuring_type").unwrap().id.clone()).collect::<Vec<_>>();
                assert_eq!(json!(targets), case["targets"], "{case}");
                assert!(ecore_model::validate_publication(model, ecore_model::ReferenceCompleteness::Closed).is_empty());
            }
            let before = serde_json::to_value(&graph).unwrap();
            assert_eq!(definition_materialize_binary_cross_featuring(&mut graph, "cross", "again").unwrap(), 0);
            assert_eq!(before, serde_json::to_value(&graph).unwrap());
            if expected > 0 {
                let mut collision = original.clone();
                collision.push(fresh_definition_element(format!("generated.{}", expected-1), "Feature").unwrap());
                let before = serde_json::to_value(&collision).unwrap();
                assert!(definition_materialize_binary_cross_featuring(&mut collision, "cross", "generated").is_err());
                assert_eq!(before, serde_json::to_value(&collision).unwrap());
                let mut unresolved = original.clone();
                unresolved.iter_mut().find(|e| e.id == format!("end{}", 1-position)).unwrap().properties.insert("is_implied_included".into(), json!(false));
                let before = serde_json::to_value(&unresolved).unwrap();
                assert!(definition_materialize_binary_cross_featuring(&mut unresolved, "cross", "new").is_err());
                assert_eq!(before, serde_json::to_value(&unresolved).unwrap());
                let mut completed = original;
                completed.iter_mut().find(|e| e.id == "cross").unwrap().properties.insert("is_implied_included".into(), json!(true));
                let before = serde_json::to_value(&completed).unwrap();
                assert!(definition_materialize_binary_cross_featuring(&mut completed, "cross", "new").is_err());
                assert_eq!(before, serde_json::to_value(&completed).unwrap());
            }
        }
        for ends in [&[true][..], &[true, true, true][..]] {
            let mut graph = cross_test_graph(ends, true);
            for element in &mut graph { element.properties.insert("is_implied_included".into(), json!(true)); }
            cross_test_own(&mut graph, "end0", "OwningMembership", fresh_definition_element("cross".into(), "Feature").unwrap());
            let before = serde_json::to_value(&graph).unwrap();
            assert!(definition_materialize_binary_cross_featuring(&mut graph, "cross", "new").unwrap_err().message.contains("nonbinary"));
            assert_eq!(before, serde_json::to_value(&graph).unwrap());
        }
    }

    #[test]
    fn definition_owned_cross_specialization_matches_pilot_and_is_atomic() {
        let artifact: Value = serde_json::from_str(include_str!("../../../../../../docs/conformance/2026-08-support/cross-feature-pilot-controls.json")).unwrap();
        let cases = artifact["specialization_controls"].as_array().unwrap();
        assert_eq!(cases.len(), 12);
        for case in cases {
            let mut graph = cross_test_graph(&[true, true], true);
            cross_test_own(&mut graph, "end0", "OwningMembership", fresh_definition_element("cross".into(), "Feature").unwrap());
            for index in 0..case["type_count"].as_u64().unwrap() {
                let id = format!("type{index}");
                let mut target = fresh_definition_element(id.clone(), "Classifier").unwrap();
                target.properties.insert("is_implied_included".into(), json!(true));
                graph.push(target);
                definition_append_implied_specialization(&mut graph, &format!("typing{index}"), "FeatureTyping", "end0", &id).unwrap();
            }
            let mut general = fresh_definition_element("general".into(), "Feature").unwrap();
            general.properties.insert("is_end".into(), case["redefined_end"].clone());
            general.properties.insert("is_implied_included".into(), json!(true));
            graph.push(general);
            definition_append_implied_specialization(&mut graph, "redefinition", "Redefinition", "end0", "general").unwrap();
            if case["with_cross"].as_bool().unwrap() {
                for id in ["other", "generalCross"] {
                    let mut member = fresh_definition_element(id.into(), "Feature").unwrap();
                    member.properties.insert("is_implied_included".into(), json!(true));
                    graph.push(member);
                }
                definition_append_feature_chain(&mut graph, "generalChain", &["other", "generalCross"]).unwrap();
                definition_append_implied_specialization(&mut graph, "generalCrossing", "CrossSubsetting", "general", "generalChain").unwrap();
            }
            // Complete owner/type flags are supplied fixture inputs, never
            // asserted by the stage being qualified.
            graph.iter_mut().find(|e| e.id == "end0").unwrap().properties.insert("is_implied_included".into(), json!(true));
            let original = graph.clone();
            let expected = case["types"].as_array().unwrap().len() + case["subsets"].as_array().unwrap().len();
            if expected > 0 {
                let cross = graph.iter().find(|e| e.id == "cross").unwrap();
                assert!(matches!(definition_general_type_inputs(&graph, cross).unwrap(),
                    DefinitionGeneralTypes::Deferred(GeneratedLinkTarget::ConstructCrossSpecialization { owner_id }) if owner_id == "cross"));
            }
            assert_eq!(definition_materialize_owned_cross_specialization(&mut graph, "cross", "generated").unwrap(), expected, "{case}");
            let restored: Vec<KirElement> = serde_json::from_str(&serde_json::to_string(&graph).unwrap()).unwrap();
            for model in [&graph, &restored] {
                let cross = model.iter().find(|e| e.id == "cross").unwrap();
                assert!(!scope_boolean(cross, "is_implied_included").unwrap());
                for (kind, field) in [("FeatureTyping", "types"), ("Subsetting", "subsets")] {
                    let targets: Vec<_> = stored_children(model, cross, "owned_relationship").unwrap().into_iter()
                        .filter(|r| metaclass_conforms(&r.kind, kind))
                        .map(|r| redefined_reference(model, r, "general").unwrap().id.clone()).collect();
                    assert_eq!(json!(targets), case[field], "{case}: {field}");
                }
                assert!(ecore_model::validate_publication(model, ecore_model::ReferenceCompleteness::Closed).is_empty());
            }
            let before = serde_json::to_value(&graph).unwrap();
            assert_eq!(definition_materialize_owned_cross_specialization(&mut graph, "cross", "again").unwrap(), 0);
            assert_eq!(before, serde_json::to_value(&graph).unwrap());
            if expected > 0 {
                let mut collision = original.clone();
                let colliding_index = expected - 1;
                collision.push(fresh_definition_element(format!("generated.{colliding_index}"), "Feature").unwrap());
                let before = serde_json::to_value(&collision).unwrap();
                assert!(definition_materialize_owned_cross_specialization(&mut collision, "cross", "generated").is_err());
                assert_eq!(before, serde_json::to_value(&collision).unwrap());
                let mut completed = original.clone();
                completed.iter_mut().find(|e| e.id == "cross").unwrap().properties.insert("is_implied_included".into(), json!(true));
                let before = serde_json::to_value(&completed).unwrap();
                assert!(definition_materialize_owned_cross_specialization(&mut completed, "cross", "new").is_err());
                assert_eq!(before, serde_json::to_value(&completed).unwrap());
            }
            let mut unresolved = original;
            unresolved.iter_mut().find(|e| e.id == "end0").unwrap().properties.insert("is_implied_included".into(), json!(false));
            let before = serde_json::to_value(&unresolved).unwrap();
            assert!(definition_materialize_owned_cross_specialization(&mut unresolved, "cross", "new").is_err());
            assert_eq!(before, serde_json::to_value(&unresolved).unwrap());
        }
    }

    #[test]
    fn definition_owned_cross_feature_matches_pinned_selection() {
        let artifact: Value = serde_json::from_str(include_str!("../../../../../../docs/conformance/2026-08-support/cross-feature-pilot-controls.json")).unwrap();
        let cases = artifact["selection_controls"].as_array().unwrap(); assert_eq!(cases.len(), 72);
        for case in cases {
            let mut graph = cross_test_graph(&[case["is_end"].as_bool().unwrap()], case["type_owner"].as_bool().unwrap());
            let candidate = fresh_definition_element("candidate".into(), case["candidate_kind"].as_str().unwrap()).unwrap();
            cross_test_own(&mut graph, "end0", case["membership_kind"].as_str().unwrap(), candidate);
            let document = crate::KirDocument { metadata: Default::default(), elements: graph };
            let restored: crate::KirDocument = serde_json::from_str(&serde_json::to_string(&document).unwrap()).unwrap();
            for model in [&document, &restored] {
                let before = serde_json::to_value(model).unwrap();
                assert_eq!(json!(crate::definition_document::owned_cross_feature(model, "end0").unwrap().into_iter().collect::<Vec<_>>()), case["selected"], "{case}");
                assert_eq!(before, serde_json::to_value(model).unwrap());
            }
        }
        let ordered = artifact["ordered_selection_controls"].as_array().unwrap(); assert_eq!(ordered.len(), 3);
        for case in ordered {
            let mut graph = cross_test_graph(&[true], true);
            for (i, kind) in case["kinds"].as_array().unwrap().iter().enumerate() {
                cross_test_own(&mut graph, "end0", "OwningMembership", fresh_definition_element(format!("member{i}"), kind.as_str().unwrap()).unwrap());
            }
            let owner = graph.iter().find(|e| e.id == "end0").unwrap();
            assert_eq!(json!(definition_owned_cross_feature(&graph, owner).unwrap().map(|e| e.id.clone()).into_iter().collect::<Vec<_>>()), case["selected"]);
        }

    }

    #[test]
    fn definition_binary_crossing_matches_pilot_and_is_atomic() {
        let artifact: Value = serde_json::from_str(include_str!("../../../../../../docs/conformance/2026-08-support/cross-feature-pilot-controls.json")).unwrap();
        let cases = artifact["binary_controls"].as_array().unwrap(); assert_eq!(cases.len(), 8);
        for case in cases {
            let position = case["target_index"].as_u64().unwrap() as usize;
            let mut ends = [true, true]; ends[position] = case["is_end"].as_bool().unwrap();
            let mut graph = cross_test_graph(&ends, true); let owner_id = format!("end{position}");
            cross_test_own(&mut graph, &owner_id, "OwningMembership", fresh_definition_element("cross".into(), "Feature").unwrap());
            if case["existing"].as_bool().unwrap() {
                graph.push(fresh_definition_element("existing".into(), "Feature").unwrap());
                let mut relation = fresh_definition_element("existing.crossing".into(), "CrossSubsetting").unwrap();
                relation.properties.insert("crossed_feature".into(), json!("existing"));
                let owner = graph.iter_mut().find(|e| e.id == owner_id).unwrap();
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, owner, &mut relation).unwrap();
                graph.push(relation);
            }
            let mut document = crate::KirDocument { metadata: Default::default(), elements: graph };
            let before = serde_json::to_value(&document).unwrap();
            let added = crate::definition_document::materialize_binary_crossing(&mut document, &owner_id, "generated").unwrap();
            let expected = case["chains"].as_array().unwrap(); assert_eq!(added, !expected.is_empty(), "{case}");
            if !added { assert_eq!(before, serde_json::to_value(&document).unwrap()); continue; }
            let restored: crate::KirDocument = serde_json::from_str(&serde_json::to_string(&document).unwrap()).unwrap();
            for model in [&document, &restored] {
                assert!(ecore_model::validate_publication(&model.elements, ecore_model::ReferenceCompleteness::Closed).is_empty());
                let chain = model.elements.iter().find(|e| e.id == "generated.chain").unwrap();
                assert_eq!(json!([implicit_chain_signature(&model.elements, chain).unwrap()]), case["chains"]);
                let relation = model.elements.iter().find(|e| e.id == "generated.crossing").unwrap();
                assert_eq!(chain.properties["owning_relationship"], relation.id);
                assert!(scope_boolean(relation, "is_implied").unwrap());
                let owner = model.elements.iter().find(|e| e.id == owner_id).unwrap();
                assert_eq!(definition_reference_targets(&model.elements, owner, "cross_feature").unwrap()[0].id, "cross");
                assert!(model.elements.iter().all(|e| !scope_boolean(e, "is_implied_included").unwrap()));
            }
            let snapshot = serde_json::to_value(&document).unwrap();
            assert!(!crate::definition_document::materialize_binary_crossing(&mut document, &owner_id, "second").unwrap());
            assert_eq!(snapshot, serde_json::to_value(&document).unwrap());
        }
        for shape in ["complete", "compound"] {
            let mut graph = cross_test_graph(&[true, true], true);
            cross_test_own(&mut graph, "end0", "OwningMembership", fresh_definition_element("cross".into(), "Feature").unwrap());
            if shape == "complete" {
                graph.iter_mut().find(|e| e.id == "end0").unwrap().properties.insert("is_implied_included".into(), json!(true));
            } else {
                let mut relation = fresh_definition_element("compound".into(), "FeatureChaining").unwrap();
                relation.properties.insert("chaining_feature".into(), json!("end1"));
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS, graph.iter_mut().find(|e| e.id == "cross").unwrap(), &mut relation).unwrap();
                graph.push(relation);
            }
            let before = serde_json::to_value(&graph).unwrap();
            assert!(definition_materialize_binary_crossing(&mut graph, "end0", "new").is_err(), "{shape}");
            assert_eq!(before, serde_json::to_value(&graph).unwrap());
        }
        for count in [1, 3] {
            let mut graph = cross_test_graph(&vec![true; count], true);
            cross_test_own(&mut graph, "end0", "OwningMembership", fresh_definition_element("cross".into(), "Feature").unwrap());
            let before = serde_json::to_value(&graph).unwrap();
            assert!(definition_materialize_binary_crossing(&mut graph, "end0", "new").unwrap_err().message.contains("nonbinary"));
            assert_eq!(before, serde_json::to_value(&graph).unwrap());
        }
    }

    #[test]
    fn definition_binary_crossing_source_stage_matches_pilot() {
        let artifact: Value = serde_json::from_str(include_str!("../../../../../../docs/conformance/2026-08-support/cross-feature-pilot-controls.json")).unwrap();
        let cases = artifact["source_controls"].as_array().unwrap(); assert_eq!(cases.len(), 6);
        for case in cases {
            let source = case["source"].as_str().unwrap();
            let original = crate::definition_document::parse_and_link(source, crate::SourceLanguage::Kerml).unwrap();
            let owner_id = original.elements.iter().find(|e| e.properties.get("declared_name") == Some(&json!("e"))).unwrap().id.clone();
            let mut document = original.clone();
            assert!(crate::definition_document::materialize_binary_crossing(&mut document, &owner_id, "crossing").unwrap());
            let restored: crate::KirDocument = serde_json::from_str(&serde_json::to_string(&document).unwrap()).unwrap();
            for model in [&document, &restored] {
                let selected = crate::definition_document::owned_cross_feature(model, &owner_id).unwrap().unwrap();
                let cross = model.elements.iter().find(|e| e.id == selected).unwrap();
                assert_eq!(cross.properties["declared_name"], case["cross"]);
                let chain = model.elements.iter().find(|e| e.id == "crossing.chain").unwrap();
                let names: Vec<_> = implicit_chain_signature(&model.elements, chain).unwrap().iter()
                    .map(|id| model.elements.iter().find(|e| &e.id == id).unwrap().properties["declared_name"].clone()).collect();
                assert_eq!(json!([names]), case["chains"]);
                let owner = model.elements.iter().find(|e| e.id == owner_id).unwrap();
                assert_eq!(definition_reference_targets(&model.elements, owner, "cross_feature").unwrap()[0].id, selected);
            }
            // Identity collision must leave the original model unchanged.
            let mut collision = original;
            collision.elements.push(fresh_definition_element("reserved.chain".into(), "Feature").unwrap());
            let before = serde_json::to_value(&collision).unwrap();
            assert!(crate::definition_document::materialize_binary_crossing(&mut collision, &owner_id, "reserved").is_err());
            assert_eq!(before, serde_json::to_value(&collision).unwrap());
        }
    }

    fn definition_type_default_library() -> crate::KirDocument {
        let artifact: Value = serde_json::from_str(include_str!("../../../../resources/metamodels/sysml-2.0-pilot-2026-08/definition-defaults.extract.json")).unwrap();
        let mut packages: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();
        for name in artifact["bindings"].as_array().unwrap().iter()
            .flat_map(|binding| binding["labels"].as_object().unwrap().values())
            .map(|value| value.as_str().unwrap())
            .chain(default_generals_generated::DEFAULT_GENERALS.iter().map(|(_, name, _)| *name)) {
            let (package, name) = name.split_once("::").unwrap();
            packages.entry(package.into()).or_default().insert(name.into());
        }
        let mut source = String::new();
        for (package, names) in packages {
            source.push_str(&format!("standard library package {package} {{"));
            for name in names {
                let kind = match (package.as_str(), name.as_str()) {
                    ("Base", "DataValue") => "datatype",
                    ("Occurrences", "Occurrence") => "class",
                    ("Objects", "Object") => "struct",
                    _ => "classifier",
                };
                source.push_str(&format!("{kind} {name};"));
            }
            source.push('}');
        }
        // These dependency fixtures exercise resolved names and canonical Ecore
        // ownership; they are not qualification of the actual standard library.
        crate::definition_document::parse_and_link_sources(&[crate::definition_document::DefinitionSource {
            uri: "test-default-library.kerml", text: &source, language: crate::SourceLanguage::Kerml,
        }]).unwrap()
    }

    #[test]
    fn definition_type_default_transaction_matches_all_cached_definition_selectors() {
        let artifact: Value = serde_json::from_str(include_str!("../../../../resources/metamodels/sysml-2.0-pilot-2026-08/definition-defaults.extract.json")).unwrap();
        let library = definition_type_default_library();
        for case in artifact["controls"].as_array().unwrap() {
            let kind = case["kind"].as_str().unwrap();
            let mut document = library.clone();
            let mut owner = fresh_definition_element("owner".into(), kind).unwrap();
            if ecore_model::feature(kind, "is_individual").is_some() {
                owner.properties.insert("is_individual".into(), case["individual"].clone());
            }
            document.elements.push(owner);
            let ends = case["owned_ends"].as_u64().unwrap() as usize;
            for index in 0..ends + case["non_end_features"].as_u64().unwrap() as usize {
                let mut feature = fresh_definition_element(format!("end{index}"), "Feature").unwrap();
                feature.properties.insert("is_end".into(), json!(index < ends));
                cross_test_own(&mut document.elements, "owner", "FeatureMembership", feature);
            }
            let expected = case["general_types"].as_array().unwrap();
            let bindings = standard_default_bindings(&document.elements, &expected.iter().map(|v| v.as_str().unwrap()).collect()).unwrap();
            let inserted = crate::definition_document::materialize_type_defaults(&mut document, &[("owner", "defaults")]).unwrap();
            assert_eq!(inserted, expected.len(), "{case}");
            let owner = document.elements.iter().find(|e| e.id == "owner").unwrap();
            let relations = stored_children(&document.elements, owner, "owned_relationship").unwrap();
            let actual: Vec<_> = relations.iter().filter(|e| metaclass_conforms(&e.kind, "Specialization"))
                .map(|relation| {
                    assert_eq!(relation.kind.rsplit("::").next(), Some("Subclassification"));
                    assert!(scope_boolean(relation, "is_implied").unwrap());
                    assert_eq!(redefined_reference(&document.elements, relation, "specific").unwrap().id, "owner");
                    let general = redefined_reference(&document.elements, relation, "general").unwrap();
                    json!(bindings.iter().find(|(_, id)| *id == &general.id).unwrap().0)
                }).collect();
            assert_eq!(actual, *expected, "{case}");
            assert!(!scope_boolean(owner, "is_implied_included").unwrap());
            assert!(ecore_model::validate_publication(&document.elements, ecore_model::ReferenceCompleteness::Closed).is_empty());
            let snapshot = serde_json::to_value(&document).unwrap();
            assert_eq!(crate::definition_document::materialize_type_defaults(&mut document, &[("owner", "retry")]).unwrap(), 0, "{case}");
            assert_eq!(snapshot, serde_json::to_value(&document).unwrap());
            let mut restored: crate::KirDocument = serde_json::from_value(snapshot.clone()).unwrap();
            restored.elements.reverse();
            assert_eq!(crate::definition_document::materialize_type_defaults(&mut restored, &[("owner", "restored")]).unwrap(), 0, "{case}");
        }
    }

    #[test]
    fn definition_mixed_parameter_source_and_replay() {
        let library = "standard library package Base { classifier Anything; feature things; } standard library package Performances { behavior Performance; function Evaluation specializes Performance; } standard library package Occurrences { class Occurrence; }";
        let source = "package P { class G { in feature a; out feature b; } function F specializes G { in feature x; out feature y; } }";
        for text in [format!("{library} {source}"),format!("{source} {library}")] {
            let mut doc = crate::definition_document::parse_and_link(&text,crate::SourceLanguage::Kerml).unwrap();
            for reversed in [false,true] {
                if reversed { doc = serde_json::from_value(serde_json::to_value(&doc).unwrap()).unwrap(); doc.elements.reverse(); }
                let before=serde_json::to_value(&doc).unwrap();
                for (name,expected) in [("x","a"),("y","b")] {
                    let target=doc.elements.iter().find(|e|e.properties.get("declared_name")==Some(&json!(name))).unwrap();
                    let actual=definition_redefined_features(&doc.elements,target,false).unwrap();
                    assert_eq!(actual.len(),1);
                    assert_eq!(actual[0].properties.get("declared_name"),Some(&json!(expected)));
                }
                let general=doc.elements.iter().find(|e|e.properties.get("declared_name")==Some(&json!("G"))).unwrap();
                assert!(definition_parameter_collection(&doc.elements,general,true).unwrap().is_empty());
                assert_eq!(definition_parameter_collection(&doc.elements,general,false).unwrap().len(),2);
                assert_eq!(serde_json::to_value(&doc).unwrap(),before);
            }
        }
    }

    #[test]
    fn definition_plain_type_strategy_reaches_source_and_replay() {
        let library="standard library package Base { classifier Anything; } standard library package Performances { behavior Performance; function Evaluation specializes Performance; predicate BooleanEvaluation specializes Evaluation; } standard library package Metaobjects { metaclass Metaobject; }";
        let source="package P { behavior B; function F; predicate C; metaclass M; }";
        for text in [format!("{library} {source}"),format!("{source} {library}")] {
            let mut doc=crate::definition_document::parse_and_link(&text,crate::SourceLanguage::Kerml).unwrap();
            for (name,target_name) in [("B","Performance"),("F","Evaluation"),("C","BooleanEvaluation"),("M","Metaobject")] {
                let owner=doc.elements.iter().find(|e|e.properties.get("declared_name")==Some(&json!(name))).unwrap().clone();
                let target=doc.elements.iter().find(|e|e.properties.get("declared_name")==Some(&json!(target_name))).unwrap().clone();
                assert!(definition_specializes(&doc.elements,&owner,&target).unwrap(),"{name}");
                assert!(definition_type_default_contribution_owners(&doc.elements).contains(&owner.id));
                assert_eq!(crate::definition_document::materialize_type_defaults(&mut doc,&[(owner.id.as_str(),format!("plain.default.{name}").as_str())]).unwrap(),1);
                assert_eq!(crate::definition_document::materialize_type_defaults(&mut doc,&[(owner.id.as_str(),"retry")]).unwrap(),0);
                assert!(!scope_boolean(doc.elements.iter().find(|e|e.id==owner.id).unwrap(),"is_implied_included").unwrap());
                let snapshot=serde_json::to_value(&doc).unwrap();
                doc=serde_json::from_value(snapshot).unwrap();doc.elements.reverse();
                assert!(definition_specializes(&doc.elements,doc.elements.iter().find(|e|e.id==owner.id).unwrap(),doc.elements.iter().find(|e|e.id==target.id).unwrap()).unwrap());
            }
        }
    }

    #[test]
    fn definition_type_default_transaction_parses_classifiers_and_constructs_plain_type() {
        let library = definition_type_default_library();
        let mut document = crate::definition_document::parse_and_link("classifier C; class K; datatype D; struct S;", crate::SourceLanguage::Kerml).unwrap();
        document.elements.extend(library.elements);
        let mut plain = fresh_definition_element("plain_type".into(), "Type").unwrap();
        plain.properties.insert("declared_name".into(), json!("T"));
        document.elements.push(plain);
        let owners: Vec<_> = ["T", "C", "K", "D", "S"].iter().map(|name| {
            document.elements.iter().find(|e| e.properties.get("declared_name") == Some(&json!(name))).unwrap().id.clone()
        }).collect();
        let prefixes: Vec<_> = (0..5).map(|index| format!("default{index}")).collect();
        let batch: Vec<_> = owners.iter().zip(&prefixes).map(|(id,prefix)| (id.as_str(), prefix.as_str())).collect();
        assert_eq!(crate::definition_document::materialize_type_defaults(&mut document, &batch).unwrap(), 5);
        for (id, (_, qualified, relationship_kind)) in owners.iter().zip(default_generals_generated::DEFAULT_GENERALS) {
            let owner = document.elements.iter().find(|e| &e.id == id).unwrap();
            let relations = stored_children(&document.elements, owner, "owned_relationship").unwrap();
            assert_eq!(relations.len(), 1);
            assert_eq!(relations[0].kind.rsplit("::").next(), Some(*relationship_kind));
            let target = redefined_reference(&document.elements, relations[0], "general").unwrap();
            assert_eq!(target.properties["declared_name"], json!(qualified.split_once("::").unwrap().1));
            assert!(!scope_boolean(owner, "is_implied_included").unwrap());
        }
        assert_eq!(crate::definition_document::materialize_type_defaults(&mut document, &batch).unwrap(), 0);
        let self_id = document.elements.iter().find(|e| e.properties.get("declared_name") == Some(&json!("Anything"))).unwrap().id.clone();
        assert_eq!(crate::definition_document::materialize_type_defaults(&mut document, &[(self_id.as_str(), "self")]).unwrap(), 0);
    }

    #[test]
    fn definition_type_default_transaction_rejects_unassessed_inputs_atomically() {
        let base = definition_type_default_library();
        for invalid in ["adapter", "missing_owner", "duplicate_owner", "empty_prefix", "collision", "complete", "unassessed_implied", "missing_library"] {
            let mut document = base.clone();
            document.elements.push(fresh_definition_element("owner".into(), "Class").unwrap());
            document.elements.push(fresh_definition_element("other".into(), if invalid == "adapter" { "Feature" } else { "Class" }).unwrap());
            if invalid == "complete" {
                document.elements.iter_mut().find(|e| e.id == "other").unwrap().properties.insert("is_implied_included".into(), json!(true));
            }
            if invalid == "collision" { document.elements.push(fresh_definition_element("second.0".into(), "Type").unwrap()); }
            if invalid == "unassessed_implied" {
                let mut relation = fresh_definition_element("unassessed".into(), "Subclassification").unwrap();
                relation.properties.insert("is_implied".into(), json!(true));
                relation.properties.insert("subclassifier".into(), json!("other"));
                relation.properties.insert("superclassifier".into(), json!("owner"));
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,
                    document.elements.iter_mut().find(|e| e.id == "other").unwrap(), &mut relation).unwrap();
                document.elements.push(relation);
            }
            if invalid == "missing_library" { document.elements.retain(|e| e.id == "owner" || e.id == "other"); }
            let before = serde_json::to_value(&document).unwrap();
            let batch = match invalid {
                "missing_owner" => vec![("owner", "first"), ("absent", "second")],
                "duplicate_owner" => vec![("owner", "first"), ("owner", "second")],
                "empty_prefix" => vec![("owner", "first"), ("other", "")],
                _ => vec![("owner", "first"), ("other", "second")],
            };
            assert!(crate::definition_document::materialize_type_defaults(&mut document, &batch).is_err(), "{invalid}");
            assert_eq!(before, serde_json::to_value(&document).unwrap(), "{invalid}");
        }
    }

    #[test]
    fn definition_feature_default_transaction_replays_canonical_source_models() {
        let artifact: Value = serde_json::from_str(include_str!("../../../../resources/metamodels/sysml-2.0-pilot-2026-08/feature-defaults.extract.json")).unwrap();
        let library = "standard library package Base { classifier Anything; datatype DataValue specializes Anything; feature things; feature dataValues : DataValue subsets things; }";
        for case in artifact["feature_type_controls"].as_array().unwrap() {
            let source = case["source"].as_str().unwrap();
            // Cached controls already declare their dependency library.
            let mut document = crate::definition_document::parse_and_link(source, crate::SourceLanguage::Kerml).unwrap();
            let owner_id = document.elements.iter().find(|e| e.properties.get("declared_name") == Some(&json!("x"))).unwrap().id.clone();
            let owner = document.elements.iter().find(|e| e.id == owner_id).unwrap();
            let name = definition_feature_default_name(&document.elements,owner).unwrap();
            assert!(matches!(standard_default_binding(&document.elements,name),Ok(GeneratedLinkTarget::Local(_))),"cached source control must supply its own default dependency");
            let before_types = definition_feature_types(&document.elements,owner).unwrap().iter().map(|e|e.id.clone()).collect::<Vec<_>>();
            let inserted = crate::definition_document::materialize_feature_defaults(&mut document,&[(owner_id.as_str(),"default")]).unwrap();
            assert!(inserted <= 1);
            let snapshot = serde_json::to_value(&document).unwrap();
            let mut restored: crate::KirDocument = serde_json::from_value(snapshot.clone()).unwrap();
            for model in [&mut document,&mut restored] {
                assert_eq!(crate::definition_document::materialize_feature_defaults(model,&[(owner_id.as_str(),"retry")]).unwrap(),0);
                assert_eq!(snapshot,serde_json::to_value(&*model).unwrap());
                let owner = model.elements.iter().find(|e|e.id==owner_id).unwrap();
                assert_eq!(definition_feature_types(&model.elements,owner).unwrap().iter().map(|e|e.id.clone()).collect::<Vec<_>>(),before_types);
                assert!(definition_redefined_features(&model.elements,owner,false).is_ok());
                assert!(!scope_boolean(owner,"is_implied_included").unwrap());
            }
        }
        let mut document = crate::definition_document::parse_and_link(&format!("{library} package P {{ feature x; feature y : Base::DataValue; }}"),crate::SourceLanguage::Kerml).unwrap();
        let ids: Vec<_> = ["x","y"].iter().map(|name|document.elements.iter().find(|e|e.properties.get("declared_name")==Some(&json!(name))).unwrap().id.clone()).collect();
        let batch = [(ids[0].as_str(),"x.default"),(ids[1].as_str(),"y.default")];
        assert_eq!(crate::definition_document::materialize_feature_defaults(&mut document,&batch).unwrap(),2);
        for (id,expected) in ids.iter().zip(["things","dataValues"]) {
            let owner = document.elements.iter().find(|e|&e.id==id).unwrap();
            let relation = stored_children(&document.elements,owner,"owned_relationship").unwrap().into_iter().find(|e|scope_boolean(e,"is_implied").unwrap()).unwrap();
            assert_eq!(relation.kind.rsplit("::").next(),Some("Subsetting"));
            assert_eq!(redefined_reference(&document.elements,relation,"general").unwrap().properties["declared_name"],json!(expected));
        }
        assert_eq!(crate::definition_document::materialize_feature_defaults(&mut document,&batch).unwrap(),0);
    }

    #[test]
    fn definition_feature_default_transaction_rejects_unknown_partial_contributions() {
        let source = "standard library package Base { feature things; feature wrong; } package P { feature x; feature y; }";
        let original = crate::definition_document::parse_and_link(source,crate::SourceLanguage::Kerml).unwrap();
        for shape in ["wrong_target","wrong_specific","nested_relation","wrong_category"] {
            let mut document = original.clone();
            let named = |name:&str|document.elements.iter().find(|e|e.properties.get("declared_name")==Some(&json!(name))).unwrap().id.clone();
            let (x,y,wrong,things)=(named("x"),named("y"),named("wrong"),named("things"));
            let kind = if shape=="wrong_category" {"Redefinition"}else{"Subsetting"};
            let mut relation = fresh_definition_element("unknown".into(),kind).unwrap();
            relation.properties.insert("is_implied".into(),json!(true));
            let specific = ecore_model::redefined_feature(kind,"specific").unwrap();
            let general = ecore_model::redefined_feature(kind,"general").unwrap();
            relation.properties.insert(specific.field.into(),json!(if shape=="wrong_specific" {&x}else{&y}));
            relation.properties.insert(general.field.into(),json!(if shape=="wrong_target" {&wrong}else{&things}));
            ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,document.elements.iter_mut().find(|e|e.id==y).unwrap(),&mut relation).unwrap();
            if shape=="nested_relation" {
                let mut child = fresh_definition_element("nested".into(),"Feature").unwrap();
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS,&mut relation,&mut child).unwrap();
                document.elements.push(child);
            }
            document.elements.push(relation);
            let snapshot = serde_json::to_value(&document).unwrap();
            assert!(crate::definition_document::materialize_feature_defaults(&mut document,&[(x.as_str(),"first"),(y.as_str(),"second")]).is_err(),"{shape}");
            assert_eq!(snapshot,serde_json::to_value(&document).unwrap());
        }
    }

    #[test]
    fn definition_feature_owned_ends_match_pilot_and_replay_after_persistence() {
        let artifact: Value = serde_json::from_str(include_str!("../../../../../../docs/conformance/2026-08-support/feature-owned-end-pilot-controls.json")).unwrap();
        assert_eq!(artifact["cases"].as_array().unwrap().len(),8);
        let mut query_count=0;
        for case in artifact["cases"].as_array().unwrap() {
            let mut document=crate::definition_document::parse_and_link(case["source"].as_str().unwrap(),crate::SourceLanguage::Kerml).unwrap();
            let mut ids=Vec::new();
            for observation in case["observations"].as_array().unwrap() {
                let owner=document.elements.iter().find(|e|e.properties.get("declared_name")==Some(&observation["feature"])).unwrap();
                assert!(definition_feature_owned_end(&document.elements,owner).unwrap());
                assert_eq!(json!(definition_feature_default_name(&document.elements,owner).unwrap()),observation["default"]);
                let DefinitionGeneralTypes::Ready(generals)=definition_general_type_inputs(&document.elements,owner).unwrap() else {panic!("control dependency must resolve")};
                let paths=generals.iter().map(|id|{
                    let mut names=Vec::new();let mut cursor=Some(document.elements.iter().find(|e|&e.id==id).unwrap());
                    while let Some(element)=cursor {
                        if let Some(name)=element.properties.get("declared_name").and_then(Value::as_str) {names.push(name.to_owned());}
                        cursor=generated_parent_namespace(&document.elements,&element.id).unwrap();
                    }
                    names.reverse();names
                }).collect::<Vec<_>>();
                assert_eq!(json!(paths),observation["generals"],"{case}");
                ids.push(owner.id.clone());query_count+=1;
            }
            let prefixes=(0..ids.len()).map(|i|format!("end.default.{i}")).collect::<Vec<_>>();
            let batch=ids.iter().zip(&prefixes).map(|(id,prefix)|(id.as_str(),prefix.as_str())).collect::<Vec<_>>();
            crate::definition_document::materialize_feature_defaults(&mut document,&batch).unwrap();
            let snapshot=serde_json::to_value(&document).unwrap();
            let mut restored:crate::KirDocument=serde_json::from_value(snapshot.clone()).unwrap();
            for model in [&mut document,&mut restored] {
                assert_eq!(crate::definition_document::materialize_feature_defaults(model,&batch).unwrap(),0,"{case}");
                assert_eq!(serde_json::to_value(&*model).unwrap(),snapshot);
                for id in &ids {
                    let owner=model.elements.iter().find(|e|&e.id==id).unwrap();
                    assert!(definition_general_type_inputs(&model.elements,owner).is_ok());
                    assert!(definition_redefined_features(&model.elements,owner,false).is_ok());
                    assert!(!scope_boolean(owner,"is_implied_included").unwrap());
                }
                assert!(ecore_model::validate_publication(&model.elements,ecore_model::ReferenceCompleteness::Closed).is_empty());
            }
        }
        assert_eq!(query_count,18);
    }

    #[test]
    fn definition_feature_owned_end_contributions_reject_wrong_positions_and_contexts() {
        let artifact:Value=serde_json::from_str(include_str!("../../../../../../docs/conformance/2026-08-support/feature-owned-end-pilot-controls.json")).unwrap();
        let original=crate::definition_document::parse_and_link(artifact["cases"][0]["source"].as_str().unwrap(),crate::SourceLanguage::Kerml).unwrap();
        for shape in ["wrong_position","wrong_owner_inputs","wrong_membership","unknown_typing"] {
            let mut document=original.clone();
            let named=|name:&str|document.elements.iter().find(|e|e.properties.get("declared_name")==Some(&json!(name))).unwrap().id.clone();
            let (left,right,parent,target)=(named("leftEnd"),named("rightEnd"),named("outer"),named("target"));
            if shape=="wrong_owner_inputs" {document.elements.iter_mut().find(|e|e.id==parent).unwrap().properties.insert("direction".into(),json!("in"));}
            else if shape=="wrong_membership" {
                let member=document.elements.iter().find(|e|e.id==left).unwrap().properties["owning_relationship"].as_str().unwrap().to_owned();
                document.elements.iter_mut().find(|e|e.id==member).unwrap().kind="SysML::OwningMembership".into();
            } else {
                let kind=if shape=="wrong_position" {"Redefinition"}else{"FeatureTyping"};
                let mut relation=fresh_definition_element("unknown".into(),kind).unwrap();
                relation.properties.insert("is_implied".into(),json!(true));
                relation.properties.insert(ecore_model::redefined_feature(kind,"specific").unwrap().field.into(),json!(left));
                let general=if shape=="wrong_position" {target}else{parent};
                relation.properties.insert(ecore_model::redefined_feature(kind,"general").unwrap().field.into(),json!(general));
                ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,document.elements.iter_mut().find(|e|e.id==left).unwrap(),&mut relation).unwrap();document.elements.push(relation);
            }
            let before=serde_json::to_value(&document).unwrap();
            assert!(crate::definition_document::materialize_feature_defaults(&mut document,&[(right.as_str(),"first"),(left.as_str(),"second")]).is_err(),"{shape}");
            assert_eq!(before,serde_json::to_value(&document).unwrap());
        }
    }

    #[test]
    fn definition_crossing_chain_defaults_replay_without_losing_wrapper_identity() {
        for binary in [false,true] {
            let context=if binary {"classifier C { end cross feature e; end feature other; }"}
                else {"package P { classifier T { feature leaf; } feature target : T; feature owner crosses target.leaf; }"};
            let source=format!("standard library package Base {{ classifier Anything; feature things; feature wrong; }} {context}");
            let mut document=crate::definition_document::parse_and_link(&source,crate::SourceLanguage::Kerml).unwrap();
            if binary {
                let owner=document.elements.iter().find(|e|e.properties.get("declared_name")==Some(&json!("e"))).unwrap().id.clone();
                crate::definition_document::materialize_binary_crossing(&mut document,&owner,"cross").unwrap();
            }
            let crossing=document.elements.iter().find(|e|e.kind.rsplit("::").next()==Some("CrossSubsetting")).unwrap();
            let chain=redefined_reference(&document.elements,crossing,"general").unwrap().id.clone();
            let signature=implicit_chain_signature(&document.elements,document.elements.iter().find(|e|e.id==chain).unwrap()).unwrap();
            assert_eq!(crate::definition_document::materialize_feature_defaults(&mut document,&[(chain.as_str(),"chain.default")]).unwrap(),1);
            let snapshot=serde_json::to_value(&document).unwrap();
            let mut restored:crate::KirDocument=serde_json::from_value(snapshot.clone()).unwrap();
            for model in [&mut document,&mut restored] {
                let chain_element=model.elements.iter().find(|e|e.id==chain).unwrap();
                assert!(definition_is_assessed_cross_chain(&model.elements,chain_element).unwrap(),"binary={binary} chain={:?} parts={:?}",chain_element,stored_children(&model.elements,chain_element,"owned_relationship").unwrap());
                assert_eq!(implicit_chain_signature(&model.elements,chain_element).unwrap(),signature);
                assert_eq!(crate::definition_document::materialize_feature_defaults(model,&[(chain.as_str(),"replay")]).unwrap(),0);
                assert_eq!(serde_json::to_value(&*model).unwrap(),snapshot);
            }
            let wrong=document.elements.iter().find(|e|e.properties.get("declared_name")==Some(&json!("wrong"))).unwrap().id.clone();
            document.elements.iter_mut().find(|e|e.id=="chain.default.0").unwrap().properties.insert("subsetted_feature".into(),json!(wrong));
            let before=serde_json::to_value(&document).unwrap();
            assert!(crate::definition_document::materialize_feature_defaults(&mut document,&[(chain.as_str(),"invalid")]).is_err());
            assert_eq!(before,serde_json::to_value(&document).unwrap());
        }
    }

    fn usage_variability_fixture(case: &Value) -> crate::KirDocument {
        static LIBRARY:std::sync::OnceLock<crate::KirDocument>=std::sync::OnceLock::new();
        let mut library=LIBRARY.get_or_init(|| {
            let mut doc=crate::definition_document::parse_and_link("standard library package Occurrences { class Occurrence; assoc HappensLink; } standard library package Links { assoc SelfLink; } standard library package Actions { behavior Action; }",crate::SourceLanguage::Kerml).unwrap();
            // Completed dependency fixtures; cold library lifecycle is separate.
            for e in &mut doc.elements {if metaclass_conforms(&e.kind,"Type") {e.properties.insert("is_implied_included".into(),json!(true));}}
            doc
        }).clone();
        library.elements.extend(compatibility_fixture(case));
        let receiver=case["receiver"].as_str().unwrap();
        let usage=library.elements.iter_mut().find(|e|e.id==receiver).unwrap();
        usage.properties.insert("is_portion".into(),case["is_portion"].clone());usage.properties.insert("is_composite".into(),case["is_composite"].clone());
        for (i,edge) in case["library_edges"].as_array().unwrap().iter().enumerate() {
            let kind=edge[0].as_str().unwrap();let source=edge[1].as_str().unwrap();let name=edge[2].as_str().unwrap().rsplit("::").next().unwrap();
            let target=library.elements.iter().find(|e|e.properties.get("declared_name")==Some(&json!(name))).unwrap().id.clone();
            let mut relation=fresh_definition_element(format!("library.relation.{i}"),kind).unwrap();
            for (field,value) in [("specific",source),("general",target.as_str())] {let c=ecore_model::redefined_feature(kind,field).unwrap();if !c.derived {relation.properties.insert(c.field.into(),json!(value));}}
            ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,library.elements.iter_mut().find(|e|e.id==source).unwrap(),&mut relation).unwrap();library.elements.push(relation);
        }
        library
    }

    #[test]
    fn definition_usage_variability_bindings_match_pilot_compatibility_and_persistence() {
        let data:Value=serde_json::from_str(include_str!("../../../../../../docs/conformance/2026-08-support/usage-variability-pilot-controls.json")).unwrap();
        assert_eq!(data["controls"].as_array().unwrap().len(),752);
        assert_eq!(data["bindings"].as_object().unwrap().len(),47);
        for case in data["controls"].as_array().unwrap() {
            let doc=usage_variability_fixture(case);
            let read=|model:&crate::KirDocument| {
                let receiver=model.elements.iter().find(|e|e.id==case["receiver"].as_str().unwrap()).unwrap();
                assert_eq!(json!(definition_may_time_vary_typed_query(&model.elements,receiver).unwrap()),case["may_time_vary"],"{case}");
                let sub=model.elements.iter().find(|e|e.id=="sub").unwrap();let sup=model.elements.iter().find(|e|e.id=="sup").unwrap();
                let answer=json!(definition_is_compatible_query(&model.elements,sub,sup).unwrap());
                assert_eq!(answer,case["compatible"],"{case}");assert_eq!(answer,case["can_access"],"{case}");
            };
            for reverse in [false,true] {
                let mut model=doc.clone();if reverse {model.elements.reverse();}
                let before=serde_json::to_value(&model).unwrap();read(&model);assert_eq!(before,serde_json::to_value(&model).unwrap());
                let exported=crate::abstract_syntax_json::export_sysml_abstract_syntax_value(&model,Default::default()).unwrap();assert!(!exported.has_errors(),"{case}");
                let imported=crate::abstract_syntax_json::import_sysml_abstract_syntax_value(exported.value,Default::default()).unwrap();assert!(!imported.has_errors(),"{case}");
                let mut replay=imported.persistable_document().unwrap();replay.elements.reverse();read(&replay);
            }
        }
    }

    #[test]
    fn definition_usage_variability_compatibility_preserves_pending_and_invalid_dependencies() {
        let data:Value=serde_json::from_str(include_str!("../../../../../../docs/conformance/2026-08-support/usage-variability-pilot-controls.json")).unwrap();
        for placement in ["super","first_chain"] {
            let case=data["controls"].as_array().unwrap().iter().find(|c|c["kind"]=="ReferenceUsage"&&c["shape"]=="variable"&&c["placement"]==placement).unwrap();
            for malformed in [false,true] {
                let mut doc=usage_variability_fixture(case);let relation=doc.elements.iter_mut().find(|e|e.id=="library.relation.0").unwrap();
                if malformed {relation.properties.insert("general".into(),json!(false));}else{relation.properties.remove("general");}
                let before=serde_json::to_value(&doc).unwrap();
                let usage=doc.elements.iter().find(|e|e.id==case["receiver"].as_str().unwrap()).unwrap();
                let sub=doc.elements.iter().find(|e|e.id=="sub").unwrap();let sup=doc.elements.iter().find(|e|e.id=="sup").unwrap();
                for answer in [definition_may_time_vary_typed_query(&doc.elements,usage),definition_is_compatible_query(&doc.elements,sub,sup)] {
                    if malformed {assert!(matches!(answer,Err(QueryFailure::Rejected(_))),"{answer:?}");}
                    else {assert!(matches!(answer,Err(QueryFailure::Required(Prerequisite::ReadField{ref owner_id,ref field})) if owner_id=="library.relation.0"&&field=="general"),"{answer:?}");}
                }
                assert_eq!(before,serde_json::to_value(&doc).unwrap());
            }
        }
    }



    // Structural controls exercise the shared producer. Actual 94-library and
    // fixed original-expression evidence is collected by the R34 batch runner.
    fn reference_binding_batch_fixture(count:usize)->(crate::KirDocument,Vec<String>) {
        let artifact:Value=serde_json::from_str(include_str!("../../../../resources/metamodels/sysml-2.0-pilot-2026-08/compatibility.extract.json")).unwrap();
        let mut source=artifact["expression_defaults"]["library_result_case"]["source"].as_str().unwrap().to_owned();
        if count==2 {source=source.replace("feature x = y;","feature x = y; feature z = y;");}
        let mut doc=crate::definition_document::parse_and_link(&source,crate::SourceLanguage::Kerml).unwrap();
        let mut ids=doc.elements.iter().filter(|node|node.kind.rsplit("::").next()==Some("FeatureReferenceExpression"))
            .map(|node|node.id.clone()).collect::<Vec<_>>();ids.sort();assert_eq!(ids.len(),count);
        for (ordinal,id) in ids.iter().enumerate() {
            crate::definition_document::materialize_expression_result(&mut doc,id,
                &format!("result.{ordinal}.member"),&format!("result.{ordinal}")).unwrap();
            reference_result_scope::materialize(&mut doc.elements,id,&format!("result.{ordinal}.subsetting")).unwrap();
        }
        (doc,ids)
    }

    #[test]
    fn definition_reference_binding_batch_constructs_all_roles_preserves_flags_and_replays_after_persistence() {
        let (original,ids)=reference_binding_batch_fixture(2);
        let roots=[Prerequisite::ReferenceBindingBatch{owner_ids:ids.clone()}];
        let (graph,pending)=link_generated_graph_planned(original.elements.clone(),Vec::new(),
            &|_|Err(error("no lexical reads expected")),true,&[],&|_|{},Some(&roots)).unwrap();
        assert!(pending.is_empty());
        for node in &original.elements {
            let after=graph.iter().find(|after|after.id==node.id).unwrap();
            assert_eq!(node.properties.get("is_implied_included"),after.properties.get("is_implied_included"));
        }
        for id in &ids {
            let binding=format!("{id}.implicit.reference-binding");
            for fresh in [&binding,&format!("{binding}.end.0"),&format!("{binding}.end.1")] {
                assert!(scope_boolean(graph.iter().find(|node|node.id==*fresh).unwrap(),"is_implied_included").unwrap());
            }
            let connector=graph.iter().find(|node|node.id==binding).unwrap();
            assert_eq!(definition_reference_targets(&graph,connector,"related_feature").unwrap().len(),2);
        }
        let mut doc=crate::KirDocument{metadata:BTreeMap::new(),elements:graph};
        let exported=crate::abstract_syntax_json::export_sysml_abstract_syntax_value(&doc,Default::default()).unwrap();
        assert!(!exported.has_errors());
        let imported=crate::abstract_syntax_json::import_sysml_abstract_syntax_value(exported.value,Default::default()).unwrap();
        assert!(!imported.has_errors());doc=imported.persistable_document().unwrap();doc.elements.reverse();
        let before=serde_json::to_value(&doc).unwrap();
        assert_eq!(reference_binding::materialize_batch(&mut doc.elements,&ids).unwrap(),0);
        assert_eq!(before,serde_json::to_value(&doc).unwrap());
    }

    #[test]
    fn definition_reference_binding_batch_keeps_exact_typed_reads_and_rejects_unregistered_jobs() {
        let (original,ids)=reference_binding_batch_fixture(1);
        let expression=original.elements.iter().find(|node|node.id==ids[0]).unwrap();
        let index=original.elements.iter().map(|node|(node.id.as_str(),node)).collect();
        let query=DefinitionNameQuery::new(&original.elements,&index);
        let member=stored_children_projection_query(&query,expression,"owned_relationship").unwrap().into_iter()
            .find(|node|node.kind.rsplit("::").next()==Some("Membership")).unwrap().id.clone();
        let mut graph=original.elements.clone();
        graph.iter_mut().find(|node|node.id==member).unwrap().properties.remove("member_element");
        let before=serde_json::to_value(&graph).unwrap();
        let failure=reference_binding::materialize_batch(&mut graph,&ids).unwrap_err();
        assert!(matches!(failure,QueryFailure::Required(Prerequisite::ReadField{owner_id,field})
            if owner_id==member&&field=="member_element"));
        assert_eq!(before,serde_json::to_value(&graph).unwrap());
        let roots=[Prerequisite::ReferenceBindingBatch{owner_ids:ids}];
        let failure=link_generated_graph_planned(graph.clone(),Vec::new(),&|_|Err(error("must not invent lexical input")),
            true,&[],&|_|{},Some(&roots)).err().expect("unregistered dependency must reject");
        assert!(failure.message.contains("not pending"));
        assert_eq!(before,serde_json::to_value(&graph).unwrap());
    }

