    #[test]
    fn definition_reference_binding_batch_requires_canonical_replay_endpoints_and_placement() {
        let (mut doc,ids)=reference_binding_batch_fixture(1);
        assert_eq!(reference_binding::materialize_batch(&mut doc.elements,&ids).unwrap(),1);
        for shape in ["endpoint","membership","end_role","connector_role","missing_default"] {
            let mut changed=doc.clone();let binding=format!("{}.implicit.reference-binding",ids[0]);
            match shape {
                "endpoint"=>{
                    let relation=changed.elements.iter_mut().find(|node|node.kind.rsplit("::").next()==Some("ReferenceSubsetting")
                        && node.id==format!("{binding}.end.0.reference")).unwrap();
                    relation.properties.insert("referenced_feature".into(),json!(format!("{binding}.end.1")));
                },
                "membership"=>changed.elements.iter_mut().find(|node|node.id==format!("{binding}.membership")).unwrap().kind="SysML::FeatureMembership".into(),
                "end_role"=>{changed.elements.iter_mut().find(|node|node.id==format!("{binding}.end.0")).unwrap().properties.insert("is_end".into(),json!(false));},
                "missing_default"=>{
                    let connector=changed.elements.iter().find(|node|node.id==binding).unwrap();
                    let relation=connector.properties["owned_relationship"].as_array().unwrap().iter().map(|v|v.as_str().unwrap())
                        .find(|id|changed.elements.iter().any(|node|node.id==*id&&node.kind.rsplit("::").next()==Some("Subsetting"))).unwrap().to_owned();
                    changed.elements.retain(|node|node.id!=relation);
                    changed.elements.iter_mut().find(|node|node.id==binding).unwrap().properties.get_mut("owned_relationship").unwrap().as_array_mut().unwrap().retain(|value|value.as_str()!=Some(relation.as_str()));
                },
                _=>{changed.elements.iter_mut().find(|node|node.id==binding).unwrap().properties.insert("is_variable".into(),json!(true));},
            }
            let before=serde_json::to_value(&changed).unwrap();
            assert!(reference_binding::materialize_batch(&mut changed.elements,&ids).is_err(),"{shape}");
            assert_eq!(before,serde_json::to_value(&changed).unwrap());
        }
    }


    #[test]
    fn definition_reference_binding_batch_supports_incomplete_expression_feature_membership() {
        let (mut doc,ids)=reference_binding_batch_fixture(1);
        let owner_id=&ids[0];
        // An owned literal is the first non-parameter member, as in the pinned
        // conditional-operand wrappers. Canonical ownership replaces the alias.
        let index=doc.elements.iter().map(|node|(node.id.as_str(),node)).collect();
        let query=DefinitionNameQuery::new(&doc.elements,&index);
        let alias=stored_children_projection_query(&query,index[owner_id.as_str()],"owned_relationship").unwrap().into_iter()
            .find(|node|node.kind.rsplit("::").next()==Some("Membership")).unwrap().id.clone();
        drop(query);drop(index);
        let mut literal=fresh_definition_element("nested.literal".into(),"LiteralInteger").unwrap();
        let member=doc.elements.iter_mut().find(|node|node.id==alias).unwrap();
        member.kind="SysML::FeatureMembership".into();member.properties.remove("member_element");
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS,member,&mut literal).unwrap();
        doc.elements.push(literal);
        let relation="result.0.subsetting";
        doc.elements.retain(|node|node.id!=relation);
        doc.elements.iter_mut().find(|node|node.id=="result.0").unwrap().properties.get_mut("owned_relationship").unwrap()
            .as_array_mut().unwrap().retain(|value|value.as_str()!=Some(relation));
        let package=doc.elements.iter().find(|node|node.properties.get("declared_name")==Some(&json!("Performances"))).unwrap().id.clone();
        let mut prototype=fresh_definition_element("literal.prototype".into(),"Feature").unwrap();
        prototype.properties.insert("declared_name".into(),json!("literalIntegerEvaluations"));
        let mut membership=fresh_definition_element("literal.prototype.member".into(),"OwningMembership").unwrap();
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS,&mut membership,&mut prototype).unwrap();
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,
            doc.elements.iter_mut().find(|node|node.id==package).unwrap(),&mut membership).unwrap();
        doc.elements.extend([membership,prototype]);
        // Include the imported behavior-owned contribution dependency. These
        // bounded prototypes retain incomplete flags; the fixed pinned library
        // contract remains the independent resource-level verification scope.
        let mut performance=fresh_definition_element("performance.prototype".into(),"Behavior").unwrap();
        performance.properties.insert("declared_name".into(),json!("Performance"));
        let mut membership=fresh_definition_element("performance.prototype.member".into(),"OwningMembership").unwrap();
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS,&mut membership,&mut performance).unwrap();
        ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,
            doc.elements.iter_mut().find(|node|node.id==package).unwrap(),&mut membership).unwrap();
        doc.elements.extend([membership,performance]);
        for (id,name,parent,kind) in [
            ("performances.prototype","performances",package.as_str(),"OwningMembership"),
            ("enclosed.prototype","enclosedPerformances","performance.prototype","FeatureMembership")] {
            let mut node=fresh_definition_element(id.into(),"Step").unwrap();
            node.properties.insert("declared_name".into(),json!(name));
            let mut membership=fresh_definition_element(format!("{id}.member"),kind).unwrap();
            ecore_ownership::attach(&ecore_ownership_generated::OWNED_ELEMENTS,&mut membership,&mut node).unwrap();
            ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,
                doc.elements.iter_mut().find(|node|node.id==parent).unwrap(),&mut membership).unwrap();
            let mut typing=fresh_definition_element(format!("{id}.typing"),"FeatureTyping").unwrap();
            typing.properties.insert("typed_feature".into(),json!(id));
            typing.properties.insert("type".into(),json!("performance.prototype"));
            ecore_ownership::attach(&ecore_ownership_generated::OWNED_RELATIONSHIPS,&mut node,&mut typing).unwrap();
            doc.elements.extend([membership,node,typing]);
        }
        reference_result_scope::materialize(&mut doc.elements,owner_id,"result.nested.subsetting").unwrap();
        let flags=doc.elements.iter().map(|node|(node.id.clone(),node.properties.get("is_implied_included").cloned())).collect::<BTreeMap<_,_>>();
        assert_eq!(reference_binding::materialize_batch(&mut doc.elements,&ids).unwrap(),1);
        let binder=format!("{owner_id}.implicit.reference-binding");
        let membership=doc.elements.iter().find(|node|node.id==format!("{binder}.membership")).unwrap();
        assert_eq!(membership.kind,"SysML::FeatureMembership");
        for (id,before) in flags {
            assert_eq!(doc.elements.iter().find(|node|node.id==id).unwrap().properties.get("is_implied_included").cloned(),before);
        }
        assert_eq!(reference_binding::materialize_batch(&mut doc.elements,&ids).unwrap(),0);
    }

